private.set_updated_at:
begin
	new.updated_at = timezone('utc', now());
	return new;
end;

public.consume_analysis_rate_limit:
declare
  now_at timestamptz := pg_catalog.clock_timestamp();
  allowed boolean;
begin
  if p_key is null or char_length(p_key) = 0 or char_length(p_key) > 128
     or p_limit < 1 or p_window_seconds < 1 then
    return false;
  end if;

  insert into private.analysis_rate_limit_buckets (
    bucket_key,
    window_started_at,
    request_count,
    updated_at
  )
  values (p_key, now_at, 1, now_at)
  on conflict (bucket_key) do update
  set window_started_at = case
        when private.analysis_rate_limit_buckets.window_started_at
          + pg_catalog.make_interval(secs => p_window_seconds) <= now_at
        then now_at
        else private.analysis_rate_limit_buckets.window_started_at
      end,
      request_count = case
        when private.analysis_rate_limit_buckets.window_started_at
          + pg_catalog.make_interval(secs => p_window_seconds) <= now_at
        then 1
        else private.analysis_rate_limit_buckets.request_count + 1
      end,
      updated_at = now_at
  returning request_count <= p_limit into allowed;

  return allowed;
end;

private.bootstrap_personal_workspace:
declare
  workspace_id uuid;
  workspace_name text;
begin
  insert into public.profiles (id, email)
  values (new.id, coalesce(new.email, ''))
  on conflict (id) do update set email = excluded.email;

  select id into workspace_id
  from public.organizations
  where owner_id = new.id
  order by created_at asc
  limit 1;

  if workspace_id is null then
    workspace_name := left(
      coalesce(nullif(split_part(new.email, '@', 1), ''), 'My') || '''s workspace',
      120
    );
    insert into public.organizations (owner_id, name)
    values (new.id, workspace_name)
    returning id into workspace_id;
  end if;

  insert into public.memberships (organization_id, user_id, role)
  values (workspace_id, new.id, 'owner')
  on conflict (organization_id, user_id) do update set role = excluded.role;

  return new;
end;

public.persist_completed_analysis:
declare
  existing_analysis public.analyses%rowtype;
begin
  if not exists (
    select 1 from public.memberships
    where organization_id = p_organization_id
      and user_id = p_user_id
      and role in ('owner', 'admin', 'member')
  ) then
    raise exception 'organization access denied' using errcode = '42501';
  end if;

  select * into existing_analysis
  from public.analyses
  where idempotency_key = p_idempotency_key;
  if found then
    if existing_analysis.owner_id <> p_user_id then
      raise exception 'idempotency ownership mismatch' using errcode = '42501';
    end if;
    return jsonb_build_object(
      'analysisId', existing_analysis.id,
      'resumeId', (
        select resume_id from public.resume_versions
        where id = existing_analysis.resume_version_id
      ),
      'created', false
    );
  end if;

  insert into public.jobs (id, organization_id, owner_id, title, description)
  values (p_job_id, p_organization_id, p_user_id, p_job_title, p_job_description);
  insert into public.resumes (id, organization_id, owner_id, display_name)
  values (p_resume_id, p_organization_id, p_user_id, p_display_name);
  insert into public.resume_versions (
    id, resume_id, organization_id, owner_id, storage_key, checksum, bytes,
    media_type, page_count
  ) values (
    p_version_id, p_resume_id, p_organization_id, p_user_id, p_storage_key,
    p_checksum, p_bytes, 'application/pdf', (p_result #>> '{parseView,totalPages}')::integer
  );
  insert into public.analyses (
    id, resume_version_id, job_id, organization_id, owner_id, status,
    idempotency_key, completed_at
  ) values (
    p_analysis_id, p_version_id, p_job_id, p_organization_id, p_user_id,
    'completed', p_idempotency_key, timezone('utc', now())
  );
  insert into public.writer_drafts (
    analysis_id, organization_id, owner_id, kind, draft
  ) values (
    p_analysis_id, p_organization_id, p_user_id, 'summary', p_result->'writer'
  );
  insert into public.analysis_results (
    analysis_id, organization_id, owner_id, feedback, parse_view, rule_trace,
    keyword_coverage, parser_version, ruleset_version, normalizer_version,
    prompt_version, schema_version, model_id
  ) values (
    p_analysis_id, p_organization_id, p_user_id, p_result->'feedback',
    p_result->'parseView', p_result->'ruleTrace',
    jsonb_build_object(
      'job', p_result->'jdKeywords',
      'matched', p_result->'matchedKeywords',
      'missing', p_result->'missingKeywords'
    ),
    'parse-sim-v1', 'ats-rules-v1', 'normalizer-v1', 'qualitative-v1',
    'analysis-result-v1', p_model_id
  );

  return jsonb_build_object(
    'analysisId', p_analysis_id,
    'resumeId', p_resume_id,
    'created', true
  );
end;

public.transition_analysis:
declare
  transition_allowed boolean;
begin
  transition_allowed := (p_expected_status, p_next_status) in (
    ('created', 'uploading'), ('created', 'cancelled'),
    ('uploading', 'quarantined'), ('uploading', 'cancelled'),
    ('quarantined', 'queued'), ('quarantined', 'rejected'), ('quarantined', 'failed'),
    ('queued', 'extracting'), ('queued', 'cancelled'), ('queued', 'failed'),
    ('extracting', 'scoring'), ('extracting', 'needs_ocr'), ('extracting', 'failed'),
    ('needs_ocr', 'scoring'), ('needs_ocr', 'failed'),
    ('scoring', 'qualitative_review'), ('scoring', 'failed'),
    ('qualitative_review', 'completed'), ('qualitative_review', 'partial'), ('qualitative_review', 'failed')
  );
  if not transition_allowed then
    raise exception 'invalid analysis transition' using errcode = '22023';
  end if;

  update public.analyses
  set status = p_next_status,
      current_attempt = current_attempt + case when p_next_status = 'extracting' then 1 else 0 end,
      request_id = p_request_id,
      stage_updated_at = timezone('utc', now()),
      completed_at = case when p_next_status in ('completed', 'partial', 'failed', 'cancelled', 'rejected') then timezone('utc', now()) else completed_at end
  where id = p_analysis_id and status = p_expected_status;
  if not found then return false; end if;

  insert into public.analysis_transitions (
    analysis_id, from_status, to_status, actor_id, process_id, request_id
  ) values (
    p_analysis_id, p_expected_status, p_next_status, p_actor_id, p_process_id, p_request_id
  );
  return true;
end;

public.claim_analysis_job:
declare candidate record; a public.analyses%rowtype; j public.analysis_jobs%rowtype; checked_at timestamptz;
begin
  if p_worker_id is null or btrim(p_worker_id)='' or p_lease_seconds is null or p_lease_seconds<1 or p_lease_seconds>3600 then
    raise exception 'invalid lease parameters' using errcode='22023';
  end if;
  for candidate in select a.id from public.analyses a join public.analysis_jobs j on j.analysis_id=a.id
    where j.lease_fence is null and j.dead_lettered_at is null and j.attempt_count>=3 and j.lease_expires_at<=clock_timestamp()
      and a.status in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
      and not private.candidate_write_blocked(a.owner_id)
      and exists(select 1 from public.memberships m where m.organization_id=a.organization_id and m.user_id=a.owner_id and m.role in ('owner','admin','member'))
      and exists(select 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
        where v.id=a.resume_version_id and v.organization_id=a.organization_id and v.owner_id=a.owner_id
          and r.organization_id=a.organization_id and r.owner_id=a.owner_id and r.status='active')
    order by j.run_after,a.id limit 100 for update of a skip locked
  loop
    select * into a from public.analyses where id=candidate.id;
    select * into j from public.analysis_jobs where analysis_id=a.id and lease_fence is null for update skip locked;
    if not found then continue; end if;
    if not private.analysis_job_v2_owner_eligible(candidate.id) then continue; end if;
    checked_at:=clock_timestamp();
    if a.status not in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
      or j.dead_lettered_at is not null or j.attempt_count<3 or j.lease_expires_at is null or j.lease_expires_at>checked_at then continue; end if;
    update public.analysis_jobs set lease_owner=null,lease_expires_at=null,last_error_code='LEASE_EXPIRED',dead_lettered_at=checked_at
      where analysis_id=a.id and lease_fence is null;
    perform public.transition_analysis(a.id,a.status,'failed',null,p_worker_id,coalesce(a.request_id,'worker-dead-letter'));
  end loop;
  for candidate in select a.id from public.analyses a join public.analysis_jobs j on j.analysis_id=a.id
    where j.lease_fence is null and j.run_after<=clock_timestamp() and j.dead_lettered_at is null and j.attempt_count<3
      and (j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp())
      and not private.candidate_write_blocked(a.owner_id)
      and exists(select 1 from public.memberships m where m.organization_id=a.organization_id and m.user_id=a.owner_id and m.role in ('owner','admin','member'))
      and exists(select 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
        where v.id=a.resume_version_id and v.organization_id=a.organization_id and v.owner_id=a.owner_id
          and r.organization_id=a.organization_id and r.owner_id=a.owner_id and r.status='active')
    order by j.run_after,a.id limit 100 for update of a skip locked
  loop
    select * into j from public.analysis_jobs where analysis_id=candidate.id and lease_fence is null for update skip locked;
    if not found then continue; end if;
    if not private.analysis_job_v2_owner_eligible(candidate.id) then continue; end if;
    checked_at:=clock_timestamp();
    if j.dead_lettered_at is not null or j.attempt_count>=3 or j.run_after>checked_at
      or (j.lease_expires_at is not null and j.lease_expires_at>checked_at) then continue; end if;
    update public.analysis_jobs set lease_owner=p_worker_id,lease_expires_at=checked_at+make_interval(secs=>p_lease_seconds),
      attempt_count=attempt_count+1,last_error_code=case when j.lease_expires_at is not null then 'LEASE_EXPIRED' else last_error_code end
      where analysis_id=candidate.id and lease_fence is null returning * into j;
    return jsonb_build_object('analysisId',candidate.id,'attempt',j.attempt_count,'runAfter',j.run_after);
  end loop;
  return null;
end;

public.heartbeat_analysis_job:
begin
  if p_worker_id is null or btrim(p_worker_id)='' or p_lease_seconds is null or p_lease_seconds<1 or p_lease_seconds>3600 then return false; end if;
  update public.analysis_jobs set lease_expires_at=clock_timestamp()+make_interval(secs=>p_lease_seconds)
    where analysis_id=p_analysis_id and lease_fence is null and lease_owner=p_worker_id and lease_expires_at>clock_timestamp();
  return found;
end;

public.release_analysis_job:
declare analysis_row public.analyses%rowtype; job_row public.analysis_jobs%rowtype; checked_at timestamptz;
begin
  if p_analysis_id is null or p_worker_id is null or btrim(p_worker_id)=''
    or p_retry_delay_seconds is null or p_retry_delay_seconds<0 or p_retry_delay_seconds>3600
    or p_error_code is null or btrim(p_error_code)='' then return false; end if;
  -- Same analysis→job order as cancel, R08 and the atomic stage wrapper.
  select * into analysis_row from public.analyses where id=p_analysis_id for update;
  if not found or analysis_row.status not in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review') then return false; end if;
  select * into job_row from public.analysis_jobs where analysis_id=p_analysis_id and lease_owner=p_worker_id for update;
  if not found then return false; end if;
  checked_at:=clock_timestamp();
  -- JSON field lookup preserves the NULL-fence boundary before/after R08 adds
  -- the column. A legacy caller must never mutate a token-protected row.
  if to_jsonb(job_row)->>'lease_fence' is not null or job_row.dead_lettered_at is not null
    or job_row.attempt_count not between 1 and 3 or job_row.lease_expires_at is null or job_row.lease_expires_at<=checked_at then return false; end if;
  if job_row.attempt_count<3 then
    update public.analysis_jobs set lease_owner=null,lease_expires_at=null,last_error_code=p_error_code,
      run_after=checked_at+make_interval(secs=>p_retry_delay_seconds) where analysis_id=p_analysis_id;
    return true;
  end if;
  update public.analysis_jobs set lease_owner=null,lease_expires_at=null,last_error_code=p_error_code,dead_lettered_at=checked_at
    where analysis_id=p_analysis_id;
  if not public.transition_analysis(analysis_row.id,analysis_row.status,'failed',null,p_worker_id,
    coalesce(analysis_row.request_id,'worker-dead-letter')) then
    raise exception 'Legacy dead-letter transition failed' using errcode='23514'; end if;
  return true;
end;

