public.persist_analysis_extraction:
declare
  page jsonb;
  span jsonb;
  assertion jsonb;
  source_span jsonb;
  source_page jsonb;
  reconstructed text;
  persisted boolean;
begin
  if p_evidence_graph is not null then
    if p_extractor_version <> 'unpdf-v1'
       or p_evidence_graph ->> 'schemaVersion' is distinct from 'native-evidence-v1'
       or p_evidence_graph ->> 'extractorVersion' is distinct from p_extractor_version
       or p_evidence_graph ->> 'offsetUnit' is distinct from 'unicode_code_point'
       or jsonb_typeof(p_evidence_graph -> 'pages') is distinct from 'array'
       or jsonb_typeof(p_evidence_graph -> 'spans') is distinct from 'array'
       or jsonb_typeof(p_evidence_graph -> 'assertions') is distinct from 'array' then
      raise exception 'Invalid native evidence contract';
    end if;
    if jsonb_array_length(p_evidence_graph -> 'pages') <> p_page_count
       or jsonb_array_length(p_page_texts) <> p_page_count then
      raise exception 'Invalid native evidence page count';
    end if;
    for page in select value from jsonb_array_elements(p_evidence_graph -> 'pages') loop
      if jsonb_typeof(page -> 'text') is distinct from 'string'
         or page ->> 'pageNumber' is null
         or page ->> 'method' is distinct from 'native_text'
         or page ->> 'confidence' is distinct from 'uncalibrated'
         or page ->> 'id' is distinct from ('page-' || (page ->> 'pageNumber'))
         or (page ->> 'pageNumber')::integer not between 1 and p_page_count
         or page ->> 'text' is distinct from p_page_texts ->> ((page ->> 'pageNumber')::integer - 1) then
        raise exception 'Invalid native evidence page';
      end if;
    end loop;
    if (select count(distinct value ->> 'id') from jsonb_array_elements(p_evidence_graph -> 'pages')) <> p_page_count then
      raise exception 'Duplicate native evidence page';
    end if;
    select string_agg(value ->> 'text', E'\n\n' order by (value ->> 'pageNumber')::integer)
      into reconstructed from jsonb_array_elements(p_evidence_graph -> 'pages');
    if reconstructed is distinct from p_extracted_text then
      raise exception 'Native evidence text mismatch';
    end if;
    if (select count(distinct value ->> 'id') from jsonb_array_elements(p_evidence_graph -> 'spans'))
       <> jsonb_array_length(p_evidence_graph -> 'spans') then
      raise exception 'Duplicate native evidence span';
    end if;
    for span in select value from jsonb_array_elements(p_evidence_graph -> 'spans') loop
      select value into source_page from jsonb_array_elements(p_evidence_graph -> 'pages')
        where value ->> 'id' = span ->> 'pageId';
      if source_page is null or span ->> 'id' is null
         or jsonb_typeof(span -> 'text') is distinct from 'string'
         or span ->> 'start' is null or span ->> 'end' is null
         or (span ->> 'start')::integer < 0
         or (span ->> 'end')::integer < (span ->> 'start')::integer
         or (span ->> 'end')::integer > char_length(source_page ->> 'text')
         or span ->> 'text' is distinct from substring(source_page ->> 'text'
           from (span ->> 'start')::integer + 1
           for (span ->> 'end')::integer - (span ->> 'start')::integer) then
        raise exception 'Native evidence span mismatch';
      end if;
    end loop;
    for page in select value from jsonb_array_elements(p_evidence_graph -> 'pages') loop
      select string_agg(value ->> 'text', E'\n' order by (value ->> 'start')::integer)
        into reconstructed from jsonb_array_elements(p_evidence_graph -> 'spans')
        where value ->> 'pageId' = page ->> 'id';
      if reconstructed is distinct from page ->> 'text' then
        raise exception 'Native spans do not cover their page';
      end if;
    end loop;
    if jsonb_array_length(p_evidence_graph -> 'assertions') <> 3
       or (select count(distinct value ->> 'field') from jsonb_array_elements(p_evidence_graph -> 'assertions')
           where value ->> 'field' in ('name', 'email', 'phone')) <> 3 then
      raise exception 'Invalid native evidence assertion fields';
    end if;
    for assertion in select value from jsonb_array_elements(p_evidence_graph -> 'assertions') loop
      if assertion ->> 'confidence' is distinct from 'uncalibrated' then
        raise exception 'Native confidence is not calibrated';
      end if;
      if assertion ->> 'state' = 'not_evaluated' then
        if assertion ->> 'value' is not null or assertion ->> 'evidence' is not null then
          raise exception 'Unevaluated assertion has a value';
        end if;
      elsif assertion ->> 'state' = 'review_required' then
        select value into source_span from jsonb_array_elements(p_evidence_graph -> 'spans')
          where value ->> 'id' = assertion -> 'evidence' ->> 'spanId';
        if source_span is null or assertion ->> 'value' is null
           or assertion -> 'evidence' ->> 'start' is null
           or assertion -> 'evidence' ->> 'end' is null
           or (assertion -> 'evidence' ->> 'start')::integer < 0
           or (assertion -> 'evidence' ->> 'end')::integer <= (assertion -> 'evidence' ->> 'start')::integer
           or (assertion -> 'evidence' ->> 'end')::integer > char_length(source_span ->> 'text')
           or assertion ->> 'value' is distinct from substring(source_span ->> 'text'
             from (assertion -> 'evidence' ->> 'start')::integer + 1
             for (assertion -> 'evidence' ->> 'end')::integer - (assertion -> 'evidence' ->> 'start')::integer) then
          raise exception 'Native assertion is not grounded';
        end if;
      else
        raise exception 'Invalid native assertion state';
      end if;
    end loop;
  end if;

  persisted := public.persist_analysis_extraction(
    p_analysis_id, p_duration_ms, p_extracted_text, p_extractor_version,
    p_page_count, p_page_texts, p_process_id, p_request_id, p_text_checksum, p_warnings
  );
  if persisted then
    update public.analysis_extractions set evidence_graph = p_evidence_graph
    where analysis_id = p_analysis_id;
  end if;
  return persisted;
end;

public.complete_analysis_job:
begin
  if p_worker_id is null or btrim(p_worker_id)='' then return false; end if;
  delete from public.analysis_jobs where analysis_id=p_analysis_id and lease_fence is null and lease_owner=p_worker_id and lease_expires_at>clock_timestamp();
  return found;
end;

public.persist_deterministic_analysis:
declare
  analysis_row public.analyses%rowtype;
  transitioned boolean;
begin
  if p_taxonomy_version is null
     or btrim(p_taxonomy_version) = ''
     or p_keyword_coverage->>'taxonomyVersion' is distinct from p_taxonomy_version then
    raise exception 'invalid taxonomy version' using errcode = '22023';
  end if;

  select * into analysis_row
  from public.analyses
  where id = p_analysis_id
  for update;

  if not found or analysis_row.status <> 'scoring' then
    return false;
  end if;

  insert into public.analysis_deterministic_results (
    analysis_id, organization_id, owner_id, score, parse_view, rule_trace,
    keyword_coverage, input_text_checksum, result_checksum, parser_version,
    ruleset_version, normalizer_version, taxonomy_version
  ) values (
    p_analysis_id, analysis_row.organization_id, analysis_row.owner_id,
    p_score, p_parse_view, p_rule_trace, p_keyword_coverage,
    p_input_text_checksum, p_result_checksum, p_parser_version,
    p_ruleset_version, p_normalizer_version, p_taxonomy_version
  );

  transitioned := public.transition_analysis(
    p_analysis_id,
    'scoring',
    'qualitative_review',
    null,
    p_process_id,
    p_request_id
  );
  return transitioned;
end;

public.persist_qualitative_analysis:
declare
  analysis_row public.analyses%rowtype;
  deterministic_row public.analysis_deterministic_results%rowtype;
  transitioned boolean;
begin
  select * into analysis_row
  from public.analyses
  where id = p_analysis_id
  for update;
  if not found or analysis_row.status <> 'qualitative_review' then
    return false;
  end if;

  select * into deterministic_row
  from public.analysis_deterministic_results
  where analysis_id = p_analysis_id;
  if not found then
    raise exception 'deterministic result missing' using errcode = '23503';
  end if;

  insert into public.analysis_ai_runs (
    id, analysis_id, organization_id, owner_id, provider, model_id,
    prompt_version, input_hash, input_tokens, output_tokens, output
  ) values (
    p_run_id, p_analysis_id, analysis_row.organization_id,
    analysis_row.owner_id, p_provider, p_model_id, p_prompt_version,
    p_input_hash, p_input_tokens, p_output_tokens, p_output
  );

  insert into public.analysis_results (
    analysis_id, organization_id, owner_id, feedback, parse_view, rule_trace,
    keyword_coverage, parser_version, ruleset_version, normalizer_version,
    taxonomy_version, prompt_version, schema_version, model_id
  ) values (
    p_analysis_id, analysis_row.organization_id, analysis_row.owner_id,
    p_feedback, deterministic_row.parse_view, deterministic_row.rule_trace,
    deterministic_row.keyword_coverage, deterministic_row.parser_version,
    deterministic_row.ruleset_version, deterministic_row.normalizer_version,
    deterministic_row.taxonomy_version, p_prompt_version, 'analysis-result-v1',
    p_model_id
  );

  insert into public.writer_drafts (
    analysis_id, organization_id, owner_id, kind, draft
  ) values (
    p_analysis_id, analysis_row.organization_id, analysis_row.owner_id,
    'summary', p_writer
  );

  transitioned := public.transition_analysis(
    p_analysis_id,
    'qualitative_review',
    'completed',
    null,
    p_process_id,
    p_request_id
  );
  return transitioned;
end;

public.cancel_queued_analysis:
declare
  analysis_row public.analyses%rowtype;
begin
  select * into analysis_row
  from public.analyses
  where id = p_analysis_id
    and owner_id = p_user_id
  for update;

  if not found or analysis_row.status not in ('quarantined', 'queued') then
    return false;
  end if;

  update public.analyses
  set status = 'cancelled',
      request_id = p_request_id,
      stage_updated_at = timezone('utc', now()),
      completed_at = timezone('utc', now())
  where id = p_analysis_id
    and status = analysis_row.status;
  if not found then return false; end if;

  delete from public.analysis_jobs where analysis_id = p_analysis_id;
  insert into public.analysis_transitions (
    analysis_id, from_status, to_status, actor_id, process_id, request_id
  ) values (
    p_analysis_id, analysis_row.status, 'cancelled', p_user_id, 'web', p_request_id
  );
  return true;
end;

public.persist_partial_analysis:
declare
  analysis_row public.analyses%rowtype;
  deterministic_row public.analysis_deterministic_results%rowtype;
  transitioned boolean;
begin
  select * into analysis_row from public.analyses
  where id = p_analysis_id for update;
  if not found or analysis_row.status <> 'qualitative_review' then return false; end if;

  select * into deterministic_row from public.analysis_deterministic_results
  where analysis_id = p_analysis_id;
  if not found then
    raise exception 'deterministic result missing' using errcode = '23503';
  end if;

  insert into public.analysis_results (
    analysis_id, organization_id, owner_id, feedback, parse_view, rule_trace,
    keyword_coverage, parser_version, ruleset_version, normalizer_version,
    taxonomy_version, prompt_version, schema_version, model_id
  ) values (
    p_analysis_id, analysis_row.organization_id, analysis_row.owner_id,
    p_feedback, deterministic_row.parse_view, deterministic_row.rule_trace,
    deterministic_row.keyword_coverage, deterministic_row.parser_version,
    deterministic_row.ruleset_version, deterministic_row.normalizer_version,
    deterministic_row.taxonomy_version, 'qualitative-unavailable-v1',
    'analysis-result-v1', 'unavailable'
  ) on conflict (analysis_id) do nothing;

  insert into public.writer_drafts (
    analysis_id, organization_id, owner_id, kind, draft
  ) values (
    p_analysis_id, analysis_row.organization_id, analysis_row.owner_id,
    'summary', jsonb_build_object('summary', null, 'bullets', '[]'::jsonb)
  ) on conflict (analysis_id, kind) do nothing;

  transitioned := public.transition_analysis(
    p_analysis_id, 'qualitative_review', 'partial', null, p_process_id, p_request_id
  );
  return transitioned;
end;

public.cancel_analysis:
declare analysis_row public.analyses%rowtype; job_row public.analysis_jobs%rowtype; checked_at timestamptz;
begin
  if p_analysis_id is null or p_user_id is null or p_request_id is null or char_length(p_request_id) not between 1 and 128 then return 'not_found'; end if;
  select * into analysis_row from public.analyses where id=p_analysis_id and owner_id=p_user_id for update;
  if not found then return 'not_found'; end if;
  if analysis_row.status='cancelled' then return 'already_cancelled'; end if;
  if analysis_row.status not in ('quarantined','queued') then return 'already_started'; end if;
  select * into job_row from public.analysis_jobs where analysis_id=p_analysis_id for update;
  if found then
    checked_at:=clock_timestamp();
    -- Proven unleased means BOTH fields NULL. Owner-set/missing-expiry is
    -- uncertain; any future expiry is live even if its owner is malformed/null.
    if (job_row.lease_expires_at is null and job_row.lease_owner is not null)
      or (job_row.lease_expires_at is not null and job_row.lease_expires_at>checked_at) then return 'already_started'; end if;
  end if;
  update public.analyses set status='cancelled',request_id=p_request_id,
    stage_updated_at=timezone('utc',now()),completed_at=timezone('utc',now())
    where id=p_analysis_id and owner_id=p_user_id and status=analysis_row.status;
  if not found then return 'already_started'; end if;
  delete from public.analysis_jobs where analysis_id=p_analysis_id;
  insert into public.analysis_transitions(analysis_id,from_status,to_status,actor_id,process_id,request_id)
    values(p_analysis_id,analysis_row.status,'cancelled',p_user_id,'web',p_request_id);
  return 'cancelled';
end;

private.initialize_privacy_request_steps:
begin
  if new.kind = 'export' then
    insert into public.privacy_request_steps (request_id, step_key)
    values (new.id, 'export_manifest');
  else
    insert into public.privacy_request_steps (request_id, step_key)
    values
      (new.id, 'database'),
      (new.id, 'objects'),
      (new.id, 'backup_expiry');
  end if;
  return new;
end;

public.claim_privacy_request:
declare
  request_row public.data_requests%rowtype;
begin
  if p_worker_id is null or btrim(p_worker_id) = ''
     or p_lease_seconds < 30 or p_lease_seconds > 3600 then
    raise exception 'invalid privacy lease parameters' using errcode = '22023';
  end if;

  select * into request_row
  from public.data_requests
  where attempt_count < 3
    and next_attempt_at <= timezone('utc', now())
    and (
      status = 'queued'
      or (status = 'processing' and lease_expires_at <= timezone('utc', now()))
    )
  order by created_at asc
  for update skip locked
  limit 1;

  if not found then return null; end if;

  update public.data_requests
  set status = 'processing',
      attempt_count = attempt_count + 1,
      lease_owner = p_worker_id,
      lease_expires_at = timezone('utc', now()) + make_interval(secs => p_lease_seconds),
      last_error_code = null
  where id = request_row.id;

  return jsonb_build_object(
    'id', request_row.id,
    'kind', request_row.kind,
    'userId', request_row.user_id,
    'organizationId', request_row.organization_id,
    'attempt', request_row.attempt_count + 1
  );
end;

public.complete_privacy_request:
begin
  update public.data_requests
  set status = 'completed',
      completed_at = timezone('utc', now()),
      result_manifest = p_manifest,
      lease_owner = null,
      lease_expires_at = null,
      last_error_code = null
  where id = p_request_id
    and status = 'processing'
    and lease_owner = p_worker_id;

  if not found then return false; end if;

  update public.privacy_request_steps
  set status = 'completed', completed_at = timezone('utc', now())
  where request_id = p_request_id;

  delete from private.privacy_deletion_plans
  where request_id = p_request_id;
  return true;
end;

public.fail_privacy_request:
declare
  next_status text;
begin
  if p_error_code is null or btrim(p_error_code) = ''
     or p_max_attempts < 1 or p_max_attempts > 10 then
    return false;
  end if;
  next_status := case when (
    select attempt_count from public.data_requests
    where id = p_request_id and lease_owner = p_worker_id
  ) >= p_max_attempts then 'failed' else 'queued' end;

  update public.data_requests
  set status = next_status,
      next_attempt_at = case when next_status = 'queued'
        then timezone('utc', now()) + make_interval(secs => least(300, 10 * greatest(attempt_count, 1)))
        else next_attempt_at end,
      lease_owner = null,
      lease_expires_at = null,
      last_error_code = p_error_code
  where id = p_request_id
    and status = 'processing'
    and lease_owner = p_worker_id;
  if not found then return false; end if;

  update public.privacy_request_steps
  set status = case when next_status = 'failed' then 'failed' else 'queued' end,
      last_error_code = p_error_code,
      attempt_count = attempt_count + 1
  where request_id = p_request_id
    and status <> 'completed';
  return true;
end;

public.prepare_deletion_request:
declare
  request_row public.data_requests%rowtype;
  storage_objects jsonb;
  first_at timestamptz;
begin
  select * into request_row
  from public.data_requests
  where id = p_request_id
    and kind = 'deletion'
    and status = 'processing'
    and lease_owner = p_worker_id
  for update;
  if not found then
    raise exception 'privacy deletion request is not owned' using errcode = '42501';
  end if;

  if not private.try_lock_candidate_owners(array[request_row.user_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
  select plan.storage_objects,plan.created_at into storage_objects,first_at
  from private.privacy_deletion_plans plan
  where plan.request_id = request_row.id;

  if not found then
    select coalesce(jsonb_agg(jsonb_build_object(
      'storageKey', storage_key,
      'checksum', checksum,
      'bytes', bytes
    )), '[]'::jsonb)
    into storage_objects
    from public.resume_versions
    where owner_id = request_row.user_id;

    if not exists(select 1 from private.owned_ai_deletion_dispositions where owner_id=request_row.user_id)
      and exists(select 1 from public.data_requests d join public.privacy_request_steps s on s.request_id=d.id
        where d.user_id=request_row.user_id and d.kind='deletion' and s.step_key='database' and s.status='completed')
      then raise exception 'OWNED_AI_DISPOSITION_HISTORICAL_REPAIR' using errcode='23514';end if;
    first_at:=clock_timestamp();
    insert into private.privacy_deletion_plans (request_id, storage_objects,created_at)
    values (request_row.id, storage_objects,first_at);
  end if;

  -- Candidate rows and the durable object plan commit atomically. A retry can
  -- therefore continue deleting the same objects after database rows are gone.
  insert into private.owned_ai_deletion_dispositions(owner_id,first_request_id,prepared_at,expires_at,phase)
    values(request_row.user_id,request_row.id,first_at,first_at+interval '720 hours','prepared') on conflict(owner_id) do nothing;
  perform private.capture_owned_ai_operation_dispositions(request_row.user_id,null,request_row.id,null);
  perform private.capture_owned_legacy_ai_usage(request_row.user_id,null,request_row.id,null);
  perform private.retire_initial_feedback_publications(request_row.user_id,null,request_row.id,null);
  delete from public.analyses where owner_id = request_row.user_id;
  delete from public.jobs where owner_id = request_row.user_id;
  delete from public.resumes where owner_id = request_row.user_id;
  delete from public.consents where user_id = request_row.user_id;
  delete from public.memberships where user_id = request_row.user_id;
  delete from public.profiles where id = request_row.user_id;

  update public.privacy_request_steps
  set status = 'completed', completed_at = timezone('utc', now())
  where request_id = request_row.id and step_key = 'database';

  return jsonb_build_object(
    'storageObjects', storage_objects,
    'databaseDeletedAt', timezone('utc', now())
  );
end;

public.claim_expired_resume_objects:
declare candidate public.resumes%rowtype;root_row public.resumes%rowtype;version_row public.resume_versions%rowtype;
 item_row private.retention_items%rowtype;delivered record;result_row jsonb;results jsonb:='[]'::jsonb;
 enroll_count integer:=0;return_count integer:=0;first_item uuid;first_at timestamptz;enrolled_at timestamptz;
begin
 if p_limit is null or p_limit<1 or p_limit>1000 or p_before is null or not isfinite(p_before)
  then raise exception 'invalid retention batch size' using errcode='22023';end if;
 if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;
 -- The retained version rows are durable uncovered version inventory. p_limit
 -- bounds new keys and delivered work, NEVER the root's total history.
 select r.* into candidate from public.resumes r where ((r.status='active' and r.created_at<p_before) or r.status='deleted')
  and (exists(select 1 from public.resume_versions v where v.resume_id=r.id and not exists(
    select 1 from private.retention_items t where t.resume_id=r.id and t.owner_id=r.owner_id and t.storage_key=v.storage_key))
   or exists(select 1 from private.retention_items t where t.resume_id=r.id and t.status<>'deleted'))
  order by case when exists(select 1 from public.resume_versions v where v.resume_id=r.id and not exists(
    select 1 from private.retention_items t where t.resume_id=r.id and t.owner_id=r.owner_id and t.storage_key=v.storage_key)) then 0
   else coalesce((select min(t.attempt_count) from private.retention_items t where t.resume_id=r.id and t.status<>'deleted'),2147483647) end,
   r.created_at,r.id limit 1 for update of r skip locked;
 if not found then return;end if;
 root_row:=private.r17_lock_root(candidate.owner_id,candidate.id);
 select min(t.created_at) into first_at from private.retention_items t where t.resume_id=root_row.id and t.owner_id=root_row.owner_id;
 if root_row.status='deleted' and first_at is null then raise exception 'RETENTION_FIRST_CLOCK_REPAIR_REQUIRED' using errcode='23514';end if;
 enrolled_at:=clock_timestamp();
 if first_at is not null and (not isfinite(first_at) or enrolled_at<=first_at)
  then raise exception 'RETENTION_FIRST_CLOCK_REPAIR_REQUIRED' using errcode='23514';end if;
 for version_row in select v.* from public.resume_versions v where v.resume_id=root_row.id and not exists(
   select 1 from private.retention_items t where t.resume_id=root_row.id and t.owner_id=root_row.owner_id and t.storage_key=v.storage_key)
   order by v.created_at,v.id limit p_limit for update of v skip locked loop
  exit when enroll_count>=p_limit;
  insert into private.retention_items(resume_id,owner_id,storage_key,status,attempt_count,created_at)
    values(root_row.id,root_row.owner_id,version_row.storage_key,'queued',0,enrolled_at)
    on conflict on constraint retention_items_storage_key_key do nothing;
  if found then enroll_count:=enroll_count+1;end if;
  if not exists(select 1 from private.retention_items t where t.resume_id=root_row.id and t.owner_id=root_row.owner_id and t.storage_key=version_row.storage_key)
    then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;
 end loop;
 for delivered in select t.* from private.retention_items t join public.resume_versions v on v.resume_id=t.resume_id and v.storage_key=t.storage_key
  where t.resume_id=root_row.id and t.owner_id=root_row.owner_id and v.owner_id=root_row.owner_id and v.organization_id=root_row.organization_id
   and t.status in ('queued','failed') order by t.attempt_count,t.created_at,t.id limit p_limit for update of t skip locked loop
  exit when return_count>=p_limit;
  update private.retention_items set status='queued',attempt_count=attempt_count+1,last_error_code=null
    where id=delivered.id and status in ('queued','failed') returning * into item_row;
  if not found then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;
  if first_item is null then first_item:=item_row.id;end if;
  results:=results||jsonb_build_array(jsonb_build_object('item_id',item_row.id,'resume_id',item_row.resume_id,'storage_key',item_row.storage_key));
  return_count:=return_count+1;
 end loop;
 if return_count=0 then return;end if;
 -- Separate commands observe enrollment. Existing capture owns all operation
 -- states and preserves the earliest item/cause, including deleted old items.
 perform private.capture_owned_ai_operation_dispositions(root_row.owner_id,root_row.id,null,first_item);
 update public.resumes set status='deleted',updated_at=timezone('utc',now()) where id=root_row.id;
 for result_row in select value from jsonb_array_elements(results) loop
  item_id:=(result_row->>'item_id')::uuid;resume_id:=(result_row->>'resume_id')::uuid;storage_key:=result_row->>'storage_key';return next;
 end loop;
end;

public.complete_retention_item:
declare selected private.retention_items%rowtype;item_row private.retention_items%rowtype;root_row public.resumes%rowtype;
begin
 select * into selected from private.retention_items where id=p_item_id;
 if not found then return false;end if;
 if selected.status='deleted' then return true;end if;
 if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;
 if not private.try_lock_candidate_owners(array[selected.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
 -- Re-read terminal state after owner acquisition BEFORE requiring a parent:
 -- another completion may have committed both deletion and parent cascade.
 select * into item_row from private.retention_items where id=p_item_id for update skip locked;
 if not found then
  if exists(select 1 from private.retention_items where id=p_item_id) then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;
  return false;
 end if;
 if (item_row.owner_id,item_row.resume_id,item_row.storage_key) is distinct from (selected.owner_id,selected.resume_id,selected.storage_key)
  then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;
 if item_row.status='deleted' then return true;end if;
 root_row:=private.r17_lock_root(item_row.owner_id,item_row.resume_id);
 if root_row.status<>'deleted' or not exists(select 1 from public.resume_versions v where v.resume_id=root_row.id and v.owner_id=root_row.owner_id
   and v.organization_id=root_row.organization_id and v.storage_key=item_row.storage_key
   and v.storage_key=private.r17_storage_key(v.organization_id,v.resume_id,v.id))
  then raise exception 'RETENTION_PARENT_REPAIR_REQUIRED' using errcode='23514';end if;
 update private.retention_items set status='deleted',completed_at=clock_timestamp(),last_error_code=null where id=p_item_id and status in ('queued','failed');
 if not found then raise exception 'RETENTION_ITEM_STATE' using errcode='23514';end if;
 -- Missing/unenrolled actual versions prevent BOTH publication retirement and
 -- parent cascade, even when every recorded work item is already deleted.
 if private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true then
  perform private.capture_owned_legacy_ai_usage(root_row.owner_id,root_row.id,null,item_row.id);
  perform private.retire_initial_feedback_publications(root_row.owner_id,root_row.id,null,item_row.id);
  -- Recheck coverage under the same owner/root/source locks immediately before DELETE.
  delete from public.resumes r where r.id=root_row.id and r.owner_id=root_row.owner_id and r.status='deleted'
    and private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true;
  if not found then raise exception 'RETENTION_COVERAGE_CHANGED' using errcode='23514';end if;
 end if;
 return true;
end;

public.fail_retention_item:
declare selected private.retention_items%rowtype;item_row private.retention_items%rowtype;root_row public.resumes%rowtype;
begin
 if p_error_code is null or btrim(p_error_code)='' then return false;end if;
 select * into selected from private.retention_items where id=p_item_id;
 if not found then return false;end if;
 if selected.status='deleted' then return false;end if;
 if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;
 if not private.try_lock_candidate_owners(array[selected.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
 -- Re-read terminal state after owner acquisition BEFORE requiring a parent:
 -- another completion may have committed both deletion and parent cascade.
 select * into item_row from private.retention_items where id=p_item_id for update skip locked;
 if not found then
  if exists(select 1 from private.retention_items where id=p_item_id) then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;
  return false;
 end if;
 if item_row.status='deleted' then return false;end if;
 if (item_row.owner_id,item_row.resume_id,item_row.storage_key) is distinct from (selected.owner_id,selected.resume_id,selected.storage_key) then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;
 root_row:=private.r17_lock_root(item_row.owner_id,item_row.resume_id);
 if root_row.status<>'deleted' or not exists(select 1 from public.resume_versions v where v.resume_id=root_row.id and v.owner_id=root_row.owner_id
    and v.organization_id=root_row.organization_id and v.storage_key=item_row.storage_key)
  then raise exception 'RETENTION_ITEM_REPAIR_REQUIRED' using errcode='23514';end if;
 update private.retention_items set status='failed',last_error_code=p_error_code where id=p_item_id and status in ('queued','failed');
 return found;
end;

public.persist_native_layout_extraction:
declare
  page jsonb;
  block jsonb;
  box jsonb;
  warning jsonb;
  key text;
  page_index integer := 0;
  run_index integer;
  cursor_offset integer;
  start_offset integer;
  end_offset integer;
  source_text text;
  persisted boolean;
begin
  if p_native_layout is not null then
    if p_extractor_version is distinct from 'unpdf-v1' or p_evidence_graph is null
       or p_native_layout ->> 'schemaVersion' is distinct from 'native-layout-v1'
       or jsonb_typeof(p_native_layout -> 'pages') is distinct from 'array'
       or jsonb_typeof(p_page_texts) is distinct from 'array' then
      raise exception 'Invalid native layout contract';
    end if;
    if jsonb_array_length(p_native_layout -> 'pages') <> p_page_count
       or p_page_count not between 1 and 100 then
      raise exception 'Invalid native layout page count';
    end if;
    for page in select value from jsonb_array_elements(p_native_layout -> 'pages') loop
      page_index := page_index + 1;
      source_text := p_page_texts ->> (page_index - 1);
      if page ->> 'pageId' is distinct from ('page-' || page_index)
         or page -> 'pageNumber' is distinct from to_jsonb(page_index)
         or page ->> 'text' is distinct from source_text
         or page ->> 'coordinateSystem' is distinct from 'normalized_top_left'
         or page ->> 'readingOrder' is distinct from 'pdf_source_order'
         or jsonb_typeof(page -> 'blocks') is distinct from 'array'
         or jsonb_typeof(page -> 'warnings') is distinct from 'array' then
        raise exception 'Invalid native layout page';
      end if;
      foreach key in array array['width', 'height'] loop
        if jsonb_typeof(page -> key) is distinct from 'number'
           or (page ->> key)::numeric <= 0 or (page ->> key)::numeric > 100000 then
          raise exception 'Invalid native layout dimensions';
        end if;
      end loop;
      if jsonb_typeof(page -> 'rotation') is distinct from 'number'
         or (page ->> 'rotation')::numeric not between 0 and 359
         or trunc((page ->> 'rotation')::numeric) <> (page ->> 'rotation')::numeric
         or jsonb_array_length(page -> 'blocks') > 10000
         or jsonb_array_length(page -> 'warnings') > 5 then
        raise exception 'Invalid native layout bounds';
      end if;
      for warning in select value from jsonb_array_elements(page -> 'warnings') loop
        if warning #>> '{}' is null or warning #>> '{}' not in
          ('invalid_geometry', 'out_of_page_geometry', 'unsupported_reading_direction',
           'ambiguous_columns_or_table', 'source_order_not_top_to_bottom') then
          raise exception 'Invalid native layout warning';
        end if;
      end loop;
      if page ->> 'state' is distinct from (case when jsonb_array_length(page -> 'warnings') > 0 then 'review_required' else 'uncalibrated' end) then
        raise exception 'Invalid native layout review state';
      end if;
      cursor_offset := 0;
      run_index := 0;
      for block in select value from jsonb_array_elements(page -> 'blocks') loop
        run_index := run_index + 1;
        if block ->> 'id' is distinct from (page ->> 'pageId' || '-run-' || run_index)
           or block ->> 'pageId' is distinct from page ->> 'pageId'
           or block -> 'sourceOrder' is distinct from to_jsonb(run_index - 1)
           or block ->> 'geometry' is distinct from 'approximate_font_em'
           or jsonb_typeof(block -> 'text') is distinct from 'string'
           or jsonb_typeof(block -> 'start') is distinct from 'number'
           or jsonb_typeof(block -> 'end') is distinct from 'number'
           or trunc((block ->> 'start')::numeric) <> (block ->> 'start')::numeric
           or trunc((block ->> 'end')::numeric) <> (block ->> 'end')::numeric then
          raise exception 'Invalid native layout run';
        end if;
        start_offset := (block ->> 'start')::integer;
        end_offset := (block ->> 'end')::integer;
        if start_offset < cursor_offset or end_offset < start_offset or end_offset > char_length(source_text)
           or substring(source_text from cursor_offset + 1 for start_offset - cursor_offset) not in ('', E'\n')
           or block ->> 'text' is distinct from substring(source_text from start_offset + 1 for end_offset - start_offset) then
          raise exception 'Native layout run is not grounded';
        end if;
        cursor_offset := end_offset;
        box := block -> 'box';
        if box = 'null'::jsonb then
          if not (page -> 'warnings' ? 'invalid_geometry') then raise exception 'Missing geometry warning'; end if;
        elsif jsonb_typeof(box) = 'object' then
          foreach key in array array['x','y','width','height'] loop
            if jsonb_typeof(box -> key) is distinct from 'number'
               or abs((box ->> key)::numeric) > 100 then raise exception 'Invalid native layout box'; end if;
          end loop;
          if (box ->> 'width')::numeric < 0 or (box ->> 'height')::numeric < 0 then raise exception 'Invalid native layout box'; end if;
          if ((box ->> 'x')::numeric < 0 or (box ->> 'y')::numeric < 0
             or (box ->> 'x')::numeric + (box ->> 'width')::numeric > 1
             or (box ->> 'y')::numeric + (box ->> 'height')::numeric > 1)
             and not (page -> 'warnings' ? 'out_of_page_geometry') then raise exception 'Missing crop warning'; end if;
        else raise exception 'Invalid native layout box';
        end if;
      end loop;
      if substring(source_text from cursor_offset + 1) not in ('', E'\n') then raise exception 'Native layout does not cover its page'; end if;
    end loop;
  end if;
  persisted := public.persist_analysis_extraction(p_analysis_id, p_duration_ms, p_extracted_text,
    p_extractor_version, p_page_count, p_page_texts, p_process_id, p_request_id,
    p_text_checksum, p_warnings, p_evidence_graph);
  if persisted then
    update public.analysis_extractions set native_layout = p_native_layout where analysis_id = p_analysis_id;
  end if;
  return persisted;
end;

private.analysis_has_document_evidence:
select exists(select 1 from public.document_evidence_attempts e
  join public.analyses a on a.id = e.analysis_id
  where a.id = p_analysis_id and private.has_organization_role(a.organization_id,array['owner','admin','member','viewer']));

private.reject_evidence_update:
begin
  raise exception 'Evidence originals and corrections are immutable' using errcode = '22023';
end;

private.block_unreviewed_evidence_scores:
begin
  perform 1 from public.analyses where id = new.analysis_id for update;
  if exists (select 1 from public.document_evidence_attempts where analysis_id = new.analysis_id) then
    raise exception 'Document evidence is scoring ineligible' using errcode = '22023';
  end if;
  return new;
end;

private.evidence_keys:
select jsonb_typeof(p_value) = 'object' and
  (select array_agg(k order by k) from jsonb_object_keys(p_value) k) =
  (select array_agg(k order by k) from unnest(p_keys) k);

public.persist_document_evidence:
declare
  a public.analyses%rowtype;
  v public.resume_versions%rowtype;
  prior public.document_evidence_attempts%rowtype;
  page jsonb; span jsonb; source_span jsonb; source_page jsonb; candidate jsonb; ref jsonb;
  graph jsonb; ocr jsonb; request jsonb; word jsonb; box jsonb; field_state jsonb;
  assembled text; n integer; cursor integer; line text; line_number integer;
  left_edge numeric; top_edge numeric; right_edge numeric; bottom_edge numeric; candidate_count integer;
  expected_blockers jsonb := '["uncalibrated_confidence"]'::jsonb; resource jsonb;
begin
  select * into a from public.analyses where id = p_analysis_id for update;
  if not found then return false; end if;
  if a.status not in ('extracting','needs_ocr','scoring','qualitative_review','partial','completed') then return false; end if;
  select * into strict v from public.resume_versions where id = a.resume_version_id;
  if (p_envelope ? 'fieldExtractorVersion' and (jsonb_typeof(p_envelope->'fieldExtractorVersion') is distinct from 'string' or p_envelope->>'fieldExtractorVersion' is distinct from 'evidence-fields/1.0.1'))
     or not private.evidence_keys(p_envelope - 'fieldExtractorVersion', array['schemaVersion','id','ownerId','analysisId','sourceId','inputSha256','createdAt','retentionPolicyId','nativeSource','ocrSource','ocrFailure','status','scoringEligible','confidence','spans','assertions','fields','blockers'])
     or p_envelope->>'schemaVersion' is distinct from 'evidence/2.0.0'
     or p_envelope->>'ownerId' is distinct from a.owner_id::text
     or p_envelope->>'analysisId' is distinct from a.id::text
     or p_envelope->>'sourceId' is distinct from v.id::text
     or p_envelope->>'inputSha256' is distinct from v.checksum
     or v.owner_id <> a.owner_id or v.organization_id <> a.organization_id
     or p_envelope->'scoringEligible' is distinct from 'false'::jsonb
     or p_envelope->>'status' not in ('review_required','insufficient','unsupported','failed')
     or p_envelope->'confidence' is distinct from '{"kind":"uncalibrated","reason":"calibration_not_approved"}'::jsonb
       or jsonb_typeof(p_envelope->'retentionPolicyId') is distinct from 'string' or char_length(p_envelope->>'retentionPolicyId') not between 1 and 100
     or jsonb_typeof(p_envelope->'spans') is distinct from 'array'
     or jsonb_typeof(p_envelope->'assertions') is distinct from 'array'
     or jsonb_typeof(p_envelope->'fields') is distinct from 'array'
     or jsonb_typeof(p_envelope->'blockers') is distinct from 'array'
     or jsonb_array_length(p_envelope->'spans') not between 1 and 20000
     or jsonb_array_length(p_envelope->'assertions') > 1000
     or octet_length(p_envelope::text) > 10000000 then
    raise exception 'Invalid document evidence envelope' using errcode = '22023';
  end if;
  if jsonb_typeof(p_envelope->'id') is distinct from 'string' or jsonb_typeof(p_envelope->'createdAt') is distinct from 'string' or p_envelope->>'createdAt' !~ '^\d{4}-\d{2}-\d{2}T.*Z$' then raise exception 'Invalid evidence identity/time' using errcode = '22023'; end if;
  perform (p_envelope->>'id')::uuid, (p_envelope->>'createdAt')::timestamptz;
  graph := p_envelope->'nativeSource';
  if not private.evidence_keys(graph,array['schemaVersion','extractorVersion','offsetUnit','pages','spans','assertions'])
     or graph->>'schemaVersion' is distinct from 'native-evidence-v1'
     or graph->>'extractorVersion' is distinct from 'unpdf-v1'
     or graph->>'offsetUnit' is distinct from 'unicode_code_point'
     or jsonb_typeof(graph->'pages') is distinct from 'array'
     or jsonb_typeof(graph->'spans') is distinct from 'array'
     or jsonb_typeof(graph->'assertions') is distinct from 'array'
     or jsonb_array_length(graph->'pages') not between 1 and 20 then
    raise exception 'Invalid native evidence source' using errcode = '22023';
  end if;
  if (select sum(char_length(value->>'text')) + (count(*)-1)*2 from jsonb_array_elements(graph->'pages')) > 500000 then raise exception 'Native source text limit' using errcode = '22023'; end if;
  n := 0;
  for page in select value from jsonb_array_elements(graph->'pages') loop
    n := n + 1;
    if not private.evidence_keys(page,array['id','pageNumber','text','method','confidence'])
       or page->>'id' is distinct from 'page-' || n or page->>'pageNumber' is distinct from n::text
       or not private.evidence_integer(page->'pageNumber',1,20)
       or jsonb_typeof(page->'text') is distinct from 'string'
       or page->>'method' is distinct from 'native_text' or page->>'confidence' is distinct from 'uncalibrated' then
      raise exception 'Invalid native page' using errcode = '22023';
    end if;
    cursor := 0; line_number := 0;
    for line in select regexp_split_to_table(page->>'text', E'\n') loop
      line_number := line_number + 1;
      select value into source_span from jsonb_array_elements(graph->'spans') where value->>'id' = page->>'id' || '-line-' || line_number;
      if source_span is null or not private.evidence_keys(source_span,array['id','pageId','start','end','text'])
         or not private.evidence_integer(source_span->'start',0,500000) or not private.evidence_integer(source_span->'end',0,500000)
         or source_span->>'pageId' is distinct from page->>'id'
         or source_span->>'start' is distinct from cursor::text
         or source_span->>'end' is distinct from (cursor + char_length(line))::text
         or source_span->>'text' is distinct from line then
        raise exception 'Native span mismatch' using errcode = '22023';
      end if;
      cursor := cursor + char_length(line) + 1;
    end loop;
  end loop;
  if (select count(*) from jsonb_array_elements(graph->'spans')) <> (select coalesce(sum(1 + char_length(value->>'text') - char_length(replace(value->>'text', E'\n',''))),0) from jsonb_array_elements(graph->'pages')) then
    raise exception 'Native source has extra spans' using errcode = '22023';
  end if;
  if jsonb_array_length(graph->'assertions') <> 3 or (select count(distinct value->>'field') from jsonb_array_elements(graph->'assertions') where value->>'field' in ('name','email','phone')) <> 3 then
    raise exception 'Invalid native assertions' using errcode = '22023';
  end if;
  for candidate in select value from jsonb_array_elements(graph->'assertions') loop
    if not private.evidence_keys(candidate,array['field','value','state','confidence','evidence']) or candidate->>'confidence' is distinct from 'uncalibrated' then raise exception 'Invalid native assertion' using errcode = '22023'; end if;
    if candidate->>'state' = 'not_evaluated' then
      if candidate->'value' <> 'null'::jsonb or candidate->'evidence' <> 'null'::jsonb then raise exception 'Invalid unevaluated assertion' using errcode = '22023'; end if;
    elsif candidate->>'state' = 'review_required' then
      ref := candidate->'evidence';
      select value into source_span from jsonb_array_elements(graph->'spans') where value->>'id' = ref->>'spanId';
      if source_span is null or not private.evidence_keys(ref,array['spanId','start','end']) or not private.evidence_integer(ref->'start',0,500000) or not private.evidence_integer(ref->'end',1,500000) or (ref->>'end')::integer <= (ref->>'start')::integer or (ref->>'end')::integer > char_length(source_span->>'text') or candidate->>'value' is distinct from substring(source_span->>'text' from (ref->>'start')::integer+1 for (ref->>'end')::integer-(ref->>'start')::integer) then raise exception 'Ungrounded native assertion' using errcode = '22023'; end if;
    else raise exception 'Invalid native assertion state' using errcode = '22023'; end if;
  end loop;
  ocr := p_envelope->'ocrSource';
  if ocr <> 'null'::jsonb then
    if not private.evidence_keys(ocr - 'resourceUsage',array['schemaVersion','request','provider','status','scoringEligible','offsetUnit','coordinateSystem','durationMs','measuredWallTimeMs','cost','pages'])
       or ocr->>'schemaVersion' is distinct from 'ocr-evidence-v1'
       or ocr->'scoringEligible' is distinct from 'false'::jsonb
       or ocr->>'status' not in ('review_required','insufficient')
       or ocr->>'offsetUnit' is distinct from 'unicode_code_point'
       or ocr->>'coordinateSystem' is distinct from 'normalized_top_left'
       or jsonb_typeof(ocr->'pages') is distinct from 'array' or jsonb_array_length(ocr->'pages') not between 1 and 10 then raise exception 'Invalid OCR source' using errcode = '22023'; end if;
    request := ocr->'request';
    if not private.evidence_keys(request,array['schemaVersion','attemptId','ownerId','analysisId','sourceId','createdAt','retentionPolicyId','sourceSha256','nativePageTexts','selectedPages','remainingDeadlineMs','limits','allocation','policy'])
       or request->>'schemaVersion' is distinct from 'selective-ocr-request-v1'
       or request->>'ownerId' is distinct from a.owner_id::text
       or request->>'analysisId' is distinct from a.id::text
       or request->>'sourceId' is distinct from v.id::text
       or request->>'sourceSha256' is distinct from v.checksum
       or request->'nativePageTexts' is distinct from (select jsonb_agg(value->'text') from jsonb_array_elements(graph->'pages'))
       or request->'policy' is distinct from '{"executionMode":"self_hosted","purpose":"synthetic_local_test","allowThirdPartyProcessing":false}'::jsonb
       or not private.evidence_keys(request->'limits',array['maxCharacters','maxPages'])
       or not private.evidence_integer(request->'limits'->'maxCharacters',1,200000) or not private.evidence_integer(request->'limits'->'maxPages',1,20)
       or (request->'limits'->>'maxCharacters')::integer not between 1 and 200000
       or (request->'limits'->>'maxPages')::integer not between 1 and 20
       or not private.evidence_keys(request->'allocation',array['id','maxWallTimeMs','maxPages','externalApiFeeMicros'])
       or jsonb_typeof(request->'allocation'->'id') is distinct from 'string' or char_length(request->'allocation'->>'id') not between 1 and 100
       or not private.evidence_integer(request->'allocation'->'maxWallTimeMs',1,10000) or not private.evidence_integer(request->'allocation'->'maxPages',1,10)
       or request->'allocation'->'externalApiFeeMicros' is distinct from '0'::jsonb
       or (request->'allocation'->>'maxWallTimeMs')::integer not between 1 and 10000
       or (request->'allocation'->>'maxPages')::integer not between 1 and 10
       or (request->>'remainingDeadlineMs')::integer not between 1 and 30000
       or not private.evidence_integer(request->'remainingDeadlineMs',1,30000)
       or jsonb_typeof(request->'selectedPages') is distinct from 'array'
       or jsonb_array_length(request->'selectedPages') <> jsonb_array_length(ocr->'pages')
       or request->'selectedPages' is distinct from (select coalesce(jsonb_agg(jsonb_build_object('pageId',value->'id','pageNumber',value->'pageNumber')),'[]'::jsonb) from jsonb_array_elements(graph->'pages') where char_length(regexp_replace(value->>'text','\s','','g')) < 8)
       or (ocr->>'durationMs')::numeric not between 0 and least((request->>'remainingDeadlineMs')::integer,(request->'allocation'->>'maxWallTimeMs')::integer)
       or jsonb_typeof(ocr->'durationMs') is distinct from 'number' or jsonb_typeof(ocr->'measuredWallTimeMs') is distinct from 'number'
       or (ocr->>'measuredWallTimeMs')::numeric not between 0 and least((request->>'remainingDeadlineMs')::integer,(request->'allocation'->>'maxWallTimeMs')::integer)
       or ocr->'cost' is distinct from jsonb_build_object('apiFeeMicros',0,'compute',jsonb_build_object('status','unknown','valueMicros',null,'reason','host_rate_unavailable'),'boundedAllocation',request->'allocation','attempts',1)
       or not private.evidence_keys(ocr->'provider',array['name','executionMode','executionLocation','physicalRegion','versions'])
       or ocr->'provider'->>'name' is distinct from 'tesseract'
       or ocr->'provider'->>'executionMode' is distinct from 'self_hosted'
       or ocr->'provider'->>'executionLocation' is distinct from 'local_host'
       or ocr->'provider'->'physicalRegion' is distinct from '{"value":null,"reason":"not_verified"}'::jsonb
       or not private.evidence_keys(ocr->'provider'->'versions',array['engine','renderer','languageData']) then raise exception 'Invalid OCR request binding' using errcode = '22023'; end if;
    perform (request->>'attemptId')::uuid, (request->>'createdAt')::timestamptz;
    if jsonb_typeof(request->'attemptId') is distinct from 'string' or jsonb_typeof(request->'createdAt') is distinct from 'string' or request->>'createdAt' !~ '^\d{4}-\d{2}-\d{2}T.*Z$' or jsonb_typeof(request->'retentionPolicyId') is distinct from 'string' or request->>'retentionPolicyId' !~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,99}$' or exists(select 1 from jsonb_each(ocr->'provider'->'versions') where jsonb_typeof(value) is distinct from 'string' or char_length(value #>> '{}') not between 1 and 100) or jsonb_array_length(ocr->'pages') > (request->'allocation'->>'maxPages')::integer or jsonb_array_length(graph->'pages') > (request->'limits'->>'maxPages')::integer then raise exception 'Invalid OCR bounds' using errcode = '22023'; end if;
    resource := ocr->'resourceUsage';
    if ocr->'provider'->'versions'->>'engine' = 'tesseract-5.3.0-2/text-fusion-v4' then
      if ocr->'provider'->'versions' is distinct from '{"engine":"tesseract-5.3.0-2/text-fusion-v4","renderer":"poppler-22.12.0-2+deb12u3/dpi-150","languageData":"model-bundle-sha256:74a6c07f4943981367364af90d830c36c6de018cb0c7762caba61e51189c44cc"}'::jsonb or resource is null then raise exception 'Invalid OCR fusion profile' using errcode = '22023'; end if;
    if resource is not null and (not private.evidence_keys(resource - 'containerMemoryPeak',array['kind','cpuTimeMs','maxChildRssBytes','rendererCalls','recognitionCalls']) or resource->>'kind' is distinct from 'child_process_rusage' or not private.evidence_number(resource->'cpuTimeMs',0,30000) or not private.evidence_integer(resource->'maxChildRssBytes',1,1073741824) or not private.evidence_integer(resource->'rendererCalls',1,10) or not private.evidence_integer(resource->'recognitionCalls',1,20) or (resource->>'rendererCalls')::integer <> jsonb_array_length(ocr->'pages') or (resource->>'recognitionCalls')::integer <> 2 * jsonb_array_length(ocr->'pages')) then raise exception 'Invalid OCR resource receipt' using errcode = '22023'; end if;
    else
    if resource is not null and (not private.evidence_keys(resource - 'containerMemoryPeak',array['kind','cpuTimeMs','maxChildRssBytes','rendererCalls','recognitionCalls']) or resource->>'kind' is distinct from 'child_process_rusage' or not private.evidence_number(resource->'cpuTimeMs',0,30000) or not private.evidence_integer(resource->'maxChildRssBytes',1,1073741824) or not private.evidence_integer(resource->'rendererCalls',1,10) or not private.evidence_integer(resource->'recognitionCalls',1,10) or (resource->>'rendererCalls')::integer <> jsonb_array_length(ocr->'pages') or (resource->>'recognitionCalls')::integer <> jsonb_array_length(ocr->'pages')) then raise exception 'Invalid OCR resource receipt' using errcode = '22023'; end if;
    end if;
    if resource ? 'containerMemoryPeak' then
      word := resource->'containerMemoryPeak';
      if not private.evidence_keys(word,array['kind','measuredThrough','valueBytes','reason']) or word->>'kind' is distinct from 'cgroup_v2_memory_peak' or word->>'measuredThrough' is distinct from 'recognition_complete' or not coalesce(((private.evidence_integer(word->'valueBytes',1,9007199254740991) and word->'reason'='null'::jsonb) or (word->'valueBytes'='null'::jsonb and word->>'reason' in ('cgroup_scope_unverified','cgroup_peak_invalid','cgroup_files_unavailable'))),false) then raise exception 'Invalid OCR memory receipt' using errcode = '22023'; end if;
    end if;
    n := 0;
    for page in select value from jsonb_array_elements(ocr->'pages') loop
      if not private.evidence_keys(page,array['pageNumber','pageId','imageSha256','widthPixels','heightPixels','rotation','text','words','dimensionUnit','method'])
         or page->>'pageId' is distinct from 'page-' || (page->>'pageNumber')
         or request->'selectedPages'->n is distinct from jsonb_build_object('pageId',page->'pageId','pageNumber',page->'pageNumber')
         or (page->>'pageNumber')::integer not between 1 and jsonb_array_length(graph->'pages')
         or not private.evidence_integer(page->'pageNumber',1,20) or not private.evidence_integer(page->'widthPixels',1,10000000) or not private.evidence_integer(page->'heightPixels',1,10000000) or not private.evidence_integer(page->'rotation',0,359)
         or jsonb_typeof(page->'imageSha256') is distinct from 'string'
         or page->>'imageSha256' !~ '^[a-f0-9]{64}$'
         or (page->>'widthPixels')::integer <= 0 or (page->>'heightPixels')::integer <= 0
         or (page->>'widthPixels')::bigint * (page->>'heightPixels')::bigint > 10000000
         or (page->>'rotation')::integer not between 0 and 359
         or page->>'dimensionUnit' is distinct from 'pixel' or page->>'method' is distinct from 'local_ocr'
         or jsonb_typeof(page->'text') is distinct from 'string'
         or char_length(page->>'text') > 200000
         or jsonb_typeof(page->'words') is distinct from 'array' or jsonb_array_length(page->'words') > 10000 then raise exception 'Invalid OCR page' using errcode = '22023'; end if;
      n := n + 1; cursor := 0;
      for word in select value from jsonb_array_elements(page->'words') loop
        box := word->'box';
        if not private.evidence_keys(word,array['text','start','end','box','confidence'])
           or jsonb_typeof(word->'text') is distinct from 'string' or jsonb_typeof(word->'start') is distinct from 'number' or jsonb_typeof(word->'end') is distinct from 'number'
           or not private.evidence_integer(word->'start',0,200000) or not private.evidence_integer(word->'end',1,200000)
           or word->>'text' !~ '^\S+$' or (word->>'start')::integer < cursor
           or (word->>'end')::integer <= (word->>'start')::integer
           or (word->>'end')::integer > char_length(page->>'text')
           or substring(page->>'text' from cursor+1 for (word->>'start')::integer-cursor) ~ '\S'
           or word->>'text' is distinct from substring(page->>'text' from (word->>'start')::integer+1 for (word->>'end')::integer-(word->>'start')::integer)
           or not private.evidence_keys(box,array['x','y','width','height'])
           or jsonb_typeof(box->'x') is distinct from 'number' or jsonb_typeof(box->'y') is distinct from 'number' or jsonb_typeof(box->'width') is distinct from 'number' or jsonb_typeof(box->'height') is distinct from 'number'
           or (box->>'x')::numeric not between 0 and 1 or (box->>'y')::numeric not between 0 and 1
           or (box->>'width')::numeric <= 0 or (box->>'height')::numeric <= 0
           or (box->>'x')::numeric+(box->>'width')::numeric > 1 or (box->>'y')::numeric+(box->>'height')::numeric > 1
           or not private.evidence_keys(word->'confidence',array['kind','scale','value'])
           or word->'confidence'->>'kind' is distinct from 'uncalibrated'
           or word->'confidence'->>'scale' is distinct from 'tesseract_0_100'
           or jsonb_typeof(word->'confidence'->'value') is distinct from 'number'
           or (word->'confidence'->>'value')::numeric not between 0 and 100 then raise exception 'Ungrounded OCR word' using errcode = '22023'; end if;
        cursor := (word->>'end')::integer;
      end loop;
      if substring(page->>'text' from cursor+1) ~ '\S' then raise exception 'OCR word coverage mismatch' using errcode = '22023'; end if;
    end loop;
    if (select count(distinct value->>'pageId') from jsonb_array_elements(ocr->'pages')) <> n then raise exception 'Duplicate OCR pages' using errcode = '22023'; end if;
    if (select sum(char_length(value->>'text')) + (count(*)-1)*2 from jsonb_array_elements(graph->'pages')) + (select sum(char_length(value->>'text')) + (count(*)-1)*2 from jsonb_array_elements(ocr->'pages')) > (request->'limits'->>'maxCharacters')::integer then raise exception 'OCR source text limit' using errcode = '22023'; end if;
    if ocr->>'status' is distinct from (case when exists(select 1 from jsonb_array_elements(ocr->'pages') where value->>'text' ~ '\S') then 'review_required' else 'insufficient' end) then raise exception 'OCR status contradicts pages' using errcode = '22023'; end if;
  end if;
  if p_envelope->'ocrFailure' <> 'null'::jsonb and (ocr <> 'null'::jsonb or not private.evidence_keys(p_envelope->'ocrFailure',array['code']) or p_envelope->'ocrFailure'->>'code' not in ('unsupported','timeout','cancelled','resource_limit','engine_failure','invalid_request','invalid_output')) then raise exception 'Invalid OCR failure' using errcode = '22023'; end if;
  if jsonb_array_length(p_envelope->'fields') <> 8 or (select count(distinct value->>'field') from jsonb_array_elements(p_envelope->'fields') where value->>'field' in ('name','email','phone','employer','role','dates','education','certification')) <> 8 then raise exception 'Invalid field states' using errcode = '22023'; end if;
  for field_state in select value from jsonb_array_elements(p_envelope->'fields') loop
    if not private.evidence_keys(field_state,array['field','state']) or field_state->>'state' not in ('not_evaluated','review_required','conflict') then raise exception 'Invalid field state' using errcode = '22023'; end if;
  end loop;
  if exists (select 1 from jsonb_array_elements(p_envelope->'blockers') b where b.value #>> '{}' not in ('uncalibrated_confidence','missing_critical_fields','conflicting_critical_fields','missing_ocr_pages','ocr_failure','no_text')) or not p_envelope->'blockers' @> '["uncalibrated_confidence"]'::jsonb then raise exception 'Invalid evidence blockers' using errcode = '22023'; end if;
  for span in select value from jsonb_array_elements(p_envelope->'spans') loop
    if not private.evidence_keys(span,array['id','pageId','method','text','start','end','box','confidence'])
       or jsonb_typeof(span->'id') is distinct from 'string' or char_length(span->>'id') not between 1 and 100
       or jsonb_typeof(span->'text') is distinct from 'string'
       or jsonb_typeof(span->'start') is distinct from 'number' or jsonb_typeof(span->'end') is distinct from 'number'
       or not private.evidence_integer(span->'start',0,200000) or not private.evidence_integer(span->'end',0,200000) or char_length(span->>'text') > 200000
       or span->'confidence'->>'kind' is distinct from 'uncalibrated'
       or not private.evidence_keys(span->'confidence',array['kind','value']) then raise exception 'Invalid evidence span' using errcode = '22023'; end if;
    if span->>'method' = 'native_text' then
      select value into source_span from jsonb_array_elements(graph->'spans') where value->>'pageId' = span->>'pageId' and value->'start' = span->'start' and value->'end' = span->'end' and value->'text' = span->'text';
      if source_span is null or span->'box' <> 'null'::jsonb or span->'confidence'->'value' <> 'null'::jsonb then raise exception 'Ungrounded native envelope span' using errcode = '22023'; end if;
    elsif span->>'method' = 'local_ocr' then
      select value into source_page from jsonb_array_elements(ocr->'pages') where value->>'pageId' = span->>'pageId';
      if source_page is null or (span->>'start')::integer < 0 or (span->>'end')::integer < (span->>'start')::integer or (span->>'end')::integer > char_length(source_page->>'text') or span->>'text' is distinct from substring(source_page->>'text' from (span->>'start')::integer+1 for (span->>'end')::integer-(span->>'start')::integer) or span->'confidence'->'value' <> 'null'::jsonb then raise exception 'Ungrounded OCR envelope span' using errcode = '22023'; end if;
      select min((value->'box'->>'x')::numeric),min((value->'box'->>'y')::numeric),max((value->'box'->>'x')::numeric+(value->'box'->>'width')::numeric),max((value->'box'->>'y')::numeric+(value->'box'->>'height')::numeric) into left_edge,top_edge,right_edge,bottom_edge from jsonb_array_elements(source_page->'words') where (value->>'start')::integer >= (span->>'start')::integer and (value->>'end')::integer <= (span->>'end')::integer;
      box := span->'box';
      if left_edge is null then
        if box <> 'null'::jsonb then raise exception 'Fabricated OCR geometry' using errcode = '22023'; end if;
      elsif not private.evidence_keys(box,array['x','y','width','height']) or not private.evidence_number(box->'x',0,1) or not private.evidence_number(box->'y',0,1) or not private.evidence_number(box->'width',0,1) or (box->>'width')::numeric <= 0 or not private.evidence_number(box->'height',0,1) or (box->>'height')::numeric <= 0 or abs((box->>'x')::numeric-left_edge)>0.000000000001 or abs((box->>'y')::numeric-top_edge)>0.000000000001 or abs((box->>'width')::numeric-(right_edge-left_edge))>0.000000000001 or abs((box->>'height')::numeric-(bottom_edge-top_edge))>0.000000000001 then raise exception 'Fabricated OCR geometry' using errcode = '22023'; end if;
    else
      raise exception 'Invalid extraction method' using errcode = '22023';
    end if;
  end loop;
  if (select count(distinct value->>'id') from jsonb_array_elements(p_envelope->'spans')) <> jsonb_array_length(p_envelope->'spans') then raise exception 'Duplicate evidence spans' using errcode = '22023'; end if;
  -- Require the complete deterministic source projection, including empty
  -- lines; a caller cannot omit inconvenient native/OCR source text.
  for source_span in select value from jsonb_array_elements(graph->'spans') loop
    if not exists(select 1 from jsonb_array_elements(p_envelope->'spans') where value->>'id' = 'native-' || (source_span->>'id') and value->>'method' = 'native_text' and value->'text' = source_span->'text' and value->'start' = source_span->'start' and value->'end' = source_span->'end' and value->'pageId' = source_span->'pageId') then raise exception 'Native projection incomplete' using errcode = '22023'; end if;
  end loop;
  n := jsonb_array_length(graph->'spans');
  if ocr <> 'null'::jsonb then
    for page in select value from jsonb_array_elements(ocr->'pages') loop
      cursor := 0; line_number := 0;
      for line in select regexp_split_to_table(page->>'text', E'\n') loop
        line_number := line_number + 1; n := n + 1;
        if not exists(select 1 from jsonb_array_elements(p_envelope->'spans') where value->>'id' = 'ocr-' || (page->>'pageId') || '-line-' || line_number and value->>'method' = 'local_ocr' and value->>'text' = line and value->>'start' = cursor::text and value->>'end' = (cursor+char_length(line))::text and value->>'pageId' = page->>'pageId') then raise exception 'OCR projection incomplete' using errcode = '22023'; end if;
        cursor := cursor + char_length(line) + 1;
      end loop;
    end loop;
  end if;
  if jsonb_array_length(p_envelope->'spans') <> n then raise exception 'Evidence projection has extra spans' using errcode = '22023'; end if;
  for candidate in select value from jsonb_array_elements(p_envelope->'assertions') loop
    if not private.evidence_keys(candidate,array['id','field','value','evidence','state','confidence'])
       or jsonb_typeof(candidate->'id') is distinct from 'string' or char_length(candidate->>'id') not between 1 and 100
       or jsonb_typeof(candidate->'value') is distinct from 'string' or char_length(candidate->>'value') not between 1 and 500
       or candidate->>'field' not in ('name','email','phone','employer','role','dates','education','certification')
       or candidate->>'state' is distinct from 'review_required'
       or candidate->'confidence' is distinct from '{"kind":"uncalibrated","value":null}'::jsonb
       or jsonb_typeof(candidate->'evidence') is distinct from 'array' or jsonb_array_length(candidate->'evidence') not between 1 and 20 then raise exception 'Invalid evidence assertion' using errcode = '22023'; end if;
    assembled := '';
    for ref in select value from jsonb_array_elements(candidate->'evidence') loop
      select value into source_span from jsonb_array_elements(p_envelope->'spans') where value->>'id' = ref->>'spanId';
      if source_span is null or not private.evidence_keys(ref,array['spanId','start','end']) or not private.evidence_integer(ref->'start',0,200000) or not private.evidence_integer(ref->'end',1,200000) or (ref->>'end')::integer <= (ref->>'start')::integer or (ref->>'end')::integer > char_length(source_span->>'text') then raise exception 'Invalid assertion reference' using errcode = '22023'; end if;
      assembled := assembled || substring(source_span->>'text' from (ref->>'start')::integer+1 for (ref->>'end')::integer-(ref->>'start')::integer);
    end loop;
    if candidate->>'value' is distinct from assembled then raise exception 'Ungrounded evidence assertion' using errcode = '22023'; end if;
  end loop;
  if (select count(distinct value->>'id') from jsonb_array_elements(p_envelope->'assertions')) <> jsonb_array_length(p_envelope->'assertions') then raise exception 'Duplicate assertion IDs' using errcode = '22023'; end if;
  for field_state in select value from jsonb_array_elements(p_envelope->'fields') loop
    select count(distinct value->>'value') into candidate_count from jsonb_array_elements(p_envelope->'assertions') where value->>'field' = field_state->>'field';
    if field_state->>'state' is distinct from (case when candidate_count=0 then 'not_evaluated' when candidate_count=1 then 'review_required' else 'conflict' end) then raise exception 'Field state contradicts candidates' using errcode = '22023'; end if;
  end loop;
  if p_envelope->>'status' is distinct from (case when p_envelope->'ocrFailure' <> 'null'::jsonb then case when p_envelope->'ocrFailure'->>'code' = 'unsupported' then 'unsupported' else 'failed' end when exists(select 1 from jsonb_array_elements(p_envelope->'spans') where btrim(value->>'text') <> '') then 'review_required' else 'insufficient' end) then raise exception 'Evidence status contradicts sources' using errcode = '22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'fields') where value->>'state'='not_evaluated') then expected_blockers := expected_blockers || '["missing_critical_fields"]'::jsonb; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'fields') where value->>'state'='conflict') then expected_blockers := expected_blockers || '["conflicting_critical_fields"]'::jsonb; end if;
  if exists(select 1 from jsonb_array_elements(graph->'pages') p where char_length(regexp_replace(p.value->>'text','\s','','g')) < 8 and not exists(select 1 from jsonb_array_elements(coalesce(ocr->'pages','[]'::jsonb)) op where op.value->'pageNumber'=p.value->'pageNumber')) then expected_blockers := expected_blockers || '["missing_ocr_pages"]'::jsonb; end if;
  if p_envelope->'ocrFailure' <> 'null'::jsonb then expected_blockers := expected_blockers || '["ocr_failure"]'::jsonb; end if;
  if not exists(select 1 from jsonb_array_elements(p_envelope->'spans') where btrim(value->>'text') <> '') then expected_blockers := expected_blockers || '["no_text"]'::jsonb; end if;
  if p_envelope->'blockers' is distinct from expected_blockers then raise exception 'Blockers contradict evidence' using errcode = '22023'; end if;
  select * into prior from public.document_evidence_attempts where id = (p_envelope->>'id')::uuid;
  if found then
    if prior.analysis_id <> a.id or prior.envelope <> p_envelope then raise exception 'Evidence idempotency conflict' using errcode = '22023'; end if;
    return true;
  end if;
  insert into public.document_evidence_attempts(id,analysis_id,organization_id,owner_id,resume_version_id,input_sha256,attempt_number,envelope)
  values ((p_envelope->>'id')::uuid,a.id,a.organization_id,a.owner_id,v.id,v.checksum,
    coalesce((select max(attempt_number) from public.document_evidence_attempts where analysis_id = a.id),0)+1,p_envelope);
  if a.status in ('extracting','scoring','needs_ocr') then
    update public.analyses set status = 'needs_ocr',stage_updated_at = now() where id = a.id;
    if a.status <> 'needs_ocr' then insert into public.analysis_transitions(analysis_id,from_status,to_status,process_id,request_id) values(a.id,a.status,'needs_ocr',p_process_id,p_request_id); end if;
  end if;
  return true;
end;

public.correct_document_evidence:
declare
  a public.analyses%rowtype; attempt public.document_evidence_attempts%rowtype;
  prior public.evidence_corrections%rowtype; candidate jsonb; revision integer; correction_id uuid;
begin
  select * into a from public.analyses where id = p_analysis_id and owner_id = p_user_id for update;
  if not found then return jsonb_build_object('status','not_found'); end if;
  select * into attempt from public.document_evidence_attempts where id = p_attempt_id and analysis_id = a.id and owner_id = p_user_id;
  if not found then return jsonb_build_object('status','not_found'); end if;
  select * into prior from public.evidence_corrections where analysis_id = a.id and idempotency_key = p_idempotency_key;
  if found then
    if prior.attempt_id = p_attempt_id and prior.actor_id = p_user_id and prior.expected_revision = p_expected_revision and prior.field = p_field and prior.operation = p_operation and prior.value = p_value and prior.candidate_id is not distinct from p_candidate_id then
      return jsonb_build_object('status','applied','revision',prior.revision,'id',prior.id,'idempotent',true);
    end if;
    return jsonb_build_object('status','conflict');
  end if;
  select coalesce(max(c.revision),0) into revision from public.evidence_corrections c where c.analysis_id = a.id;
  if attempt.attempt_number <> (select max(attempt_number) from public.document_evidence_attempts where analysis_id = a.id) or p_expected_revision is distinct from revision then return jsonb_build_object('status','conflict','revision',revision); end if;
  if p_field is null or p_field not in ('name','email','phone','employer','role','dates','education','certification') or p_operation is null or p_operation not in ('confirm','correct') or p_value is null or p_value <> btrim(p_value) or char_length(p_value) not between 1 and 2000 or p_idempotency_key is null or p_request_id is null or char_length(p_request_id) not between 1 and 100 then raise exception 'Invalid evidence correction' using errcode = '22023'; end if;
  if p_operation = 'confirm' then
    select value into candidate from jsonb_array_elements(attempt.envelope->'assertions') where value->>'id' = p_candidate_id and value->>'field' = p_field and value->>'value' = p_value;
    if candidate is null then raise exception 'Confirmation requires exact source candidate' using errcode = '22023'; end if;
  elsif p_candidate_id is not null then
    raise exception 'Corrections cannot fabricate source candidates' using errcode = '22023';
  end if;
  insert into public.evidence_corrections(attempt_id,analysis_id,organization_id,owner_id,actor_id,revision,expected_revision,field,operation,value,candidate_id,idempotency_key,request_id)
  values(attempt.id,a.id,a.organization_id,a.owner_id,p_user_id,revision+1,p_expected_revision,p_field,p_operation,p_value,p_candidate_id,p_idempotency_key,p_request_id) returning id into correction_id;
  insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
  values(a.organization_id,p_user_id,'document_evidence.' || p_operation,'evidence_correction',correction_id,'success',p_request_id);
  return jsonb_build_object('status','applied','revision',revision+1,'id',correction_id,'idempotent',false);
end;

private.validate_canonical_source:
begin
  -- Locks serialize new versions with source/root deletion or access removal.
  perform 1 from public.resumes r join public.resume_versions v on v.resume_id = r.id
    where r.id = new.resume_id and r.status = 'active'
      and r.owner_id = new.owner_id and r.organization_id = new.organization_id
      and v.id = new.source_resume_version_id
      and v.owner_id = new.owner_id and v.organization_id = new.organization_id
    for share of r,v;
  if not found then
    raise exception 'Canonical source ownership mismatch' using errcode = '22023';
  end if;
  return new;
end;

private.reject_canonical_update:
begin
  raise exception 'Canonical versions and facts are immutable' using errcode = '22023';
end;

public.save_canonical_version:
declare
  root public.resumes%rowtype; source public.resume_versions%rowtype;
  head public.canonical_resume_versions%rowtype; prior public.canonical_resume_versions%rowtype;
  evidence public.document_evidence_attempts%rowtype; target public.canonical_resume_versions%rowtype;
  op text; fact jsonb; old_fact jsonb; citation jsonb; span jsonb; section jsonb; entry jsonb; bullet jsonb;
  event jsonb; object_ids text[]; references_ids text[] := '{}'::text[]; ref text;
  new_entries jsonb; new_bullets jsonb; new_sections jsonb := '[]'::jsonb;
  content_chars bigint; revision_value integer;
begin
  if p_command->>'schemaVersion'='entry-regroup-storage/1.0.0' then return private.entry_regroup_save_version(p_user_id,p_source_id,p_body,p_command,p_request_id); end if;
  if p_user_id is null then return jsonb_build_object('status','not_found'); end if;
  perform private.lock_candidate_owners(array[p_user_id]);
  if not private.try_candidate_privacy_write(p_user_id) then return jsonb_build_object('status','not_found'); end if;
  if p_body is null or octet_length(p_body::text)>1048576 or not private.canonical_shape_valid(p_body)
    or p_command is null or not private.evidence_keys(p_command,case when p_command->>'operation'='rename_section' then array['operation','expectedVersionId','idempotencyKey','factId','value','targetVersionId','sectionId'] else array['operation','expectedVersionId','idempotencyKey','factId','value','targetVersionId'] end)
    or p_request_id is null or char_length(p_request_id) not between 1 and 100 then
    raise exception 'Invalid canonical request' using errcode='22023'; end if;
  op:=p_command->>'operation';
  if op not in ('import','edit','confirm','rollback','rename_section') then raise exception 'Invalid canonical operation' using errcode='22023'; end if;
  if op='import' and p_body->>'producerVersion' in ('canonical-engine/1.0.3','canonical-engine/1.0.4') then raise exception 'GROUPED_IMPORT_REQUIRES_ADMISSION' using errcode='22023'; end if;
  select * into root from public.resumes where id=(p_body->>'resumeId')::uuid for update;
  if not found or root.owner_id<>p_user_id or root.status<>'active'
    or not exists(select 1 from public.memberships where user_id=p_user_id and organization_id=root.organization_id)
    or not private.try_candidate_privacy_write(p_user_id) then
    return jsonb_build_object('status','not_found'); end if;
  if p_body->>'ownerId'<>p_user_id::text or p_body->>'organizationId'<>root.organization_id::text then
    raise exception 'Canonical ownership mismatch' using errcode='22023'; end if;
  select * into source from public.resume_versions where id=p_source_id and resume_id=root.id
    and owner_id=p_user_id and organization_id=root.organization_id;
  if not found then return jsonb_build_object('status','not_found'); end if;
  select * into prior from public.canonical_resume_versions
    where resume_id=root.id and idempotency_key=(p_command->>'idempotencyKey')::uuid;
  if found then
    if prior.command->>'operation' in ('grouped_original_import','entry_regroup') or (op='import' and prior.content->>'producerVersion' in ('canonical-engine/1.0.3','canonical-engine/1.0.4')) then return jsonb_build_object('status','conflict'); end if;
    if prior.command<>p_command or prior.source_resume_version_id<>p_source_id then return jsonb_build_object('status','conflict'); end if;
    return jsonb_build_object('status','applied','versionId',prior.id,'revision',prior.revision,'idempotent',true);
  end if;
  select v.* into head from public.canonical_resume_heads h join public.canonical_resume_versions v on v.id=h.version_id where h.resume_id=root.id;
  if (p_command->>'expectedVersionId')::uuid is distinct from head.id then return jsonb_build_object('status','conflict'); end if;
  if head.id is not null then perform private.entry_regroup_validate_head(head.id); end if;
  if op in ('edit','confirm','rename_section') and (head.content->>'producerVersion' in ('canonical-engine/1.0.3','canonical-engine/1.0.4') or p_body->>'producerVersion' in ('canonical-engine/1.0.3','canonical-engine/1.0.4') or exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=head.id))
    and p_body->'producerVersion' is distinct from head.content->'producerVersion' then raise exception 'GROUPED_PRODUCER_RETAG' using errcode='22023'; end if;
  if op='import' and head.id is not null then return jsonb_build_object('status','conflict'); end if;
  if op<>'import' and head.id is null then return jsonb_build_object('status','conflict'); end if;
  if (p_body->>'parentVersionId')::uuid is distinct from head.id then raise exception 'Invalid parent' using errcode='22023'; end if;
  if head.id is not null and (head.source_resume_version_id<>p_source_id
      or p_body->'sourceEvidenceVersionId' is distinct from head.content->'sourceEvidenceVersionId') then
    raise exception 'Source cannot change within a lineage' using errcode='22023'; end if;
  select * into evidence from public.document_evidence_attempts where id=(p_body->>'sourceEvidenceVersionId')::uuid
    and resume_version_id=p_source_id and owner_id=p_user_id and organization_id=root.organization_id;
  if not found then raise exception 'Canonical evidence missing' using errcode='22023'; end if;
  if p_body->>'analysisId'<>evidence.analysis_id::text or p_body->>'inputSha256'<>evidence.input_sha256
    or p_body->'retentionPolicyId' is distinct from evidence.envelope->'retentionPolicyId' then
    raise exception 'Canonical provenance metadata mismatch' using errcode='22023'; end if;
  object_ids:=array[p_body->>'resumeId',p_body->>'versionId'];
  content_chars:=0;
  for fact in select value from jsonb_array_elements(p_body->'facts') loop
    object_ids:=array_append(object_ids,fact->>'id');
    content_chars:=content_chars+char_length(fact->>'value');
    if fact->>'value'<>btrim(fact->>'value') or fact->>'state'='source_supported' then
      raise exception 'Unsupported canonical fact' using errcode='22023'; end if;
    if (fact->>'state'='candidate_confirmed') is distinct from (fact->'confirmation'<>'null'::jsonb) then
      raise exception 'Confirmation state mismatch' using errcode='22023'; end if;
    if fact->'confirmation'<>'null'::jsonb and (fact->'confirmation'->>'actorId'<>p_user_id::text
      or fact->'confirmation'->>'value'<>fact->>'value') then raise exception 'Invalid confirmation' using errcode='22023'; end if;
    for citation in select value from jsonb_array_elements(fact->'sources') loop
      select value into span from jsonb_array_elements(evidence.envelope->'spans') where value->>'id'=citation->>'spanId';
      if span is null or citation->>'attemptId'<>evidence.id::text or (citation->>'end')::int<=(citation->>'start')::int
        or (citation->>'end')::int>char_length(span->>'text') then raise exception 'Invalid canonical citation' using errcode='22023'; end if;
      -- Source text is exact and Unicode code-point indexed, including OCR.
      if substring(span->>'text' from (citation->>'start')::int+1 for (citation->>'end')::int-(citation->>'start')::int)
        <> fact->>'value' then raise exception 'Fact does not match cited text' using errcode='22023'; end if;
    end loop;
    if op='import' and (fact->>'state'<>'unconfirmed' or jsonb_array_length(fact->'sources')=0) then
      raise exception 'Imports require uncertain sourced facts' using errcode='22023'; end if;
  end loop;
  for ref in select jsonb_array_elements_text(p_body->'contactFactIds') loop
    if not exists(select 1 from jsonb_array_elements(p_body->'facts') where value->>'id'=ref and value->>'type' in ('name','email','phone','link','location')) then
      raise exception 'Invalid contact reference' using errcode='22023'; end if;
  end loop;
  references_ids:=array(select jsonb_array_elements_text(p_body->'contactFactIds'));
  if cardinality(references_ids)<>(select count(distinct x) from unnest(references_ids) x) then
    raise exception 'Duplicate contact references' using errcode='22023'; end if;
  for section in select value from jsonb_array_elements(p_body->'sections') loop
    if jsonb_array_length(section->'factIds')<>(select count(distinct value) from jsonb_array_elements(section->'factIds')) then
      raise exception 'Duplicate section references' using errcode='22023'; end if;
    object_ids:=array_append(object_ids,section->>'id'); content_chars:=content_chars+char_length(section->>'title');
    references_ids:=references_ids||array(select jsonb_array_elements_text(section->'factIds'));
    for entry in select value from jsonb_array_elements(section->'entries') loop
      if jsonb_array_length(entry->'factIds')<>(select count(distinct value) from jsonb_array_elements(entry->'factIds')) then
        raise exception 'Duplicate entry references' using errcode='22023'; end if;
      object_ids:=array_append(object_ids,entry->>'id');
      references_ids:=references_ids||array(select jsonb_array_elements_text(entry->'factIds'));
      for bullet in select value from jsonb_array_elements(entry->'bullets') loop
        object_ids:=array_append(object_ids,bullet->>'id'); content_chars:=content_chars+char_length(bullet->>'text');
        references_ids:=references_ids||array(select jsonb_array_elements_text(bullet->'factIds'));
        if jsonb_array_length(bullet->'factIds')<>1 or not exists(select 1 from jsonb_array_elements(p_body->'facts') f
          where f.value->>'id'=bullet->'factIds'->>0 and f.value->>'value'=bullet->>'text') then
          raise exception 'Draft bullet must reference its exact factual content' using errcode='22023'; end if;
      end loop;
    end loop;
  end loop;
  if jsonb_array_length(p_body->'changes')<>1 then raise exception 'Exactly one append-only event required' using errcode='22023'; end if;
  event:=p_body->'changes'->0; object_ids:=array_append(object_ids,event->>'id');
  if content_chars>200000 or cardinality(object_ids)<>(select count(distinct x) from unnest(object_ids) x)
    or event->>'actorId'<>p_user_id::text or event->>'createdAt'<>p_body->>'createdAt' then raise exception 'Invalid canonical identities or event' using errcode='22023'; end if;
  for ref in select unnest(references_ids) loop
    if not exists(select 1 from jsonb_array_elements(p_body->'facts') where value->>'id'=ref) then raise exception 'Dangling fact reference' using errcode='22023'; end if;
  end loop;
  if op='import' then
    if event->>'action'<>'import' or event->>'targetId'<>p_body->>'versionId' or event->'priorValue'<>'null'::jsonb then
      raise exception 'Invalid import event' using errcode='22023'; end if;
  elsif op in ('edit','confirm') then
    select value into old_fact from jsonb_array_elements(head.content->'facts') where value->>'id'=p_command->>'factId';
    if old_fact is null or event->>'targetId'<>old_fact->>'id' or event->>'action'<>'edit' or event->>'priorValue'<>old_fact->>'value'
      or p_body->'contactFactIds'<>head.content->'contactFactIds' or p_body->'locale'<>head.content->'locale'
      or jsonb_array_length(p_body->'facts')<>jsonb_array_length(head.content->'facts') then raise exception 'Invalid edit target' using errcode='22023'; end if;
    for fact in select value from jsonb_array_elements(p_body->'facts') loop
      if fact->>'id'=old_fact->>'id' then
        if fact->>'type'<>old_fact->>'type' then raise exception 'Fact type changed' using errcode='22023'; end if;
        if op='edit' and (fact->>'value' is distinct from p_command->>'value' or fact->>'state'<>'unconfirmed'
          or fact->'sources'<>'[]'::jsonb or fact->'confirmation'<>'null'::jsonb) then raise exception 'Edited fact must be unconfirmed' using errcode='22023'; end if;
        if op='confirm' and (fact->>'value'<>old_fact->>'value' or fact->'sources'<>old_fact->'sources'
          or fact->>'state'<>'candidate_confirmed' or fact->'confirmation'->>'confirmedAt'<>p_body->>'createdAt') then raise exception 'Confirmation must bind exact value' using errcode='22023'; end if;
      elsif not exists(select 1 from jsonb_array_elements(head.content->'facts') where value=fact) then
        raise exception 'Unrelated facts changed' using errcode='22023'; end if;
    end loop;
    -- Only update preview text for the one edited, singly-linked bullet.
    for section in select value from jsonb_array_elements(head.content->'sections') loop
      new_entries:='[]';
      for entry in select value from jsonb_array_elements(section->'entries') loop
        new_bullets:='[]';
        for bullet in select value from jsonb_array_elements(entry->'bullets') loop
          if op='edit' and bullet->'factIds'=jsonb_build_array(old_fact->>'id') then
            bullet:=jsonb_set(bullet,'{text}',p_command->'value'); end if;
          new_bullets:=new_bullets||jsonb_build_array(bullet);
        end loop;
        new_entries:=new_entries||jsonb_build_array(jsonb_set(entry,'{bullets}',new_bullets));
      end loop;
      new_sections:=new_sections||jsonb_build_array(jsonb_set(section,'{entries}',new_entries));
    end loop;
    if p_body->'sections'<>new_sections then raise exception 'Unrelated structure changed' using errcode='22023'; end if;
  elsif op='rename_section' then
    select value into section from jsonb_array_elements(head.content->'sections') where value->>'id'=p_command->>'sectionId';
    if section is null or jsonb_typeof(p_command->'value')<>'string' or char_length(p_command->>'value') not between 1 and 100
      or p_body->'facts'<>head.content->'facts' or p_body->'contactFactIds'<>head.content->'contactFactIds' or p_body->'locale'<>head.content->'locale'
      or event->>'action'<>'edit' or event->>'targetId'<>section->>'id' or event->>'priorValue'<>section->>'title' then
      raise exception 'Invalid section rename' using errcode='22023'; end if;
    select jsonb_agg(case when value->>'id'=section->>'id' then jsonb_set(value,'{title}',p_command->'value') else value end order by ordinality)
      into new_sections from jsonb_array_elements(head.content->'sections') with ordinality;
    if p_body->'sections'<>new_sections then raise exception 'Unrelated structure changed' using errcode='22023'; end if;
  else
    with recursive ancestors as (select id,parent_version_id from public.canonical_resume_versions where id=head.id
      union all select v.id,v.parent_version_id from public.canonical_resume_versions v join ancestors a on v.id=a.parent_version_id)
      select v.* into target from public.canonical_resume_versions v join ancestors a on a.id=v.id where v.id=(p_command->>'targetVersionId')::uuid;
    if target.id is not null then perform private.entry_regroup_validate_head(target.id); end if;
    if target.id is null or p_body->'producerVersion' is distinct from target.content->'producerVersion' or p_body->'facts'<>target.content->'facts' or p_body->'sections'<>target.content->'sections'
      or p_body->'contactFactIds'<>target.content->'contactFactIds' or p_body->'locale'<>target.content->'locale'
      or event->>'action'<>'rollback' or event->>'targetId'<>p_body->>'versionId' or event->'priorValue'<>'null'::jsonb then
      raise exception 'Invalid rollback lineage' using errcode='22023'; end if;
  end if;
  revision_value:=coalesce(head.revision,0)+1;
  insert into public.canonical_resume_versions(id,resume_id,source_resume_version_id,organization_id,owner_id,locale,state,content,created_at,
    parent_version_id,source_evidence_version_id,revision,idempotency_key,command,request_id)
    values((p_body->>'versionId')::uuid,root.id,source.id,root.organization_id,p_user_id,p_body->>'locale',p_body->>'state',p_body,(p_body->>'createdAt')::timestamptz,
      head.id,evidence.id,revision_value,(p_command->>'idempotencyKey')::uuid,p_command,p_request_id);
  insert into public.resume_facts(canonical_version_id,id,organization_id,owner_id,type,value,state,sources,confirmation)
    select (p_body->>'versionId')::uuid,(value->>'id')::uuid,root.organization_id,p_user_id,value->>'type',value->>'value',value->>'state',value->'sources',nullif(value->'confirmation','null'::jsonb)
      from jsonb_array_elements(p_body->'facts');
  insert into public.change_events(canonical_version_id,id,owner_id,organization_id,actor_id,operation,event,created_at)
    values((p_body->>'versionId')::uuid,(event->>'id')::uuid,p_user_id,root.organization_id,p_user_id,op,event,(p_body->>'createdAt')::timestamptz);
  insert into public.canonical_resume_heads(resume_id,version_id,owner_id,organization_id,revision)
    values(root.id,(p_body->>'versionId')::uuid,p_user_id,root.organization_id,revision_value)
    on conflict(resume_id) do update set version_id=excluded.version_id,revision=excluded.revision;
  insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
    values(root.organization_id,p_user_id,'canonical.'||op,'canonical_resume_version',(p_body->>'versionId')::uuid,'success',p_request_id);
  perform private.write_correction_snapshot((p_body->>'versionId')::uuid,p_command);
  return jsonb_build_object('status','applied','versionId',p_body->>'versionId','revision',revision_value,'idempotent',false);
end;

public.export_canonical_records:
declare snapshot jsonb;
begin
  select jsonb_build_object(
    'canonicalResumeVersions',coalesce((select jsonb_agg(to_jsonb(v) order by v.revision)
      from public.canonical_resume_versions v where v.owner_id=p_user_id),'[]'::jsonb),
    'resumeFacts',coalesce((select jsonb_agg(to_jsonb(f) order by f.canonical_version_id,f.id)
      from public.resume_facts f where f.owner_id=p_user_id),'[]'::jsonb),
    'canonicalResumeHeads',coalesce((select jsonb_agg(to_jsonb(h) order by h.resume_id)
      from public.canonical_resume_heads h where h.owner_id=p_user_id),'[]'::jsonb),
    'changeEvents',coalesce((select jsonb_agg(to_jsonb(e) order by e.canonical_version_id,e.id)
      from public.change_events e where e.owner_id=p_user_id),'[]'::jsonb)
    ) into snapshot;
  if octet_length(snapshot::text)>33554432 then
    raise exception 'Canonical export exceeds manifest limit' using errcode='22023';
  end if;
  return snapshot;
end;

public.save_job_requirements:
declare a public.analyses%rowtype; job public.jobs%rowtype; head public.job_requirement_versions%rowtype;
 prior public.job_requirement_versions%rowtype; command jsonb; item jsonb; evidence jsonb; cue jsonb;
 ids uuid[] := '{}'::uuid[]; keys text[] := '{}'::text[]; key text; rev integer; stated_years text[];
begin
 if p_body is null or p_request_id is null or char_length(p_request_id) not between 1 and 100 or p_idempotency_key is null
   or not private.job_requirement_shape_valid(p_body) or octet_length(p_body::text)>1048576 then
   raise exception 'Invalid requirement envelope' using errcode='22023'; end if;
 select * into a from public.analyses where id=p_analysis_id and owner_id=p_user_id for update;
 if a.id is null or a.job_id is null or not private.try_candidate_privacy_write(p_user_id)
   or not exists(select 1 from public.memberships where organization_id=a.organization_id and user_id=p_user_id) then
   return jsonb_build_object('status','not_found'); end if;
 perform 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id where v.id=a.resume_version_id
   and v.owner_id=p_user_id and v.organization_id=a.organization_id and r.owner_id=p_user_id and r.status='active' for share of v,r;
 if not found then return jsonb_build_object('status','not_found'); end if;
 select * into job from public.jobs where id=a.job_id and owner_id=p_user_id and organization_id=a.organization_id for share;
 if job.id is null then return jsonb_build_object('status','not_found'); end if;
 if p_body->>'ownerId'<>p_user_id::text or p_body->>'organizationId'<>a.organization_id::text
   or p_body->>'analysisId'<>a.id::text or p_body->>'jobId'<>job.id::text
   or p_body->>'sourceText'<>job.description or p_body->>'inputSha256'<>encode(extensions.digest(convert_to(job.description,'UTF8'),'sha256'),'hex') then
   raise exception 'Requirement provenance mismatch' using errcode='22023'; end if;
 command:=jsonb_build_object('sourceHash',p_body->>'inputSha256','locale',p_body->>'locale','domain',p_body->>'domain','expectedVersionId',p_expected_version);
 select * into prior from public.job_requirement_versions where analysis_id=a.id and idempotency_key=p_idempotency_key;
 if prior.id is not null then
   if prior.command<>command then return jsonb_build_object('status','conflict'); end if;
   return jsonb_build_object('status','applied','versionId',prior.id,'revision',prior.revision,'idempotent',true); end if;
 select * into head from public.job_requirement_versions where analysis_id=a.id order by revision desc limit 1;
 if head.id is distinct from p_expected_version then return jsonb_build_object('status','conflict'); end if;
 if p_body->>'parentVersionId' is distinct from p_expected_version::text then raise exception 'Requirement lineage mismatch' using errcode='22023'; end if;
 for item in select value from jsonb_array_elements(p_body->'requirements') loop
   evidence:=item->'evidence';
   if (item->>'id')::uuid=any(ids) or item->>'id'=p_body->>'id' then raise exception 'Duplicate requirement ID' using errcode='22023'; end if;
   ids:=array_append(ids,(item->>'id')::uuid);
   key:=concat(item->>'type',':',evidence->>'start',':',evidence->>'end',':',item->>'value');
   if key=any(keys) then raise exception 'Duplicate requirement span' using errcode='22023'; end if;
   keys:=array_append(keys,key);
   if (evidence->>'end')::int<=(evidence->>'start')::int or (evidence->>'end')::int>char_length(job.description)
     or substring(job.description from (evidence->>'start')::int+1 for (evidence->>'end')::int-(evidence->>'start')::int)<>evidence->>'quote'
     or position(item->>'value' in evidence->>'quote')=0 or item->>'value'<>btrim(item->>'value')
     or ((item->>'negated')::boolean and item->>'importance'='required')
     or (item->'minimumYears'<>'null'::jsonb and item->>'type'<>'experience') then
     raise exception 'Invalid exact JD evidence' using errcode='22023'; end if;
   cue:=item->'importanceEvidence';
   if item->'minimumYears'<>'null'::jsonb then
     stated_years:=regexp_match(evidence->>'quote','\y([0-9]{1,2})([[:space:]]*[-–][[:space:]]*[0-9]{1,2}|[[:space:]]*[+])?[[:space:]]*(years?|yrs?)\y','i');
     if stated_years is null or (stated_years[1])::numeric<>(item->>'minimumYears')::numeric then
       raise exception 'Experience value differs from JD' using errcode='22023'; end if;
   end if;
   if (item->>'importanceBasis'='explicit') is distinct from (cue<>'null'::jsonb) then
     raise exception 'Explicit importance citation required' using errcode='22023'; end if;
   if cue<>'null'::jsonb and ((cue->>'end')::int<=(cue->>'start')::int or (cue->>'end')::int>char_length(job.description)
     or substring(job.description from (cue->>'start')::int+1 for (cue->>'end')::int-(cue->>'start')::int)<>cue->>'quote') then
     raise exception 'Invalid importance citation' using errcode='22023'; end if;
 end loop;
 if jsonb_array_length(p_body->'requirements')=0 and p_body->>'state'='review_required' then raise exception 'Empty requirements cannot imply success' using errcode='22023'; end if;
 if (p_body->>'domain'<>'software-engineering' or p_body->>'locale'<>'en-IN') and p_body->>'state'<>'unsupported' then
   raise exception 'Unsupported domain promoted' using errcode='22023'; end if;
 rev:=coalesce(head.revision,0)+1;
 insert into public.job_requirement_versions(id,analysis_id,job_id,owner_id,organization_id,parent_version_id,revision,idempotency_key,command,content,created_at)
 values((p_body->>'id')::uuid,a.id,job.id,p_user_id,a.organization_id,head.id,rev,p_idempotency_key,command,p_body,(p_body->>'createdAt')::timestamptz);
 insert into public.job_requirements(version_id,id,owner_id,organization_id,item)
 select (p_body->>'id')::uuid,(value->>'id')::uuid,p_user_id,a.organization_id,value from jsonb_array_elements(p_body->'requirements');
 insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
 values(a.organization_id,p_user_id,'requirements.import','job_requirement_version',(p_body->>'id')::uuid,'success',p_request_id);
 return jsonb_build_object('status','applied','versionId',p_body->>'id','revision',rev,'idempotent',false);
end;

public.export_job_requirement_records:
declare snapshot jsonb;
begin
 select jsonb_build_object('jobRequirementVersions',coalesce((select jsonb_agg(to_jsonb(v) order by v.analysis_id,v.revision) from public.job_requirement_versions v where owner_id=p_user_id),'[]'::jsonb),
   'jobRequirements',coalesce((select jsonb_agg(to_jsonb(r) order by r.version_id,r.id) from public.job_requirements r where owner_id=p_user_id),'[]'::jsonb)) into snapshot;
 if octet_length(snapshot::text)>33554432 then raise exception 'Requirement export exceeds manifest limit' using errcode='22023'; end if;
 return snapshot;
end;

private.authoring_pattern:
declare result_value text; measurement_value text; scope_value text; method_value text; line text; label text; val text; seen text[]:=array[]::text[];
begin
  if p_pattern not in ('xyz','action_impact_context','action_scope_result') then raise exception 'Invalid pattern' using errcode='22023'; end if;
  for line in select unnest(string_to_array(p_value,E'\n')) offset 1 loop
    label:=split_part(line,': ',1); val:=substring(line from char_length(label)+3);
    if label in ('Result','Measurement','Scope','Method') then
      if label=any(seen) then raise exception 'Ambiguous clarification' using errcode='22023'; end if;
      seen:=array_append(seen,label);
      if val='' or lower(btrim(val)) in ('unknown','n/a','na','none','not known','no measurement') then val:=null; end if;
      if label='Result' then result_value:=val; elsif label='Measurement' then measurement_value:=val;
      elsif label='Scope' then scope_value:=val; else method_value:=val; end if;
    end if;
  end loop;
  if result_value is null or (p_pattern='xyz' and (measurement_value is null or method_value is null)) or (p_pattern<>'xyz' and scope_value is null) then
    raise exception 'Missing clarification' using errcode='22023'; end if;
  if p_pattern='xyz' then return result_value||'; measured by '||measurement_value||'; by '||method_value||'.';
  elsif p_pattern='action_impact_context' then return split_part(p_value,E'\n',1)||'; impact: '||result_value||'; context: '||scope_value||'.';
  else return split_part(p_value,E'\n',1)||'; scope: '||scope_value||'; result: '||result_value||'.'; end if;
end;

public.apply_authoring_action:
declare a public.analyses%rowtype; root public.resumes%rowtype; head public.canonical_resume_versions%rowtype;
  current_requirements public.job_requirement_versions%rowtype;
  prior public.authoring_events%rowtype; old_fact jsonb; patch jsonb; canonical_command jsonb; applied jsonb; confirmed jsonb;
  action_value text; op text; value_text text; question_kind_value text; label text; target uuid; undo_target uuid; line text; lines text[]; position_value int; event_id uuid:=gen_random_uuid(); result_value jsonb;
begin
  if p_user_id is null then return jsonb_build_object('status','not_found'); end if;
  perform private.lock_candidate_owners(array[p_user_id]);
  if not private.try_candidate_privacy_write(p_user_id) then return jsonb_build_object('status','not_found'); end if;
  if p_command is null or octet_length(p_command::text)>16384 or not private.evidence_keys(p_command,
    array['action','expectedVersionId','idempotencyKey','targetFactId','sectionId','value','questionKind','pattern','targetVersionId','confirmation','patch'])
    or p_request_id is null or char_length(p_request_id) not between 1 and 100 then raise exception 'Invalid authoring command' using errcode='22023'; end if;
  action_value:=p_command->>'action';
  if action_value not in ('edit','confirm','rename','clarify','accept','reject','undo','restore') then raise exception 'Invalid authoring action' using errcode='22023'; end if;
  select * into a from public.analyses where id=p_analysis_id and owner_id=p_user_id;
  if not found then return jsonb_build_object('status','not_found'); end if;
  select r.* into root from public.resumes r join public.resume_versions v on v.resume_id=r.id where v.id=a.resume_version_id for update of r;
  if root.id is null or root.owner_id<>p_user_id or root.status<>'active' or root.organization_id<>a.organization_id
    or not exists(select 1 from public.memberships where user_id=p_user_id and organization_id=root.organization_id)
    or not private.try_candidate_privacy_write(p_user_id) then return jsonb_build_object('status','not_found'); end if;
  select * into prior from public.authoring_events where analysis_id=a.id and idempotency_key=(p_command->>'idempotencyKey')::uuid;
  if found then if prior.command<>p_command then return jsonb_build_object('status','conflict'); end if;
    return prior.result||jsonb_build_object('idempotent',true); end if;
  -- Fresh legacy proposals may not bypass the typed protocol. Exact prior replay
  -- and the existing owner/privacy admission remain above this branch.
  if action_value in ('accept','reject') then
    perform 1 from public.analyses current_analysis where current_analysis.id=a.id
      and current_analysis.owner_id=p_user_id and current_analysis.organization_id=a.organization_id
      and current_analysis.resume_version_id=a.resume_version_id
      and current_analysis.job_id is not distinct from a.job_id for share;
    if not found then return jsonb_build_object('status','conflict'); end if;
    if a.job_id is not null then
      perform 1 from public.jobs current_job where current_job.id=a.job_id
        and current_job.owner_id=p_user_id and current_job.organization_id=a.organization_id for share;
      if not found then return jsonb_build_object('status','unavailable'); end if;
    end if;
    select * into current_requirements from public.job_requirement_versions
      where analysis_id=a.id and owner_id=p_user_id and organization_id=a.organization_id
      order by revision desc limit 1 for share;
    if found and (current_requirements.job_id is distinct from a.job_id
      or current_requirements.content->>'schemaVersion' is distinct from 'requirements/1.0.0') then
      return jsonb_build_object('status','unavailable');
    end if;
  end if;
  select v.* into head from public.canonical_resume_heads h join public.canonical_resume_versions v on v.id=h.version_id where h.resume_id=root.id;
  if head.id is null or head.source_resume_version_id<>a.resume_version_id or head.content->>'analysisId'<>a.id::text then return jsonb_build_object('status','not_found'); end if;
  if head.id is distinct from (p_command->>'expectedVersionId')::uuid then return jsonb_build_object('status','conflict'); end if;
  target:=(p_command->>'targetFactId')::uuid;
  if action_value in ('edit','confirm','clarify','accept','reject') then
    select value into old_fact from jsonb_array_elements(head.content->'facts') where value->>'id'=target::text;
    if old_fact is null then raise exception 'Unknown fact' using errcode='22023'; end if;
  end if;
  if action_value in ('accept','reject') then
    patch:=p_command->'patch';
    if not private.evidence_keys(patch,array['schemaVersion','id','producerVersion','baseVersionId','targetFactId','sectionId','entryId','sourceFactIds','affectedRuleIds','affectedRequirementIds','pattern','operations','rationale','confidence','clarificationNeeds','state'])
      or patch->>'schemaVersion'<>'suggestion-patch/1.0.0' or patch->>'producerVersion'<>'grounded-patterns/1.0.0'
      or patch->>'baseVersionId'<>head.id::text or patch->>'targetFactId'<>target::text
      or patch->'sourceFactIds'<>jsonb_build_array(target::text) or patch->'confidence'<>jsonb_build_object('kind','uncalibrated','value',null)
      or patch->>'pattern'<>p_command->>'pattern' or old_fact->>'type'<>'contribution'
      or not exists(select 1 from jsonb_array_elements(head.content->'sections') s cross join lateral jsonb_array_elements(s.value->'entries') e
        where s.value->>'id'=patch->>'sectionId' and e.value->>'id'=patch->>'entryId' and (e.value->'factIds' ? target::text
          or exists(select 1 from jsonb_array_elements(e.value->'bullets') b where b.value->'factIds' ? target::text))) then
      raise exception 'Invalid patch bindings' using errcode='22023'; end if;
    if action_value='accept' then
      if old_fact->>'state'<>'candidate_confirmed' or patch->>'state'<>'ready' or p_command->'confirmation'<>'true'::jsonb then raise exception 'Candidate review required' using errcode='22023'; end if;
      value_text:=private.authoring_pattern(old_fact->>'value',p_command->>'pattern');
      if patch->'operations'<>jsonb_build_array(jsonb_build_object('operation','replace_fact','factId',target::text,'value',value_text))
        or p_command->>'value'<>value_text then raise exception 'Unsupported generated fact' using errcode='22023'; end if;
    end if;
  end if;
  if action_value='reject' then
    if p_body is not null or p_confirmation_body is not null then raise exception 'Reject cannot mutate content' using errcode='22023'; end if;
    applied:=jsonb_build_object('status','applied','versionId',head.id,'revision',head.revision,'idempotent',false);
  else
    if action_value='rename' then op:='rename_section'; value_text:=p_command->>'value';
    elsif action_value='confirm' then op:='confirm';
    elsif action_value in ('undo','restore') then
      op:='rollback'; undo_target:=(p_command->>'targetVersionId')::uuid;
      if action_value='undo' then
        select base_version_id into undo_target from public.authoring_events where resume_id=root.id and result_version_id=head.id and base_version_id<>head.id order by created_at desc limit 1;
        undo_target:=coalesce(undo_target,head.parent_version_id);
        if undo_target is null or (p_command->>'targetVersionId')::uuid is distinct from undo_target then raise exception 'Invalid undo target' using errcode='22023'; end if;
      end if;
    else op:='edit'; if action_value='edit' then value_text:=p_command->>'value'; end if; end if;
    if action_value='clarify' then
      question_kind_value:=p_command->>'questionKind'; label:=initcap(question_kind_value)||': ';
      if question_kind_value not in ('result','measurement','scope','method','ownership') or old_fact->>'type'<>'contribution'
        or p_command->'confirmation'<>'true'::jsonb or char_length(p_command->>'value') not between 1 and 300
        or p_command->>'value'<>btrim(p_command->>'value') or (p_command->>'value') ~ '[[:cntrl:]]' then raise exception 'Invalid clarification' using errcode='22023'; end if;
      lines:=string_to_array(old_fact->>'value',E'\n'); value_text:=lines[1]; position_value:=0;
      foreach line in array lines loop position_value:=position_value+1; if position_value>1 and left(line,char_length(label))<>label then value_text:=value_text||E'\n'||line; end if; end loop;
      value_text:=value_text||E'\n'||label||(p_command->>'value');
    end if;
    canonical_command:=jsonb_build_object('operation',op,'expectedVersionId',head.id,'idempotencyKey',gen_random_uuid(),
      'factId',case when op in ('edit','confirm') then target else null end,'value',case when op in ('edit','rename_section') then value_text else null end,
      'targetVersionId',case when op='rollback' then undo_target else null end);
    if op='rename_section' then canonical_command:=canonical_command||jsonb_build_object('sectionId',p_command->'sectionId'); end if;
    applied:=public.save_canonical_version(p_user_id,a.resume_version_id,p_body,canonical_command,p_request_id);
    if applied->>'status'<>'applied' then return applied; end if;
    if action_value in ('clarify','accept') then
      canonical_command:=jsonb_build_object('operation','confirm','expectedVersionId',applied->'versionId','idempotencyKey',gen_random_uuid(),
        'factId',target,'value',null,'targetVersionId',null);
      confirmed:=public.save_canonical_version(p_user_id,a.resume_version_id,p_confirmation_body,canonical_command,p_request_id);
      if confirmed->>'status'<>'applied' then raise exception 'Confirmation transaction failed' using errcode='22023'; end if;
      applied:=confirmed;
    elsif p_confirmation_body is not null then raise exception 'Unexpected confirmation' using errcode='22023'; end if;
  end if;
  result_value:=applied||jsonb_build_object('eventId',event_id,'action',action_value);
  insert into public.authoring_events(id,analysis_id,resume_id,owner_id,organization_id,base_version_id,result_version_id,idempotency_key,action,command,result,retention_policy_id)
    values(event_id,a.id,root.id,p_user_id,root.organization_id,head.id,case when action_value='reject' then null else (applied->>'versionId')::uuid end,
      (p_command->>'idempotencyKey')::uuid,action_value,p_command,result_value,head.content->>'retentionPolicyId');
  insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
    values(root.organization_id,p_user_id,'authoring.'||action_value,'authoring_event',event_id,'success',p_request_id);
  return result_value;
end;

public.export_authoring_records:
declare snapshot jsonb;
begin
  select jsonb_build_object('authoringEvents',coalesce((select jsonb_agg(to_jsonb(e) order by created_at,id) from public.authoring_events e where owner_id=p_user_id),'[]'::jsonb)) into snapshot;
  if octet_length(snapshot::text)>33554432 then raise exception 'Authoring export exceeds manifest limit' using errcode='22023'; end if;
  return snapshot;
end;

public.export_resume_workspace_records:
declare snapshot jsonb;
begin
  snapshot:=public.export_canonical_records(p_user_id)||public.export_job_requirement_records(p_user_id)||public.export_authoring_records(p_user_id)
    ||private.entry_association_export_records(p_user_id)||private.entry_regroup_export_records(p_user_id);
  if octet_length(snapshot::text)>33554432 then raise exception 'Workspace export exceeds manifest limit' using errcode='22023'; end if;
  return snapshot;
end;

public.admit_paddle_ocr:
declare
  now_at timestamptz := pg_catalog.clock_timestamp();
  analysis_organization_id uuid;
  analysis_source_id uuid;
  version_organization_id uuid;
  version_checksum text;
  version_bytes integer;
  version_page_count integer;
  admission_id uuid;
  bucket_pages integer;
  bucket_bytes bigint;
begin
  if p_owner_id is null or p_analysis_id is null or p_source_id is null
     or p_source_sha256 is null
     or p_source_sha256 !~ '^[a-f0-9]{64}$'
     or p_page_numbers is null
     or pg_catalog.cardinality(p_page_numbers) not between 1 and 10
     or p_upload_bytes is null
     or p_upload_bytes < 1
     or p_upload_bytes > 104857600
     or p_max_pages is null or p_max_pages < 1 or p_max_pages > 1000
     or p_max_upload_bytes is null or p_max_upload_bytes < 1
     or p_max_upload_bytes > 107374182400
     or p_window_seconds is null or p_window_seconds < 60
     or p_window_seconds > 604800 then
    return null;
  end if;
  if exists (
    select 1 from unnest(p_page_numbers) as pages(page_number)
    where page_number is null or page_number < 1 or page_number > 20
  ) or (
    select count(distinct page_number)
    from unnest(p_page_numbers) as pages(page_number)
  ) <> pg_catalog.cardinality(p_page_numbers) then
    return null;
  end if;

  select analysis.organization_id, analysis.resume_version_id
    into analysis_organization_id, analysis_source_id
  from public.analyses analysis
  where analysis.id = p_analysis_id
    and analysis.owner_id = p_owner_id;
  if not found then return null; end if;

  select version.organization_id, version.checksum, version.bytes,
    version.page_count
    into version_organization_id, version_checksum, version_bytes,
      version_page_count
  from public.resume_versions version
  where version.id = p_source_id
    and version.owner_id = p_owner_id
    and version.id = analysis_source_id;
  if not found
     or version_organization_id is distinct from analysis_organization_id
     or version_checksum is distinct from p_source_sha256
     or p_upload_bytes <> version_bytes::bigint * pg_catalog.cardinality(p_page_numbers)
     or (
       version_page_count is not null
       and exists (
         select 1 from unnest(p_page_numbers) as pages(page_number)
         where page_number > version_page_count
       )
     ) then
    return null;
  end if;

  insert into public.paddle_ocr_admissions (
    organization_id, owner_id, analysis_id, source_id, source_sha256,
    upload_bytes
  )
  values (
    analysis_organization_id, p_owner_id, p_analysis_id, p_source_id,
    p_source_sha256, p_upload_bytes
  )
  on conflict (analysis_id, source_id, source_sha256) do nothing
  returning id into admission_id;
  if admission_id is null then return null; end if;

  insert into public.paddle_ocr_admission_pages (admission_id, page_number)
  select admission_id, page_number
  from unnest(p_page_numbers) as pages(page_number);

  insert into private.paddle_ocr_budget_buckets as bucket (
    owner_id, window_started_at, page_count, upload_bytes, updated_at
  )
  values (
    p_owner_id, now_at, pg_catalog.cardinality(p_page_numbers),
    p_upload_bytes, now_at
  )
  on conflict (owner_id) do update
  set window_started_at = case
        when bucket.window_started_at
          + pg_catalog.make_interval(secs => p_window_seconds) <= now_at
        then now_at
        else bucket.window_started_at
      end,
      page_count = case
        when bucket.window_started_at
          + pg_catalog.make_interval(secs => p_window_seconds) <= now_at
        then pg_catalog.cardinality(p_page_numbers)
        else bucket.page_count + pg_catalog.cardinality(p_page_numbers)
      end,
      upload_bytes = case
        when bucket.window_started_at
          + pg_catalog.make_interval(secs => p_window_seconds) <= now_at
        then p_upload_bytes
        else bucket.upload_bytes + p_upload_bytes
      end,
      updated_at = now_at
  returning page_count, upload_bytes into bucket_pages, bucket_bytes;

  if bucket_pages > p_max_pages or bucket_bytes > p_max_upload_bytes then
    raise exception 'PaddleOCR admission budget exceeded' using errcode = 'P0001';
  end if;
  return admission_id;
exception
  when sqlstate 'P0001' then
    return null;
end;

public.record_paddle_ocr_attempt:
begin
  if p_admission_id is null or p_page_number is null or p_state is null then
    return false;
  end if;
  if not exists (
    select 1 from public.paddle_ocr_admission_pages page
    where page.admission_id = p_admission_id
      and page.page_number = p_page_number
  ) then
    return false;
  end if;

  if p_state = 'submit_started' then
    if p_job_id is not null then return false; end if;
    if exists (
      select 1 from public.paddle_ocr_attempt_events event
      where event.admission_id = p_admission_id
        and event.page_number = p_page_number
    ) then
      return false;
    end if;
  elsif p_state = 'acknowledged' then
    if p_job_id is null
       or char_length(p_job_id) not between 1 and 256
       or p_job_id <> btrim(p_job_id)
       or p_job_id ~ '[\r\n]' then
      return false;
    end if;
    if not exists (
      select 1 from public.paddle_ocr_attempt_events event
      where event.admission_id = p_admission_id
        and event.page_number = p_page_number
        and event.state = 'submit_started'
    ) or exists (
      select 1 from public.paddle_ocr_attempt_events event
      where event.admission_id = p_admission_id
        and event.page_number = p_page_number
        and event.state in ('acknowledged', 'completed')
    ) then
      return false;
    end if;
  elsif p_state = 'completed' then
    if p_job_id is null
       or char_length(p_job_id) not between 1 and 256
       or p_job_id <> btrim(p_job_id)
       or p_job_id ~ '[\r\n]' then
      return false;
    end if;
    if not exists (
      select 1 from public.paddle_ocr_attempt_events event
      where event.admission_id = p_admission_id
        and event.page_number = p_page_number
        and event.state = 'acknowledged'
        and event.job_id = p_job_id
    ) or exists (
      select 1 from public.paddle_ocr_attempt_events event
      where event.admission_id = p_admission_id
        and event.page_number = p_page_number
        and event.state = 'completed'
    ) then
      return false;
    end if;
  else
    return false;
  end if;

  insert into public.paddle_ocr_attempt_events (
    admission_id, page_number, state, job_id
  )
  values (p_admission_id, p_page_number, p_state, p_job_id)
  on conflict (admission_id, page_number, state) do nothing;
  return found;
end;

private.correction_command_bytes:
declare result bytea := convert_to(E'C02OP1\n','UTF8'); atom text; token bytea; data bytea;
begin
  if p_atoms is null
    or (cardinality(p_atoms)>0 and (array_ndims(p_atoms)<>1 or array_lower(p_atoms,1)<>1)) then
    raise exception 'CORRECTION_CODEC_ATOMS' using errcode='22023';
  end if;
  if cardinality(p_atoms)>1024 then raise exception 'CORRECTION_CODEC_LIMIT' using errcode='22023'; end if;
  foreach atom in array p_atoms loop
    if atom is null then token:=convert_to('N;','UTF8');
    else
      if octet_length(atom)>65536 then raise exception 'CORRECTION_CODEC_LIMIT' using errcode='22023'; end if;
      data:=convert_to(atom,'UTF8');
      if octet_length(result)+char_length(octet_length(data)::text)+octet_length(data)+3>65536 then
        raise exception 'CORRECTION_CODEC_LIMIT' using errcode='22023';
      end if;
      token:=convert_to('T'||octet_length(data)::text||':','UTF8')||data||convert_to(';','UTF8');
    end if;
    if octet_length(result)+octet_length(token)>65536 then
      raise exception 'CORRECTION_CODEC_LIMIT' using errcode='22023';
    end if;
    result:=result||token;
  end loop;
  return result;
end;

private.candidate_owner_lock_keys:
declare keys bigint[];
begin
  if p_owners is null or cardinality(p_owners) not between 1 and 1024
    or array_ndims(p_owners)<>1 or array_lower(p_owners,1)<>1
    or exists(select 1 from unnest(p_owners) o where o is null) then
    raise exception 'CORRECTION_OWNER_BATCH' using errcode='22023';
  end if;
  select array_agg(k order by k) into keys from (
    select distinct ('x'||substr(encode(extensions.digest(
      convert_to('resumide:owner-write:v1:'||lower(o::text),'UTF8'),'sha256'),'hex'),1,16))::bit(64)::bigint k
    from unnest(p_owners) o
  ) derived;
  return keys;
end;

private.lock_candidate_owners:
declare k bigint;
begin
  foreach k in array private.candidate_owner_lock_keys(p_owners) loop
    perform pg_advisory_xact_lock(k);
  end loop;
end;

private.try_lock_candidate_owners:
declare k bigint;
begin
  foreach k in array private.candidate_owner_lock_keys(p_owners) loop
    if not pg_try_advisory_xact_lock(k) then return false; end if;
  end loop;
  return true;
end;

private.check_correction_ledger_integrit:
declare
  op public.candidate_correction_operations%rowtype;
  choice public.candidate_correction_assignments%rowtype;
  prior_choice public.candidate_correction_assignments%rowtype;
  applied public.candidate_correction_applications%rowtype;
  prior_applied public.candidate_correction_applications%rowtype;
  snap public.canonical_correction_snapshots%rowtype;
  link public.canonical_correction_snapshot_facts%rowtype;
  ver public.canonical_resume_versions%rowtype;
  fact public.resume_facts%rowtype;
  result_fact public.resume_facts%rowtype;
  event public.evidence_corrections%rowtype;
  evidence public.document_evidence_attempts%rowtype;
  previous_id uuid; previous_revision integer; child_id uuid;
  n integer; offset_count integer; i integer; matched integer;
  section jsonb; entry jsonb; bullet jsonb;
begin
  if tg_table_name='candidate_correction_operations' then
    select * into op from public.candidate_correction_operations where id=new.id;
    if not found then return null; end if; -- Transaction-local cascading erasure.
    n:=cardinality(op.selected_assignment_ids);
    select count(*) into matched from public.candidate_correction_assignments a
      where a.id=any(op.selected_assignment_ids)
        and (a.owner_id,a.organization_id,a.resume_id,a.analysis_id,a.source_resume_version_id,a.attempt_id,a.input_sha256)
          =(op.owner_id,op.organization_id,op.resume_id,op.analysis_id,op.source_resume_version_id,op.attempt_id,op.input_sha256);
    if matched<>n then raise exception 'CORRECTION_SELECTION_SCOPE' using errcode='23514'; end if;
    if exists(select 1 from public.candidate_correction_assignments a where a.id=any(op.selected_assignment_ids)
      and a.mapping_mode='existing' and a.base_version_id is distinct from op.expected_canonical_version_id) then
      raise exception 'CORRECTION_SELECTION_BASE' using errcode='23514';
    end if;
    if op.expected_canonical_version_id is not null then
      select * into ver from public.canonical_resume_versions where id=op.expected_canonical_version_id;
      if ver.source_evidence_version_id is distinct from op.attempt_id then
        raise exception 'CORRECTION_HEAD_ATTEMPT' using errcode='23514';
      end if;
      previous_revision:=ver.revision;
    else previous_revision:=0; end if;
    previous_id:=op.expected_canonical_version_id;
    if op.kind='assign' then
      if op.result_assignment_revision<>op.expected_assignment_revision+n
        or op.result_revision is distinct from nullif(previous_revision,0)
        or exists(select 1 from public.candidate_correction_applications where operation_id=op.id) then
        raise exception 'CORRECTION_ASSIGN_RESULT' using errcode='23514';
      end if;
      for i in 1..n loop
        select * into choice from public.candidate_correction_assignments where id=op.selected_assignment_ids[i];
        if choice.operation_id<>op.id or choice.assignment_revision<>op.expected_assignment_revision+i then
          raise exception 'CORRECTION_ASSIGN_ORDER' using errcode='23514';
        end if;
      end loop;
    else
      offset_count:=case when op.initial_import_version_id is null then 0 else 1 end;
      if (op.expected_canonical_version_id is null)<>(op.initial_import_version_id is not null)
        or op.result_assignment_revision<>op.expected_assignment_revision
        or cardinality(op.child_version_ids)<>n+offset_count
        or (select count(*) from public.candidate_correction_applications where operation_id=op.id)<>n then
        raise exception 'CORRECTION_APPLY_RESULT' using errcode='23514';
      end if;
      for i in 1..cardinality(op.child_version_ids) loop
        child_id:=op.child_version_ids[i];
        select * into ver from public.canonical_resume_versions where id=child_id
          and resume_id=op.resume_id and source_resume_version_id=op.source_resume_version_id
          and owner_id=op.owner_id and organization_id=op.organization_id;
        if not found or ver.parent_version_id is distinct from previous_id or ver.revision<>previous_revision+1
          or ver.source_evidence_version_id is distinct from op.attempt_id
          or ver.content->>'analysisId' is distinct from op.analysis_id::text
          or ver.content->>'inputSha256' is distinct from op.input_sha256 then
          raise exception 'CORRECTION_CHILD_CHAIN' using errcode='23514';
        end if;
        if i>offset_count then
          select * into applied from public.candidate_correction_applications
            where operation_id=op.id and step_ordinal=i-offset_count;
          if not found or applied.result_version_id<>child_id
            or applied.base_version_id is distinct from previous_id
            or applied.assignment_id<>op.selected_assignment_ids[i-offset_count] then
            raise exception 'CORRECTION_CHILD_APPLICATION' using errcode='23514';
          end if;
        end if;
        previous_id:=child_id; previous_revision:=ver.revision;
      end loop;
      if op.result_version_id<>previous_id or op.result_revision<>previous_revision then
        raise exception 'CORRECTION_FINAL_RESULT' using errcode='23514';
      end if;
    end if;

  elsif tg_table_name='candidate_correction_assignments' then
    select * into choice from public.candidate_correction_assignments where id=new.id;
    if not found then return null; end if;
    select * into op from public.candidate_correction_operations where id=choice.operation_id;
    if op.kind<>'assign' or choice.target_model_version<>op.target_model_version
      or choice.expected_assignment_revision<>op.expected_assignment_revision
      or not(choice.id=any(op.selected_assignment_ids))
      or (choice.mapping_mode='existing' and choice.base_version_id is distinct from op.expected_canonical_version_id)
      or (choice.mapping_mode='imported_assertion' and op.expected_canonical_version_id is not null) then
      raise exception 'CORRECTION_ASSIGN_BINDING' using errcode='23514';
    end if;
    if choice.supersedes_assignment_id is not null then
      select * into prior_choice from public.candidate_correction_assignments where id=choice.supersedes_assignment_id;
      if prior_choice.correction_event_id<>choice.correction_event_id
        or prior_choice.assignment_revision>=choice.assignment_revision then
        raise exception 'CORRECTION_ASSIGN_SUPERSESSION' using errcode='23514';
      end if;
    end if;
    select * into evidence from public.document_evidence_attempts where id=choice.attempt_id;
    if jsonb_typeof(evidence.envelope->'assertions') is distinct from 'array' then
      raise exception 'CORRECTION_ASSERTIONS' using errcode='23514';
    end if;
    if choice.target_kind='observed_assertion' then
      select count(*) into matched from jsonb_array_elements(evidence.envelope->'assertions') a
        where a->>'id'=choice.assertion_id and a->>'field'=choice.field;
      if matched<>1 then raise exception 'CORRECTION_ASSERTION_BINDING' using errcode='23514'; end if;
    elsif exists(select 1 from jsonb_array_elements(evidence.envelope->'assertions') a where a->>'field'=choice.field) then
      raise exception 'CORRECTION_FIELD_OBSERVED' using errcode='23514';
    end if;
    if choice.mapping_mode='existing' then
      select * into fact from public.resume_facts where canonical_version_id=choice.base_version_id and id=choice.fact_id;
      select * into ver from public.canonical_resume_versions where id=choice.base_version_id;
      if fact.type<>choice.field then raise exception 'CORRECTION_FACT_TYPE' using errcode='23514'; end if;
      if choice.location_kind='contact' then
        if jsonb_typeof(ver.content->'contactFactIds') is distinct from 'array'
          or (ver.content->'contactFactIds' ? choice.fact_id::text) is not true then
          raise exception 'CORRECTION_CONTACT_LOCATION' using errcode='23514';
        end if;
      else
        select value into section from jsonb_array_elements(ver.content->'sections') where value->>'id'=choice.section_id::text;
        if section is null then raise exception 'CORRECTION_SECTION_LOCATION' using errcode='23514'; end if;
        if choice.location_kind='section' then
          if jsonb_typeof(section->'factIds') is distinct from 'array'
            or (section->'factIds' ? choice.fact_id::text) is not true then raise exception 'CORRECTION_SECTION_FACT' using errcode='23514'; end if;
        else
          select value into entry from jsonb_array_elements(section->'entries') where value->>'id'=choice.entry_id::text;
          if entry is null then raise exception 'CORRECTION_ENTRY_LOCATION' using errcode='23514'; end if;
          if choice.location_kind='entry' then
            if jsonb_typeof(entry->'factIds') is distinct from 'array'
              or (entry->'factIds' ? choice.fact_id::text) is not true then raise exception 'CORRECTION_ENTRY_FACT' using errcode='23514'; end if;
          elsif choice.location_kind='bullet' then
            select value into bullet from jsonb_array_elements(entry->'bullets') where value->>'id'=choice.bullet_id::text;
            if bullet is null or jsonb_typeof(bullet->'factIds') is distinct from 'array'
              or (bullet->'factIds' ? choice.fact_id::text) is not true then raise exception 'CORRECTION_BULLET_FACT' using errcode='23514'; end if;
          else raise exception 'CORRECTION_EXISTING_LOCATION' using errcode='23514';
          end if;
        end if;
      end if;
    end if;

  elsif tg_table_name='candidate_correction_applications' then
    select * into applied from public.candidate_correction_applications where id=new.id;
    if not found then return null; end if;
    select * into op from public.candidate_correction_operations where id=applied.operation_id;
    select * into choice from public.candidate_correction_assignments where id=applied.assignment_id;
    select * into event from public.evidence_corrections where id=choice.correction_event_id;
    select * into fact from public.resume_facts where canonical_version_id=applied.result_version_id and id=applied.result_fact_id;
    select * into ver from public.canonical_resume_versions where id=applied.result_version_id;
    if op.kind='assign' or not(applied.assignment_id=any(op.selected_assignment_ids))
      or ver.parent_version_id is distinct from applied.base_version_id
      or fact.type is distinct from choice.field or fact.value is distinct from event.value
      or fact.state is distinct from 'unconfirmed' or fact.sources is distinct from '[]'::jsonb
      or fact.confirmation is not null then
      raise exception 'CORRECTION_APPLICATION_FACT' using errcode='23514';
    end if;
    if applied.supersedes_application_id is not null then
      select * into prior_applied from public.candidate_correction_applications where id=applied.supersedes_application_id;
      select * into prior_choice from public.candidate_correction_assignments where id=prior_applied.assignment_id;
      if (prior_applied.resume_id,prior_applied.analysis_id,prior_applied.source_resume_version_id,prior_applied.attempt_id,prior_applied.input_sha256)
          is distinct from (applied.resume_id,applied.analysis_id,applied.source_resume_version_id,applied.attempt_id,applied.input_sha256)
        or prior_choice.correction_event_id<>choice.correction_event_id
        or (select revision from public.canonical_resume_versions where id=prior_applied.result_version_id)>=ver.revision then
        raise exception 'CORRECTION_APPLICATION_SUPERSESSION' using errcode='23514';
      end if;
    end if;

  elsif tg_table_name='canonical_correction_snapshots' then
    select * into snap from public.canonical_correction_snapshots where canonical_version_id=new.canonical_version_id;
    if not found then return null; end if;
    select * into ver from public.canonical_resume_versions where id=snap.canonical_version_id;
    if (snap.inherited_from_version_id is not null and ver.parent_version_id is distinct from snap.inherited_from_version_id)
      or (snap.origin_kind='raw_import' and (ver.parent_version_id is not null or ver.revision<>1))
      or (snap.origin_kind in ('raw_import','legacy_restore') and exists(
        select 1 from public.canonical_correction_snapshot_facts where canonical_version_id=snap.canonical_version_id)) then
      raise exception 'CORRECTION_SNAPSHOT_ORIGIN' using errcode='23514';
    end if;
    if snap.inherited_from_version_id is not null then
      select revision into previous_revision from public.canonical_resume_versions where id=snap.inherited_from_version_id;
      if ver.revision<>previous_revision+1 then raise exception 'CORRECTION_SNAPSHOT_PARENT_REVISION' using errcode='23514'; end if;
    end if;
    if snap.restored_from_version_id is not null then
      select revision into previous_revision from public.canonical_resume_versions where id=snap.restored_from_version_id;
      if previous_revision>=ver.revision
        or (snap.origin_kind='legacy_restore' and exists(select 1 from public.canonical_correction_snapshots where canonical_version_id=snap.restored_from_version_id))
        or (snap.origin_kind='restore' and not exists(select 1 from public.canonical_correction_snapshots where canonical_version_id=snap.restored_from_version_id)) then
        raise exception 'CORRECTION_SNAPSHOT_RESTORE' using errcode='23514';
      end if;
    end if;
    if snap.source_operation_id is not null then
      select * into op from public.candidate_correction_operations where id=snap.source_operation_id;
      if (snap.origin_kind='raw_import' and op.initial_import_version_id is distinct from snap.canonical_version_id)
        or (snap.origin_kind='correction' and not(snap.canonical_version_id=any(op.child_version_ids))) then
        raise exception 'CORRECTION_SNAPSHOT_OPERATION' using errcode='23514';
      end if;
    end if;

  elsif tg_table_name='canonical_correction_snapshot_facts' then
    select * into link from public.canonical_correction_snapshot_facts
      where canonical_version_id=new.canonical_version_id and fact_id=new.fact_id;
    if not found then return null; end if;
    select * into snap from public.canonical_correction_snapshots where canonical_version_id=link.canonical_version_id;
    select * into applied from public.candidate_correction_applications where id=link.application_id;
    select * into ver from public.canonical_resume_versions where id=link.canonical_version_id;
    select * into fact from public.resume_facts where canonical_version_id=link.canonical_version_id and id=link.fact_id;
    select * into result_fact from public.resume_facts where canonical_version_id=applied.result_version_id and id=applied.result_fact_id;
    if (snap.resume_id,snap.source_resume_version_id) is distinct from (applied.resume_id,applied.source_resume_version_id)
      or ver.source_evidence_version_id is distinct from applied.attempt_id
      or ver.content->>'analysisId' is distinct from applied.analysis_id::text
      or ver.content->>'inputSha256' is distinct from applied.input_sha256
      or link.fact_id<>applied.result_fact_id or fact.type is distinct from result_fact.type or fact.value is distinct from result_fact.value then
      raise exception 'CORRECTION_SNAPSHOT_FACT' using errcode='23514';
    end if;
    if snap.origin_kind='correction' and applied.result_version_id=link.canonical_version_id
      and applied.operation_id=snap.source_operation_id then return null; end if;
    previous_id:=case when snap.origin_kind in ('inherited','correction') then snap.inherited_from_version_id
      when snap.origin_kind='restore' then snap.restored_from_version_id else null end;
    if previous_id is null or not exists(select 1 from public.canonical_correction_snapshot_facts p
      where p.canonical_version_id=previous_id and p.fact_id=link.fact_id and p.application_id=link.application_id
        and p.owner_id=link.owner_id and p.organization_id=link.organization_id) then
      raise exception 'CORRECTION_SNAPSHOT_LINEAGE' using errcode='23514';
    end if;
  end if;
  return null;
end;

private.ai_budget_immutable:
begin
  raise exception 'Immutable technical AI budget record' using errcode = '23514';
end;

private.ai_budget_projection_identity:
begin
  if tg_table_name = 'ai_budget_pools' then
    if row(new.organization_id, new.period, new.pool_policy_version, new.token_limit, new.cost_limit_microusd, new.created_at)
      is distinct from row(old.organization_id, old.period, old.pool_policy_version, old.token_limit, old.cost_limit_microusd, old.created_at) then
      raise exception 'Immutable technical AI budget identity' using errcode = '23514';
    end if;
  elsif row(new.id, new.operation_id, new.organization_id, new.ordinal, new.period, new.reserved_cost_microusd, new.created_at)
    is distinct from row(old.id, old.operation_id, old.organization_id, old.ordinal, old.period, old.reserved_cost_microusd, old.created_at) then
    raise exception 'Immutable technical AI budget identity' using errcode = '23514';
  end if;
  return new;
end;

private.ai_budget_binding_sha256:
declare
  atom text;
  bytes bytea := convert_to(E'AIBUDGET1\n', 'UTF8');
begin
  foreach atom in array array[p_user_id::text, p_organization_id::text, p_request->>'operationId', p_request->>'surface',
    p_request->>'payloadSha256', p_request->>'model', p_request->>'promptPolicyVersion', p_request->>'policyVersion',
    p_request->>'reservedInputTokens', p_request->>'reservedOutputTokens'] loop
    if atom is null then raise exception 'Invalid technical AI budget binding' using errcode = '22023'; end if;
    bytes := bytes || convert_to('T' || octet_length(convert_to(atom, 'UTF8'))::text || ':' || atom || ';', 'UTF8');
  end loop;
  return encode(extensions.digest(bytes, 'sha256'), 'hex');
end;

private.ai_budget_request_valid:
declare
  keys text[];
  expected text[] := array['operationId','attemptId','attemptOrdinal','surface','payloadSha256','model',
    'promptPolicyVersion','policyVersion','reservedInputTokens','reservedOutputTokens'];
  key text;
begin
  if p_request is null or jsonb_typeof(p_request) is distinct from 'object' or octet_length(p_request::text) > 8192 then return false; end if;
  if p_action = 'settle' then expected := expected || array['usage'];
  elsif p_action = 'reconcile' then expected := expected || array['usage','reconciliationId','operatorId','evidenceSha256'];
  elsif p_action not in ('reserve','claim_dispatch','release','mark_unknown') then return false;
  end if;
  select array_agg(k order by k) into keys from jsonb_object_keys(p_request) k;
  if keys is distinct from (select array_agg(k order by k) from unnest(expected) k) then return false; end if;
  foreach key in array array['operationId','attemptId'] || case when p_action='reconcile' then array['reconciliationId','operatorId'] else '{}'::text[] end loop
    if jsonb_typeof(p_request->key) is distinct from 'string' or (p_request->>key) !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then return false; end if;
  end loop;
  foreach key in array array['payloadSha256'] || case when p_action='reconcile' then array['evidenceSha256'] else '{}'::text[] end loop
    if jsonb_typeof(p_request->key) is distinct from 'string' or (p_request->>key) !~ '^[a-f0-9]{64}$' then return false; end if;
  end loop;
  foreach key in array array['model','promptPolicyVersion','policyVersion'] loop
    if jsonb_typeof(p_request->key) is distinct from 'string' or (p_request->>key) !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}$' then return false; end if;
  end loop;
  if jsonb_typeof(p_request->'surface') is distinct from 'string' or (p_request->>'surface') not in ('qualitative','rewrite','build')
    or jsonb_typeof(p_request->'attemptOrdinal') is distinct from 'number'
    or (p_request->>'attemptOrdinal')::numeric not in (1,2,3) then return false; end if;
  foreach key in array array['reservedInputTokens','reservedOutputTokens'] loop
    if jsonb_typeof(p_request->key) is distinct from 'string' or (p_request->>key) !~ '^[1-9][0-9]{0,15}$' then return false; end if;
    if (p_request->>key)::numeric > 9007199254740991 then return false; end if;
  end loop;
  if p_action in ('settle','reconcile') then
    if jsonb_typeof(p_request->'usage') is distinct from 'object' then return false; end if;
    select array_agg(k order by k) into keys from jsonb_object_keys(p_request->'usage') k;
    if keys is distinct from array['inputTokens','outputTokens'] then return false; end if;
    foreach key in array array['inputTokens','outputTokens'] loop
      if jsonb_typeof(p_request->'usage'->key) is distinct from 'string' or (p_request->'usage'->>key) !~ '^(0|[1-9][0-9]{0,15})$' then return false; end if;
      if (p_request->'usage'->>key)::numeric > 9007199254740991 then return false; end if;
    end loop;
  end if;
  return true;
end;

private.ai_budget_transition:
declare
  organization_owner uuid;
  operation_row private.ai_budget_operations%rowtype;
  attempt_row private.ai_budget_attempts%rowtype;
  pool_row private.ai_budget_pools%rowtype;
  policy_row private.ai_budget_policies%rowtype;
  opening_row private.ai_budget_period_openings%rowtype;
  event_row private.ai_budget_events%rowtype;
  op_id uuid; attempt_id uuid; ordinal integer; binding text; period_start date;
  reserved_input numeric; reserved_output numeric; reserved_total numeric; reserve_cost numeric;
  actual_input numeric; actual_output numeric; actual_cost numeric;
  previous_ordinal integer; operation_exists boolean; attempt_exists boolean;
begin
  if p_user_id is null or p_organization_id is null or not private.ai_budget_request_valid(p_request,p_action) then
    return private.ai_budget_denied('AI_BUDGET_INVALID');
  end if;
  select owner_id into organization_owner from public.organizations where id=p_organization_id for update;
  if not found then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  if p_action in ('reserve','claim_dispatch') then
    if organization_owner<>p_user_id then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
    perform 1 from public.memberships where organization_id=p_organization_id and user_id=p_user_id and role in ('owner','admin','member') for update;
    if not found or not private.try_candidate_privacy_write(p_user_id) then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  elsif p_action='reconcile' then
    perform 1 from private.ai_budget_reconciliation_operators where organization_id=p_organization_id
      and operator_id=(p_request->>'operatorId')::uuid and enabled for share;
    if not found then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  end if;
  op_id:=(p_request->>'operationId')::uuid;
  attempt_id:=(p_request->>'attemptId')::uuid;
  ordinal:=(p_request->>'attemptOrdinal')::numeric::integer;
  binding:=private.ai_budget_binding_sha256(p_user_id,p_organization_id,p_request);
  reserved_input:=(p_request->>'reservedInputTokens')::numeric;
  reserved_output:=(p_request->>'reservedOutputTokens')::numeric;
  reserved_total:=reserved_input+reserved_output;

  select * into operation_row from private.ai_budget_operations where id=op_id and organization_id=p_organization_id and user_id=p_user_id for update;
  operation_exists:=found;
  if not operation_exists and exists(select 1 from private.ai_budget_operations where id=op_id) then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  if operation_exists and operation_row.binding_sha256<>binding then return private.ai_budget_denied('AI_BUDGET_CONFLICT'); end if;
  select * into attempt_row from private.ai_budget_attempts where id=attempt_id and organization_id=p_organization_id for update;
  attempt_exists:=found;
  if not attempt_exists and exists(select 1 from private.ai_budget_attempts where id=attempt_id) then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  if attempt_exists and (attempt_row.operation_id<>op_id or attempt_row.ordinal<>ordinal) then return private.ai_budget_denied('AI_BUDGET_CONFLICT'); end if;

  if p_action='reserve' then
    if attempt_exists then return private.ai_budget_receipt(attempt_id,true,false); end if;
    if private.ai_budget_blocked(p_organization_id) then return private.ai_budget_denied('AI_BUDGET_BLOCKED'); end if;
    if not operation_exists then
      select * into policy_row from private.ai_budget_policies where version=p_request->>'policyVersion' and model=p_request->>'model' and enabled;
      if not found then return private.ai_budget_denied('AI_BUDGET_DISABLED'); end if;
      if ordinal<>1 then return private.ai_budget_denied('AI_BUDGET_CONFLICT'); end if;
    else
      if ordinal>operation_row.attempt_limit then return private.ai_budget_denied('AI_BUDGET_EXHAUSTED'); end if;
      select coalesce(max(a.ordinal),0) into previous_ordinal from private.ai_budget_attempts a where a.operation_id=op_id;
      if ordinal<>previous_ordinal+1 then return private.ai_budget_denied('AI_BUDGET_CONFLICT'); end if;
      if exists(select 1 from private.ai_budget_attempts a where a.operation_id=op_id and a.state in ('reserved','dispatched')) then
        return private.ai_budget_denied('AI_BUDGET_STATE');
      end if;
      select * into policy_row from private.ai_budget_policies where version=operation_row.policy_version;
    end if;
    period_start:=date_trunc('month',clock_timestamp() at time zone 'UTC')::date;
    select * into pool_row from private.ai_budget_pools where organization_id=p_organization_id and period=period_start for update;
    if not found then
      select * into opening_row from private.ai_budget_period_openings where organization_id=p_organization_id and period=period_start;
      if not found then return private.ai_budget_denied('AI_BUDGET_DISABLED'); end if;
      insert into private.ai_budget_pools(organization_id,period,pool_policy_version,token_limit,cost_limit_microusd,
        reserved_tokens,reserved_cost_microusd,spent_tokens,spent_cost_microusd)
      select p_organization_id,period_start,p.version,p.monthly_token_limit,p.monthly_cost_limit_microusd,
        0,0,opening_row.opening_spent_tokens,opening_row.opening_spent_cost_microusd
      from private.ai_budget_policies p where p.version=opening_row.pool_policy_version and p.enabled
      returning * into pool_row;
      if not found then return private.ai_budget_denied('AI_BUDGET_DISABLED'); end if;
    end if;
    reserve_cost:=private.ai_budget_cost(reserved_input,reserved_output,policy_row.input_microusd_per_million,policy_row.output_microusd_per_million);
    if private.ai_budget_blocked(p_organization_id) then return private.ai_budget_denied('AI_BUDGET_BLOCKED'); end if;
    if pool_row.spent_tokens+pool_row.reserved_tokens+reserved_total>pool_row.token_limit
      or pool_row.spent_cost_microusd+pool_row.reserved_cost_microusd+reserve_cost>pool_row.cost_limit_microusd then
      return private.ai_budget_denied('AI_BUDGET_EXHAUSTED');
    end if;
    if not operation_exists then
      insert into private.ai_budget_operations(id,organization_id,user_id,surface,payload_sha256,model,prompt_policy_version,policy_version,
        reserved_input_tokens,reserved_output_tokens,input_microusd_per_million,output_microusd_per_million,attempt_limit,binding_sha256)
      values(op_id,p_organization_id,p_user_id,p_request->>'surface',p_request->>'payloadSha256',p_request->>'model',
        p_request->>'promptPolicyVersion',policy_row.version,reserved_input,reserved_output,policy_row.input_microusd_per_million,
        policy_row.output_microusd_per_million,policy_row.max_attempts,binding);
    end if;
    insert into private.ai_budget_attempts(id,operation_id,organization_id,ordinal,period,state,reserved_cost_microusd)
      values(attempt_id,op_id,p_organization_id,ordinal,period_start,'reserved',reserve_cost);
    update private.ai_budget_pools set reserved_tokens=reserved_tokens+reserved_total,reserved_cost_microusd=reserved_cost_microusd+reserve_cost
      where organization_id=p_organization_id and period=period_start;
    insert into private.ai_budget_events(attempt_id,kind) values(attempt_id,'reserve');
    return private.ai_budget_receipt(attempt_id,false,false);
  end if;

  if not operation_exists or not attempt_exists then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  select * into pool_row from private.ai_budget_pools where organization_id=p_organization_id and period=attempt_row.period for update;
  if p_action='claim_dispatch' then
    if attempt_row.state in ('dispatched','held_unknown','settled') then return private.ai_budget_receipt(attempt_id,true,false); end if;
    if attempt_row.state<>'reserved' then return private.ai_budget_denied('AI_BUDGET_STATE'); end if;
    if private.ai_budget_blocked(p_organization_id) then return private.ai_budget_denied('AI_BUDGET_BLOCKED'); end if;
    update private.ai_budget_attempts set state='dispatched',updated_at=clock_timestamp() where id=attempt_id;
    insert into private.ai_budget_events(attempt_id,kind) values(attempt_id,'dispatch');
    return private.ai_budget_receipt(attempt_id,false,true);
  elsif p_action='release' then
    if attempt_row.state='released' then return private.ai_budget_receipt(attempt_id,true,false); end if;
    if attempt_row.state<>'reserved' then return private.ai_budget_denied('AI_BUDGET_STATE'); end if;
    update private.ai_budget_pools set reserved_tokens=reserved_tokens-reserved_total,reserved_cost_microusd=reserved_cost_microusd-attempt_row.reserved_cost_microusd
      where organization_id=p_organization_id and period=attempt_row.period;
    update private.ai_budget_attempts set state='released',updated_at=clock_timestamp() where id=attempt_id;
    insert into private.ai_budget_events(attempt_id,kind) values(attempt_id,'release');
    return private.ai_budget_receipt(attempt_id,false,false);
  elsif p_action='mark_unknown' then
    if attempt_row.state='held_unknown' then return private.ai_budget_receipt(attempt_id,true,false); end if;
    if attempt_row.state<>'dispatched' then return private.ai_budget_denied('AI_BUDGET_STATE'); end if;
    update private.ai_budget_attempts set state='held_unknown',updated_at=clock_timestamp() where id=attempt_id;
    insert into private.ai_budget_events(attempt_id,kind) values(attempt_id,'unknown');
    return private.ai_budget_receipt(attempt_id,false,false);
  end if;

  actual_input:=(p_request->'usage'->>'inputTokens')::numeric;
  actual_output:=(p_request->'usage'->>'outputTokens')::numeric;
  actual_cost:=private.ai_budget_cost(actual_input,actual_output,operation_row.input_microusd_per_million,operation_row.output_microusd_per_million);
  if p_action='settle' then
    if attempt_row.state='settled' then
      if attempt_row.actual_input_tokens<>actual_input or attempt_row.actual_output_tokens<>actual_output then return private.ai_budget_denied('AI_BUDGET_CONFLICT'); end if;
      return private.ai_budget_receipt(attempt_id,true,false);
    end if;
    if attempt_row.state<>'dispatched' then return private.ai_budget_denied('AI_BUDGET_STATE'); end if;
  else
    select * into event_row from private.ai_budget_events where reconciliation_id=(p_request->>'reconciliationId')::uuid;
    if found then
      if event_row.attempt_id<>attempt_id or event_row.operator_id<>(p_request->>'operatorId')::uuid
        or event_row.evidence_sha256<>p_request->>'evidenceSha256' or event_row.input_tokens<>actual_input or event_row.output_tokens<>actual_output then
        return private.ai_budget_denied('AI_BUDGET_CONFLICT');
      end if;
      return private.ai_budget_receipt(attempt_id,true,false);
    end if;
    if attempt_row.state='settled' then
      if attempt_row.actual_input_tokens<>actual_input or attempt_row.actual_output_tokens<>actual_output then
        return private.ai_budget_denied('AI_BUDGET_CONFLICT');
      end if;
      if not (actual_input>operation_row.reserved_input_tokens or actual_output>operation_row.reserved_output_tokens
        or actual_cost>attempt_row.reserved_cost_microusd) then return private.ai_budget_denied('AI_BUDGET_STATE'); end if;
      if exists(select 1 from private.ai_budget_events e where e.attempt_id=attempt_row.id and e.kind='reconcile') then
        return private.ai_budget_denied('AI_BUDGET_CONFLICT');
      end if;
      -- Audit an already charged overrun. Identical observed usage only: this
      -- appends authority/evidence, never refunds or charges the attempt again.
      insert into private.ai_budget_events(attempt_id,kind,input_tokens,output_tokens,cost_microusd,reconciliation_id,operator_id,evidence_sha256)
        values(attempt_id,'reconcile',actual_input,actual_output,actual_cost,(p_request->>'reconciliationId')::uuid,
          (p_request->>'operatorId')::uuid,p_request->>'evidenceSha256');
      return private.ai_budget_receipt(attempt_id,false,false);
    end if;
    if attempt_row.state<>'held_unknown' then return private.ai_budget_denied('AI_BUDGET_STATE'); end if;
  end if;
  update private.ai_budget_pools set reserved_tokens=reserved_tokens-reserved_total,reserved_cost_microusd=reserved_cost_microusd-attempt_row.reserved_cost_microusd,
    spent_tokens=spent_tokens+actual_input+actual_output,spent_cost_microusd=spent_cost_microusd+actual_cost
    where organization_id=p_organization_id and period=attempt_row.period;
  update private.ai_budget_attempts set state='settled',actual_input_tokens=actual_input,actual_output_tokens=actual_output,
    actual_cost_microusd=actual_cost,updated_at=clock_timestamp() where id=attempt_id;
  insert into private.ai_budget_events(attempt_id,kind,input_tokens,output_tokens,cost_microusd,reconciliation_id,operator_id,evidence_sha256)
    values(attempt_id,case when p_action='settle' then 'settle' else 'reconcile' end,actual_input,actual_output,actual_cost,
      case when p_action='reconcile' then (p_request->>'reconciliationId')::uuid end,
      case when p_action='reconcile' then (p_request->>'operatorId')::uuid end,
      case when p_action='reconcile' then p_request->>'evidenceSha256' end);
  return private.ai_budget_receipt(attempt_id,false,false);
exception
  when unique_violation then return private.ai_budget_denied('AI_BUDGET_CONFLICT');
  when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return private.ai_budget_denied('AI_BUDGET_INVALID');
  when others then return private.ai_budget_denied('AI_BUDGET_UNAVAILABLE');
end;

public.ai_budget_reserve_next:
declare
  organization_owner uuid;
  chosen_ordinal integer;
begin
  if not private.ai_budget_source_generic_allowed(p_user_id,p_request) then return private.ai_budget_denied('AI_BUDGET_DENIED');end if;
  if p_user_id is null or p_organization_id is null or jsonb_typeof(p_request) is distinct from 'object'
    or p_request ? 'attemptOrdinal'
    or not private.ai_budget_request_valid(p_request||'{"attemptOrdinal":1}'::jsonb,'reserve') then
    return private.ai_budget_denied('AI_BUDGET_INVALID');
  end if;
  select owner_id into organization_owner from public.organizations where id=p_organization_id for update;
  if not found or organization_owner<>p_user_id then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;
  perform 1 from public.memberships where organization_id=p_organization_id and user_id=p_user_id
    and role in ('owner','admin','member') for update;
  if not found or not private.try_candidate_privacy_write(p_user_id) then return private.ai_budget_denied('AI_BUDGET_DENIED'); end if;

  select a.ordinal into chosen_ordinal from private.ai_budget_attempts a
    where a.id=(p_request->>'attemptId')::uuid and a.organization_id=p_organization_id;
  if not found then
    select coalesce(max(a.ordinal),0)+1 into chosen_ordinal from private.ai_budget_attempts a
      join private.ai_budget_operations o on o.id=a.operation_id
      where o.id=(p_request->>'operationId')::uuid and o.organization_id=p_organization_id and o.user_id=p_user_id;
  end if;
  if chosen_ordinal>3 then return private.ai_budget_denied('AI_BUDGET_EXHAUSTED'); end if;
  return private.ai_budget_transition(p_user_id,p_organization_id,
    p_request||jsonb_build_object('attemptOrdinal',chosen_ordinal),'reserve');
exception
  when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return private.ai_budget_denied('AI_BUDGET_INVALID');
  when others then return private.ai_budget_denied('AI_BUDGET_UNAVAILABLE');
end;

private.analysis_admission_identity:
begin
  if tg_op='DELETE' then raise exception 'Immutable admission history' using errcode='23514'; end if;
  if tg_table_name='analysis_admission_operations' then
    if row(new.id,new.organization_id,new.owner_id,new.idempotency_key,new.binding_sha256,new.created_at)
      is distinct from row(old.id,old.organization_id,old.owner_id,old.idempotency_key,old.binding_sha256,old.created_at)
      or old.adopted_upload_id is not null then raise exception 'Immutable admission identity' using errcode='23514'; end if;
  else
    if row(new.id,new.operation_id,new.analysis_id,new.resume_id,new.version_id,new.job_id,new.storage_key,new.created_at)
      is distinct from row(old.id,old.operation_id,old.analysis_id,old.resume_id,old.version_id,old.job_id,old.storage_key,old.created_at)
      or not ((old.state='prepared' and new.state in ('adopted','cleanup_pending'))
        or (old.state='cleanup_pending' and new.state='cleaned')) then
      raise exception 'Invalid admission transition' using errcode='23514';
    end if;
  end if;
  return new;
end;

private.analysis_admission_hash:
declare atom text; bytes bytea:=convert_to(E'ANALYSIS-ADMISSION1\n','UTF8');
begin
  foreach atom in array array[p_request->>'checksum',p_request->>'bytes',p_request->>'titleSha256',
    p_request->>'jobSha256',p_request->>'nameSha256',p_request->>'requestPolicySha256',
    p_request->>'policyVersion',p_request->>'consentPolicyVersion'] loop
    if atom is null then raise exception 'Invalid admission binding' using errcode='22023'; end if;
    bytes:=bytes||convert_to('T'||octet_length(convert_to(atom,'UTF8'))::text||':'||atom||';','UTF8');
  end loop;
  return encode(extensions.digest(bytes,'sha256'),'hex');
end;

private.analysis_admission_request_valid:
declare keys text[]; expected text[]:=array['idempotencyKey','uploadId','analysisId','resumeId','versionId','jobId',
  'checksum','bytes','titleSha256','jobSha256','nameSha256','requestPolicySha256','policyVersion','consentPolicyVersion','bindingSha256']; key text;
begin
  if p_request is null or jsonb_typeof(p_request) is distinct from 'object' or octet_length(p_request::text)>2097152 then return false; end if;
  if p_final then expected:=expected||array['jobTitle','jobDescription','displayName','requestId']; end if;
  select array_agg(k order by k) into keys from jsonb_object_keys(p_request) k;
  if keys is distinct from (select array_agg(k order by k) from unnest(expected) k) then return false; end if;
  foreach key in array array['idempotencyKey','uploadId','analysisId','resumeId','versionId','jobId'] loop
    if jsonb_typeof(p_request->key) is distinct from 'string' or (p_request->>key) !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then return false; end if;
  end loop;
  foreach key in array array['checksum','titleSha256','jobSha256','nameSha256','requestPolicySha256','bindingSha256'] loop
    if jsonb_typeof(p_request->key) is distinct from 'string' or (p_request->>key) !~ '^[a-f0-9]{64}$' then return false; end if;
  end loop;
  if p_request->>'policyVersion' is distinct from 'analysis-admission/1.0.0'
    or p_request->>'consentPolicyVersion' is distinct from 'candidate-ai-v1'
    or jsonb_typeof(p_request->'bytes') is distinct from 'number'
    or (p_request->>'bytes') !~ '^[1-9][0-9]{0,7}$' then return false; end if;
  if (p_request->>'bytes')::integer>10485760 or private.analysis_admission_hash(p_request) is distinct from p_request->>'bindingSha256' then return false; end if;
  if p_final then
    foreach key in array array['jobTitle','jobDescription','displayName','requestId'] loop
      if jsonb_typeof(p_request->key) is distinct from 'string' then return false; end if;
    end loop;
    if encode(extensions.digest(convert_to(p_request->>'jobTitle','UTF8'),'sha256'),'hex') is distinct from p_request->>'titleSha256'
      or encode(extensions.digest(convert_to(p_request->>'jobDescription','UTF8'),'sha256'),'hex') is distinct from p_request->>'jobSha256'
      or encode(extensions.digest(convert_to(p_request->>'displayName','UTF8'),'sha256'),'hex') is distinct from p_request->>'nameSha256'
      or (p_request->>'requestId') !~ '^[A-Za-z0-9._:-]{8,128}$' then return false; end if;
  end if;
  return true;
end;

private.analysis_admission_authorized:
begin
  if p_user_id is null or p_organization_id is null then return false; end if;
  perform 1 from public.organizations where id=p_organization_id and owner_id=p_user_id for update;
  if not found then return false; end if;
  perform 1 from public.memberships where organization_id=p_organization_id and user_id=p_user_id and role='owner' for share;
  if not found then return false; end if;
  perform 1 from public.consents where organization_id=p_organization_id and user_id=p_user_id
    and purpose='qualitative_ai' and policy_version='candidate-ai-v1' for share;
  if not found then return false; end if;
  return private.try_candidate_privacy_write(p_user_id);
end;

public.prepare_analysis_admission:
declare o private.analysis_admission_operations%rowtype; path text;
begin
  if not private.analysis_admission_request_valid(p_request,false) then return private.analysis_admission_denied('ADMISSION_INVALID'); end if;
  if not private.analysis_admission_authorized(p_user_id,p_organization_id) then return private.analysis_admission_denied('ADMISSION_DENIED'); end if;
  select * into o from private.analysis_admission_operations where organization_id=p_organization_id and owner_id=p_user_id
    and idempotency_key=(p_request->>'idempotencyKey')::uuid for update;
  if found then
    if o.binding_sha256 is distinct from p_request->>'bindingSha256' then return private.analysis_admission_denied('ADMISSION_CONFLICT'); end if;
    if o.adopted_upload_id is not null then return private.analysis_admission_replay(o.id,p_request); end if;
  else
    insert into private.analysis_admission_operations(organization_id,owner_id,idempotency_key,binding_sha256)
      values(p_organization_id,p_user_id,(p_request->>'idempotencyKey')::uuid,p_request->>'bindingSha256') returning * into o;
  end if;
  path:='organizations/'||p_organization_id::text||'/resumes/'||(p_request->>'resumeId')::uuid::text||'/versions/'||(p_request->>'versionId')::uuid::text||'.pdf';
  insert into private.analysis_admission_uploads(id,operation_id,analysis_id,resume_id,version_id,job_id,storage_key)
    values((p_request->>'uploadId')::uuid,o.id,(p_request->>'analysisId')::uuid,(p_request->>'resumeId')::uuid,
      (p_request->>'versionId')::uuid,(p_request->>'jobId')::uuid,path);
  return jsonb_build_object('schemaVersion','analysis-admission/1.0.0','kind','upload','operationId',o.id,'bindingSha256',o.binding_sha256,
    'uploadId',(p_request->>'uploadId')::uuid,'analysisId',(p_request->>'analysisId')::uuid,'resumeId',(p_request->>'resumeId')::uuid,
    'versionId',(p_request->>'versionId')::uuid,'jobId',(p_request->>'jobId')::uuid,'storageKey',path);
exception when unique_violation then return private.analysis_admission_denied('ADMISSION_CONFLICT');
  when insufficient_privilege then return private.analysis_admission_denied('ADMISSION_DENIED');
  when others then return private.analysis_admission_denied('ADMISSION_UNAVAILABLE');
end;

public.finalize_analysis_admission:
declare o private.analysis_admission_operations%rowtype; u private.analysis_admission_uploads%rowtype; result jsonb; created boolean:=false; cleanup boolean:=false;
begin
  if not private.analysis_admission_request_valid(p_request,true) then return private.analysis_admission_denied('ADMISSION_INVALID'); end if;
  if not private.analysis_admission_authorized(p_user_id,p_organization_id) then return private.analysis_admission_denied('ADMISSION_DENIED'); end if;
  select * into o from private.analysis_admission_operations where id=p_operation_id and owner_id=p_user_id and organization_id=p_organization_id for update;
  if not found then return private.analysis_admission_denied('ADMISSION_DENIED'); end if;
  select * into u from private.analysis_admission_uploads where id=p_upload_id and operation_id=o.id for update;
  if not found then return private.analysis_admission_denied('ADMISSION_DENIED'); end if;
  if o.binding_sha256 is distinct from p_request->>'bindingSha256' or o.idempotency_key is distinct from (p_request->>'idempotencyKey')::uuid
    or u.id is distinct from (p_request->>'uploadId')::uuid or u.analysis_id is distinct from (p_request->>'analysisId')::uuid
    or u.resume_id is distinct from (p_request->>'resumeId')::uuid or u.version_id is distinct from (p_request->>'versionId')::uuid
    or u.job_id is distinct from (p_request->>'jobId')::uuid then return private.analysis_admission_denied('ADMISSION_CONFLICT'); end if;
  if o.adopted_upload_id is not null then
    result:=private.analysis_admission_replay(o.id,p_request);
    if o.adopted_upload_id<>u.id then
      if u.state='prepared' then update private.analysis_admission_uploads set state='cleanup_pending' where id=u.id; end if;
      cleanup:=u.state in ('prepared','cleanup_pending');
    end if;
  else
    if u.state<>'prepared' then return private.analysis_admission_denied('ADMISSION_CONFLICT'); end if;
    result:=public.create_queued_analysis(u.analysis_id,(p_request->>'bytes')::integer,p_request->>'checksum',p_request->>'displayName',
      o.id,p_request->>'jobDescription',u.job_id,p_request->>'jobTitle',p_organization_id,p_request->>'requestId',u.resume_id,u.storage_key,p_user_id,u.version_id);
    -- The old RPC's global key is never authority to adopt an unrelated result.
    if result->'created' is distinct from 'true'::jsonb or result->>'analysisId' is distinct from u.analysis_id::text
      or result->>'resumeId' is distinct from u.resume_id::text then raise exception 'Legacy key collision' using errcode='23505'; end if;
    update private.analysis_admission_uploads set state='adopted' where id=u.id;
    update private.analysis_admission_operations set adopted_upload_id=u.id where id=o.id;
    created:=true;
  end if;
  return jsonb_build_object('schemaVersion','analysis-admission/1.0.0','kind','result','operationId',o.id,'bindingSha256',o.binding_sha256,
    'analysisId',result->>'analysisId','resumeId',result->>'resumeId','created',created,'uploadId',u.id,'storageKey',u.storage_key,'cleanupPending',cleanup);
exception when unique_violation then return private.analysis_admission_denied('ADMISSION_CONFLICT');
  when insufficient_privilege then return private.analysis_admission_denied('ADMISSION_DENIED');
  when others then return private.analysis_admission_denied('ADMISSION_UNAVAILABLE');
end;

public.cleanup_analysis_admission:
declare o private.analysis_admission_operations%rowtype; u private.analysis_admission_uploads%rowtype;
begin
  -- Exact post-work compensation, not new admission: may finish after revocation.
  perform 1 from public.organizations where id=p_organization_id for update;
  select * into o from private.analysis_admission_operations where id=p_operation_id and owner_id=p_user_id and organization_id=p_organization_id for update;
  if not found or p_action is null or p_action not in ('pending','cleaned') then return false; end if;
  select * into u from private.analysis_admission_uploads where id=p_upload_id and operation_id=o.id for update;
  if not found or u.state='adopted' or o.adopted_upload_id=u.id then return false; end if;
  if p_action='pending' then
    if u.state='prepared' then update private.analysis_admission_uploads set state='cleanup_pending' where id=u.id; end if;
  elsif u.state='cleanup_pending' then
    update private.analysis_admission_uploads set state='cleaned' where id=u.id;
  elsif u.state<>'cleaned' then return false;
  end if;
  return true;
end;

private.analysis_job_v2_owner_eligible:
declare a public.analyses%rowtype;
begin
  select * into a from public.analyses where id=p_analysis_id;
  if not found then return false; end if;
  if not private.try_candidate_privacy_write(a.owner_id) then return false; end if;
  perform 1 from public.memberships m where m.organization_id=a.organization_id and m.user_id=a.owner_id
    and m.role in ('owner','admin','member') for share skip locked;
  if not found then return false; end if;
  perform 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
    where v.id=a.resume_version_id and v.organization_id=a.organization_id and v.owner_id=a.owner_id
      and r.organization_id=a.organization_id and r.owner_id=a.owner_id and r.status='active'
    for share of v,r skip locked;
  return found;
end;

public.claim_analysis_job_v2:
declare
  candidate record; a public.analyses%rowtype; j public.analysis_jobs%rowtype;
  checked_at timestamptz; token uuid; expires_at timestamptz;
begin
  if p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_lease_seconds is null or p_lease_seconds<1 or p_lease_seconds>3600 then
    raise exception 'Invalid fenced lease parameters' using errcode='22023';
  end if;
  -- Both the expired sweep and candidate selection acquire analysis first.
  -- Bounded sweep work does not grant a safe shared-project verification scope.
  for candidate in
    select a.id from public.analyses a join public.analysis_jobs j on j.analysis_id=a.id
    where j.dead_lettered_at is null and j.attempt_count>=3 and j.lease_expires_at<=clock_timestamp()
      and a.status in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
      and not private.analysis_job_v2_review_handoff(a.id)
      and not private.candidate_write_blocked(a.owner_id)
      and exists(select 1 from public.memberships m where m.organization_id=a.organization_id and m.user_id=a.owner_id and m.role in ('owner','admin','member'))
      and exists(select 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
        where v.id=a.resume_version_id and v.organization_id=a.organization_id and v.owner_id=a.owner_id
          and r.organization_id=a.organization_id and r.owner_id=a.owner_id and r.status='active')
    order by j.run_after,a.id limit 100 for update of a skip locked
  loop
    select * into a from public.analyses where id=candidate.id;
    select * into j from public.analysis_jobs where analysis_id=a.id for update skip locked;
    if not found then continue; end if;
    if not private.analysis_job_v2_owner_eligible(a.id) then continue; end if;
    checked_at:=clock_timestamp();
    if a.status not in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
      or j.dead_lettered_at is not null or j.attempt_count<3 or j.lease_expires_at is null or j.lease_expires_at>checked_at
      or private.analysis_job_v2_review_handoff(a.id) then continue; end if;
    update public.analysis_jobs set lease_owner=null,lease_expires_at=null,last_error_code='LEASE_EXPIRED',dead_lettered_at=checked_at
      where analysis_id=a.id;
    if not public.transition_analysis(a.id,a.status,'failed',null,p_worker_id,coalesce(a.request_id,'worker-dead-letter')) then
      raise exception 'Fenced dead-letter transition failed' using errcode='23514';
    end if;
  end loop;

  for candidate in
    select a.id from public.analyses a join public.analysis_jobs j on j.analysis_id=a.id
    where j.run_after<=clock_timestamp() and j.dead_lettered_at is null and j.attempt_count<3
      and (j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp())
      and a.status in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
      and not private.analysis_job_v2_review_handoff(a.id)
      and not private.candidate_write_blocked(a.owner_id)
      and exists(select 1 from public.memberships m where m.organization_id=a.organization_id and m.user_id=a.owner_id and m.role in ('owner','admin','member'))
      and exists(select 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
        where v.id=a.resume_version_id and v.organization_id=a.organization_id and v.owner_id=a.owner_id
          and r.organization_id=a.organization_id and r.owner_id=a.owner_id and r.status='active')
    order by j.run_after,a.id limit 100 for update of a skip locked
  loop
    select * into a from public.analyses where id=candidate.id;
    select * into j from public.analysis_jobs where analysis_id=a.id for update skip locked;
    if not found then continue; end if;
    if not private.analysis_job_v2_owner_eligible(a.id) then continue; end if;
    checked_at:=clock_timestamp();
    if a.status not in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
      or j.dead_lettered_at is not null or j.attempt_count>=3 or j.run_after>checked_at
      or (j.lease_expires_at is not null and j.lease_expires_at>checked_at)
      or private.analysis_job_v2_review_handoff(a.id) then continue; end if;
    token:=gen_random_uuid(); expires_at:=checked_at+make_interval(secs=>p_lease_seconds);
    update public.analysis_jobs set lease_owner=p_worker_id,lease_fence=token,lease_expires_at=expires_at,
      attempt_count=attempt_count+1,last_error_code=case when j.lease_expires_at is not null then 'LEASE_EXPIRED' else last_error_code end
      where analysis_id=a.id returning * into j;
    return jsonb_build_object('schemaVersion','analysis-job-lease/2.0.0','analysisId',a.id,'attempt',j.attempt_count,
      'runAfter',j.run_after,'leaseFence',token,'leaseExpiresAt',expires_at);
  end loop;
  return null;
end;

public.heartbeat_analysis_job_v2:
declare a public.analyses%rowtype; j public.analysis_jobs%rowtype; checked_at timestamptz;
begin
  if p_analysis_id is null or p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_attempt is null or p_attempt not between 1 and 3 or p_lease_fence is null
    or p_lease_seconds is null or p_lease_seconds<1 or p_lease_seconds>3600 then return false; end if;
  select * into a from public.analyses where id=p_analysis_id for update;
  if not found or a.status='cancelled' then return false; end if;
  select * into j from public.analysis_jobs where analysis_id=p_analysis_id and lease_owner=p_worker_id
    and attempt_count=p_attempt and lease_fence=p_lease_fence for update;
  if not found then return false; end if;
  if not private.analysis_job_v2_owner_eligible(a.id) then return false; end if;
  checked_at:=clock_timestamp();
  if j.dead_lettered_at is not null or j.lease_expires_at is null or j.lease_expires_at<=checked_at then return false; end if;
  update public.analysis_jobs set lease_expires_at=checked_at+make_interval(secs=>p_lease_seconds)
    where analysis_id=p_analysis_id and lease_owner=p_worker_id and attempt_count=p_attempt and lease_fence=p_lease_fence;
  return found;
end;

public.complete_analysis_job_v2:
declare a public.analyses%rowtype; j public.analysis_jobs%rowtype;
begin
  if p_analysis_id is null or p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_attempt is null or p_attempt not between 1 and 3 or p_lease_fence is null then return false; end if;
  select * into a from public.analyses where id=p_analysis_id for update;
  if not found or a.status='cancelled' then return false; end if;
  select * into j from public.analysis_jobs where analysis_id=p_analysis_id and lease_owner=p_worker_id
    and attempt_count=p_attempt and lease_fence=p_lease_fence for update;
  if not found then return false; end if;
  if not private.analysis_job_v2_owner_eligible(a.id) then return false; end if;
  if j.dead_lettered_at is not null or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp() then return false; end if;
  if a.status not in ('completed','partial','failed','rejected') and not private.analysis_job_v2_review_handoff(a.id) then return false; end if;
  delete from public.analysis_jobs where analysis_id=p_analysis_id and lease_owner=p_worker_id
    and attempt_count=p_attempt and lease_fence=p_lease_fence;
  return found;
end;

public.release_analysis_job_v2:
declare a public.analyses%rowtype; j public.analysis_jobs%rowtype; checked_at timestamptz;
begin
  if p_analysis_id is null or p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_attempt is null or p_attempt not between 1 and 3 or p_lease_fence is null
    or p_retry_delay_seconds is null or p_retry_delay_seconds<0 or p_retry_delay_seconds>3600
    or p_error_code is null or p_error_code !~ '^[A-Z0-9_]{1,64}$' then return false; end if;
  select * into a from public.analyses where id=p_analysis_id for update;
  if not found or a.status not in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review','failed') then return false; end if;
  select * into j from public.analysis_jobs where analysis_id=p_analysis_id and lease_owner=p_worker_id
    and attempt_count=p_attempt and lease_fence=p_lease_fence for update;
  if not found then return false; end if;
  if not private.analysis_job_v2_owner_eligible(a.id) then return false; end if;
  checked_at:=clock_timestamp();
  if j.dead_lettered_at is not null or j.lease_expires_at is null or j.lease_expires_at<=checked_at
    or private.analysis_job_v2_review_handoff(a.id) then return false; end if;
  if j.attempt_count<3 and a.status<>'failed' then
    update public.analysis_jobs set lease_owner=null,lease_expires_at=null,last_error_code=p_error_code,
      run_after=checked_at+make_interval(secs=>p_retry_delay_seconds)
      where analysis_id=p_analysis_id and lease_fence=p_lease_fence and attempt_count=p_attempt;
    -- Keep the non-null fence: no legacy worker may adopt this retry row.
    return found;
  end if;
  update public.analysis_jobs set lease_owner=null,lease_expires_at=null,last_error_code=p_error_code,dead_lettered_at=checked_at
    where analysis_id=p_analysis_id and lease_fence=p_lease_fence and attempt_count=p_attempt;
  if a.status<>'failed' and not public.transition_analysis(a.id,a.status,'failed',null,p_worker_id,coalesce(a.request_id,'worker-dead-letter')) then
    raise exception 'Fenced dead-letter transition failed' using errcode='23514';
  end if;
  return true;
end;

private.analysis_stage_strings:
declare key text;
begin
  foreach key in array p_keys loop
    if jsonb_typeof(p_value->key) is distinct from 'string' then return false; end if;
  end loop;
  return true;
end;

private.lock_analysis_stage_lease:
declare a public.analyses%rowtype; j public.analysis_jobs%rowtype; v public.resume_versions%rowtype;
begin
  if p_analysis_id is null or p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_attempt is null or p_attempt not between 1 and 3 or p_lease_fence is null then return false; end if;
  select * into a from public.analyses where id=p_analysis_id for update;
  if not found or a.status='cancelled' then return false; end if;
  if not private.try_candidate_privacy_write(a.owner_id) then return false; end if;
  select * into j from public.analysis_jobs where analysis_id=p_analysis_id and lease_owner=p_worker_id
    and attempt_count=p_attempt and lease_fence=p_lease_fence for update;
  if not found or j.dead_lettered_at is not null then return false; end if;
  perform 1 from public.memberships m where m.organization_id=a.organization_id and m.user_id=a.owner_id
    and m.role in ('owner','admin','member') for share skip locked;
  if not found then return false; end if;
  -- Extraction updates version.page_count. Take its write-compatible lock now,
  -- avoiding two stage transactions both upgrading a shared version lock later.
  select * into v from public.resume_versions where id=a.resume_version_id
    and organization_id=a.organization_id and owner_id=a.owner_id for no key update skip locked;
  if not found then return false; end if;
  perform 1 from public.resumes r where r.id=v.resume_id and r.organization_id=a.organization_id
    and r.owner_id=a.owner_id and r.status='active' for share skip locked;
  if not found then return false; end if;
  -- Refresh AFTER all locks; transaction-start time must not revive a lease.
  return j.lease_expires_at is not null and j.lease_expires_at>clock_timestamp();
end;

public.persist_analysis_stage_v2:
declare
  keys text[]; strings text[]; result boolean;
  extraction_keys text[]:=array['p_analysis_id','p_duration_ms','p_extracted_text','p_extractor_version','p_page_count',
    'p_page_texts','p_process_id','p_request_id','p_text_checksum','p_warnings'];
begin
  if p_analysis_id is null or p_operation is null or jsonb_typeof(p_parameters) is distinct from 'object'
    or jsonb_typeof(p_parameters->'p_analysis_id') is distinct from 'string'
    or (p_parameters->>'p_analysis_id')::uuid is distinct from p_analysis_id then return false; end if;

  case p_operation
  when 'transition_analysis' then
    keys:=array['p_analysis_id','p_expected_status','p_next_status','p_actor_id','p_process_id','p_request_id'];
    strings:=array['p_analysis_id','p_expected_status','p_next_status','p_process_id','p_request_id'];
    if p_parameters->'p_actor_id' is distinct from 'null'::jsonb then return false; end if;
  when 'persist_analysis_extraction','persist_native_layout_extraction' then
    keys:=extraction_keys;
    strings:=array['p_analysis_id','p_extracted_text','p_extractor_version','p_process_id','p_request_id','p_text_checksum'];
    if not private.analysis_stage_integer(p_parameters->'p_duration_ms') or not private.analysis_stage_integer(p_parameters->'p_page_count')
      or jsonb_typeof(p_parameters->'p_page_texts') is distinct from 'array' or jsonb_typeof(p_parameters->'p_warnings') is distinct from 'array' then return false; end if;
    if p_operation='persist_native_layout_extraction' then
      keys:=keys||array['p_evidence_graph','p_native_layout'];
    elsif p_parameters ? 'p_evidence_graph' then keys:=keys||array['p_evidence_graph']; end if;
    if (p_parameters ? 'p_evidence_graph') and jsonb_typeof(p_parameters->'p_evidence_graph') not in ('object','null') then return false; end if;
    if p_operation='persist_native_layout_extraction' and jsonb_typeof(p_parameters->'p_native_layout') not in ('object','null') then return false; end if;
  when 'persist_document_evidence' then
    keys:=array['p_analysis_id','p_envelope','p_process_id','p_request_id'];
    strings:=array['p_analysis_id','p_process_id','p_request_id'];
    if jsonb_typeof(p_parameters->'p_envelope') is distinct from 'object' then return false; end if;
  when 'persist_deterministic_analysis' then
    keys:=array['p_analysis_id','p_input_text_checksum','p_keyword_coverage','p_normalizer_version','p_parse_view','p_parser_version',
      'p_process_id','p_request_id','p_result_checksum','p_rule_trace','p_ruleset_version','p_score','p_taxonomy_version'];
    strings:=array['p_analysis_id','p_input_text_checksum','p_normalizer_version','p_parser_version','p_process_id','p_request_id',
      'p_result_checksum','p_ruleset_version','p_taxonomy_version'];
    if not private.analysis_stage_integer(p_parameters->'p_score') or jsonb_typeof(p_parameters->'p_keyword_coverage') is distinct from 'object'
      or jsonb_typeof(p_parameters->'p_parse_view') is distinct from 'object' or jsonb_typeof(p_parameters->'p_rule_trace') is distinct from 'array' then return false; end if;
  when 'persist_partial_analysis' then
    keys:=array['p_analysis_id','p_feedback','p_process_id','p_request_id'];
    strings:=array['p_analysis_id','p_process_id','p_request_id'];
    if jsonb_typeof(p_parameters->'p_feedback') is distinct from 'object' then return false; end if;
  when 'persist_qualitative_analysis' then
    keys:=array['p_analysis_id','p_feedback','p_input_hash','p_input_tokens','p_model_id','p_output','p_output_tokens',
      'p_process_id','p_prompt_version','p_provider','p_request_id','p_run_id','p_writer'];
    strings:=array['p_analysis_id','p_input_hash','p_model_id','p_process_id','p_prompt_version','p_provider','p_request_id','p_run_id'];
    if not private.analysis_stage_integer(p_parameters->'p_input_tokens') or not private.analysis_stage_integer(p_parameters->'p_output_tokens')
      or jsonb_typeof(p_parameters->'p_feedback') is distinct from 'object' or jsonb_typeof(p_parameters->'p_output') is distinct from 'object'
      or jsonb_typeof(p_parameters->'p_writer') is distinct from 'object' then return false; end if;
  else return false;
  end case;
  if not private.analysis_stage_parameter_keys(p_parameters,keys) or not private.analysis_stage_strings(p_parameters,strings) then return false; end if;
  if not private.lock_analysis_stage_lease(p_analysis_id,p_worker_id,p_attempt,p_lease_fence) then return false; end if;

  -- A subtransaction is essential: inner legacy functions may write before
  -- returning false. An expired post-check must roll back those writes, too.
  begin
    case p_operation
    when 'transition_analysis' then
      result:=public.transition_analysis(p_analysis_id,p_parameters->>'p_expected_status',p_parameters->>'p_next_status',
        null::uuid,p_parameters->>'p_process_id',p_parameters->>'p_request_id');
    when 'persist_analysis_extraction' then
      if p_parameters ? 'p_evidence_graph' then
        result:=public.persist_analysis_extraction(p_analysis_id,(p_parameters->>'p_duration_ms')::integer,p_parameters->>'p_extracted_text',
          p_parameters->>'p_extractor_version',(p_parameters->>'p_page_count')::integer,p_parameters->'p_page_texts',p_parameters->>'p_process_id',
          p_parameters->>'p_request_id',p_parameters->>'p_text_checksum',p_parameters->'p_warnings',nullif(p_parameters->'p_evidence_graph','null'::jsonb));
      else
        result:=public.persist_analysis_extraction(p_analysis_id,(p_parameters->>'p_duration_ms')::integer,p_parameters->>'p_extracted_text',
          p_parameters->>'p_extractor_version',(p_parameters->>'p_page_count')::integer,p_parameters->'p_page_texts',p_parameters->>'p_process_id',
          p_parameters->>'p_request_id',p_parameters->>'p_text_checksum',p_parameters->'p_warnings');
      end if;
    when 'persist_native_layout_extraction' then
      result:=public.persist_native_layout_extraction(p_analysis_id,(p_parameters->>'p_duration_ms')::integer,p_parameters->>'p_extracted_text',
        p_parameters->>'p_extractor_version',(p_parameters->>'p_page_count')::integer,p_parameters->'p_page_texts',p_parameters->>'p_process_id',
        p_parameters->>'p_request_id',p_parameters->>'p_text_checksum',p_parameters->'p_warnings',
        nullif(p_parameters->'p_evidence_graph','null'::jsonb),nullif(p_parameters->'p_native_layout','null'::jsonb));
    when 'persist_document_evidence' then
      result:=public.persist_document_evidence(p_analysis_id,p_parameters->'p_envelope',p_parameters->>'p_process_id',p_parameters->>'p_request_id');
    when 'persist_deterministic_analysis' then
      result:=public.persist_deterministic_analysis(p_analysis_id,p_parameters->>'p_input_text_checksum',p_parameters->'p_keyword_coverage',
        p_parameters->>'p_normalizer_version',p_parameters->'p_parse_view',p_parameters->>'p_parser_version',p_parameters->>'p_process_id',
        p_parameters->>'p_request_id',p_parameters->>'p_result_checksum',p_parameters->'p_rule_trace',p_parameters->>'p_ruleset_version',
        (p_parameters->>'p_score')::integer,p_parameters->>'p_taxonomy_version');
    when 'persist_partial_analysis' then
      result:=public.persist_partial_analysis(p_analysis_id,p_parameters->'p_feedback',p_parameters->>'p_process_id',p_parameters->>'p_request_id');
    when 'persist_qualitative_analysis' then
      result:=public.persist_qualitative_analysis(p_analysis_id,p_parameters->'p_feedback',p_parameters->>'p_input_hash',
        (p_parameters->>'p_input_tokens')::integer,p_parameters->>'p_model_id',p_parameters->'p_output',
        (p_parameters->>'p_output_tokens')::integer,p_parameters->>'p_process_id',p_parameters->>'p_prompt_version',
        p_parameters->>'p_provider',p_parameters->>'p_request_id',(p_parameters->>'p_run_id')::uuid,p_parameters->'p_writer');
    end case;
    if result is not true or not private.lock_analysis_stage_lease(p_analysis_id,p_worker_id,p_attempt,p_lease_fence) then
      raise exception 'Fenced stage write did not commit' using errcode='P0F01';
    end if;
    return true;
  exception when others then
    -- Roll back this subtransaction, withhold the write and expose no source,
    -- candidate text, token, raw validation exception or provider payload.
    return false;
  end;
exception when others then return false;
end;

private.candidate_write_blocked:
select p_owner_id is null or exists(select 1 from private.owned_ai_deletion_dispositions p where p.owner_id=p_owner_id) or exists(select 1 from public.data_requests d
  where d.user_id=p_owner_id and d.kind='deletion'
    and d.status is distinct from 'failed' and d.status is distinct from 'cancelled');

private.try_candidate_privacy_write:
declare owner_key bigint;
begin
  if p_owner_id is null or current_setting('transaction_isolation') not in ('read committed','read uncommitted') then return false; end if;
  foreach owner_key in array private.candidate_owner_lock_keys(array[p_owner_id]) loop
    -- Never wait while holding candidate/source/queue row locks.
    if not pg_try_advisory_xact_lock_shared(owner_key) then return false; end if;
  end loop;
  -- Separate VOLATILE command sees deletions committed before lock acquisition.
  return not private.candidate_write_blocked(p_owner_id);
end;

private.serialize_deletion_request:
begin
  if tg_op='UPDATE' and (new.id,new.user_id,new.organization_id,new.kind)
    is distinct from (old.id,old.user_id,old.organization_id,old.kind) then
    raise exception 'PRIVACY_REQUEST_IDENTITY' using errcode='23514'; end if;
  if new.kind='deletion' then
    if current_setting('transaction_isolation') not in ('read committed','read uncommitted') then
      raise exception 'PRIVACY_ISOLATION_UNSUPPORTED' using errcode='25000'; end if;
    if not private.try_lock_candidate_owners(array[new.user_id]) then
      raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03'; end if;
    -- Separate command after owner acquisition observes a committed preparation.
    if tg_op='UPDATE' and new.status='cancelled' and exists(select 1 from private.owned_ai_deletion_dispositions p where p.owner_id=new.user_id) then
      raise exception 'PRIVACY_DELETION_PREPARED' using errcode='42501';end if;
  elsif new.kind='export' and (tg_op='INSERT'
    or (new.result_manifest is not null and new.result_manifest<>'null'::jsonb
      and new.result_manifest is distinct from old.result_manifest)) then
    -- New intake/personal-data copies are work; failure bookkeeping and manifest
    -- erasure remain available after deletion, including the privacy worker.
    if not private.try_candidate_privacy_write(new.user_id) then
      raise exception 'CANDIDATE_WRITE_BLOCKED' using errcode='42501'; end if;
  end if;
  return new;
end;

private.guard_candidate_privacy_write:
declare new_owner uuid; old_owner uuid;
begin
  if tg_nargs<>1 or tg_table_schema<>'public' then
    raise exception 'PRIVACY_GUARD_SCOPE' using errcode='23514'; end if;
  new_owner:=(to_jsonb(new)->>tg_argv[0])::uuid;
  if new_owner is null then raise exception 'PRIVACY_GUARD_OWNER' using errcode='23514'; end if;
  if tg_op='UPDATE' then
    old_owner:=(to_jsonb(old)->>tg_argv[0])::uuid;
    if new_owner is distinct from old_owner then raise exception 'PRIVACY_GUARD_OWNER' using errcode='23514'; end if;
    -- Only the existing content-free cancellation/retention tombstones bypass
    -- new-work admission. No INSERT, owner transfer or content change is exempt.
    if tg_table_name='resumes' and to_jsonb(new)->>'status'='deleted'
      and (to_jsonb(new)-array['status','updated_at'])=(to_jsonb(old)-array['status','updated_at']) then return new; end if;
    if tg_table_name='analyses' and to_jsonb(new)->>'status'='cancelled' and to_jsonb(old)->>'status' in ('queued','quarantined','cancelled')
      and (to_jsonb(new)-array['status','request_id','stage_updated_at','completed_at','updated_at'])
        =(to_jsonb(old)-array['status','request_id','stage_updated_at','completed_at','updated_at']) then return new; end if;
  end if;
  if not private.try_candidate_privacy_write(new_owner) then
    raise exception 'CANDIDATE_WRITE_BLOCKED' using errcode='42501'; end if;
  return new;
end;

public.recover_terminal_analysis_jobs_v2:
declare candidate record; a public.analyses%rowtype; j public.analysis_jobs%rowtype;
  checked_at timestamptz; recovered integer:=0;
begin
  if p_limit is null or p_limit not between 1 and 100 then
    raise exception 'Invalid recovery limit' using errcode='22023'; end if;
  for candidate in
    select a.id from public.analyses a join public.analysis_jobs j on j.analysis_id=a.id
    where j.dead_lettered_at is null and ((j.lease_owner is null and j.lease_expires_at is null) or j.lease_expires_at<=clock_timestamp())
      and (a.status in ('completed','partial','rejected','failed')
        or (a.status in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
          and private.analysis_job_v2_review_handoff(a.id)))
      and not private.candidate_write_blocked(a.owner_id)
      and exists(select 1 from public.memberships m where m.organization_id=a.organization_id and m.user_id=a.owner_id and m.role in ('owner','admin','member'))
      and exists(select 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
        where v.id=a.resume_version_id and v.organization_id=a.organization_id and v.owner_id=a.owner_id
          and r.organization_id=a.organization_id and r.owner_id=a.owner_id and r.status='active')
    order by j.run_after,a.id limit p_limit for update of a skip locked
  loop
    select * into a from public.analyses where id=candidate.id;
    select * into j from public.analysis_jobs where analysis_id=a.id for update skip locked;
    if not found then continue; end if;
    if not private.analysis_job_v2_owner_eligible(a.id) then continue; end if;
    checked_at:=clock_timestamp();
    if j.dead_lettered_at is not null or (j.lease_expires_at is null and j.lease_owner is not null)
      or (j.lease_expires_at is not null and j.lease_expires_at>checked_at) then continue; end if;
    if a.status='failed' then
      -- Preserve attempt/error/fence history. No retry, deletion or status rewrite.
      update public.analysis_jobs set lease_owner=null,lease_expires_at=null,dead_lettered_at=checked_at,
        last_error_code=coalesce(last_error_code,'TERMINAL_FAILURE') where analysis_id=a.id;
      recovered:=recovered+1;
    elsif a.status in ('completed','partial','rejected')
      or (a.status in ('quarantined','queued','extracting','needs_ocr','scoring','qualitative_review')
        and private.analysis_job_v2_review_handoff(a.id)) then
      -- NULL-fence legacy leftovers are eligible; live/uncertain leases never are.
      delete from public.analysis_jobs where analysis_id=a.id;
      recovered:=recovered+1;
    end if;
  end loop;
  return recovered;
end;

private.correction_fail:
begin
  case p_kind
    when 'not_found' then raise exception 'C02_NOT_FOUND' using errcode='42501';
    when 'conflict' then raise exception 'C02_CONFLICT' using errcode='P0C01';
    when 'invalid' then raise exception 'C02_INVALID' using errcode='22023';
    else raise exception 'C02_UNAVAILABLE' using errcode='P0C03';
  end case;
end;

private.correction_scope:
declare a public.analyses%rowtype; r public.resumes%rowtype; v public.resume_versions%rowtype;
  e public.document_evidence_attempts%rowtype; h public.canonical_resume_versions%rowtype;
  review_max bigint; review_count bigint; assignment_max bigint; assignment_count bigint; initial_owner uuid;
begin
  select owner_id into initial_owner from public.analyses where id=p_analysis_id;
  if initial_owner is distinct from p_user_id or p_user_id is null then perform private.correction_fail('not_found'); end if;
  -- Only the frozen candidate owner, before ANY row lock. Never add owners later.
  perform private.lock_candidate_owners(array[p_user_id]);
  if not private.try_candidate_privacy_write(p_user_id) then perform private.correction_fail('not_found'); end if;
  select root.* into r from public.resumes root join public.resume_versions source on source.resume_id=root.id
    join public.analyses analysis on analysis.resume_version_id=source.id
    where analysis.id=p_analysis_id and analysis.owner_id=p_user_id and source.owner_id=p_user_id
      and root.owner_id=p_user_id and source.organization_id=analysis.organization_id and root.organization_id=analysis.organization_id
    for update of root;
  if not found or r.status<>'active' then perform private.correction_fail('not_found'); end if;
  select * into a from public.analyses where id=p_analysis_id and owner_id=p_user_id and organization_id=r.organization_id for update;
  if not found then perform private.correction_fail('not_found'); end if;
  perform 1 from public.memberships where organization_id=r.organization_id and user_id=p_user_id and role in ('owner','admin','member') for share;
  if not found then perform private.correction_fail('not_found'); end if;
  select * into v from public.resume_versions where id=a.resume_version_id and resume_id=r.id
    and owner_id=p_user_id and organization_id=r.organization_id for share;
  if not found then perform private.correction_fail('not_found'); end if;
  select * into e from public.document_evidence_attempts where analysis_id=a.id
    order by attempt_number desc limit 1 for share;
  if not found or (e.owner_id,e.organization_id,e.resume_version_id,e.input_sha256)
    is distinct from (p_user_id,r.organization_id,v.id,v.checksum)
    or e.envelope->>'id' is distinct from e.id::text or e.envelope->>'analysisId' is distinct from a.id::text
    or e.envelope->>'ownerId' is distinct from p_user_id::text or e.envelope->>'sourceId' is distinct from v.id::text
    or e.envelope->>'inputSha256' is distinct from v.checksum or e.envelope->>'schemaVersion' is distinct from 'evidence/2.0.0'
    or jsonb_typeof(e.envelope->'assertions') is distinct from 'array' or jsonb_typeof(e.envelope->'spans') is distinct from 'array' then
    perform private.correction_fail('unavailable'); end if;
  select coalesce(max(revision),0),count(*) into review_max,review_count from public.evidence_corrections where analysis_id=a.id;
  select coalesce(max(assignment_revision),0),count(*) into assignment_max,assignment_count
    from public.candidate_correction_assignments where analysis_id=a.id;
  if review_max>1000 or review_count<>review_max or assignment_max>1000 or assignment_count<>assignment_max
    or exists(select 1 from public.evidence_corrections where analysis_id=a.id and (owner_id,organization_id) is distinct from (p_user_id,r.organization_id))
    or exists(select 1 from public.candidate_correction_assignments where analysis_id=a.id
      and (owner_id,organization_id,resume_id,source_resume_version_id,input_sha256) is distinct from (p_user_id,r.organization_id,r.id,v.id,v.checksum)) then
    perform private.correction_fail('unavailable'); end if;
  select version.* into h from public.canonical_resume_heads head join public.canonical_resume_versions version on version.id=head.version_id
    where head.resume_id=r.id for update of head;
  if found and ((h.owner_id,h.organization_id,h.source_resume_version_id) is distinct from (p_user_id,r.organization_id,v.id)
    or h.content->>'analysisId' is distinct from a.id::text or private.canonical_shape_valid(h.content) is not true) then
    perform private.correction_fail('conflict'); end if;
  if h.id is not null then perform private.entry_regroup_validate_head(h.id); end if;
  return jsonb_build_object('ownerId',p_user_id,'organizationId',r.organization_id,'resumeId',r.id,'analysisId',a.id,
    'sourceId',v.id,'attemptId',e.id,'inputSha256',v.checksum,'evidenceSchemaVersion','evidence/2.0.0',
    'fieldExtractorVersion',e.envelope->'fieldExtractorVersion','targetModelVersion','evidence-targets/1.0.0',
    'projectionModelVersion','canonical-corrections/1.0.1','admissionPolicyVersion','candidate-correction-admission/1.0.0',
    'reviewRevision',review_max,'assignmentRevision',assignment_max,'headId',h.id,'headRevision',h.revision,'headAttemptId',h.source_evidence_version_id);
end;

private.correction_location:
declare result jsonb:='[]'; s jsonb; e jsonb; b jsonb;
begin
  if p_body->'contactFactIds' ? p_fact::text then result:=result||jsonb_build_array(jsonb_build_object('kind','contact','sectionId',null,'entryId',null,'bulletId',null)); end if;
  for s in select value from jsonb_array_elements(p_body->'sections') loop
    if s->'factIds' ? p_fact::text then result:=result||jsonb_build_array(jsonb_build_object('kind','section','sectionId',s->>'id','entryId',null,'bulletId',null)); end if;
    for e in select value from jsonb_array_elements(s->'entries') loop
      if e->'factIds' ? p_fact::text then result:=result||jsonb_build_array(jsonb_build_object('kind','entry','sectionId',s->>'id','entryId',e->>'id','bulletId',null)); end if;
      for b in select value from jsonb_array_elements(e->'bullets') loop
        if b->'factIds' ? p_fact::text then result:=result||jsonb_build_array(jsonb_build_object('kind','bullet','sectionId',s->>'id','entryId',e->>'id','bulletId',b->>'id')); end if;
      end loop;
    end loop;
  end loop;
  return coalesce((select jsonb_agg(value order by convert_to(value::text,'UTF8')) from jsonb_array_elements(result)),'[]'::jsonb);
end;

private.correction_assert_fact_placement:
declare locations jsonb:=private.correction_location(p_body,p_fact); entries integer;
begin
  select count(distinct value->>'entryId') into entries
    from jsonb_array_elements(locations) where value->>'entryId' is not null;
  if jsonb_array_length(locations)=0
    or (p_field not in ('name','email','phone') and entries>1) then
    perform private.correction_fail('conflict');
  end if;
end;

private.write_correction_snapshot:
declare v public.canonical_resume_versions%rowtype; application public.candidate_correction_applications%rowtype;
  source_operation uuid; origin text; inherited uuid; restored uuid;
begin
  select * into strict v from public.canonical_resume_versions where id=p_version_id;
  if exists(select 1 from public.canonical_correction_snapshots where canonical_version_id=v.id) then perform private.correction_fail('conflict'); end if;
  select * into application from public.candidate_correction_applications where result_version_id=v.id;
  if found then
    source_operation:=application.operation_id; origin:='correction'; inherited:=v.parent_version_id;
  elsif v.parent_version_id is null then
    origin:='raw_import';
    select id into source_operation from public.candidate_correction_operations where initial_import_version_id=v.id;
  elsif p_command->>'operation'='rollback' then
    restored:=(p_command->>'targetVersionId')::uuid;
    origin:=case when exists(select 1 from public.canonical_correction_snapshots where canonical_version_id=restored) then 'restore' else 'legacy_restore' end;
  else origin:='inherited'; inherited:=v.parent_version_id;
  end if;
  insert into public.canonical_correction_snapshots(canonical_version_id,owner_id,organization_id,resume_id,source_resume_version_id,
    source_operation_id,origin_kind,inherited_from_version_id,restored_from_version_id,admission_policy_version)
    values(v.id,v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,source_operation,origin,inherited,restored,'candidate-correction-admission/1.0.0');
  insert into public.canonical_correction_snapshot_facts(canonical_version_id,fact_id,owner_id,organization_id,application_id)
    select v.id,old.fact_id,v.owner_id,v.organization_id,old.application_id
      from public.canonical_correction_snapshot_facts old
      join public.resume_facts fact on fact.canonical_version_id=v.id and fact.id=old.fact_id
      join public.candidate_correction_applications applied on applied.id=old.application_id
      join public.resume_facts original on original.canonical_version_id=applied.result_version_id and original.id=applied.result_fact_id
    where old.canonical_version_id=coalesce(inherited,restored) and old.owner_id=v.owner_id and old.organization_id=v.organization_id
      and fact.type=original.type and fact.value=original.value
      and (p_command->>'operation' is distinct from 'edit' or old.fact_id::text is distinct from p_command->>'factId')
      and (application.id is null or old.fact_id<>application.result_fact_id)
      and (application.supersedes_application_id is null or old.application_id<>application.supersedes_application_id);
  if application.id is not null then
    insert into public.canonical_correction_snapshot_facts(canonical_version_id,fact_id,owner_id,organization_id,application_id)
      values(v.id,application.result_fact_id,v.owner_id,v.organization_id,application.id);
  end if;
  perform private.entry_regroup_write_snapshot(p_version_id,p_command);
end;

private.correction_validate_command:
declare key text; item jsonb; location jsonb; mode text;
begin
  if jsonb_typeof(p_command) is distinct from 'object' or octet_length(p_command::text)>65536
    or private.evidence_keys(p_command,array['schemaVersion','kind','idempotencyKey','sourceId','attemptId','inputSha256',
      'evidenceSchemaVersion','fieldExtractorVersion','targetModelVersion','projectionModelVersion','admissionPolicyVersion',
      'expectedReviewRevision','expectedAssignmentRevision','expectedVersionId','acknowledgement','selectors']) is not true
    or p_command->>'schemaVersion' is distinct from 'candidate-correction-command/1.0.0'
    or p_command->>'kind' not in ('assign','apply','add','reapply') or (p_command->>'kind'='assign') is distinct from p_assign
    or p_command->'acknowledgement' is distinct from 'true'::jsonb then perform private.correction_fail('invalid'); end if;
  foreach key in array array['idempotencyKey','sourceId','attemptId'] loop
    if private.correction_uuid(p_command->key) is not true then perform private.correction_fail('invalid'); end if;
  end loop;
  if private.correction_uuid(p_command->'expectedVersionId',true) is not true
    or jsonb_typeof(p_command->'inputSha256') is distinct from 'string' or p_command->>'inputSha256' !~ '^[a-f0-9]{64}$'
    or p_command->>'evidenceSchemaVersion' is distinct from 'evidence/2.0.0'
    or p_command->>'targetModelVersion' is distinct from 'evidence-targets/1.0.0'
    or p_command->>'projectionModelVersion' is distinct from 'canonical-corrections/1.0.1'
    or p_command->>'admissionPolicyVersion' is distinct from 'candidate-correction-admission/1.0.0'
    or (p_command->'fieldExtractorVersion'<>'null'::jsonb and (jsonb_typeof(p_command->'fieldExtractorVersion') is distinct from 'string'
      or char_length(p_command->>'fieldExtractorVersion') not between 1 and 100)) then perform private.correction_fail('invalid'); end if;
  foreach key in array array['expectedReviewRevision','expectedAssignmentRevision'] loop
    if jsonb_typeof(p_command->key) is distinct from 'number' or p_command->>key !~ '^(0|[1-9][0-9]{0,9})$'
      or (p_command->>key)::bigint>2147483647 then perform private.correction_fail('invalid'); end if;
  end loop;
  if jsonb_typeof(p_command->'selectors') is distinct from 'array' or jsonb_array_length(p_command->'selectors') not between 1 and 32 then
    perform private.correction_fail('invalid'); end if;
  for item in select value from jsonb_array_elements(p_command->'selectors') loop
    if not p_assign then
      if private.evidence_keys(item,array['assignmentId','priorApplicationId']) is not true
        or private.correction_uuid(item->'assignmentId') is not true or private.correction_uuid(item->'priorApplicationId',true) is not true
        or (item->'priorApplicationId'<>'null'::jsonb) is distinct from (p_command->>'kind'='reapply') then perform private.correction_fail('invalid'); end if;
      continue;
    end if;
    if private.evidence_keys(item,array['eventId','targetKind','assertionId','opaqueTargetId','mappingMode','baseVersionId','factId',
      'mappingProofKind','originVersionId','originFactId','location','supersedesAssignmentId']) is not true
      or private.correction_uuid(item->'eventId') is not true or item->>'targetKind' not in ('observed_assertion','unobserved_field')
      or jsonb_typeof(item->'opaqueTargetId') is distinct from 'string' or char_length(item->>'opaqueTargetId') not between 1 and 200
      or (item->>'targetKind'='observed_assertion') is distinct from (item->'assertionId'<>'null'::jsonb)
      or (item->'assertionId'<>'null'::jsonb and (jsonb_typeof(item->'assertionId') is distinct from 'string' or char_length(item->>'assertionId') not between 1 and 100)) then
      perform private.correction_fail('invalid'); end if;
    foreach key in array array['baseVersionId','factId','originVersionId','originFactId','supersedesAssignmentId'] loop
      if private.correction_uuid(item->key,true) is not true then perform private.correction_fail('invalid'); end if;
    end loop;
    if (item->'baseVersionId'='null'::jsonb) is distinct from (item->'factId'='null'::jsonb)
      or (item->'originVersionId'='null'::jsonb) is distinct from (item->'originFactId'='null'::jsonb)
      or item->>'mappingProofKind' not in ('current_citations','owned_origin_chain','explicit_candidate_add')
      or (item->>'mappingProofKind'='owned_origin_chain') is distinct from (item->'originVersionId'<>'null'::jsonb) then perform private.correction_fail('invalid'); end if;
    mode:=item->>'mappingMode'; location:=item->'location';
    if jsonb_typeof(item->'mappingMode') is distinct from 'string' or jsonb_typeof(item->'mappingProofKind') is distinct from 'string'
      or jsonb_typeof(location->'kind') is distinct from 'string' then perform private.correction_fail('invalid'); end if;
    if mode not in ('existing','imported_assertion','add') or private.evidence_keys(location,array['kind','sectionId','entryId','bulletId','newSectionType','newSectionTitle']) is not true
      or location->>'kind' not in ('contact','section','entry','bullet','new_entry','new_section_entry') then perform private.correction_fail('invalid'); end if;
    foreach key in array array['sectionId','entryId','bulletId'] loop
      if private.correction_uuid(location->key,true) is not true then perform private.correction_fail('invalid'); end if;
    end loop;
    if mode='imported_assertion' then
      if item->'baseVersionId'<>'null'::jsonb or item->>'targetKind'<>'observed_assertion' or item->>'mappingProofKind'<>'current_citations'
        or location->>'kind' not in ('contact','entry') or location->'sectionId'<>'null'::jsonb or location->'entryId'<>'null'::jsonb
        or location->'bulletId'<>'null'::jsonb or location->'newSectionType'<>'null'::jsonb or location->'newSectionTitle'<>'null'::jsonb then perform private.correction_fail('invalid'); end if;
    else
      if (mode='existing' and (item->'baseVersionId'='null'::jsonb or item->>'mappingProofKind'='explicit_candidate_add'))
        or (mode='add' and (item->'baseVersionId'<>'null'::jsonb or item->>'mappingProofKind'<>'explicit_candidate_add')) then perform private.correction_fail('invalid'); end if;
      if location->>'kind'='new_section_entry' then
        if mode<>'add' or location->'sectionId'<>'null'::jsonb or location->'entryId'<>'null'::jsonb or location->'bulletId'<>'null'::jsonb
          or jsonb_typeof(location->'newSectionType') is distinct from 'string'
          or location->>'newSectionType' not in ('summary','experience','education','skills','certifications','projects','other')
          or jsonb_typeof(location->'newSectionTitle') is distinct from 'string' or char_length(location->>'newSectionTitle') not between 1 and 100
          or location->>'newSectionTitle'<>btrim(location->>'newSectionTitle') then perform private.correction_fail('invalid'); end if;
      else
        if location->'newSectionType'<>'null'::jsonb or location->'newSectionTitle'<>'null'::jsonb
          or (location->>'kind'='contact' and (location->'sectionId'<>'null'::jsonb or location->'entryId'<>'null'::jsonb or location->'bulletId'<>'null'::jsonb))
          or (location->>'kind' in ('section','new_entry') and (location->'sectionId'='null'::jsonb or location->'entryId'<>'null'::jsonb or location->'bulletId'<>'null'::jsonb))
          or (location->>'kind'='entry' and (location->'sectionId'='null'::jsonb or location->'entryId'='null'::jsonb or location->'bulletId'<>'null'::jsonb))
          or (location->>'kind'='bullet' and (location->'sectionId'='null'::jsonb or location->'entryId'='null'::jsonb or location->'bulletId'='null'::jsonb))
          or (location->>'kind'='new_entry' and mode<>'add') then perform private.correction_fail('invalid'); end if;
      end if;
    end if;
  end loop;
end;

private.correction_normalize:
declare raw jsonb; item jsonb; result jsonb:='[]'; event public.evidence_corrections%rowtype;
  choice public.candidate_correction_assignments%rowtype; evidence public.document_evidence_attempts%rowtype;
  version public.canonical_resume_versions%rowtype; origin public.canonical_resume_versions%rowtype;
  fact public.resume_facts%rowtype; original_fact public.resume_facts%rowtype; assertion jsonb; ref jsonb; span jsonb;
  assembled text; count_value integer; depth integer; seen uuid[]; previous_revision integer; location jsonb;
begin
  foreach assembled in array array['sourceId','attemptId','inputSha256','evidenceSchemaVersion','fieldExtractorVersion',
    'targetModelVersion','projectionModelVersion','admissionPolicyVersion'] loop
    if p_command->assembled is distinct from p_scope->assembled then perform private.correction_fail('conflict'); end if;
  end loop;
  select * into strict evidence from public.document_evidence_attempts where id=(p_scope->>'attemptId')::uuid;
  for raw in select value from jsonb_array_elements(p_command->'selectors') loop
    if p_command->>'kind'='assign' then item:=raw||jsonb_build_object('assignmentId',null,'priorApplicationId',null);
    else
      select * into choice from public.candidate_correction_assignments where id=(raw->>'assignmentId')::uuid
        and (owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,attempt_id,input_sha256)=
          ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'analysisId')::uuid,
            (p_scope->>'sourceId')::uuid,(p_scope->>'attemptId')::uuid,p_scope->>'inputSha256');
      if not found then perform private.correction_fail('conflict'); end if;
      item:=private.correction_selector_from_row(choice,(raw->>'priorApplicationId')::uuid);
    end if;
    select * into event from public.evidence_corrections where id=(item->>'eventId')::uuid
      and (owner_id,organization_id,analysis_id,attempt_id,actor_id)=((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,
        (p_scope->>'analysisId')::uuid,evidence.id,(p_scope->>'ownerId')::uuid);
    if not found or event.operation<>'correct' or event.candidate_id is not null or event.field not in ('name','email','phone','employer','role','dates','education','certification')
      or event.value<>btrim(event.value) then perform private.correction_fail('invalid'); end if;
    assertion:=null;
    if item->>'targetKind'='observed_assertion' then
      select count(*),jsonb_agg(value)->0 into count_value,assertion from jsonb_array_elements(evidence.envelope->'assertions')
        where value->>'id'=item->>'assertionId' and value->>'field'=event.field;
      if count_value<>1 or jsonb_typeof(assertion->'evidence') is distinct from 'array' or jsonb_array_length(assertion->'evidence') not between 1 and 20 then perform private.correction_fail('invalid'); end if;
      assembled:='';
      for ref in select value from jsonb_array_elements(assertion->'evidence') loop
        select count(*),jsonb_agg(value)->0 into count_value,span from jsonb_array_elements(evidence.envelope->'spans') where value->>'id'=ref->>'spanId';
        if count_value<>1 or private.evidence_keys(ref,array['spanId','start','end']) is not true
          or private.evidence_integer(ref->'start',0,200000) is not true or private.evidence_integer(ref->'end',1,200000) is not true
          or (ref->>'end')::integer<=(ref->>'start')::integer or (ref->>'end')::integer>char_length(span->>'text') then perform private.correction_fail('invalid'); end if;
        assembled:=assembled||substring(span->>'text' from (ref->>'start')::integer+1 for (ref->>'end')::integer-(ref->>'start')::integer);
      end loop;
      if assertion->>'value' is distinct from assembled then perform private.correction_fail('invalid'); end if;
    elsif exists(select 1 from jsonb_array_elements(evidence.envelope->'assertions') where value->>'field'=event.field) then
      perform private.correction_fail('invalid');
    end if;
    if item->>'mappingMode'='existing' then
      if item->'baseVersionId' is distinct from p_command->'expectedVersionId' then perform private.correction_fail('conflict'); end if;
      select * into version from public.canonical_resume_versions where id=(item->>'baseVersionId')::uuid
        and (owner_id,organization_id,resume_id,source_resume_version_id,source_evidence_version_id)=
          ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,evidence.id);
      select * into fact from public.resume_facts where canonical_version_id=version.id and id=(item->>'factId')::uuid;
      if version.id is null or fact.id is null or fact.type<>event.field then perform private.correction_fail('invalid'); end if;
      location:=item->'location';
      if not exists(select 1 from jsonb_array_elements(private.correction_location(version.content,fact.id)) l
        where l.value=jsonb_build_object('kind',location->>'kind','sectionId',location->'sectionId','entryId',location->'entryId','bulletId',location->'bulletId')) then perform private.correction_fail('invalid'); end if;
      perform private.correction_assert_fact_placement(version.content,fact.id,event.field);
      if item->>'mappingProofKind'='current_citations' then original_fact:=fact;
      else
        if (item->>'originFactId')::uuid<>fact.id then perform private.correction_fail('invalid'); end if;
        origin:=version; seen:='{}'; depth:=0;
        loop
          if origin.id is null or origin.id=any(seen) or depth>64 then perform private.correction_fail('invalid'); end if;
          seen:=array_append(seen,origin.id);
          if origin.id=(item->>'originVersionId')::uuid then exit; end if;
          previous_revision:=origin.revision;
          select * into origin from public.canonical_resume_versions where id=origin.parent_version_id
            and (owner_id,organization_id,resume_id,source_resume_version_id,source_evidence_version_id)=
              ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,evidence.id);
          if not found or origin.revision<>previous_revision-1 then perform private.correction_fail('invalid'); end if;
          depth:=depth+1;
        end loop;
        select * into original_fact from public.resume_facts where canonical_version_id=origin.id and id=fact.id;
      end if;
      if original_fact.id is null or original_fact.type<>event.field then perform private.correction_fail('invalid'); end if;
      if assertion is not null then
        if private.correction_sorted_citations(original_fact.sources)<>private.correction_citations(assertion,evidence.id) then perform private.correction_fail('invalid'); end if;
      elsif item->>'mappingProofKind'<>'owned_origin_chain' or not exists(
        select 1 from public.canonical_correction_snapshot_facts link
          join public.candidate_correction_applications applied on applied.id=link.application_id
          join public.candidate_correction_assignments assigned on assigned.id=applied.assignment_id
        where link.canonical_version_id=origin.id and link.fact_id=original_fact.id and link.owner_id=(p_scope->>'ownerId')::uuid
          and link.organization_id=(p_scope->>'organizationId')::uuid and assigned.analysis_id=(p_scope->>'analysisId')::uuid
          and assigned.source_resume_version_id=(p_scope->>'sourceId')::uuid and assigned.attempt_id=evidence.id
          and assigned.input_sha256=p_scope->>'inputSha256' and assigned.target_kind='unobserved_field' and assigned.field=event.field) then
        -- A candidate-added absent slot has no source assertion/citation. Its
        -- exact owned snapshot/application origin can prove identity, not truth.
        perform private.correction_fail('invalid');
      end if;
    elsif item->>'mappingMode'='imported_assertion' and p_command->>'kind'='assign' and p_command->'expectedVersionId'<>'null'::jsonb then perform private.correction_fail('conflict');
    elsif item->>'mappingMode'='add' and p_command->>'kind'='assign' then
      if p_command->'expectedVersionId'='null'::jsonb then
        version.content:='{"facts":[],"sections":[],"contactFactIds":[]}'::jsonb;
      else
        select * into version from public.canonical_resume_versions where id=(p_command->>'expectedVersionId')::uuid
          and (owner_id,organization_id,resume_id,source_resume_version_id,source_evidence_version_id)=
            ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,evidence.id);
        if not found then perform private.correction_fail('conflict'); end if;
      end if;
      -- Dry placement checks existing owned structure/field compatibility only;
      -- null scratch IDs are discarded. No technical IDs/writes before replay.
      perform private.correction_place(version.content,item->'location',event.field,null,event.value,null,null,null);
    end if;
    item:=item||jsonb_build_object('field',event.field,'eventRevision',event.revision);
    if exists(select 1 from jsonb_array_elements(result) where value->>'eventId'=event.id::text) then perform private.correction_fail('invalid'); end if;
    result:=result||jsonb_build_array(item);
  end loop;
  return (select jsonb_agg(value order by (value->>'eventRevision')::integer,
    array_position(array['name','email','phone','employer','role','dates','education','certification'],value->>'field'),
    convert_to(coalesce(value->>'assertionId','unobserved:'||(value->>'field')),'UTF8'),
    array_position(array['contact','section','entry','bullet','new_entry','new_section_entry'],value->'location'->>'kind'),
    convert_to(coalesce(value->>'baseVersionId',''),'UTF8'),convert_to(coalesce(value->>'factId',''),'UTF8'),
    convert_to(coalesce(value->'location'->>'sectionId',''),'UTF8'),convert_to(coalesce(value->'location'->>'entryId',''),'UTF8'),convert_to(coalesce(value->'location'->>'bulletId',''),'UTF8'))
    from jsonb_array_elements(result));
end;

private.correction_atoms:
declare atoms text[]; item jsonb; location jsonb;
begin
  atoms:=array[p_command->>'kind',p_scope->>'ownerId',p_scope->>'organizationId',p_scope->>'resumeId',p_scope->>'analysisId',
    p_scope->>'sourceId',p_scope->>'attemptId',p_scope->>'inputSha256',p_scope->>'ownerId',p_scope->>'evidenceSchemaVersion',
    p_scope->>'fieldExtractorVersion',p_scope->>'targetModelVersion',p_scope->>'projectionModelVersion',p_scope->>'admissionPolicyVersion',
    p_command->>'expectedReviewRevision',p_command->>'expectedAssignmentRevision',p_command->>'expectedVersionId','1',jsonb_array_length(p_selectors)::text];
  for item in select value from jsonb_array_elements(p_selectors) loop
    location:=item->'location';
    atoms:=atoms||array[item->>'assignmentId',item->>'eventId',item->>'eventRevision',
      (array_position(array['name','email','phone','employer','role','dates','education','certification'],item->>'field')-1)::text,
      item->>'targetKind',item->>'assertionId',item->>'opaqueTargetId',item->>'mappingMode',item->>'baseVersionId',item->>'factId',
      item->>'mappingProofKind',item->>'originVersionId',item->>'originFactId',
      (array_position(array['contact','section','entry','bullet','new_entry','new_section_entry'],location->>'kind')-1)::text,
      location->>'sectionId',location->>'entryId',location->>'bulletId',location->>'newSectionType',location->>'newSectionTitle',
      item->>'supersedesAssignmentId',item->>'priorApplicationId'];
  end loop;
  return atoms;
end;

private.correction_latest:
declare newer public.evidence_corrections%rowtype; target jsonb; choice public.candidate_correction_assignments%rowtype;
begin
  for newer in select * from public.evidence_corrections where analysis_id=(p_scope->>'analysisId')::uuid
    and attempt_id=(p_scope->>'attemptId')::uuid and field=p_item->>'field' and revision>(p_item->>'eventRevision')::integer loop
    if newer.operation='confirm' then
      if newer.candidate_id is null or newer.candidate_id is not distinct from p_item->>'assertionId' then return false; end if;
    else
      select value into target from jsonb_array_elements(p_pending) where value->>'eventId'=newer.id::text;
      if not found then
        select * into choice from public.candidate_correction_assignments where correction_event_id=newer.id order by assignment_revision desc limit 1;
        if not found then return false; end if;
        target:=private.correction_selector_from_row(choice);
      end if;
      if (target->>'targetKind',target->>'assertionId') is not distinct from (p_item->>'targetKind',p_item->>'assertionId') then return false; end if;
    end if;
  end loop;
  return true;
end;

private.correction_replay:
declare op public.candidate_correction_operations%rowtype; recorded jsonb:='[]'; item jsonb; choice public.candidate_correction_assignments%rowtype;
  application public.candidate_correction_applications%rowtype; normalized jsonb; selected_id uuid;
begin
  select * into op from public.candidate_correction_operations where resume_id=(p_scope->>'resumeId')::uuid
    and idempotency_key=(p_command->>'idempotencyKey')::uuid;
  if not found then return null; end if;
  if op.command_sha256<>p_hash or op.kind<>p_command->>'kind'
    or (op.owner_id,op.organization_id,op.analysis_id,op.source_resume_version_id,op.attempt_id,op.input_sha256,op.actor_id)
      is distinct from ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'analysisId')::uuid,
        (p_scope->>'sourceId')::uuid,(p_scope->>'attemptId')::uuid,p_scope->>'inputSha256',(p_scope->>'ownerId')::uuid)
    or op.expected_review_revision<>(p_command->>'expectedReviewRevision')::bigint
    or op.expected_assignment_revision<>(p_command->>'expectedAssignmentRevision')::bigint
    or op.expected_canonical_version_id is distinct from (p_command->>'expectedVersionId')::uuid
    or (op.evidence_schema_version,op.field_extractor_version,op.target_model_version,op.projection_model_version,op.admission_policy_version)
      is distinct from (p_command->>'evidenceSchemaVersion',p_command->>'fieldExtractorVersion',p_command->>'targetModelVersion',p_command->>'projectionModelVersion',p_command->>'admissionPolicyVersion') then
    perform private.correction_fail('conflict'); end if;
  foreach selected_id in array op.selected_assignment_ids loop
    select * into strict choice from public.candidate_correction_assignments where id=selected_id;
    if op.kind='assign' then normalized:=private.correction_selector_from_row(choice)||'{"assignmentId":null}'::jsonb;
    else
      select * into strict application from public.candidate_correction_applications where operation_id=op.id and assignment_id=choice.id;
      normalized:=private.correction_selector_from_row(choice,application.supersedes_application_id);
    end if;
    normalized:=normalized||jsonb_build_object('field',choice.field,'eventRevision',choice.correction_revision);
    recorded:=recorded||jsonb_build_array(normalized);
  end loop;
  if recorded<>p_selectors then perform private.correction_fail('conflict'); end if;
  return private.correction_receipt(op.id,true);
end;

private.correction_admit_new:
declare item jsonb; current_choice public.candidate_correction_assignments%rowtype; prior public.candidate_correction_applications%rowtype;
  prior_event uuid;
begin
  if p_command->'expectedVersionId' is distinct from p_scope->'headId'
    or p_command->'expectedReviewRevision' is distinct from p_scope->'reviewRevision'
    or p_command->'expectedAssignmentRevision' is distinct from p_scope->'assignmentRevision'
    or (p_scope->'headId'<>'null'::jsonb and p_scope->'headAttemptId' is distinct from p_scope->'attemptId') then perform private.correction_fail('conflict'); end if;
  for item in select value from jsonb_array_elements(p_selectors) loop
    if not private.correction_latest(p_scope,item,p_selectors) then perform private.correction_fail('conflict'); end if;
    select * into current_choice from public.candidate_correction_assignments where correction_event_id=(item->>'eventId')::uuid order by assignment_revision desc limit 1;
    if p_command->>'kind'='assign' then
      if current_choice.id is distinct from (item->>'supersedesAssignmentId')::uuid then perform private.correction_fail('conflict'); end if;
    else
      if current_choice.id is distinct from (item->>'assignmentId')::uuid then perform private.correction_fail('conflict'); end if;
      select applied.* into prior from public.candidate_correction_applications applied
        join public.candidate_correction_assignments assigned on assigned.id=applied.assignment_id
        join public.canonical_resume_versions result on result.id=applied.result_version_id
        where assigned.correction_event_id=(item->>'eventId')::uuid order by result.revision desc limit 1;
      if p_command->>'kind'='reapply' then
        if prior.id is null or prior.id is distinct from (item->>'priorApplicationId')::uuid then perform private.correction_fail('conflict'); end if;
      elsif prior.id is not null or item->'priorApplicationId'<>'null'::jsonb then perform private.correction_fail('conflict'); end if;
      if (p_command->>'kind'='add' and item->>'mappingMode'<>'add')
        or (p_command->>'kind'='apply' and item->>'mappingMode'='add') then perform private.correction_fail('invalid'); end if;
    end if;
  end loop;
end;

private.correction_place:
declare s jsonb; e jsonb; b jsonb; sections jsonb:='[]'; entries jsonb; bullets jsonb; found_section boolean:=false;
  found_entry boolean:=false; found_bullet boolean:=false; kind text:=p_location->>'kind'; section_type text;
begin
  if kind='contact' then
    if p_field not in ('name','email','phone') or exists(select 1 from jsonb_array_elements(p_body->'facts') where value->>'type'=p_field) then perform private.correction_fail('invalid'); end if;
    return jsonb_set(p_body,'{contactFactIds}',(p_body->'contactFactIds')||jsonb_build_array(p_fact));
  end if;
  if p_field in ('name','email','phone') then perform private.correction_fail('invalid'); end if;
  if kind='new_section_entry' then
    section_type:=p_location->>'newSectionType';
    if (p_field in ('employer','role','dates') and section_type<>'experience') or (p_field='education' and section_type<>'education')
      or (p_field='certification' and section_type<>'certifications') then perform private.correction_fail('invalid'); end if;
    return jsonb_set(p_body,'{sections}',(p_body->'sections')||jsonb_build_array(jsonb_build_object('id',p_section,'type',section_type,
      'title',p_location->>'newSectionTitle','factIds','[]'::jsonb,'entries',jsonb_build_array(jsonb_build_object('id',p_entry,'factIds',jsonb_build_array(p_fact),'bullets','[]'::jsonb)))));
  end if;
  for s in select value from jsonb_array_elements(p_body->'sections') loop
    if s->>'id'=p_location->>'sectionId' then
      found_section:=true; section_type:=s->>'type';
      if (p_field in ('employer','role','dates') and (section_type<>'experience' or kind='section'))
        or (p_field='education' and section_type<>'education') or (p_field='certification' and section_type<>'certifications') then perform private.correction_fail('invalid'); end if;
      if kind='section' then s:=jsonb_set(s,'{factIds}',(s->'factIds')||jsonb_build_array(p_fact));
      elsif kind='new_entry' then
        s:=jsonb_set(s,'{entries}',(s->'entries')||jsonb_build_array(jsonb_build_object('id',p_entry,'factIds',jsonb_build_array(p_fact),'bullets','[]'::jsonb)));
      else
        entries:='[]';
        for e in select value from jsonb_array_elements(s->'entries') loop
          if e->>'id'=p_location->>'entryId' then
            found_entry:=true;
            if kind='entry' then e:=jsonb_set(e,'{factIds}',(e->'factIds')||jsonb_build_array(p_fact));
            elsif kind='bullet' then
              bullets:='[]';
              for b in select value from jsonb_array_elements(e->'bullets') loop
                bullets:=bullets||jsonb_build_array(b);
                if b->>'id'=p_location->>'bulletId' then
                  found_bullet:=true;
                  -- Preserve the selected factual bullet; insert one new singly-
                  -- linked sibling immediately after it, never merge/replace it.
                  bullets:=bullets||jsonb_build_array(jsonb_build_object('id',p_bullet,'text',p_value,'factIds',jsonb_build_array(p_fact)));
                end if;
              end loop;
              e:=jsonb_set(e,'{bullets}',bullets);
            else perform private.correction_fail('invalid'); end if;
          end if;
          entries:=entries||jsonb_build_array(e);
        end loop;
        s:=jsonb_set(s,'{entries}',entries);
      end if;
    end if;
    sections:=sections||jsonb_build_array(s);
  end loop;
  if not found_section or (kind in ('entry','bullet') and not found_entry) or (kind='bullet' and not found_bullet) then perform private.correction_fail('invalid'); end if;
  return jsonb_set(p_body,'{sections}',sections);
end;

private.correction_child_body:
declare base public.canonical_resume_versions%rowtype; event public.evidence_corrections%rowtype;
  previous public.candidate_correction_applications%rowtype; previous_choice public.candidate_correction_assignments%rowtype; original public.canonical_resume_versions%rowtype;
  evidence public.document_evidence_attempts%rowtype; assertion jsonb; fact jsonb; body jsonb; sections jsonb:='[]'; entries jsonb; bullets jsonb;
  s jsonb; e jsonb; b jsonb; fact_id uuid; new_fact uuid; count_value integer; changed jsonb; loc jsonb;
begin
  base.content:=p_parent; base.id:=(p_parent->>'versionId')::uuid; base.owner_id:=(p_parent->>'ownerId')::uuid;
  select * into strict event from public.evidence_corrections where id=(p_item->>'eventId')::uuid;
  if p_item->>'mappingMode'='existing' then fact_id:=(p_item->>'factId')::uuid; end if;
  if fact_id is null and p_item->'priorApplicationId'<>'null'::jsonb then
    select * into strict previous from public.candidate_correction_applications where id=(p_item->>'priorApplicationId')::uuid;
    select * into strict original from public.canonical_resume_versions where id=previous.result_version_id;
    select * into strict previous_choice from public.candidate_correction_assignments where id=previous.assignment_id;
    select value into fact from jsonb_array_elements(base.content->'facts') where value->>'id'=previous.result_fact_id::text and value->>'type'=event.field;
    if found and (p_item->>'mappingMode'<>'add' or (private.correction_selector_from_row(previous_choice)->'location')=p_item->'location') then
      fact_id:=previous.result_fact_id;
      if private.correction_location(base.content,fact_id)<>private.correction_location(original.content,fact_id) then perform private.correction_fail('conflict'); end if;
    end if;
  end if;
  if fact_id is null and p_item->>'mappingMode'='existing' then fact_id:=(p_item->>'factId')::uuid; end if;
  if fact_id is null and p_item->>'mappingMode'='imported_assertion' then
    select * into strict evidence from public.document_evidence_attempts where id=event.attempt_id;
    select value into strict assertion from jsonb_array_elements(evidence.envelope->'assertions') where value->>'id'=p_item->>'assertionId' and value->>'field'=event.field;
    select count(*),min((value->>'id')::text)::uuid into count_value,fact_id from jsonb_array_elements(base.content->'facts')
      where value->>'type'=event.field and private.correction_sorted_citations(value->'sources')=private.correction_citations(assertion,event.attempt_id);
    if count_value<>1 then perform private.correction_fail('conflict'); end if;
  end if;
  body:=base.content||jsonb_build_object('versionId',p_version,'parentVersionId',base.id,'createdAt',p_created);
  if fact_id is not null then
    select value into fact from jsonb_array_elements(base.content->'facts') where value->>'id'=fact_id::text and value->>'type'=event.field;
    if not found then perform private.correction_fail('conflict'); end if;
    perform private.correction_assert_fact_placement(base.content,fact_id,event.field);
    changed:=fact||jsonb_build_object('value',event.value,'state','unconfirmed','sources','[]'::jsonb,'confirmation',null);
    body:=jsonb_set(body,'{facts}',(select jsonb_agg(case when value->>'id'=fact_id::text then changed else value end order by ordinality)
      from jsonb_array_elements(base.content->'facts') with ordinality));
    for s in select value from jsonb_array_elements(base.content->'sections') loop
      entries:='[]';
      for e in select value from jsonb_array_elements(s->'entries') loop
        bullets:='[]';
        for b in select value from jsonb_array_elements(e->'bullets') loop
          if b->'factIds'=jsonb_build_array(fact_id) then b:=jsonb_set(b,'{text}',to_jsonb(event.value)); end if;
          bullets:=bullets||jsonb_build_array(b);
        end loop;
        entries:=entries||jsonb_build_array(jsonb_set(e,'{bullets}',bullets));
      end loop;
      sections:=sections||jsonb_build_array(jsonb_set(s,'{entries}',entries));
    end loop;
    body:=jsonb_set(body,'{sections}',sections);
    body:=jsonb_set(body,'{changes}',jsonb_build_array(jsonb_build_object('id',p_change,'actorId',base.owner_id,'action','edit',
      'targetId',fact_id,'priorValue',fact->>'value','createdAt',p_created)));
  else
    if p_item->>'mappingMode'<>'add' then perform private.correction_fail('invalid'); end if;
    new_fact:=gen_random_uuid();
    -- Placement operates on the old facts so contact duplicate checks remain
    -- independent of the one newly appended fact.
    body:=private.correction_place(body,p_item->'location',event.field,new_fact,event.value,gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
    body:=jsonb_set(body,'{facts}',(body->'facts')||jsonb_build_array(jsonb_build_object('id',new_fact,'type',event.field,'value',event.value,
      'state','unconfirmed','sources','[]'::jsonb,'confirmation',null)));
    body:=body||jsonb_build_object('producerVersion','canonical-engine/1.0.2','changes',jsonb_build_array(jsonb_build_object('id',p_change,
      'actorId',base.owner_id,'action','create','targetId',new_fact,'priorValue',null,'createdAt',p_created)));
  end if;
  return body;
end;

private.validate_correction_child:
declare evidence public.document_evidence_attempts%rowtype; op text:='add'; fact jsonb; citation jsonb; span jsonb;
  section jsonb; entry jsonb; bullet jsonb; event jsonb; ref text; object_ids text[]; references_ids text[]:='{}'; content_chars bigint;
begin
  if private.canonical_shape_valid(p_body) is not true or octet_length(p_body::text)>1048576 then perform private.correction_fail('invalid'); end if;
  select * into strict evidence from public.document_evidence_attempts where id=p_attempt and owner_id=p_user_id;
  if p_body->>'ownerId' is distinct from p_user_id::text or p_body->>'analysisId' is distinct from evidence.analysis_id::text
    or p_body->>'inputSha256' is distinct from evidence.input_sha256 or p_body->'retentionPolicyId' is distinct from evidence.envelope->'retentionPolicyId'
    or p_body->>'sourceEvidenceVersionId' is distinct from evidence.id::text then perform private.correction_fail('invalid'); end if;
  object_ids:=array[p_body->>'resumeId',p_body->>'versionId'];
  content_chars:=0;
  for fact in select value from jsonb_array_elements(p_body->'facts') loop
    object_ids:=array_append(object_ids,fact->>'id');
    content_chars:=content_chars+char_length(fact->>'value');
    if fact->>'value'<>btrim(fact->>'value') or fact->>'state'='source_supported' then
      raise exception 'Unsupported canonical fact' using errcode='22023'; end if;
    if (fact->>'state'='candidate_confirmed') is distinct from (fact->'confirmation'<>'null'::jsonb) then
      raise exception 'Confirmation state mismatch' using errcode='22023'; end if;
    if fact->'confirmation'<>'null'::jsonb and (fact->'confirmation'->>'actorId'<>p_user_id::text
      or fact->'confirmation'->>'value'<>fact->>'value') then raise exception 'Invalid confirmation' using errcode='22023'; end if;
    for citation in select value from jsonb_array_elements(fact->'sources') loop
      select value into span from jsonb_array_elements(evidence.envelope->'spans') where value->>'id'=citation->>'spanId';
      if span is null or citation->>'attemptId'<>evidence.id::text or (citation->>'end')::int<=(citation->>'start')::int
        or (citation->>'end')::int>char_length(span->>'text') then raise exception 'Invalid canonical citation' using errcode='22023'; end if;
      -- Source text is exact and Unicode code-point indexed, including OCR.
      if substring(span->>'text' from (citation->>'start')::int+1 for (citation->>'end')::int-(citation->>'start')::int)
        <> fact->>'value' then raise exception 'Fact does not match cited text' using errcode='22023'; end if;
    end loop;
    if op='import' and (fact->>'state'<>'unconfirmed' or jsonb_array_length(fact->'sources')=0) then
      raise exception 'Imports require uncertain sourced facts' using errcode='22023'; end if;
  end loop;
  for ref in select jsonb_array_elements_text(p_body->'contactFactIds') loop
    if not exists(select 1 from jsonb_array_elements(p_body->'facts') where value->>'id'=ref and value->>'type' in ('name','email','phone','link','location')) then
      raise exception 'Invalid contact reference' using errcode='22023'; end if;
  end loop;
  references_ids:=array(select jsonb_array_elements_text(p_body->'contactFactIds'));
  if cardinality(references_ids)<>(select count(distinct x) from unnest(references_ids) x) then
    raise exception 'Duplicate contact references' using errcode='22023'; end if;
  for section in select value from jsonb_array_elements(p_body->'sections') loop
    if jsonb_array_length(section->'factIds')<>(select count(distinct value) from jsonb_array_elements(section->'factIds')) then
      raise exception 'Duplicate section references' using errcode='22023'; end if;
    object_ids:=array_append(object_ids,section->>'id'); content_chars:=content_chars+char_length(section->>'title');
    references_ids:=references_ids||array(select jsonb_array_elements_text(section->'factIds'));
    for entry in select value from jsonb_array_elements(section->'entries') loop
      if jsonb_array_length(entry->'factIds')<>(select count(distinct value) from jsonb_array_elements(entry->'factIds')) then
        raise exception 'Duplicate entry references' using errcode='22023'; end if;
      object_ids:=array_append(object_ids,entry->>'id');
      references_ids:=references_ids||array(select jsonb_array_elements_text(entry->'factIds'));
      for bullet in select value from jsonb_array_elements(entry->'bullets') loop
        object_ids:=array_append(object_ids,bullet->>'id'); content_chars:=content_chars+char_length(bullet->>'text');
        references_ids:=references_ids||array(select jsonb_array_elements_text(bullet->'factIds'));
        if jsonb_array_length(bullet->'factIds')<>1 or not exists(select 1 from jsonb_array_elements(p_body->'facts') f
          where f.value->>'id'=bullet->'factIds'->>0 and f.value->>'value'=bullet->>'text') then
          raise exception 'Draft bullet must reference its exact factual content' using errcode='22023'; end if;
      end loop;
    end loop;
  end loop;
  if jsonb_array_length(p_body->'changes')<>1 then raise exception 'Exactly one append-only event required' using errcode='22023'; end if;
  event:=p_body->'changes'->0; object_ids:=array_append(object_ids,event->>'id');
  if content_chars>200000 or cardinality(object_ids)<>(select count(distinct x) from unnest(object_ids) x)
    or event->>'actorId'<>p_user_id::text or event->>'createdAt'<>p_body->>'createdAt' then raise exception 'Invalid canonical identities or event' using errcode='22023'; end if;
  for ref in select unnest(references_ids) loop
    if not exists(select 1 from jsonb_array_elements(p_body->'facts') where value->>'id'=ref) then raise exception 'Dangling fact reference' using errcode='22023'; end if;
  end loop;
end;

private.save_candidate_authored_fact:
declare base public.canonical_resume_versions%rowtype; choice public.candidate_correction_assignments%rowtype; event public.evidence_corrections%rowtype;
  application public.candidate_correction_applications%rowtype; fact jsonb; change jsonb; expected jsonb; section jsonb; entry jsonb; bullet jsonb;
  new_section uuid; new_entry uuid; new_bullet uuid; new_fact uuid; command jsonb;
begin
  select * into strict choice from public.candidate_correction_assignments where id=p_assignment;
  select * into strict event from public.evidence_corrections where id=choice.correction_event_id;
  select * into strict base from public.canonical_resume_versions where id=(p_body->>'parentVersionId')::uuid
    and owner_id=p_user_id and source_resume_version_id=p_source_id and resume_id=choice.resume_id and organization_id=choice.organization_id;
  perform 1 from public.canonical_resume_heads where resume_id=base.resume_id and version_id=base.id;
  if not found or choice.mapping_mode<>'add' or base.source_evidence_version_id<>choice.attempt_id then perform private.correction_fail('conflict'); end if;
  select * into strict application from public.candidate_correction_applications where result_version_id=(p_body->>'versionId')::uuid
    and assignment_id=choice.id and operation_id=p_operation and base_version_id=base.id;
  perform private.entry_regroup_validate_head(base.id);
  new_fact:=application.result_fact_id;
  fact:=jsonb_build_object('id',new_fact,'type',event.field,'value',event.value,'state','unconfirmed','sources','[]'::jsonb,'confirmation',null);
  if p_body->'facts' is distinct from (base.content->'facts')||jsonb_build_array(fact)
    or p_body->>'producerVersion' is distinct from 'canonical-engine/1.0.2'
    or (p_body-array['versionId','parentVersionId','createdAt','producerVersion','facts','sections','contactFactIds','changes'])
      is distinct from (base.content-array['versionId','parentVersionId','createdAt','producerVersion','facts','sections','contactFactIds','changes']) then perform private.correction_fail('invalid'); end if;
  change:=p_body->'changes'->0;
  if change is distinct from jsonb_build_object('id',change->>'id','actorId',p_user_id,'action','create','targetId',new_fact,'priorValue',null,'createdAt',p_body->>'createdAt') then
    perform private.correction_fail('invalid'); end if;
  if choice.location_kind='new_section_entry' then
    section:=p_body->'sections'->(jsonb_array_length(p_body->'sections')-1); new_section:=(section->>'id')::uuid; new_entry:=(section->'entries'->0->>'id')::uuid;
  elsif choice.location_kind='new_entry' then
    select value into strict section from jsonb_array_elements(p_body->'sections') where value->>'id'=choice.section_id::text;
    entry:=section->'entries'->(jsonb_array_length(section->'entries')-1); new_entry:=(entry->>'id')::uuid;
  elsif choice.location_kind='bullet' then
    select b.value into strict bullet from jsonb_array_elements(p_body->'sections') s cross join lateral jsonb_array_elements(s.value->'entries') e
      cross join lateral jsonb_array_elements(e.value->'bullets') b
      where s.value->>'id'=choice.section_id::text and e.value->>'id'=choice.entry_id::text and b.value->'factIds'=jsonb_build_array(new_fact);
    new_bullet:=(bullet->>'id')::uuid;
  end if;
  expected:=private.correction_place(base.content,private.correction_selector_from_row(choice)->'location',event.field,new_fact,event.value,new_section,new_entry,new_bullet);
  if p_body->'sections' is distinct from expected->'sections' or p_body->'contactFactIds' is distinct from expected->'contactFactIds' then perform private.correction_fail('invalid'); end if;
  perform private.validate_correction_child(p_body,p_user_id,choice.attempt_id);
  command:=jsonb_build_object('operation','add','expectedVersionId',base.id,'idempotencyKey',p_body->>'versionId','factId',new_fact,'value',event.value,'targetVersionId',null);
  insert into public.canonical_resume_versions(id,resume_id,source_resume_version_id,organization_id,owner_id,locale,state,content,created_at,
    parent_version_id,source_evidence_version_id,revision,idempotency_key,command,request_id)
    values((p_body->>'versionId')::uuid,base.resume_id,p_source_id,base.organization_id,p_user_id,p_body->>'locale',p_body->>'state',p_body,(p_body->>'createdAt')::timestamptz,
      base.id,choice.attempt_id,base.revision+1,(p_body->>'versionId')::uuid,command,p_request_id);
  insert into public.resume_facts(canonical_version_id,id,organization_id,owner_id,type,value,state,sources,confirmation)
    select (p_body->>'versionId')::uuid,(value->>'id')::uuid,base.organization_id,p_user_id,value->>'type',value->>'value',value->>'state',value->'sources',nullif(value->'confirmation','null'::jsonb)
      from jsonb_array_elements(p_body->'facts');
  insert into public.change_events(canonical_version_id,id,owner_id,organization_id,actor_id,operation,event,created_at)
    values((p_body->>'versionId')::uuid,(change->>'id')::uuid,p_user_id,base.organization_id,p_user_id,'add',change,(p_body->>'createdAt')::timestamptz);
  update public.canonical_resume_heads set version_id=(p_body->>'versionId')::uuid,revision=base.revision+1 where resume_id=base.resume_id;
  insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
    values(base.organization_id,p_user_id,'canonical.add','canonical_resume_version',(p_body->>'versionId')::uuid,'success',p_request_id);
  perform private.write_correction_snapshot((p_body->>'versionId')::uuid,command);
  return jsonb_build_object('status','applied','versionId',p_body->>'versionId','revision',base.revision+1,'idempotent',false);
end;

public.assign_candidate_correction_targe:
declare scope jsonb; selectors jsonb; item jsonb; location jsonb; command_hash text; replay jsonb;
  ids uuid[]:='{}'; op_id uuid; ordinal integer:=0;
begin
  -- This exception block encloses ALL writes: a failure rolls the whole action
  -- back, never JSON-returning a partially imported/applied transaction.
  perform private.correction_validate_command(p_command,true);
  if p_request_id is null or char_length(p_request_id) not between 1 and 100 then perform private.correction_fail('invalid'); end if;
  scope:=private.correction_scope(p_user_id,p_analysis_id);
  if not private.canonical_correction_write_ready() then perform private.correction_fail('unavailable'); end if;
  selectors:=private.correction_normalize(scope,p_command);
  command_hash:=private.correction_command_sha256(private.correction_atoms(scope,p_command,selectors));
  replay:=private.correction_replay(scope,p_command,selectors,command_hash);
  if replay is not null then return replay; end if;
  perform private.correction_admit_new(scope,p_command,selectors);
  if (scope->>'assignmentRevision')::bigint+jsonb_array_length(selectors)>1000 then perform private.correction_fail('unavailable'); end if;
  select array_agg(gen_random_uuid() order by ordinality) into ids from jsonb_array_elements(selectors) with ordinality;
  op_id:=private.correction_insert_operation(scope,p_command,command_hash,ids,'{}',null,(scope->>'headId')::uuid,(scope->>'headRevision')::integer,
    (scope->>'assignmentRevision')::bigint+cardinality(ids),p_request_id);
  for item in select value from jsonb_array_elements(selectors) loop
    ordinal:=ordinal+1; location:=item->'location';
    insert into public.candidate_correction_assignments(id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,attempt_id,input_sha256,
      operation_id,actor_id,assignment_revision,expected_assignment_revision,correction_event_id,correction_revision,field,event_operation,target_model_version,
      target_kind,assertion_id,opaque_target_id,supersedes_assignment_id,mapping_mode,base_version_id,fact_id,mapping_proof_kind,origin_version_id,origin_fact_id,
      location_kind,section_id,entry_id,bullet_id,new_section_type,new_section_title)
      values(ids[ordinal],p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid,
        scope->>'inputSha256',op_id,p_user_id,(scope->>'assignmentRevision')::bigint+ordinal,(scope->>'assignmentRevision')::bigint,
        (item->>'eventId')::uuid,(item->>'eventRevision')::integer,item->>'field','correct',scope->>'targetModelVersion',item->>'targetKind',item->>'assertionId',
        item->>'opaqueTargetId',(item->>'supersedesAssignmentId')::uuid,item->>'mappingMode',(item->>'baseVersionId')::uuid,(item->>'factId')::uuid,
        item->>'mappingProofKind',(item->>'originVersionId')::uuid,(item->>'originFactId')::uuid,location->>'kind',(location->>'sectionId')::uuid,
        (location->>'entryId')::uuid,(location->>'bulletId')::uuid,location->>'newSectionType',location->>'newSectionTitle');
  end loop;
  return private.correction_receipt(op_id,false);
exception
  when insufficient_privilege then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','not_found');
  when sqlstate 'P0C01' or unique_violation then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','conflict');
  when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','invalid');
  when others then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','unavailable');
end;

public.apply_candidate_corrections:
declare scope jsonb; selectors jsonb; item jsonb; body jsonb; parent_body jsonb; plans jsonb:='[]'; replay jsonb; command_hash text;
  selected_ids uuid[]; children uuid[]:='{}'; initial_id uuid; parent_id uuid; final_id uuid; op_id uuid; app_id uuid; result_fact uuid;
  ordinal integer:=0; offset_value integer:=0; total_bytes bigint:=0; revision_value integer; created text; result jsonb; canonical_command jsonb;
begin
  perform private.correction_validate_command(p_command,false);
  if p_request_id is null or char_length(p_request_id) not between 1 and 100 then perform private.correction_fail('invalid'); end if;
  scope:=private.correction_scope(p_user_id,p_analysis_id);
  if not private.canonical_correction_write_ready() then perform private.correction_fail('unavailable'); end if;
  selectors:=private.correction_normalize(scope,p_command);
  command_hash:=private.correction_command_sha256(private.correction_atoms(scope,p_command,selectors));
  replay:=private.correction_replay(scope,p_command,selectors,command_hash);
  if replay is not null then return replay; end if;
  perform private.correction_admit_new(scope,p_command,selectors);
  parent_id:=(scope->>'headId')::uuid; revision_value:=coalesce((scope->>'headRevision')::integer,0);
  if parent_id is null then
    if jsonb_typeof(p_import_body) is distinct from 'object' or private.canonical_shape_valid(p_import_body) is not true
      or p_import_body->'parentVersionId' is distinct from 'null'::jsonb or p_import_body->>'producerVersion' not in ('canonical-engine/1.0.0','canonical-engine/1.0.1')
      or (p_import_body->>'ownerId',p_import_body->>'organizationId',p_import_body->>'resumeId',p_import_body->>'analysisId',p_import_body->>'sourceEvidenceVersionId',p_import_body->>'inputSha256')
        is distinct from (scope->>'ownerId',scope->>'organizationId',scope->>'resumeId',scope->>'analysisId',scope->>'attemptId',scope->>'inputSha256') then perform private.correction_fail('invalid'); end if;
    parent_body:=p_import_body; initial_id:=(p_import_body->>'versionId')::uuid; children:=array[initial_id]; offset_value:=1;
    total_bytes:=octet_length(p_import_body::text); if total_bytes>1048576 then perform private.correction_fail('invalid'); end if;
  else
    if p_import_body is not null and p_import_body<>'null'::jsonb then perform private.correction_fail('invalid'); end if;
    select content into strict parent_body from public.canonical_resume_versions where id=parent_id;
  end if;
  -- Freeze bounded child plans BEFORE any canonical/ledger write. Technical
  -- IDs are allocated only after exact replay and all fresh CAS/target checks.
  for item in select value from jsonb_array_elements(selectors) loop
    final_id:=gen_random_uuid(); created:=to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
    body:=private.correction_child_body(parent_body,final_id,item,created,gen_random_uuid());
    if octet_length(body::text)>1048576 then perform private.correction_fail('invalid'); end if;
    total_bytes:=total_bytes+octet_length(body::text); if total_bytes>8388608 then perform private.correction_fail('unavailable'); end if;
    plans:=plans||jsonb_build_array(body); children:=array_append(children,final_id); parent_body:=body;
  end loop;
  select array_agg((value->>'assignmentId')::uuid order by ordinality) into selected_ids from jsonb_array_elements(selectors) with ordinality;
  op_id:=private.correction_insert_operation(scope,p_command,command_hash,selected_ids,children,initial_id,final_id,
    revision_value+cardinality(children),(scope->>'assignmentRevision')::bigint,p_request_id);
  if initial_id is not null then
    canonical_command:=jsonb_build_object('operation','import','expectedVersionId',null,'idempotencyKey',initial_id,'factId',null,'value',null,'targetVersionId',null);
    result:=public.save_canonical_version(p_user_id,(scope->>'sourceId')::uuid,p_import_body,canonical_command,p_request_id);
    if result->>'status' is distinct from 'applied' or result->'idempotent' is distinct from 'false'::jsonb or result->>'versionId' is distinct from initial_id::text then perform private.correction_fail('conflict'); end if;
    parent_id:=initial_id;
  end if;
  for item in select value from jsonb_array_elements(selectors) loop
    body:=plans->ordinal; ordinal:=ordinal+1;
    result_fact:=(body->'changes'->0->>'targetId')::uuid; app_id:=gen_random_uuid();
    insert into public.candidate_correction_applications(id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,attempt_id,input_sha256,
      operation_id,assignment_id,actor_id,step_ordinal,base_version_id,result_version_id,result_fact_id,supersedes_application_id)
      values(app_id,p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid,
        scope->>'inputSha256',op_id,(item->>'assignmentId')::uuid,p_user_id,ordinal,parent_id,(body->>'versionId')::uuid,result_fact,(item->>'priorApplicationId')::uuid);
    if body->'changes'->0->>'action'='create' then
      result:=private.save_candidate_authored_fact(p_user_id,(scope->>'sourceId')::uuid,body,(item->>'assignmentId')::uuid,op_id,p_request_id);
    else
      canonical_command:=jsonb_build_object('operation','edit','expectedVersionId',parent_id,'idempotencyKey',body->>'versionId','factId',result_fact,
        'value',(select value->>'value' from jsonb_array_elements(body->'facts') where value->>'id'=result_fact::text),'targetVersionId',null);
      result:=public.save_canonical_version(p_user_id,(scope->>'sourceId')::uuid,body,canonical_command,p_request_id);
    end if;
    if result->>'status' is distinct from 'applied' or result->'idempotent' is distinct from 'false'::jsonb or result->>'versionId' is distinct from body->>'versionId' then perform private.correction_fail('conflict'); end if;
    parent_id:=(body->>'versionId')::uuid;
  end loop;
  return private.correction_receipt(op_id,false);
exception
  when insufficient_privilege then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','not_found');
  when sqlstate 'P0C01' or unique_violation then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','conflict');
  when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','invalid');
  when others then return jsonb_build_object('schemaVersion','candidate-correction-result/1.0.0','status','unavailable');
end;

public.read_candidate_correction_ledger:
declare scope jsonb; result jsonb; table_name text; count_value bigint;
begin
  scope:=private.correction_scope(p_user_id,p_analysis_id);
  if (select count(*) from public.candidate_correction_operations where analysis_id=p_analysis_id)>1000
    or (select count(*) from public.candidate_correction_applications where analysis_id=p_analysis_id)>1000
    or (select count(*) from public.canonical_correction_snapshots where resume_id=(scope->>'resumeId')::uuid and source_resume_version_id=(scope->>'sourceId')::uuid)>1000
    or (select count(*) from public.canonical_correction_snapshot_facts f join public.canonical_correction_snapshots s on s.canonical_version_id=f.canonical_version_id
      where s.resume_id=(scope->>'resumeId')::uuid and s.source_resume_version_id=(scope->>'sourceId')::uuid)>20000 then perform private.correction_fail('unavailable'); end if;
  select jsonb_build_object('schemaVersion','candidate-correction-ledger/1.0.0','status','ready','writeReady',private.canonical_correction_write_ready(),
    'scoringEligible',false,'binding',scope-array['headId','headRevision','headAttemptId','reviewRevision','assignmentRevision'],
    'reviewRevision',scope->'reviewRevision','assignmentRevision',scope->'assignmentRevision','headId',scope->'headId',
    'operations',coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at,o.id) from public.candidate_correction_operations o where o.analysis_id=p_analysis_id),'[]'::jsonb),
    'assignments',coalesce((select jsonb_agg(to_jsonb(a) order by a.assignment_revision) from public.candidate_correction_assignments a where a.analysis_id=p_analysis_id),'[]'::jsonb),
    'applications',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at,a.id) from public.candidate_correction_applications a where a.analysis_id=p_analysis_id),'[]'::jsonb),
    'snapshots',coalesce((select jsonb_agg(to_jsonb(s) order by s.created_at,s.canonical_version_id) from public.canonical_correction_snapshots s
      where s.resume_id=(scope->>'resumeId')::uuid and s.source_resume_version_id=(scope->>'sourceId')::uuid),'[]'::jsonb),
    'snapshotFacts',coalesce((select jsonb_agg(to_jsonb(f) order by f.canonical_version_id,f.fact_id) from public.canonical_correction_snapshot_facts f
      join public.canonical_correction_snapshots s on s.canonical_version_id=f.canonical_version_id
      where s.resume_id=(scope->>'resumeId')::uuid and s.source_resume_version_id=(scope->>'sourceId')::uuid),'[]'::jsonb)) into result;
  if octet_length(result::text)>8388608 then perform private.correction_fail('unavailable'); end if;
  return result;
exception when insufficient_privilege then return jsonb_build_object('schemaVersion','candidate-correction-ledger/1.0.0','status','not_found');
  when others then return jsonb_build_object('schemaVersion','candidate-correction-ledger/1.0.0','status','unavailable');
end;

private.correction_original_import_allow:
declare evidence public.document_evidence_attempts%rowtype; event public.evidence_corrections%rowtype;
  choice public.candidate_correction_assignments%rowtype; assertion jsonb; assertion_id text; assertion_count integer;
  resolved jsonb:='[]'::jsonb;
begin
  select * into strict evidence from public.document_evidence_attempts where id=(p_scope->>'attemptId')::uuid;
  for event in select * from public.evidence_corrections where analysis_id=(p_scope->>'analysisId')::uuid
    and attempt_id=evidence.id order by revision loop
    if (event.owner_id,event.organization_id,event.actor_id) is distinct from
      ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'ownerId')::uuid)
      or event.field not in ('name','email','phone','employer','role','dates','education','certification')
      or event.operation not in ('correct','confirm') then perform private.correction_fail('unavailable'); end if;
    assertion_id:=null; assertion:=null;
    if event.operation='confirm' then
      assertion_id:=event.candidate_id;
    else
      if event.candidate_id is not null then perform private.correction_fail('unavailable'); end if;
      select * into choice from public.candidate_correction_assignments where correction_event_id=event.id
        order by assignment_revision desc limit 1;
      if found then
        if (choice.owner_id,choice.organization_id,choice.resume_id,choice.analysis_id,choice.source_resume_version_id,
            choice.attempt_id,choice.input_sha256,choice.actor_id,choice.field,choice.correction_revision,choice.target_model_version)
          is distinct from ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,
            (p_scope->>'analysisId')::uuid,(p_scope->>'sourceId')::uuid,evidence.id,p_scope->>'inputSha256',
            (p_scope->>'ownerId')::uuid,event.field,event.revision,p_scope->>'targetModelVersion') then
          perform private.correction_fail('unavailable'); end if;
        if choice.target_kind<>'observed_assertion' or choice.assertion_id is null then return false; end if;
        assertion_id:=choice.assertion_id;
      else
        select count(*),min(value->>'id') into assertion_count,assertion_id
          from jsonb_array_elements(evidence.envelope->'assertions') where value->>'field'=event.field;
        if assertion_count<>1 then return false; end if;
      end if;
    end if;
    select count(*),jsonb_agg(value)->0 into assertion_count,assertion
      from jsonb_array_elements(evidence.envelope->'assertions') where value->>'id'=assertion_id and value->>'field'=event.field;
    if assertion_count<>1 or (event.operation='confirm' and assertion->>'value' is distinct from event.value) then
      perform private.correction_fail('unavailable'); end if;
    resolved:=resolved||jsonb_build_array(jsonb_build_object('field',event.field,'assertion_id',assertion_id,
      'operation',event.operation,'revision',event.revision));
  end loop;
  return not exists(select 1 from (
    select distinct on (r.field,r.assertion_id) r.operation from jsonb_to_recordset(resolved)
      as r(field text,assertion_id text,operation text,revision integer)
      order by r.field,r.assertion_id,r.revision desc
  ) latest where latest.operation<>'confirm');
end;

public.import_canonical_original:
declare scope jsonb; key text; prior public.canonical_resume_versions%rowtype; result jsonb;
begin
  if private.evidence_keys(p_binding,array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256',
      'evidenceSchemaVersion','fieldExtractorVersion','targetModelVersion','projectionModelVersion','admissionPolicyVersion',
      'reviewRevision','assignmentRevision','canonicalHeadId']) is not true
    or private.evidence_keys(p_command,array['operation','expectedVersionId','idempotencyKey','factId','value','targetVersionId']) is not true
    or p_command->>'operation' is distinct from 'import' or p_command->'expectedVersionId' is distinct from 'null'::jsonb
    or p_command->'factId' is distinct from 'null'::jsonb or p_command->'value' is distinct from 'null'::jsonb
    or p_command->'targetVersionId' is distinct from 'null'::jsonb
    or jsonb_typeof(p_command->'idempotencyKey') is distinct from 'string'
    or private.correction_uuid(to_jsonb(lower(p_command->>'idempotencyKey'))) is not true
    or private.evidence_integer(p_binding->'reviewRevision',0,2147483647) is not true
    or private.evidence_integer(p_binding->'assignmentRevision',0,2147483647) is not true
    or private.correction_uuid(p_binding->'canonicalHeadId',true) is not true
    or p_request_id is null or char_length(p_request_id) not between 1 and 100
    or private.canonical_shape_valid(p_body) is not true or octet_length(p_body::text)>1048576
    or p_body->>'producerVersion' not in ('canonical-engine/1.0.0','canonical-engine/1.0.1')
    or p_body->'parentVersionId' is distinct from 'null'::jsonb then perform private.correction_fail('invalid'); end if;
  scope:=private.correction_scope(p_user_id,p_analysis_id);
  if not private.canonical_correction_write_ready() then perform private.correction_fail('unavailable'); end if;
  foreach key in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256',
    'evidenceSchemaVersion','fieldExtractorVersion','targetModelVersion','projectionModelVersion','admissionPolicyVersion'] loop
    if p_binding->key is distinct from scope->key then perform private.correction_fail('conflict'); end if;
  end loop;
  if (p_body->>'ownerId',p_body->>'organizationId',p_body->>'resumeId',p_body->>'analysisId',p_body->>'sourceEvidenceVersionId',p_body->>'inputSha256')
    is distinct from (scope->>'ownerId',scope->>'organizationId',scope->>'resumeId',scope->>'analysisId',scope->>'attemptId',scope->>'inputSha256') then
    perform private.correction_fail('conflict'); end if;
  -- Current authority/source/attempt precede replay. Captured revisions/head are
  -- fresh admission preconditions, not new semantic replay identity. Generated
  -- body IDs are deliberately ignored, matching the existing legacy command.
  select * into prior from public.canonical_resume_versions where resume_id=(scope->>'resumeId')::uuid
    and idempotency_key=(p_command->>'idempotencyKey')::uuid;
  if found then
    if prior.command is distinct from p_command or prior.parent_version_id is not null
      or (prior.owner_id,prior.organization_id,prior.source_resume_version_id,prior.source_evidence_version_id)
        is distinct from ((scope->>'ownerId')::uuid,(scope->>'organizationId')::uuid,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid)
      or prior.content->>'analysisId' is distinct from scope->>'analysisId'
      or prior.content->>'inputSha256' is distinct from scope->>'inputSha256'
      or prior.content->>'producerVersion' not in ('canonical-engine/1.0.0','canonical-engine/1.0.1')
      or private.canonical_shape_valid(prior.content) is not true then perform private.correction_fail('conflict'); end if;
    return jsonb_build_object('status','applied','versionId',prior.id,'revision',prior.revision,'idempotent',true);
  end if;
  if scope->'headId' is distinct from 'null'::jsonb or p_binding->'canonicalHeadId' is distinct from scope->'headId'
    or p_binding->'reviewRevision' is distinct from scope->'reviewRevision'
    or p_binding->'assignmentRevision' is distinct from scope->'assignmentRevision' then perform private.correction_fail('conflict'); end if;
  if private.correction_original_import_allowed(scope) is not true then perform private.correction_fail('conflict'); end if;
  result:=public.save_canonical_version(p_user_id,(scope->>'sourceId')::uuid,p_body,p_command,p_request_id);
  if result->>'status' in ('not_found','conflict') then perform private.correction_fail(result->>'status'); end if;
  if private.evidence_keys(result,array['status','versionId','revision','idempotent']) is not true
    or result->>'status' is distinct from 'applied' or result->>'versionId' is distinct from p_body->>'versionId'
    or result->'revision' is distinct from '1'::jsonb or result->'idempotent' is distinct from 'false'::jsonb then
    perform private.correction_fail('unavailable'); end if;
  return result;
exception
  when insufficient_privilege then return jsonb_build_object('status','not_found');
  when sqlstate 'P0C01' or unique_violation then return jsonb_build_object('status','conflict');
  when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('status','invalid');
  when others then return jsonb_build_object('status','unavailable');
end;

private.jd_relation_canonical_json:
declare kind text collate "C"; result text collate "C"; item jsonb; key text collate "C"; number_value numeric;
  separator text collate "C":=case when p_spaced then ', ' else ',' end;
begin
  if p_value is null or p_depth>32 then raise exception 'Invalid JD semantic value' using errcode='22023'; end if;
  kind:=jsonb_typeof(p_value);
  if kind in ('null','boolean','string') then return p_value::text; end if;
  if kind='number' then
    number_value:=(p_value#>>'{}')::numeric;
    if number_value<>trunc(number_value) or abs(number_value)>9007199254740991 then
      raise exception 'Invalid JD semantic integer' using errcode='22023'; end if;
    return number_value::bigint::text;
  end if;
  result:='';
  if kind='array' then
    for item in select value from jsonb_array_elements(p_value) loop
      if result<>'' then result:=result||separator; end if;
      result:=result||private.jd_relation_canonical_json(item,p_spaced,p_depth+1);
    end loop;
    return '['||result||']';
  elsif kind='object' then
    for key in select value from jsonb_object_keys(p_value) as keys(value) order by value collate "C" loop
      if key collate "C" !~ '^[ -~]+$' then raise exception 'Invalid JD semantic key' using errcode='22023'; end if;
      if result<>'' then result:=result||separator; end if;
      result:=result||to_jsonb(key)::text||case when p_spaced then ': ' else ':' end
        ||private.jd_relation_canonical_json(p_value->key,p_spaced,p_depth+1);
    end loop;
    return '{'||result||'}';
  end if;
  raise exception 'Invalid JD semantic type' using errcode='22023';
end;

private.jd_relation_in_ranges:
declare low_value integer:=0; high_value integer:=jsonb_array_length(p_ranges)-1; middle_value integer; pair jsonb;
begin
  while low_value<=high_value loop
    middle_value:=(low_value+high_value)/2; pair:=p_ranges->middle_value;
    if p_codepoint<(pair->>0)::integer then high_value:=middle_value-1;
    elsif p_codepoint>(pair->>1)::integer then low_value:=middle_value+1;
    else return true; end if;
  end loop;
  return false;
end;

private.jd_relation_mapping:
declare low_value integer:=0; high_value integer:=jsonb_array_length(p_pairs)-1; middle_value integer; pair jsonb;
begin
  while low_value<=high_value loop
    middle_value:=(low_value+high_value)/2; pair:=p_pairs->middle_value;
    if p_codepoint<(pair->>0)::integer then high_value:=middle_value-1;
    elsif p_codepoint>(pair->>0)::integer then low_value:=middle_value+1;
    else return pair->1; end if;
  end loop;
  return null;
end;

private.jd_relation_lower:
declare data jsonb:=private.jd_relation_unicode_profile()->'data'; result text collate "C":=''; scalar text collate "C"; point integer;
  mapped jsonb; target jsonb; position_value integer; cursor_value integer; before_cased boolean; after_cased boolean;
begin
  for position_value in 1..char_length(p_text) loop
    scalar:=substring(p_text from position_value for 1); point:=ascii(scalar);
    if point=931 then
      before_cased:=false; after_cased:=false; cursor_value:=position_value-1;
      while cursor_value>=1 loop
        point:=ascii(substring(p_text from cursor_value for 1));
        if not private.jd_relation_in_ranges(data->'caseIgnorableRanges',point) then
          before_cased:=private.jd_relation_in_ranges(data->'casedRanges',point); exit; end if;
        cursor_value:=cursor_value-1;
      end loop;
      cursor_value:=position_value+1;
      while cursor_value<=char_length(p_text) loop
        point:=ascii(substring(p_text from cursor_value for 1));
        if not private.jd_relation_in_ranges(data->'caseIgnorableRanges',point) then
          after_cased:=private.jd_relation_in_ranges(data->'casedRanges',point); exit; end if;
        cursor_value:=cursor_value+1;
      end loop;
      if before_cased and not after_cased then result:=result||chr(962); continue; end if;
      point:=931;
    end if;
    mapped:=private.jd_relation_mapping(data->'defaultLowerMappings',point);
    if mapped is null then result:=result||scalar;
    else for target in select value from jsonb_array_elements(mapped) loop result:=result||chr((target#>>'{}')::integer); end loop; end if;
  end loop;
  return result;
end;

private.jd_relation_fold:
declare pairs jsonb:=private.jd_relation_unicode_profile()->'data'->'regexAsciiFoldMappings';
  result text collate "C":=''; scalar text collate "C"; mapped jsonb; position_value integer;
begin
  for position_value in 1..char_length(p_text) loop
    scalar:=substring(p_text from position_value for 1); mapped:=private.jd_relation_mapping(pairs,ascii(scalar));
    result:=result||case when mapped is null then scalar else chr((mapped#>>'{}')::integer) end;
  end loop;
  return result;
end;

private.jd_relation_trim:
declare ranges jsonb:=private.jd_relation_unicode_profile()->'data'->'whitespaceRanges'; first_value integer:=1; last_value integer:=char_length(p_text);
begin
  while first_value<=last_value and private.jd_relation_in_ranges(ranges,ascii(substring(p_text from first_value for 1))) loop first_value:=first_value+1; end loop;
  while last_value>=first_value and private.jd_relation_in_ranges(ranges,ascii(substring(p_text from last_value for 1))) loop last_value:=last_value-1; end loop;
  return substring(p_text from first_value for greatest(0,last_value-first_value+1));
end;

private.jd_relation_normalize:
declare ranges jsonb:=private.jd_relation_unicode_profile()->'data'->'whitespaceRanges'; source text collate "C":=private.jd_relation_lower(p_text);
  result text collate "C":=''; scalar text collate "C"; position_value integer; was_space boolean:=false;
begin
  if p_trim then source:=private.jd_relation_trim(source); end if;
  for position_value in 1..char_length(source) loop
    scalar:=substring(source from position_value for 1);
    if private.jd_relation_in_ranges(ranges,ascii(scalar)) then
      if not was_space then result:=result||' '; end if; was_space:=true;
    else result:=result||scalar; was_space:=false; end if;
  end loop;
  return result;
end;

private.jd_relation_class_contents:
declare result text collate "C":=''; pair jsonb;
begin
  for pair in select value from jsonb_array_elements(p_ranges) loop
    result:=result||chr((pair->>0)::integer)||case when pair->>0=pair->>1 then '' else '-'||chr((pair->>1)::integer) end;
  end loop;
  return result;
end;

private.jd_relation_pattern:
declare result text collate "C":=p_pattern; data jsonb:=private.jd_relation_unicode_profile()->'data';
begin
  result:=replace(result,'\p{L}\p{N}\p{M}',private.jd_relation_class_contents(data->'identifierRanges'));
  result:=replace(result,'\p{L}\p{N}',private.jd_relation_class_contents(private.jd_relation_ln_ranges()));
  result:=replace(result,'\s','['||private.jd_relation_class_contents(data->'whitespaceRanges')||']');
  result:=replace(result,'\d','[0-9]');
  -- On the scalar-preserving ASCII /iu fold, JS regex-word is [a-z0-9_].
  result:=replace(result,'\b','(?:(?<![a-z0-9_])(?=[a-z0-9_])|(?<=[a-z0-9_])(?![a-z0-9_]))');
  return result;
end;

private.jd_relation_matches:
declare source text collate "C":=case when p_fold then private.jd_relation_fold(p_text) else p_text end;
  pattern text collate "C":=private.jd_relation_pattern(p_pattern); result jsonb:='[]'; groups_value jsonb;
  cursor_value integer:=1; start_value integer; end_value integer; group_start integer; group_end integer; group_value integer;
begin
  if p_groups not between 0 and 8 or p_limit not between 1 and 1000 then raise exception 'Invalid JD regex work bound' using errcode='22023'; end if;
  loop
    start_value:=regexp_instr(source collate "C",pattern, cursor_value,1,0);
    exit when start_value=0;
    end_value:=regexp_instr(source collate "C",pattern,cursor_value,1,1);
    if end_value<=start_value or jsonb_array_length(result)>=p_limit then raise exception 'JD regex work limit' using errcode='22023'; end if;
    groups_value:='[]';
    for group_value in 1..p_groups loop
      group_start:=regexp_instr(source collate "C",pattern,cursor_value,1,0,'',group_value);
      group_end:=regexp_instr(source collate "C",pattern,cursor_value,1,1,'',group_value);
      groups_value:=groups_value||jsonb_build_array(case when group_start=0 then 'null'::jsonb else
        jsonb_build_object('start',group_start-1,'end',group_end-1,'quote',substring(p_text from group_start for group_end-group_start)) end);
    end loop;
    result:=result||jsonb_build_array(jsonb_build_object('start',start_value-1,'end',end_value-1,
      'quote',substring(p_text from start_value for end_value-start_value),'groups',groups_value));
    exit when p_first;
    cursor_value:=end_value;
  end loop;
  return result;
end;

private.jd_relation_literals:
declare source text collate "C":=private.jd_relation_fold(p_text); literal_value text collate "C":=private.jd_relation_fold(p_literal);
  ranges jsonb; result jsonb:='[]'; cursor_value integer:=1; found_value integer; end_value integer; point integer; accepted boolean;
begin
  if literal_value='' or p_boundary not in ('ln','alias') then raise exception 'Invalid JD literal policy' using errcode='22023'; end if;
  ranges:=case when p_boundary='ln' then private.jd_relation_ln_ranges() else private.jd_relation_unicode_profile()->'data'->'identifierRanges' end;
  loop
    found_value:=strpos(substring(source from cursor_value) collate "C",literal_value collate "C");
    exit when found_value=0;
    found_value:=found_value+cursor_value-1; end_value:=found_value+char_length(literal_value); accepted:=true;
    if found_value>1 then
      point:=ascii(substring(source from found_value-1 for 1));
      accepted:=not private.jd_relation_in_ranges(ranges,point) and not (p_boundary='alias' and point in (36,95,46));
    end if;
    if accepted and end_value<=char_length(source) then
      point:=ascii(substring(source from end_value for 1));
      accepted:=not private.jd_relation_in_ranges(ranges,point) and not (p_boundary='alias' and point in (36,95));
      if accepted and p_boundary='alias' and point=46 and end_value<char_length(source) then
        point:=ascii(substring(source from end_value+1 for 1));
        accepted:=not private.jd_relation_in_ranges(ranges,point) and point not in (36,95);
      end if;
    end if;
    if accepted then
      if jsonb_array_length(result)>=case when p_boundary='alias' then 300 else 1000 end then raise exception 'JD literal work limit' using errcode='22023'; end if;
      result:=result||jsonb_build_array(jsonb_build_object('start',found_value-1,'end',end_value-1,'quote',substring(p_text from found_value for end_value-found_value)));
    end if;
    cursor_value:=case when accepted then end_value else found_value+1 end;
  end loop;
  return result;
end;

private.jd_relation_source_lines:
declare result jsonb:='[]'; line text collate "C"; labels jsonb; segments jsonb; parts jsonb; separators jsonb;
  segment jsonb; part jsonb; label jsonb; separator jsonb; raw text collate "C"; text_value text collate "C"; metadata_value text collate "C";
  offset_value integer:=0; first_value integer; end_value integer; leading_value integer; index_value integer;
  ranges jsonb:=private.jd_relation_unicode_profile()->'data'->'whitespaceRanges';
begin
  foreach line in array string_to_array(p_source,E'\n') loop
    labels:='[]';
    if private.jd_relation_test(private.jd_relation_trim(line),'^(?:title|role|location|employment\s*type|exp(?:erience)?\s*range)\s*:') then
      labels:=private.jd_relation_matches(line,'(?:title|role|location|employment\s*type|exp(?:erience)?\s*range)\s*:',0,1000);
    end if;
    segments:='[]';
    if jsonb_array_length(labels)>0 then
      for index_value in 0..jsonb_array_length(labels)-1 loop
        label:=labels->index_value;
        metadata_value:=private.jd_relation_lower(private.jd_relation_trim(split_part(label->>'quote',':',1)));
        segments:=segments||jsonb_build_array(jsonb_build_object('begin',label->'start','end',
          coalesce((labels->(index_value+1)->>'start')::integer,char_length(line)),'kind',metadata_value));
      end loop;
    else segments:=jsonb_build_array(jsonb_build_object('begin',0,'end',char_length(line),'kind',null)); end if;
    for segment in select value from jsonb_array_elements(segments) loop
      parts:='[]'; first_value:=(segment->>'begin')::integer;
      if segment->'kind'<>'null'::jsonb then parts:=jsonb_build_array(segment);
      else
        raw:=substring(line from first_value+1 for (segment->>'end')::integer-first_value);
        separators:=private.jd_relation_matches(raw,';\s*|(?:,\s*|,?\s+and\s+)(?=(?:\d{1,2}\s*\+?\s*years?|no\b|not\b))|\s+but\s+(?=(?:no|not)\b)',0,1000);
        for separator in select value from jsonb_array_elements(separators) loop
          parts:=parts||jsonb_build_array(jsonb_build_object('begin',first_value,'end',(segment->>'begin')::integer+(separator->>'start')::integer,'kind',null));
          first_value:=(segment->>'begin')::integer+(separator->>'end')::integer;
        end loop;
        parts:=parts||jsonb_build_array(jsonb_build_object('begin',first_value,'end',segment->'end','kind',null));
      end if;
      for part in select value from jsonb_array_elements(parts) loop
        first_value:=(part->>'begin')::integer; end_value:=(part->>'end')::integer;
        raw:=substring(line from first_value+1 for end_value-first_value); text_value:=private.jd_relation_trim(raw);
        leading_value:=0;
        while leading_value<char_length(raw) and private.jd_relation_in_ranges(ranges,ascii(substring(raw from leading_value+1 for 1))) loop
          leading_value:=leading_value+1;
        end loop;
        if text_value='' then leading_value:=0; end if;
        result:=result||jsonb_build_array(jsonb_build_object('text',text_value,'start',offset_value+first_value+leading_value,
          'end',offset_value+first_value+leading_value+char_length(text_value),'metadata',part->'kind'));
      end loop;
    end loop;
    offset_value:=offset_value+char_length(line)+1;
  end loop;
  return result;
end;

private.jd_relation_heading:
begin
  if private.jd_relation_test(p_text,'^(requirements|job requirements|qualifications|required qualifications|basic qualifications|minimum qualifications|required skills(?: and experience)?|skills and experience|must have|essential skills):?$') then
    return jsonb_build_object('heading','required','company',false);
  elsif private.jd_relation_test(p_text,'^(preferred qualifications|preferred|nice to have):?$') then
    return jsonb_build_object('heading','preferred','company',false);
  elsif private.jd_relation_test(p_text,'^((?:key |job )?responsibilities|duties):?$') then
    return jsonb_build_object('heading','contextual','company',false);
  elsif private.jd_relation_test(p_text,'^about (?:the job|this role):?$') then
    return jsonb_build_object('heading','unknown','company',false);
  elsif private.jd_relation_test(p_text,'^(benefits|about (?!the job\b|this role\b)[\p{L}\p{N}][\p{L}\p{N}& .,''’–-]{0,80}|company overview|equal opportunity):?$') then
    return jsonb_build_object('heading','unknown','company',true);
  end if;
  return null;
end;

private.jd_relation_importance:
declare required_value boolean; preferred_value boolean; value text collate "C";
begin
  required_value:=private.jd_relation_test(regexp_replace(private.jd_relation_fold(p_text) collate "C",
    private.jd_relation_pattern('\bwhere required\b'),'','g'),'\b(must|required|mandatory|essential|minimum)\b');
  preferred_value:=private.jd_relation_test(p_text,'\b(preferred|desirable|nice[ -]to[ -]have|bonus|optional)\b');
  if required_value and preferred_value then return jsonb_build_object('importance','unknown','importanceBasis','unknown','ambiguity',jsonb_build_array('conflicting_importance')); end if;
  value:=case when required_value then 'required' when preferred_value then 'preferred' else p_heading end;
  return jsonb_build_object('importance',value,'importanceBasis',case when value='unknown' then 'unknown' else 'explicit' end,'ambiguity','[]'::jsonb);
end;

private.jd_relation_alias:
declare literal_value text collate "C":=private.jd_relation_lower(p_value); kind text collate "C":='unmapped'; concept text collate "C"; canonical_value text collate "C";
begin
  if literal_value in ('javascript','js') then
    concept:='local-software:javascript'; canonical_value:='JavaScript'; kind:=case when literal_value='javascript' then 'exact' else 'alias' end;
  elsif literal_value in ('postgresql','postgres') then
    concept:='local-software:postgresql'; canonical_value:='PostgreSQL'; kind:=case when literal_value='postgresql' then 'exact' else 'alias' end;
  end if;
  return jsonb_build_object('kind',kind,'policyVersion','jd-local-aliases/1.0.0','conceptId',concept,'canonicalValue',canonical_value,
    'prospectiveCreditGroup',case when concept is null then null else encode(extensions.digest(convert_to('jd-local-aliases/1.0.0:'||concept,'UTF8'),'sha256'),'hex') end);
end;

private.jd_relation_alias_mentions:
declare mentions jsonb:='[]'; literal_value text collate "C"; item jsonb; result jsonb;
begin
  foreach literal_value in array array['JavaScript','PostgreSQL','Postgres','JS'] loop
    for item in select value from jsonb_array_elements(private.jd_relation_literals(p_text,literal_value,'alias')) loop
      mentions:=mentions||jsonb_build_array(item||jsonb_build_object('mapping',private.jd_relation_alias(item->>'quote')));
    end loop;
  end loop;
  if jsonb_array_length(mentions)>300 then raise exception 'JD alias mention limit' using errcode='22023'; end if;
  select coalesce(jsonb_agg(value order by (value->>'start')::integer,(value->>'end')::integer),'[]'::jsonb) into result from jsonb_array_elements(mentions);
  return result;
end;

private.jd_relation_requirement:
declare cue jsonb:='null'; ambiguity jsonb:=p_importance->'ambiguity'; value_importance text collate "C":=p_importance->>'importance';
  basis text collate "C":=p_importance->>'importanceBasis';
begin
  if private.jd_relation_utf16_length(p_evidence->>'quote')>2000 or p_ordinal>=300 then raise exception 'JD observation limit' using errcode='22023'; end if;
  if p_metadata is not null or p_negated or private.jd_relation_importance(p_evidence->>'quote','unknown')->>'importanceBasis'='explicit' then
    cue:=p_evidence-'spanId';
  elsif basis='explicit' then cue:=coalesce(p_heading_evidence,'null'::jsonb); end if;
  if p_negated then value_importance:='contextual'; basis:='explicit'; end if;
  if p_type='experience' and p_maximum is not null then ambiguity:=ambiguity||jsonb_build_array('experience_upper_bound_review'); end if;
  if p_type='skill' and private.jd_relation_test(p_evidence->>'quote','\bor\b') then ambiguity:=ambiguity||jsonb_build_array('skill_alternative_review'); end if;
  if p_negated then ambiguity:=ambiguity||jsonb_build_array('negated_clause_review'); end if;
  return jsonb_build_object('id','00000000-0000-4000-8000-'||lpad((p_ordinal+1)::text,12,'0'),'type',p_type,'value',p_value,
    'importance',value_importance,'importanceBasis',basis,'importanceEvidence',cue,'derivation','exact','minimumYears',p_minimum,
    'negated',p_negated,'ambiguity',ambiguity,'dedupGroup',encode(extensions.digest(convert_to(p_type||':'||private.jd_relation_normalize(p_value,false),'UTF8'),'sha256'),'hex'),
    'evidence',p_evidence,'confidence',jsonb_build_object('kind','uncalibrated','value',null));
end;

private.jd_relation_expected_body:
declare source text collate "C":=p_body->>'sourceText'; lines jsonb:=private.jd_relation_source_lines(source);
  requirements jsonb:='[]'; decorated jsonb:='[]'; retained jsonb:='[]'; warnings jsonb;
  line jsonb; evidence jsonb; heading_value text collate "C":='unknown'; heading_evidence jsonb:='null'; heading_change jsonb;
  company_context boolean:=false; text_value text collate "C"; metadata_value text collate "C"; importance_value jsonb; negated boolean;
  experience_metadata boolean; range_match jsonb; minimum_value integer; maximum_value integer; types text[] collate "C"; type_value text collate "C";
  skill text collate "C"; matches jsonb; requirement_value jsonb; mapping_value jsonb; tokens jsonb; token jsonb; mention jsonb; mentions jsonb;
  seen_literals text[] collate "C"; literal_value text collate "C"; group_value jsonb; in_clause jsonb; token_count integer:=0; state_value text collate "C";
  supported boolean:=(p_body->>'locale') collate "C"='en-IN' and (p_body->>'domain') collate "C"='software-engineering';
begin
  -- The registered legacy observations are reconstructed first, including metadata.
  for line in select value from jsonb_array_elements(lines) loop
    text_value:=line->>'text'; metadata_value:=line->>'metadata';
    if text_value='' then continue; end if;
    evidence:=private.jd_relation_span(source,(line->>'start')::integer,(line->>'end')::integer);
    heading_change:=private.jd_relation_heading(text_value);
    if heading_change is not null then
      heading_value:=heading_change->>'heading'; company_context:=(heading_change->>'company')::boolean;
      heading_evidence:=case when heading_value='unknown' then 'null'::jsonb else evidence-'spanId' end;
      continue;
    end if;
    if company_context or (metadata_value is not null and metadata_value in ('title','role','employment type')) then continue; end if;
    range_match:=private.jd_relation_matches(text_value,'\b(\d{1,2})(?:\s*[-–]\s*(\d{1,2})|\s*\+)?\s*(?:years?|yrs?)\b',2,1,true,true)->0;
    minimum_value:=case when range_match is null then null else (range_match->'groups'->0->>'quote')::integer end;
    maximum_value:=case when range_match->'groups'->1='null'::jsonb then null else (range_match->'groups'->1->>'quote')::integer end;
    experience_metadata:=metadata_value is not null and private.jd_relation_test(metadata_value,'^exp(?:erience)?\s*range$');
    importance_value:=case
      when experience_metadata and range_match is not null then jsonb_build_object('importance','required','importanceBasis','explicit','ambiguity','[]'::jsonb)
      when metadata_value='location' then jsonb_build_object('importance','contextual','importanceBasis','explicit','ambiguity','[]'::jsonb)
      else private.jd_relation_importance(text_value,heading_value) end;
    negated:=private.jd_relation_test(text_value,'\b(no|not(?!\s+only\b)|without|never)\b');
    types:='{}';
    if range_match is not null and (experience_metadata or private.jd_relation_test(text_value,'\b(experience|working|professional)\b')) then types:=array_append(types,'experience'); end if;
    if private.jd_relation_test(text_value,'\b(bachelor|master|degree|b\.tech|btech|bsc|msc|phd|diploma)\b')
      or private.jd_relation_test(text_value,'(?<![\p{L}\p{N}])B\.?E\.?(?![\p{L}\p{N}])',false) then types:=array_append(types,'education'); end if;
    if private.jd_relation_test(text_value,'\b(certification|certified|certificate)\b') then types:=array_append(types,'certification'); end if;
    if private.jd_relation_test(text_value,'\b(based in|located in|location|relocate|on[ -]site|hybrid|remote|bengaluru|bangalore|mumbai|delhi|hyderabad|pune)\b') then types:=array_append(types,'location'); end if;
    if private.jd_relation_test(text_value,'\b(work authorization|authori[sz]ed to work|visa|sponsorship|right to work|work permit)\b') then types:=array_append(types,'authorization'); end if;
    foreach type_value in array types loop
      requirements:=requirements||jsonb_build_array(private.jd_relation_requirement(source,evidence,type_value,text_value,
        case when type_value='experience' then minimum_value else null end,maximum_value,importance_value,heading_evidence,metadata_value,negated,jsonb_array_length(requirements)));
    end loop;
    if metadata_value is null then
      foreach skill in array array['TypeScript','JavaScript','Python','Java','SQL','React','Node.js','PostgreSQL','Docker','Kubernetes','Git','AWS','Azure','C++','C#',
        'FastAPI','Flask','Pydantic','LLMs','LLM','RAG','Generative AI','Retrieval-Augmented Generation','embedding models','embeddings','vector databases',
        'AI agents','AI agent','agent orchestration','NoSQL','Redis','async/await','asynchronous programming','GCP','Google Cloud','Object-Oriented Programming','OOP','REST APIs','microservices'] loop
        matches:=private.jd_relation_literals(text_value,skill,'ln');
        if jsonb_array_length(matches)>0 then requirements:=requirements||jsonb_build_array(private.jd_relation_requirement(source,evidence,'skill',matches->0->>'quote',null,null,
          importance_value,heading_evidence,null,negated,jsonb_array_length(requirements))); end if;
      end loop;
    end if;
    if heading_value='contextual' and private.jd_relation_test(text_value,'\b(build|develop|design|maintain|implement|test|collaborate|lead|deliver)\b') then
      requirements:=requirements||jsonb_build_array(private.jd_relation_requirement(source,evidence,'responsibility',text_value,null,null,
        importance_value,heading_evidence,metadata_value,negated,jsonb_array_length(requirements)));
    end if;
  end loop;
  -- A07 decorates literal observations without replacing their quoted value.
  for requirement_value in select value from jsonb_array_elements(requirements) loop
    tokens:='[]'; mapping_value:='null'; evidence:=requirement_value->'evidence';
    if requirement_value->>'type'='skill' then
      mapping_value:=private.jd_relation_alias(requirement_value->>'value');
      if mapping_value->>'kind'='exact' then
        mentions:=private.jd_relation_alias_mentions(evidence->>'quote');
        for mention in select value from jsonb_array_elements(mentions) loop
          if private.jd_relation_lower(mention->>'quote')=private.jd_relation_lower(requirement_value->>'value') then
            tokens:=tokens||jsonb_build_array(private.jd_relation_span(source,(evidence->>'start')::integer+(mention->>'start')::integer,
              (evidence->>'start')::integer+(mention->>'end')::integer));
          end if;
        end loop;
        if jsonb_array_length(tokens)=0 then mapping_value:=private.jd_relation_alias(''); end if;
      else
        for token in select value from jsonb_array_elements(private.jd_relation_literals(evidence->>'quote',requirement_value->>'value','ln')) loop
          tokens:=tokens||jsonb_build_array(private.jd_relation_span(source,(evidence->>'start')::integer+(token->>'start')::integer,
            (evidence->>'start')::integer+(token->>'end')::integer));
        end loop;
      end if;
    end if;
    token_count:=token_count+jsonb_array_length(tokens);
    if token_count>1000 then raise exception 'JD alias token limit' using errcode='22023'; end if;
    decorated:=decorated||jsonb_build_array(requirement_value||jsonb_build_object('mapping',mapping_value,'tokenEvidence',tokens));
  end loop;
  requirements:=decorated; heading_value:='unknown'; heading_evidence:='null'; company_context:=false;
  -- The separate alias pass retains unknown clauses and their complete member list.
  for line in select value from jsonb_array_elements(lines) loop
    text_value:=line->>'text'; metadata_value:=line->>'metadata';
    if text_value='' then continue; end if;
    evidence:=private.jd_relation_span(source,(line->>'start')::integer,(line->>'end')::integer);
    heading_change:=private.jd_relation_heading(text_value);
    if heading_change is not null then
      heading_value:=heading_change->>'heading'; company_context:=(heading_change->>'company')::boolean;
      heading_evidence:=case when heading_value='unknown' then 'null'::jsonb else evidence-'spanId' end; continue;
    end if;
    if company_context or metadata_value is not null then continue; end if;
    importance_value:=private.jd_relation_importance(text_value,heading_value);
    negated:=private.jd_relation_test(text_value,'\b(no|not(?!\s+only\b)|without|never)\b');
    mentions:=private.jd_relation_alias_mentions(text_value); seen_literals:='{}';
    for mention in select value from jsonb_array_elements(mentions) where value->'mapping'->>'kind'='alias' loop
      literal_value:=private.jd_relation_lower(mention->>'quote');
      if literal_value=any(seen_literals) then continue; end if; seen_literals:=array_append(seen_literals,literal_value);
      tokens:='[]';
      for group_value in select value from jsonb_array_elements(mentions)
        where value->'mapping'->>'kind'='alias' and private.jd_relation_lower(value->>'quote')=literal_value loop
        tokens:=tokens||jsonb_build_array(private.jd_relation_span(source,(evidence->>'start')::integer+(group_value->>'start')::integer,
          (evidence->>'start')::integer+(group_value->>'end')::integer));
      end loop;
      token_count:=token_count+jsonb_array_length(tokens);
      if token_count>1000 then raise exception 'JD alias token limit' using errcode='22023'; end if;
      requirements:=requirements||jsonb_build_array(private.jd_relation_requirement(source,evidence,'skill',mention->>'quote',null,null,
        importance_value,heading_evidence,null,negated,jsonb_array_length(requirements))||jsonb_build_object('mapping',mention->'mapping','tokenEvidence',tokens));
    end loop;
    select coalesce(jsonb_agg(value->'id' order by ordinality),'[]'::jsonb) into in_clause
      from jsonb_array_elements(requirements) with ordinality where value->'evidence'->'start'=evidence->'start' and value->'evidence'->'end'=evidence->'end';
    if jsonb_array_length(in_clause)>0 or importance_value->>'importance' in ('required','preferred')
      or jsonb_array_length(importance_value->'ambiguity')>0 or negated then
      if private.jd_relation_utf16_length(text_value)>2000 or jsonb_array_length(retained)>=300 then raise exception 'JD retained clause limit' using errcode='22023'; end if;
      retained:=retained||jsonb_build_array(jsonb_build_object('evidence',evidence,'importance',case when negated then 'contextual' else importance_value->>'importance' end,
        'negated',negated,'interpretation',case when jsonb_array_length(in_clause)>0 then 'partial_vocabulary' else 'unmapped' end,
        'reviewRequired',true,'requirementIds',in_clause));
    end if;
  end loop;
  state_value:=case when not supported then 'unsupported' when jsonb_array_length(requirements)>0 or jsonb_array_length(retained)>0 then 'review_required' else 'insufficient' end;
  warnings:=case when not supported then jsonb_build_array('unsupported_domain_or_locale') else '[]'::jsonb end
    ||jsonb_build_array('uncalibrated_requirements','domain_pack_review_pending','local_alias_policy_not_admitted','clause_interpretation_review_pending');
  return p_body||jsonb_build_object('id','ffffffff-ffff-4fff-8fff-ffffffffffff','state',state_value,'requirements',requirements,'retainedClauses',retained,
    'relations',jsonb_build_object('clauses',private.jd_relation_relations(source,requirements,retained,supported)),'warnings',warnings);
end;

private.jd_relation_duration:
declare matches jsonb; item jsonb; candidates jsonb:='[]'; operators jsonb:='[]'; groups_value jsonb; match_value jsonb;
  result jsonb; reason_value text collate "C"; amount integer; upper_value integer; comparator text collate "C"; prefix text collate "C"; group_index integer;
  start_value integer:=(p_evidence->>'start')::integer; lower_bound jsonb; upper_bound jsonb; kind text collate "C";
begin
  matches:=private.jd_relation_matches(p_evidence->>'quote',
    '(?<![\p{L}\p{N}\p{M}_.,])(?:(at\s+least|more\s+than|over|at\s+most|less\s+than|under|exactly)\s+)?(\d{1,3})(?:\s*([-–])\s*(\d{1,3})|(\s*\+))?\s*(years?|yrs?)(?![\p{L}\p{N}\p{M}_])',6,8);
  for item in select value from jsonb_array_elements(matches) loop
    candidates:=candidates||jsonb_build_array(private.jd_relation_span(p_source,start_value+(item->>'start')::integer,start_value+(item->>'end')::integer));
  end loop;
  result:=jsonb_build_object('kind','unknown','evidence',p_evidence,'lower',null,'upper',null,'operatorEvidence','[]'::jsonb,
    'candidateEvidence',candidates,'reason',null,'subjectBinding','literal_clause_only','evaluated',false);
  if jsonb_array_length(matches)=0 then
    if private.jd_relation_test(p_evidence->>'quote','\b(years?|yrs?|months?|mos?)\b') then reason_value:='unsupported_duration_review';
    else return result||jsonb_build_object('kind','not_stated','evidence',null); end if;
  elsif not p_supported then reason_value:='unsupported_segment_review';
  elsif p_negated then reason_value:='negated_duration_review';
  elsif jsonb_array_length(matches)>1 then reason_value:='multiple_durations_review';
  else
    match_value:=matches->0; groups_value:=match_value->'groups';
    amount:=(groups_value->1->>'quote')::integer;
    upper_value:=case when groups_value->3='null'::jsonb then null else (groups_value->3->>'quote')::integer end;
    comparator:=case when groups_value->0='null'::jsonb then '' else private.jd_relation_normalize(groups_value->0->>'quote') end;
    prefix:=private.jd_relation_normalize(substring(p_evidence->>'quote' from 1 for (match_value->>'start')::integer));
    if prefix not in ('','must have','requires','required:') and not private.jd_relation_test(prefix,'^(?:exp(?:erience)?\s*range|experience)\s*:$') then reason_value:='duration_prefix_review';
    elsif amount>100 or upper_value>100 then reason_value:='duration_value_review';
    elsif comparator<>'' and (groups_value->2<>'null'::jsonb or groups_value->4<>'null'::jsonb) then reason_value:='mixed_comparator_review';
    elsif upper_value is not null and amount>upper_value then reason_value:='inverted_range_review';
    else
      foreach group_index in array array[0,2,4] loop
        item:=groups_value->group_index;
        if item<>'null'::jsonb then operators:=operators||jsonb_build_array(private.jd_relation_span(p_source,
          start_value+(item->>'start')::integer,start_value+(item->>'end')::integer)); end if;
      end loop;
      lower_bound:=jsonb_build_object('value',amount,'inclusive',true,'evidence',private.jd_relation_span(p_source,
        start_value+(groups_value->1->>'start')::integer,start_value+(groups_value->1->>'end')::integer));
      upper_bound:='null';
      if upper_value is not null then
        kind:='range'; upper_bound:=jsonb_build_object('value',upper_value,'inclusive',true,'evidence',private.jd_relation_span(p_source,
          start_value+(groups_value->3->>'start')::integer,start_value+(groups_value->3->>'end')::integer));
      elsif comparator='at least' or groups_value->4<>'null'::jsonb then kind:='at_least';
      elsif comparator in ('more than','over') then kind:='more_than'; lower_bound:=lower_bound||jsonb_build_object('inclusive',false);
      elsif comparator='at most' then kind:='at_most'; upper_bound:=lower_bound; lower_bound:='null';
      elsif comparator in ('less than','under') then kind:='less_than'; upper_bound:=lower_bound||jsonb_build_object('inclusive',false); lower_bound:='null';
      elsif comparator='exactly' then kind:='exactly'; upper_bound:=lower_bound;
      else reason_value:='comparator_unstated_review'; end if;
      if reason_value is null then return result||jsonb_build_object('kind',kind,'evidence',candidates->0,'lower',lower_bound,'upper',upper_bound,'operatorEvidence',operators); end if;
    end if;
  end if;
  return result||jsonb_build_object('reason',reason_value);
end;

private.jd_relation_relations:
declare inputs jsonb:=p_retained; result jsonb:='[]'; clause_value jsonb; evidence jsonb; members jsonb; ids jsonb;
  requirement_value jsonb; token jsonb; observed jsonb; found_index integer; item jsonb; index_value integer;
  depth_value integer; deepest integer; unbalanced boolean; scalar text collate "C"; duration_value jsonb; node_count integer:=0;
  reason_value text collate "C"; expression_value jsonb; operators jsonb; operands jsonb; credit_groups jsonb; credit text collate "C";
  first_evidence jsonb; last_evidence jsonb; left_evidence jsonb; right_evidence jsonb; connector jsonb;
  between_value text collate "C"; prefix text collate "C"; suffix text collate "C"; kinds text[] collate "C"; bad_connector boolean; overlapping boolean;
begin
  for requirement_value in select value from jsonb_array_elements(p_requirements) where value->>'type'='experience' loop
    evidence:=requirement_value->'evidence';
    if exists(select 1 from jsonb_array_elements(inputs) where value->'evidence'->'start'=evidence->'start' and value->'evidence'->'end'=evidence->'end') then continue; end if;
    if jsonb_array_length(inputs)>=300 then raise exception 'JD relation clause limit' using errcode='22023'; end if;
    select coalesce(jsonb_agg(value->'id' order by ordinality),'[]'::jsonb) into ids from jsonb_array_elements(p_requirements) with ordinality
      where value->'evidence'->'start'=evidence->'start' and value->'evidence'->'end'=evidence->'end';
    inputs:=inputs||jsonb_build_array(jsonb_build_object('evidence',evidence,'importance',requirement_value->'importance','negated',requirement_value->'negated','requirementIds',ids));
  end loop;
  for clause_value in select value from jsonb_array_elements(inputs) order by (value->'evidence'->>'start')::integer,(value->'evidence'->>'end')::integer loop
    evidence:=clause_value->'evidence';
    if private.jd_relation_utf16_length(evidence->>'quote')>2000 then raise exception 'JD relation clause text limit' using errcode='22023'; end if;
    select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb),coalesce(jsonb_agg(value->'id' order by ordinality),'[]'::jsonb) into members,ids
      from jsonb_array_elements(p_requirements) with ordinality where value->'evidence'->'start'=evidence->'start' and value->'evidence'->'end'=evidence->'end';
    observed:='[]';
    for requirement_value in select value from jsonb_array_elements(members) loop
      for token in select value from jsonb_array_elements(requirement_value->'tokenEvidence') loop
        if requirement_value->>'type'<>'skill' or (token->>'start')::integer<(evidence->>'start')::integer
          or (token->>'end')::integer>(evidence->>'end')::integer
          or private.jd_relation_lower(token->>'quote')<>private.jd_relation_lower(requirement_value->>'value') then
          raise exception 'JD relation token identity mismatch' using errcode='22023'; end if;
        select ordinality::integer-1 into found_index from jsonb_array_elements(observed) with ordinality
          where value->'evidence'->'start'=token->'start' and value->'evidence'->'end'=token->'end';
        if found then
          item:=observed->found_index;
          observed:=jsonb_set(observed,array[found_index::text],item||jsonb_build_object('requirementIds',(item->'requirementIds')||jsonb_build_array(requirement_value->'id')));
        else
          if jsonb_array_length(observed)>=32 then raise exception 'JD relation operand limit' using errcode='22023'; end if;
          observed:=observed||jsonb_build_array(jsonb_build_object('evidence',token,'requirementIds',jsonb_build_array(requirement_value->'id')));
        end if;
      end loop;
    end loop;
    select coalesce(jsonb_agg(value order by (value->'evidence'->>'start')::integer,(value->'evidence'->>'end')::integer),'[]'::jsonb) into observed from jsonb_array_elements(observed);
    depth_value:=0; deepest:=0; unbalanced:=false;
    for index_value in 1..char_length(evidence->>'quote') loop
      scalar:=substring(evidence->>'quote' from index_value for 1);
      if scalar='(' then depth_value:=depth_value+1; deepest:=greatest(deepest,depth_value);
        if depth_value>8 then raise exception 'JD raw expression depth limit' using errcode='22023'; end if;
      elsif scalar=')' then if depth_value=0 then unbalanced:=true; else depth_value:=depth_value-1; end if; end if;
    end loop;
    unbalanced:=unbalanced or depth_value<>0;
    duration_value:=private.jd_relation_duration(p_source,evidence,p_supported,(clause_value->>'negated')::boolean);
    node_count:=node_count+1+jsonb_array_length(observed)+4*jsonb_array_length(duration_value->'candidateEvidence');
    if node_count>1024 then raise exception 'JD relation node limit' using errcode='22023'; end if;
    reason_value:=case
      when not p_supported then 'unsupported_segment_review'
      when unbalanced then 'unbalanced_parentheses_review'
      when deepest>0 then 'parenthesized_expression_review'
      when (clause_value->>'negated')::boolean then 'negated_expression_review'
      when exists(select 1 from jsonb_array_elements(members) where (value->'ambiguity') ? 'conflicting_importance') then 'conflicting_importance_review'
      when jsonb_array_length(observed)=0 then 'no_discovered_operands_review' else null end;
    operators:='[]'; operands:='[]'; credit_groups:='[]'; kinds:='{}'; bad_connector:=false; overlapping:=false;
    if reason_value is null then
      first_evidence:=observed->0->'evidence'; last_evidence:=observed->(jsonb_array_length(observed)-1)->'evidence';
      prefix:=private.jd_relation_normalize(substring(p_source from (evidence->>'start')::integer+1 for (first_evidence->>'start')::integer-(evidence->>'start')::integer));
      suffix:=private.jd_relation_normalize(substring(p_source from (last_evidence->>'end')::integer+1 for (evidence->>'end')::integer-(last_evidence->>'end')::integer));
      if right(suffix,1) in ('.','!') then suffix:=left(suffix,char_length(suffix)-1); end if;
      for index_value in 1..jsonb_array_length(observed)-1 loop
        left_evidence:=observed->(index_value-1)->'evidence'; right_evidence:=observed->index_value->'evidence';
        if (left_evidence->>'end')::integer>(right_evidence->>'start')::integer then overlapping:=true; exit; end if;
        between_value:=substring(p_source from (left_evidence->>'end')::integer+1 for (right_evidence->>'start')::integer-(left_evidence->>'end')::integer);
        connector:=private.jd_relation_matches(between_value,'^\s*(and|or)\s*$',1,1,true,true)->0;
        if connector is null then bad_connector:=true; exit; end if;
        token:=connector->'groups'->0;
        operators:=operators||jsonb_build_array(private.jd_relation_span(p_source,(left_evidence->>'end')::integer+(token->>'start')::integer,
          (left_evidence->>'end')::integer+(token->>'end')::integer));
        kinds:=array_append(kinds,private.jd_relation_lower(token->>'quote'));
      end loop;
      reason_value:=case
        when overlapping then 'overlapping_operands_review'
        when 'and'=any(kinds) and 'or'=any(kinds) then 'mixed_connectors_review'
        when bad_connector then 'unsupported_connector_review'
        when prefix not in ('','must have','experience with','experience in','hands-on experience with','proficiency in','knowledge of','either','both')
          or suffix not in ('','required','preferred','mandatory','essential','optional','experience','skills','experience required','skills required','is required','are required','is preferred','are preferred') then 'unsupported_scope_review'
        when (prefix='either' and 'and'=any(kinds)) or (prefix='both' and 'or'=any(kinds)) then 'scope_connector_conflict_review' else null end;
    end if;
    for item in select value from jsonb_array_elements(observed) loop
      token:=item->'evidence';
      if reason_value is null then operands:=operands||jsonb_build_array(jsonb_build_object('kind','atom','value',token->'quote','evidence',token,
        'requirementIds',item->'requirementIds','mapping',private.jd_relation_alias(token->>'quote'))); end if;
      credit:=private.jd_relation_alias(token->>'quote')->>'prospectiveCreditGroup';
      if credit is not null and not credit_groups @> jsonb_build_array(credit) then credit_groups:=credit_groups||jsonb_build_array(credit); end if;
    end loop;
    if reason_value is not null then expression_value:=jsonb_build_object('kind','unknown','reason',reason_value,'evidence',evidence,'observedRequirementIds',ids);
    elsif jsonb_array_length(operands)=1 then expression_value:=operands->0;
    else expression_value:=jsonb_build_object('kind',case when 'or'=any(kinds) then 'any_of' else 'all_of' end,
      'evidence',private.jd_relation_span(p_source,(first_evidence->>'start')::integer,(last_evidence->>'end')::integer),'operands',operands,'operatorEvidence',operators); end if;
    result:=result||jsonb_build_array(jsonb_build_object('id',encode(extensions.digest(convert_to(
      'fd69dde2640bcdc1cdd76ce622015cb577090d61581515585f7cdfe0cdcd8cdc:ffffffff-ffff-4fff-8fff-ffffffffffff:'
        ||encode(extensions.digest(convert_to(p_source,'UTF8'),'sha256'),'hex')||':'||(evidence->>'start')||':'||(evidence->>'end'),'UTF8'),'sha256'),'hex'),
      'evidence',evidence,'reviewRequired',true,'scope',jsonb_build_object('importance',clause_value->'importance','negated',clause_value->'negated'),
      'skillExpression',expression_value,'duration',duration_value,'prospectiveCreditGroups',credit_groups,'numericCredit',null));
  end loop;
  return result;
end;

private.jd_relation_lengthless_schema:
declare result jsonb; member record; item jsonb;
begin
  if p_depth>64 then raise exception 'JD structural schema depth limit' using errcode='22023'; end if;
  if jsonb_typeof(p_schema)='object' then
    result:='{}';
    for member in select key,value from jsonb_each(p_schema) where key not in ('minLength','maxLength') loop
      result:=result||jsonb_build_object(member.key,private.jd_relation_lengthless_schema(member.value,p_depth+1));
    end loop;
    return result;
  elsif jsonb_typeof(p_schema)='array' then
    result:='[]';
    for item in select value from jsonb_array_elements(p_schema) loop
      result:=result||jsonb_build_array(private.jd_relation_lengthless_schema(item,p_depth+1));
    end loop;
    return result;
  end if;
  return p_schema;
end;

private.jd_relation_lengths_valid:
declare member record; item jsonb; branch jsonb; branch_count integer; length_value integer;
begin
  if p_value is null or p_schema is null or p_depth>32 then return false; end if;
  if p_schema ? 'anyOf' or p_schema ? 'oneOf' then
    branch_count:=0;
    for branch in select value from jsonb_array_elements(coalesce(p_schema->'anyOf',p_schema->'oneOf')) loop
      if extensions.jsonb_matches_schema(private.jd_relation_lengthless_schema(branch)::json,p_value)
        and private.jd_relation_lengths_valid(p_value,branch,p_depth+1) then branch_count:=branch_count+1; end if;
    end loop;
    if p_schema ? 'oneOf' then return branch_count=1; end if;
    return branch_count>0;
  end if;
  if jsonb_typeof(p_value)='string' then
    length_value:=private.jd_relation_utf16_length(p_value#>>'{}');
    return (not p_schema ? 'minLength' or length_value>=(p_schema->>'minLength')::integer)
      and (not p_schema ? 'maxLength' or length_value<=(p_schema->>'maxLength')::integer);
  elsif jsonb_typeof(p_value)='array' and p_schema ? 'items' then
    for item in select value from jsonb_array_elements(p_value) loop
      if not private.jd_relation_lengths_valid(item,p_schema->'items',p_depth+1) then return false; end if;
    end loop;
  elsif jsonb_typeof(p_value)='object' and p_schema ? 'properties' then
    for member in select key,value from jsonb_each(p_value) loop
      if not private.jd_relation_lengths_valid(member.value,p_schema->'properties'->member.key,p_depth+1) then return false; end if;
    end loop;
  end if;
  return true;
end;

private.jd_relation_span:
begin
  if p_start<0 or p_end<=p_start or p_end>char_length(p_source) then
    raise exception 'Invalid JD source span' using errcode='22023'; end if;
  return jsonb_build_object('spanId','jd-'||p_start::text||'-'||p_end::text,
    'start',p_start,'end',p_end,'quote',substring(p_source from p_start+1 for p_end-p_start));
end;

private.jd_relation_clean:
declare result jsonb; item jsonb; member record; reference text collate "C"; ordinal_value integer; prior_refs text[] collate "C":='{}';
  start_value integer; end_value integer;
begin
  if p_value is null or p_depth>32 then raise exception 'Invalid JD semantic projection' using errcode='22023'; end if;
  if jsonb_typeof(p_value)='array' then
    result:='[]'::jsonb;
    if p_key in ('requirementIds','observedRequirementIds') then
      for item in select value from jsonb_array_elements(p_value) loop
        reference:=item#>>'{}';
        if jsonb_typeof(item)<>'string' or reference=any(prior_refs) then
          raise exception 'Invalid JD semantic reference' using errcode='22023'; end if;
        prior_refs:=array_append(prior_refs,reference);
        select ordinality::integer-1 into ordinal_value from jsonb_array_elements(p_requirements) with ordinality
          where value->>'id'=reference;
        if not found then raise exception 'Dangling JD semantic reference' using errcode='22023'; end if;
        result:=result||to_jsonb(ordinal_value);
      end loop;
      select coalesce(jsonb_agg(to_jsonb('/requirements/'||(value#>>'{}')) order by (value#>>'{}')::integer),'[]'::jsonb)
        into result from jsonb_array_elements(result);
      return result;
    elsif p_key='prospectiveCreditGroups' then
      if (select count(*) from jsonb_array_elements(p_value))<>(select count(distinct value collate "C") from jsonb_array_elements_text(p_value)) then
        raise exception 'Duplicate JD credit reference' using errcode='22023'; end if;
      select coalesce(jsonb_agg(to_jsonb(value) order by value collate "C"),'[]'::jsonb) into result from jsonb_array_elements_text(p_value);
      return result;
    elsif p_key in ('tokenEvidence','candidateEvidence') then
      for item in select value from jsonb_array_elements(p_value) order by (value->>'start')::integer,(value->>'end')::integer loop
        result:=result||jsonb_build_array(private.jd_relation_clean(item,p_source,p_requirements,null,p_depth+1));
      end loop;
      return result;
    end if;
    for item in select value from jsonb_array_elements(p_value) loop
      result:=result||jsonb_build_array(private.jd_relation_clean(item,p_source,p_requirements,null,p_depth+1));
    end loop;
    return result;
  elsif jsonb_typeof(p_value)='object' then
    if p_value ?& array['start','end','quote'] then
      if not private.evidence_integer(p_value->'start',0,20000) or not private.evidence_integer(p_value->'end',1,20000)
        or jsonb_typeof(p_value->'quote')<>'string' then raise exception 'Invalid JD source span' using errcode='22023'; end if;
      start_value:=(p_value->>'start')::integer; end_value:=(p_value->>'end')::integer;
      if end_value<=start_value or end_value>char_length(p_source)
        or substring(p_source from start_value+1 for end_value-start_value) collate "C" <> (p_value->>'quote') collate "C"
        or private.jd_relation_utf16_length(p_value->>'quote')>2000
        or (p_value ? 'spanId' and p_value->>'spanId' is distinct from 'jd-'||start_value::text||'-'||end_value::text) then
        raise exception 'JD source span mismatch' using errcode='22023'; end if;
    end if;
    result:='{}'::jsonb;
    for member in select key,value from jsonb_each(p_value) where key<>'spanId' loop
      result:=result||jsonb_build_object(member.key,private.jd_relation_clean(member.value,p_source,p_requirements,member.key,p_depth+1));
    end loop;
    return result;
  end if;
  return p_value;
end;

private.jd_relation_project:
declare requirements jsonb; retained jsonb; clauses jsonb; ids text[] collate "C":='{}'; observations text[] collate "C":='{}';
  clause_ids text[] collate "C":='{}'; clause_spans text[] collate "C":='{}'; item jsonb; observation text collate "C"; key text collate "C"; token_count integer:=0;
begin
  select coalesce(jsonb_agg(value order by (value->'evidence'->>'start')::integer,(value->'evidence'->>'end')::integer,
    (value->>'type') collate "C",(value->>'value') collate "C"),'[]'::jsonb)
    into requirements from jsonb_array_elements(p_body->'requirements');
  for item in select value from jsonb_array_elements(requirements) loop
    observation:=private.jd_relation_canonical_json(jsonb_build_array(item->'type',item->'evidence'->'start',item->'evidence'->'end',item->'value'));
    if item->>'id'=p_body->>'id' or item->>'id'=any(ids) or observation=any(observations) then
      raise exception 'Duplicate JD observation identity' using errcode='22023'; end if;
    ids:=array_append(ids,item->>'id'); observations:=array_append(observations,observation);
    token_count:=token_count+jsonb_array_length(item->'tokenEvidence');
    if token_count>1000 then raise exception 'JD token work limit' using errcode='22023'; end if;
  end loop;
  for item in select value from jsonb_array_elements(p_body->'relations'->'clauses') loop
    key:=item->'evidence'->>'start'||':'||(item->'evidence'->>'end');
    if item->>'id'=any(clause_ids) or key=any(clause_spans) then raise exception 'Duplicate JD relation identity' using errcode='22023'; end if;
    clause_ids:=array_append(clause_ids,item->>'id'); clause_spans:=array_append(clause_spans,key);
  end loop;
  select coalesce(jsonb_agg(value order by (value->'evidence'->>'start')::integer,(value->'evidence'->>'end')::integer),'[]'::jsonb)
    into retained from jsonb_array_elements(p_body->'retainedClauses');
  select coalesce(jsonb_agg(value-'id' order by (value->'evidence'->>'start')::integer,(value->'evidence'->>'end')::integer),'[]'::jsonb)
    into clauses from jsonb_array_elements(p_body->'relations'->'clauses');
  return private.jd_relation_clean((p_body-array['id','createdAt','parentVersionId'])||jsonb_build_object(
    'requirements',(select coalesce(jsonb_agg(value-'id'),'[]'::jsonb) from jsonb_array_elements(requirements)),
    'retainedClauses',retained,'relations',jsonb_build_object('clauses',clauses)),p_body->>'sourceText',requirements);
end;

private.job_requirement_relations_valid:
declare schema_value jsonb:=private.jd_relation_json_schema(); expected jsonb; created_value timestamptz;
begin
  if p_body is null or jsonb_typeof(p_body)<>'object' or getdatabaseencoding()<>'UTF8'
    or octet_length(p_body::text)>1048576 then return false; end if;
  if not extensions.jsonb_matches_schema(private.jd_relation_lengthless_schema(schema_value)::json,p_body)
    or not private.jd_relation_lengths_valid(p_body,schema_value) then return false; end if;
  if p_body->>'parentVersionId'=p_body->>'id'
    or p_body->>'inputSha256' is distinct from encode(extensions.digest(convert_to(p_body->>'sourceText','UTF8'),'sha256'),'hex') then return false; end if;
  created_value:=(p_body->>'createdAt')::timestamptz;
  if not isfinite(created_value) then return false; end if;
  expected:=private.jd_relation_expected_body(p_body);
  return private.jd_relation_canonical_json(private.jd_relation_project(p_body))
    =private.jd_relation_canonical_json(private.jd_relation_project(expected));
exception when data_exception then return false;
end;

private.reject_legacy_job_requirement_do:
begin
  if new.content->>'schemaVersion'='requirements/1.0.0' and new.parent_version_id is not null
    and exists(select 1 from public.job_requirement_versions parent where parent.id=new.parent_version_id
      and parent.content->>'schemaVersion'='requirements/2.0.0') then
    raise exception 'Review the recorded typed JD before saving' using errcode='22023';
  end if;
  return new;
end;

public.save_job_requirement_relations:
declare a public.analyses%rowtype; job public.jobs%rowtype; head public.job_requirement_versions%rowtype;
  prior public.job_requirement_versions%rowtype; semantic_value text collate "C"; command jsonb; revision_value integer;
begin
  if p_body is null or p_idempotency_key is null or p_request_id is null or char_length(p_request_id) not between 1 and 100
    or not private.job_requirement_relations_valid(p_body)
    or p_body->'parentVersionId' is distinct from coalesce(to_jsonb(p_expected_version),'null'::jsonb) then
    raise exception 'Invalid JD relation envelope' using errcode='22023'; end if;
  if p_user_id is null or p_analysis_id is null then return jsonb_build_object('status','not_found'); end if;
  -- The same R19/C02 owner mutex precedes every candidate row lock.
  perform private.lock_candidate_owners(array[p_user_id]);
  if not private.try_candidate_privacy_write(p_user_id) then return jsonb_build_object('status','not_found'); end if;
  select * into a from public.analyses where id=p_analysis_id and owner_id=p_user_id for update;
  if not found or a.job_id is null
    or not exists(select 1 from public.memberships where user_id=p_user_id and organization_id=a.organization_id) then
    return jsonb_build_object('status','not_found'); end if;
  perform 1 from public.resume_versions v join public.resumes r on r.id=v.resume_id
    where v.id=a.resume_version_id and v.owner_id=p_user_id and v.organization_id=a.organization_id
      and r.owner_id=p_user_id and r.organization_id=a.organization_id and r.status='active' for share of v,r;
  if not found then return jsonb_build_object('status','not_found'); end if;
  select * into job from public.jobs where id=a.job_id and owner_id=p_user_id and organization_id=a.organization_id for share;
  if not found then return jsonb_build_object('status','not_found'); end if;
  if (p_body->>'ownerId') collate "C" is distinct from p_user_id::text collate "C" or (p_body->>'organizationId') collate "C" is distinct from a.organization_id::text collate "C"
    or (p_body->>'analysisId') collate "C" is distinct from a.id::text collate "C" or (p_body->>'jobId') collate "C" is distinct from job.id::text collate "C" then
    raise exception 'JD relation scope mismatch' using errcode='22023'; end if;
  semantic_value:=encode(extensions.digest(convert_to(private.jd_relation_canonical_json(private.jd_relation_project(p_body)),'UTF8'),'sha256'),'hex');
  command:=jsonb_build_object('operation','save_job_requirement_relations','producerVersion','jd-relations/1.0.0',
    'semanticCodecVersion','jd-relation-command/1.0.0','admissionProfileSha256','e82d68b1e58cf220d3584a8d510128d4428441a2b02815711e7f198adaeaacb8',
    'semanticSha256',semantic_value,'expectedVersionId',p_expected_version);
  select * into prior from public.job_requirement_versions where analysis_id=a.id and idempotency_key=p_idempotency_key;
  if found then
    if prior.owner_id<>p_user_id or prior.organization_id<>a.organization_id or prior.job_id<>job.id or prior.command is distinct from command then
      return jsonb_build_object('status','conflict'); end if;
    return jsonb_build_object('status','applied','versionId',prior.id,'revision',prior.revision,'idempotent',true);
  end if;
  select * into head from public.job_requirement_versions where analysis_id=a.id order by revision desc limit 1;
  if head.id is distinct from p_expected_version then return jsonb_build_object('status','conflict'); end if;
  if p_body->>'sourceText' collate "C" is distinct from job.description collate "C"
    or p_body->>'inputSha256' is distinct from encode(extensions.digest(convert_to(job.description,'UTF8'),'sha256'),'hex') then
    raise exception 'Current JD relation source mismatch' using errcode='22023'; end if;
  -- Normalize only JSON integer representation and key order before storage.
  p_body:=private.jd_relation_canonical_json(p_body)::jsonb;
  revision_value:=coalesce(head.revision,0)+1;
  insert into public.job_requirement_versions(id,analysis_id,job_id,owner_id,organization_id,parent_version_id,revision,idempotency_key,command,content,created_at)
    values((p_body->>'id')::uuid,a.id,job.id,p_user_id,a.organization_id,head.id,revision_value,p_idempotency_key,command,p_body,(p_body->>'createdAt')::timestamptz);
  insert into public.job_requirements(version_id,id,owner_id,organization_id,item)
    select (p_body->>'id')::uuid,(value->>'id')::uuid,p_user_id,a.organization_id,value from jsonb_array_elements(p_body->'requirements');
  insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
    values(a.organization_id,p_user_id,'requirements.relations.import','job_requirement_version',(p_body->>'id')::uuid,'success',p_request_id);
  return jsonb_build_object('status','applied','versionId',p_body->>'id','revision',revision_value,'idempotent',false);
end;

private.grouped_import_command_bytes:
declare result bytea := convert_to(E'A02OP1\n','UTF8'); atom text; token bytea; data bytea;
begin
  if p_atoms is null
    or (cardinality(p_atoms)>0 and (array_ndims(p_atoms)<>1 or array_lower(p_atoms,1)<>1)) then
    raise exception 'GROUPED_IMPORT_CODEC_ATOMS' using errcode='22023';
  end if;
  if cardinality(p_atoms)>2048 then raise exception 'GROUPED_IMPORT_CODEC_LIMIT' using errcode='22023'; end if;
  foreach atom in array p_atoms loop
    if atom is null then token:=convert_to('N;','UTF8');
    else
      if octet_length(atom)>131072 then raise exception 'GROUPED_IMPORT_CODEC_LIMIT' using errcode='22023'; end if;
      data:=convert_to(atom,'UTF8');
      if octet_length(result)+char_length(octet_length(data)::text)+octet_length(data)+3>131072 then
        raise exception 'GROUPED_IMPORT_CODEC_LIMIT' using errcode='22023';
      end if;
      token:=convert_to('T'||octet_length(data)::text||':','UTF8')||data||convert_to(';','UTF8');
    end if;
    if octet_length(result)+octet_length(token)>131072 then
      raise exception 'GROUPED_IMPORT_CODEC_LIMIT' using errcode='22023';
    end if;
    result:=result||token;
  end loop;
  return result;
end;

private.grouped_import_keys:
begin
  if jsonb_typeof(p_value) is distinct from 'object' then return false; end if;
  return (select count(*)=cardinality(p_keys) and bool_and(k=any(p_keys)) from jsonb_object_keys(p_value) k);
end;

private.grouped_import_utf16_length:
declare data bytea:=convert_to(p_text,'UTF8'); units integer:=char_length(p_text); i integer; b integer;
begin
  if octet_length(data)>0 then
    for i in 0..octet_length(data)-1 loop
      b:=get_byte(data,i);
      if b between 240 and 244 then units:=units+1; end if;
    end loop;
  end if;
  return units;
end;

private.grouped_import_source_index:
declare k text; page jsonb; span jsonb; candidate jsonb; ref jsonb; source jsonb; obs jsonb;
  pages jsonb:='{}'; spans jsonb:='{}'; assertions jsonb:='{}'; observations jsonb:='{}'; by_span jsonb:='{}';
  assembled text; piece text; assembled_units integer; n integer:=0; units integer:=0; projected integer:=0;
  ocr_units integer:=0; native_span_units integer:=0; ord integer:=0; first_ord integer;
  assertion_ord integer:=0; page_key text;
begin
  if private.grouped_import_keys(p_binding,array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256',
    'evidenceSchemaVersion','fieldExtractorVersion','targetModelVersion','associationModelVersion','producerVersion',
    'admissionPolicyVersion','structuralTextProfileVersion','correctionProjectionModelVersion','correctionAdmissionPolicyVersion','effectiveLocale']) is not true
    or jsonb_typeof(p_envelope) is distinct from 'object' then perform private.grouped_import_invalid(); end if;
  foreach k in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId'] loop
    if private.grouped_import_uuid(p_binding->k) is not true then perform private.grouped_import_invalid(); end if;
  end loop;
  if jsonb_typeof(p_binding->'inputSha256') is distinct from 'string'
    or (p_binding->>'inputSha256') collate "C" !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_binding->'effectiveLocale') is distinct from 'string'
    or (p_binding->>'effectiveLocale') collate "C" !~ '^[a-z]{2,3}(?:-[A-Z]{2})?$'
    or p_binding->>'evidenceSchemaVersion' is distinct from 'evidence/2.0.0'
    or p_binding->>'fieldExtractorVersion' is distinct from 'evidence-fields/1.0.1'
    or p_binding->>'targetModelVersion' is distinct from 'evidence-targets/1.0.0'
    or p_binding->>'associationModelVersion' is distinct from 'evidence-entry-associations/1.0.0'
    or p_binding->>'producerVersion' is distinct from 'canonical-engine/1.0.3'
    or p_binding->>'admissionPolicyVersion' is distinct from 'grouped-original-admission/1.0.0'
    or p_binding->>'structuralTextProfileVersion' is distinct from 'a02-structural-text/1.0.0'
    or p_binding->>'correctionProjectionModelVersion' is distinct from 'canonical-corrections/1.0.1'
    or p_binding->>'correctionAdmissionPolicyVersion' is distinct from 'candidate-correction-admission/1.0.0'
    or p_envelope->'schemaVersion' is distinct from p_binding->'evidenceSchemaVersion'
    or p_envelope->'fieldExtractorVersion' is distinct from p_binding->'fieldExtractorVersion'
    or p_envelope->'id' is distinct from p_binding->'attemptId'
    or p_envelope->'ownerId' is distinct from p_binding->'ownerId'
    or p_envelope->'analysisId' is distinct from p_binding->'analysisId'
    or p_envelope->'sourceId' is distinct from p_binding->'sourceId'
    or p_envelope->'inputSha256' is distinct from p_binding->'inputSha256'
    or jsonb_typeof(p_envelope->'retentionPolicyId') is distinct from 'string'
    or private.grouped_import_utf16_length(p_envelope->>'retentionPolicyId') not between 1 and 100 then
    perform private.grouped_import_invalid();
  end if;
  if jsonb_typeof(p_envelope->'spans') is distinct from 'array'
    or jsonb_typeof(p_envelope->'assertions') is distinct from 'array'
    or jsonb_typeof(p_envelope->'nativeSource'->'pages') is distinct from 'array'
    or jsonb_typeof(p_envelope->'nativeSource'->'spans') is distinct from 'array'
    or jsonb_typeof(p_envelope->'nativeSource'->'assertions') is distinct from 'array' then
    perform private.grouped_import_invalid();
  end if;
  if jsonb_array_length(p_envelope->'spans') not between 1 and 20000
    or jsonb_array_length(p_envelope->'assertions')>1000
    or jsonb_array_length(p_envelope->'nativeSource'->'pages') not between 1 and 20
    or jsonb_array_length(p_envelope->'nativeSource'->'spans')>20000
    or jsonb_array_length(p_envelope->'nativeSource'->'assertions')<>3 then perform private.grouped_import_invalid(); end if;
  units:=(jsonb_array_length(p_envelope->'nativeSource'->'pages')-1)*2;
  for page in select value from jsonb_array_elements(p_envelope->'nativeSource'->'pages') loop
    n:=n+1;
    if jsonb_typeof(page->'text') is distinct from 'string' or page->>'id' is distinct from 'page-'||n
      or private.evidence_integer(page->'pageNumber',1,20) is not true or page->'pageNumber' is distinct from to_jsonb(n) then
      perform private.grouped_import_invalid();
    end if;
    units:=units+private.grouped_import_utf16_length(page->>'text');
    if units>500000 then perform private.grouped_import_invalid(); end if;
    pages:=pages||jsonb_build_object('native_text|'||(page->>'id'),page->'text');
  end loop;
  for span in select value from jsonb_array_elements(p_envelope->'nativeSource'->'spans') loop
    if jsonb_typeof(span->'text') is distinct from 'string' then perform private.grouped_import_invalid(); end if;
    native_span_units:=native_span_units+private.grouped_import_utf16_length(span->>'text');
    if native_span_units>500000 then perform private.grouped_import_invalid(); end if;
  end loop;
  if p_envelope->'ocrSource' is distinct from 'null'::jsonb then
    if jsonb_typeof(p_envelope->'ocrSource'->'pages') is distinct from 'array' then perform private.grouped_import_invalid(); end if;
    if jsonb_array_length(p_envelope->'ocrSource'->'pages') not between 1 and 10 then perform private.grouped_import_invalid(); end if;
    ocr_units:=(jsonb_array_length(p_envelope->'ocrSource'->'pages')-1)*2;
    for page in select value from jsonb_array_elements(p_envelope->'ocrSource'->'pages') loop
      if jsonb_typeof(page->'text') is distinct from 'string' or jsonb_typeof(page->'pageId') is distinct from 'string'
        or not (pages ? ('native_text|'||(page->>'pageId'))) then perform private.grouped_import_invalid(); end if;
      page_key:='local_ocr|'||(page->>'pageId');
      if pages ? page_key then perform private.grouped_import_invalid(); end if;
      ocr_units:=ocr_units+private.grouped_import_utf16_length(page->>'text');
      if ocr_units>200000 or units+ocr_units>200000 then perform private.grouped_import_invalid(); end if;
      pages:=pages||jsonb_build_object(page_key,page->'text');
    end loop;
  end if;
  -- Preflight every nested reference cardinality before assembling references.
  for candidate in select value from jsonb_array_elements(p_envelope->'assertions') loop
    if jsonb_typeof(candidate->'evidence') is distinct from 'array' then perform private.grouped_import_invalid(); end if;
    if jsonb_array_length(candidate->'evidence') not between 1 and 20 then perform private.grouped_import_invalid(); end if;
  end loop;
  for span in select value from jsonb_array_elements(p_envelope->'spans') loop
    ord:=ord+1;
    if private.grouped_import_keys(span,array['id','pageId','method','text','start','end','box','confidence']) is not true
      or jsonb_typeof(span->'id') is distinct from 'string' or jsonb_typeof(span->'pageId') is distinct from 'string'
      or jsonb_typeof(span->'text') is distinct from 'string' or span->>'method' not in ('native_text','local_ocr')
      or jsonb_typeof(span->'method') is distinct from 'string'
      or private.grouped_import_utf16_length(span->>'id') not between 1 and 100
      or private.grouped_import_utf16_length(span->>'pageId') not between 1 and 100
      or private.evidence_integer(span->'start',0,200000) is not true
      or private.evidence_integer(span->'end',0,200000) is not true then perform private.grouped_import_invalid(); end if;
    units:=private.grouped_import_utf16_length(span->>'text'); projected:=projected+units;
    if units>200000 or projected>700000 or (span->>'end')::numeric::integer-(span->>'start')::numeric::integer<>char_length(span->>'text') then
      perform private.grouped_import_invalid();
    end if;
    page_key:=(span->>'method')||'|'||(span->>'pageId');
    if not (pages ? page_key) or (span->>'end')::numeric::integer>char_length(pages->>page_key)
      or substring(pages->>page_key from (span->>'start')::numeric::integer+1
      for (span->>'end')::numeric::integer-(span->>'start')::numeric::integer) is distinct from span->>'text' then perform private.grouped_import_invalid(); end if;
  end loop;
  if (select count(distinct value->>'id') from jsonb_array_elements(p_envelope->'spans'))<>jsonb_array_length(p_envelope->'spans') then
    perform private.grouped_import_invalid();
  end if;
  select jsonb_object_agg(value->>'id',value||jsonb_build_object('ordinal',ordinality)) into spans
    from jsonb_array_elements(p_envelope->'spans') with ordinality;
  for candidate in select value from jsonb_array_elements(p_envelope->'assertions') loop
    assertion_ord:=assertion_ord+1;
    if private.grouped_import_keys(candidate,array['id','field','value','evidence','state','confidence']) is not true
      or jsonb_typeof(candidate->'id') is distinct from 'string' or jsonb_typeof(candidate->'value') is distinct from 'string'
      or jsonb_typeof(candidate->'field') is distinct from 'string'
      or candidate->>'field' not in ('name','email','phone','employer','role','dates','education','certification')
      or private.grouped_import_utf16_length(candidate->>'id') not between 1 and 100
      or private.grouped_import_utf16_length(candidate->>'value') not between 1 and 500
      or candidate->>'state' is distinct from 'review_required'
      or candidate->'confidence' is distinct from '{"kind":"uncalibrated","value":null}'::jsonb then perform private.grouped_import_invalid(); end if;
    assembled:=''; assembled_units:=0;
    for ref in select value from jsonb_array_elements(candidate->'evidence') loop
      if private.grouped_import_keys(ref,array['spanId','start','end']) is not true
        or jsonb_typeof(ref->'spanId') is distinct from 'string'
        or private.evidence_integer(ref->'start',0,200000) is not true
        or private.evidence_integer(ref->'end',1,200000) is not true then perform private.grouped_import_invalid(); end if;
      source:=spans->(ref->>'spanId');
      if source is null or (ref->>'end')::numeric::integer<=(ref->>'start')::numeric::integer
        or (ref->>'end')::numeric::integer>char_length(source->>'text') then perform private.grouped_import_invalid(); end if;
      piece:=substring(source->>'text' from (ref->>'start')::numeric::integer+1 for (ref->>'end')::numeric::integer-(ref->>'start')::numeric::integer);
      assembled_units:=assembled_units+private.grouped_import_utf16_length(piece);
      if assembled_units>500 then perform private.grouped_import_invalid(); end if;
      assembled:=assembled||piece;
    end loop;
    if assembled is distinct from candidate->>'value' then perform private.grouped_import_invalid(); end if;
  end loop;
  if (select count(distinct value->>'id') from jsonb_array_elements(p_envelope->'assertions'))<>jsonb_array_length(p_envelope->'assertions') then
    perform private.grouped_import_invalid();
  end if;
  select coalesce(jsonb_object_agg(value->>'id',value),'{}'::jsonb) into assertions from jsonb_array_elements(p_envelope->'assertions');
  -- Aggregate indexes once; bySpan stores IDs rather than duplicating large multi-reference observations.
  select coalesce(jsonb_object_agg(c.value->>'id',jsonb_build_object('assertionId',c.value->'id','field',c.value->'field',
    'value',c.value->'value','ordinal',c.ordinality,'firstOrdinal',refs.first_ordinal,'citations',refs.citations)),'{}'::jsonb)
    into observations from jsonb_array_elements(p_envelope->'assertions') with ordinality c(value,ordinality)
    cross join lateral (select min((spans->(r.value->>'spanId')->>'ordinal')::numeric::integer) as first_ordinal,
      jsonb_agg(jsonb_build_object('attemptId',p_binding->'attemptId','spanId',r.value->'spanId',
        'pageId',spans->(r.value->>'spanId')->'pageId','method',spans->(r.value->>'spanId')->'method',
        'start',r.value->'start','end',r.value->'end',
        'pageStart',(spans->(r.value->>'spanId')->>'start')::numeric::integer+(r.value->>'start')::numeric::integer,
        'pageEnd',(spans->(r.value->>'spanId')->>'start')::numeric::integer+(r.value->>'end')::numeric::integer) order by r.ordinality) as citations
      from jsonb_array_elements(c.value->'evidence') with ordinality r(value,ordinality)) refs;
  select coalesce(jsonb_object_agg(grouped.span_id,grouped.ids),'{}'::jsonb) into by_span from (
    select r.value->>'spanId' as span_id,jsonb_object_agg(c.value->>'id',true) as ids
      from jsonb_array_elements(p_envelope->'assertions') c(value) cross join lateral jsonb_array_elements(c.value->'evidence') r(value)
      group by r.value->>'spanId') grouped;
  return jsonb_build_object('spans',spans,'assertions',assertions,'observations',observations,'bySpan',by_span);
end;

private.grouped_import_same_span:
declare ws text:='['||private.grouped_import_whitespace()||']'; pattern text; m text[];
  cursor_pos integer:=0; segment_start integer:=0; previous_field text; gap text; field_name text;
  seen text[]:='{}'; matched jsonb:='{}'; obs jsonb; cite jsonb; start_pos integer; end_pos integer;
  kind text; next_kind text;
begin
  if jsonb_array_length(p_values)<2 then return null; end if;
  for obs in select value from jsonb_array_elements(p_values) loop
    if jsonb_array_length(obs->'citations')<>1 then return null; end if;
  end loop;
  pattern:='(.*?)((?:^|[|;]'||ws||'*)(name|email|phone|employer|role|date[sſ]|education|certification)'||ws||'*:'||ws||'*)';
  for m in select regexp_matches(private.grouped_import_ascii_lower(p_text) collate "C",pattern,'g') loop
    gap:=m[1];
    if previous_field=any(array['employer','role','dates','education','certification']) then
      start_pos:=segment_start+char_length(gap)-char_length(ltrim(gap,private.grouped_import_whitespace()));
      end_pos:=greatest(start_pos,segment_start+char_length(rtrim(gap,private.grouped_import_whitespace())));
      for obs in select value from jsonb_array_elements(p_values) loop
        cite:=obs->'citations'->0;
        if obs->>'field'=previous_field and (cite->>'start')::numeric::integer>=start_pos and (cite->>'end')::numeric::integer<=end_pos then
          matched:=matched||jsonb_build_object(obs->>'assertionId',true);
        end if;
      end loop;
    end if;
    cursor_pos:=cursor_pos+char_length(m[1])+char_length(m[2]); segment_start:=cursor_pos; field_name:=m[3];
    if field_name=any(array['employer','role','dates','education','certification']) then
      if field_name=any(seen) then return null; end if;
      seen:=array_append(seen,field_name);
      next_kind:=case when field_name in ('employer','role') then 'employment' when field_name='education' then 'education'
        when field_name='certification' then 'certification' else null end;
      if next_kind is not null then
        if kind is not null and kind<>next_kind then return null; end if;
        kind:=next_kind;
      end if;
    end if;
    previous_field:=field_name;
  end loop;
  gap:=substring(p_text from cursor_pos+1);
  if previous_field=any(array['employer','role','dates','education','certification']) then
    start_pos:=segment_start+char_length(gap)-char_length(ltrim(gap,private.grouped_import_whitespace()));
    end_pos:=greatest(start_pos,segment_start+char_length(rtrim(gap,private.grouped_import_whitespace())));
    for obs in select value from jsonb_array_elements(p_values) loop
      cite:=obs->'citations'->0;
      if obs->>'field'=previous_field and (cite->>'start')::numeric::integer>=start_pos and (cite->>'end')::numeric::integer<=end_pos then
        matched:=matched||jsonb_build_object(obs->>'assertionId',true);
      end if;
    end loop;
  end if;
  if kind is null then return null; end if;
  for obs in select value from jsonb_array_elements(p_values) loop
    if not (matched ? (obs->>'assertionId')) then return null; end if;
  end loop;
  return kind;
end;

private.grouped_import_flush:
declare obs jsonb; members jsonb:='[]'; has_employer boolean:=false; has_role boolean:=false;
begin
  if p_block is null or p_ambiguous then return null; end if;
  for obs in select value from jsonb_array_elements(p_block) loop
    if p_assigned ? (obs->>'assertionId') then return null; end if;
    has_employer:=has_employer or obs->>'field'='employer'; has_role:=has_role or obs->>'field'='role';
    members:=members||jsonb_build_array(jsonb_build_object('assertionId',obs->'assertionId','field',obs->'field','citations',obs->'citations'));
  end loop;
  if not has_employer or not has_role then return null; end if;
  return jsonb_build_object('pageId',p_block->0->'citations'->0->'pageId','method',p_block->0->'citations'->0->'method','members',members);
end;

private.grouped_import_project_candidate:
declare idx jsonb:=private.grouped_import_source_index(p_envelope,p_binding); pair record; bucket record; span jsonb; obs jsonb;
  protected jsonb:='{}'; preserved jsonb:='{}'; assigned jsonb:='{}'; values_here jsonb; relevant jsonb;
  kind text; text_value text; folded text; ws text:='['||private.grouped_import_whitespace()||']';
  block jsonb; ambiguous boolean; in_employment boolean; mode text; prefix text[]; field_name text;
  group_value jsonb; result jsonb:='[]'; suffix text; start_pos integer; end_pos integer; exact_line boolean; labels_count integer;
begin
  for pair in select key,value from jsonb_each(idx->'bySpan') loop
    select coalesce(jsonb_agg(ob.value order by (ob.value->>'ordinal')::numeric::integer),'[]'::jsonb) into values_here from jsonb_each(pair.value) keys
      cross join lateral (values (idx->'observations'->keys.key)) ob(value)
      where ob.value->>'field' in ('employer','role','dates','education','certification');
    kind:=private.grouped_import_same_span(idx->'spans'->pair.key->>'text',values_here);
    if kind is not null then
      protected:=protected||jsonb_build_object(pair.key,kind);
      for obs in select value from jsonb_array_elements(values_here) loop preserved:=preserved||jsonb_build_object(obs->>'assertionId',true); end loop;
    end if;
  end loop;
  for bucket in select value->>'pageId' as page_id,value->>'method' as method,min(ordinality) as first_ordinal
    from jsonb_array_elements(p_envelope->'spans') with ordinality group by value->>'pageId',value->>'method' order by min(ordinality) loop
    in_employment:=false; block:=null; ambiguous:=false;
    for span in select value from jsonb_array_elements(p_envelope->'spans') with ordinality
      where value->>'pageId'=bucket.page_id and value->>'method'=bucket.method order by (value->>'start')::numeric::integer,ordinality loop
      text_value:=span->>'text'; folded:=private.grouped_import_ascii_lower(text_value);
      select coalesce(jsonb_agg(ob.value order by (ob.value->>'firstOrdinal')::numeric::integer,(ob.value->'citations'->0->>'start')::numeric::integer,(ob.value->>'ordinal')::numeric::integer),'[]'::jsonb)
        into values_here from jsonb_each(coalesce(idx->'bySpan'->(span->>'id'),'{}'::jsonb)) keys
        cross join lateral (values (idx->'observations'->keys.key)) ob(value) where not (preserved ? (ob.value->>'assertionId'));
      select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into relevant from jsonb_array_elements(values_here) with ordinality
        where value->>'field' in ('employer','role','dates');
      prefix:=regexp_match(folded collate "C",'^([\t ]*(employer|role|dates):[\t ]*)'); field_name:=prefix[2];
      mode:=case
        when private.grouped_import_trim(folded)=any(array['employment','experience','work experience','professional experience','employment history']) then 'heading'
        when exists(select 1 from jsonb_array_elements(values_here) where value->>'field' not in ('employer','role','dates'))
          or exists(select 1 from regexp_matches(text_value collate "C",'(?:^[\t ]*|[|;]'||ws||'*)([A-Za-z][A-Za-z ]*):','g') label
            where private.grouped_import_ascii_lower(private.grouped_import_trim(label[1])) not in ('employer','role','dates')) then 'barrier'
        when protected ? (span->>'id') then 'protected'
        when private.grouped_import_trim(text_value)='' then 'blank'
        when prefix is null then 'unlabelled' else 'labelled' end;
      if mode<>'labelled' or (in_employment and field_name='employer') then
        group_value:=private.grouped_import_flush(block,ambiguous,assigned);
        if group_value is not null then
          result:=result||jsonb_build_array(group_value);
          for obs in select value from jsonb_array_elements(group_value->'members') loop assigned:=assigned||jsonb_build_object(obs->>'assertionId',true); end loop;
        end if;
        block:=null; ambiguous:=false;
      end if;
      if mode='heading' then in_employment:=true; continue;
      elsif mode='barrier' or mode='unlabelled' then in_employment:=false; continue;
      elsif mode='protected' then if protected->>(span->>'id')<>'employment' then in_employment:=false; end if; continue;
      elsif mode='blank' then continue;
      end if;
      if not in_employment then continue; end if;
      suffix:=substring(text_value from char_length(prefix[1])+1);
      start_pos:=char_length(prefix[1])+char_length(suffix)-char_length(ltrim(suffix,private.grouped_import_whitespace()));
      end_pos:=char_length(rtrim(text_value,private.grouped_import_whitespace()));
      select count(*) into labels_count from regexp_matches(folded collate "C",'(?:^[\t ]*|[|;]'||ws||'*)(employer|role|dates)'||ws||'*:','g');
      obs:=relevant->0;
      exact_line:=jsonb_array_length(values_here)=1 and jsonb_array_length(relevant)=1 and obs->>'field'=field_name
        and jsonb_array_length(obs->'citations')=1 and obs->'citations'->0->'spanId'=span->'id'
        and obs->'citations'->0->'start'=to_jsonb(start_pos) and obs->'citations'->0->'end'=to_jsonb(end_pos)
        and obs->>'value'=private.grouped_import_trim(suffix) and labels_count=1;
      if exact_line is not true then block:=coalesce(block,'[]'::jsonb)||relevant; ambiguous:=true; continue; end if;
      if block is null and field_name<>'employer' then continue; end if;
      block:=coalesce(block,'[]'::jsonb);
      if exists(select 1 from jsonb_array_elements(block) where value->>'field'=field_name) then ambiguous:=true; end if;
      block:=block||jsonb_build_array(obs);
    end loop;
    group_value:=private.grouped_import_flush(block,ambiguous,assigned);
    if group_value is not null then
      result:=result||jsonb_build_array(group_value);
      for obs in select value from jsonb_array_elements(group_value->'members') loop assigned:=assigned||jsonb_build_object(obs->>'assertionId',true); end loop;
    end if;
  end loop;
  return result;
end;

private.grouped_import_check_refs:
declare ref text; seen jsonb:='{}';
begin
  for ref in select jsonb_array_elements_text(p_refs) loop
    if seen ? ref or not (p_facts ? ref) then perform private.grouped_import_invalid(); end if;
    seen:=seen||jsonb_build_object(ref,true);
  end loop;
end;

private.grouped_import_place_original:
declare idx jsonb:=private.grouped_import_source_index(p_envelope,p_binding); projected jsonb; canonical_selection jsonb;
  facts jsonb:='{}'; facts_by_source jsonb:='{}'; assertion_facts jsonb:='{}'; matched_facts jsonb:='{}';
  identities jsonb:='{}'; locations jsonb:='{}'; non_entry jsonb:='{}'; merged jsonb:='{}'; removed jsonb:='{}'; assigned jsonb:='{}';
  fact jsonb; citation jsonb; span jsonb; candidate jsonb; section jsonb; entry jsonb; bullet jsonb; event jsonb;
  selection jsonb; member jsonb; mapping jsonb; matches jsonb; anchor jsonb; matched jsonb; location jsonb;
  expected_sources jsonb; normalized_sources jsonb; ids jsonb; mappings jsonb:='[]'; new_sections jsonb:='[]'; new_entries jsonb; new_entry jsonb;
  document jsonb; input_producer_copy jsonb; ref text; key text; fact_id text; object_id text;
  content_units integer:=0; entry_index integer; minimum_index integer;
begin
  if jsonb_typeof(p_original) is distinct from 'object' or jsonb_typeof(p_selections) is distinct from 'array' then
    perform private.grouped_import_invalid();
  end if;
  if jsonb_array_length(p_selections) not between 1 and 32 then perform private.grouped_import_invalid(); end if;
  -- Keep current original-import structure/byte limits, then supplement refinements.
  if octet_length(p_original::text)>1048576 then perform private.grouped_import_invalid(); end if;
  if private.canonical_shape_valid(p_original) is not true then perform private.grouped_import_invalid(); end if;
  if p_original->>'producerVersion' is distinct from 'canonical-engine/1.0.1'
    or p_original->'parentVersionId' is distinct from 'null'::jsonb or p_original->>'state' is distinct from 'review_required'
    or p_original->'ownerId' is distinct from p_binding->'ownerId' or p_original->'organizationId' is distinct from p_binding->'organizationId'
    or p_original->'resumeId' is distinct from p_binding->'resumeId' or p_original->'analysisId' is distinct from p_binding->'analysisId'
    or p_original->'inputSha256' is distinct from p_binding->'inputSha256'
    or p_original->'sourceEvidenceVersionId' is distinct from p_binding->'attemptId'
    or p_original->'retentionPolicyId' is distinct from p_envelope->'retentionPolicyId'
    or p_original->'locale' is distinct from p_binding->'effectiveLocale'
    or jsonb_array_length(p_original->'changes')<>1 then perform private.grouped_import_invalid(); end if;
  event:=p_original->'changes'->0;
  if event->'actorId' is distinct from p_binding->'ownerId' or event->>'action' is distinct from 'import'
    or event->'targetId' is distinct from p_original->'versionId' or event->'priorValue' is distinct from 'null'::jsonb
    or event->'createdAt' is distinct from p_original->'createdAt' then perform private.grouped_import_invalid(); end if;
  foreach object_id in array array[p_original->>'resumeId',p_original->>'versionId',event->>'id'] loop
    if identities ? object_id then perform private.grouped_import_invalid(); end if;
    identities:=identities||jsonb_build_object(object_id,true);
  end loop;
  for fact in select value from jsonb_array_elements(p_original->'facts') loop
    fact_id:=fact->>'id';
    if identities ? fact_id or fact->>'state' is distinct from 'unconfirmed' or fact->'confirmation' is distinct from 'null'::jsonb
      or jsonb_array_length(fact->'sources')=0 or fact->>'value' is distinct from private.grouped_import_trim(fact->>'value')
      or private.grouped_import_utf16_length(fact->>'value') not between 1 and 2000 then perform private.grouped_import_invalid(); end if;
    identities:=identities||jsonb_build_object(fact_id,true); facts:=facts||jsonb_build_object(fact_id,fact);
    content_units:=content_units+private.grouped_import_utf16_length(fact->>'value');
    if content_units>200000 then perform private.grouped_import_invalid(); end if;
    for citation in select value from jsonb_array_elements(fact->'sources') loop
      if private.evidence_integer(citation->'start',0,200000) is not true or private.evidence_integer(citation->'end',1,200000) is not true then
        perform private.grouped_import_invalid();
      end if;
      span:=idx->'spans'->(citation->>'spanId');
      if span is null or citation->'attemptId' is distinct from p_binding->'attemptId'
        or (citation->>'end')::numeric::integer<=(citation->>'start')::numeric::integer or (citation->>'end')::numeric::integer>char_length(span->>'text')
        or substring(span->>'text' from (citation->>'start')::numeric::integer+1 for (citation->>'end')::numeric::integer-(citation->>'start')::numeric::integer)
          is distinct from fact->>'value' then perform private.grouped_import_invalid(); end if;
    end loop;
    select jsonb_agg(jsonb_build_object('attemptId',value->'attemptId','spanId',value->'spanId',
      'start',(value->>'start')::numeric::integer,'end',(value->>'end')::numeric::integer) order by ordinality)
      into normalized_sources from jsonb_array_elements(fact->'sources') with ordinality;
    key:=jsonb_build_array(fact->'type',fact->'value',normalized_sources)::text;
    facts_by_source:=jsonb_set(facts_by_source,array[key],coalesce(facts_by_source->key,'[]'::jsonb)||jsonb_build_array(fact_id),true);
  end loop;
  -- Bijection over all critical assertions, independent of selected groups.
  for candidate in select value from jsonb_array_elements(p_envelope->'assertions') loop
    select jsonb_agg(jsonb_build_object('attemptId',p_binding->'attemptId','spanId',value->'spanId','start',value->'start','end',value->'end') order by ordinality)
      into expected_sources from jsonb_array_elements(candidate->'evidence') with ordinality;
    select jsonb_agg(jsonb_build_object('attemptId',value->'attemptId','spanId',value->'spanId',
      'start',(value->>'start')::numeric::integer,'end',(value->>'end')::numeric::integer) order by ordinality)
      into normalized_sources from jsonb_array_elements(expected_sources) with ordinality;
    key:=jsonb_build_array(candidate->'field',candidate->'value',normalized_sources)::text;
    ids:=coalesce(facts_by_source->key,'[]'::jsonb);
    if jsonb_array_length(ids)<>1 or matched_facts ? (ids->>0) then perform private.grouped_import_invalid(); end if;
    assertion_facts:=assertion_facts||jsonb_build_object(candidate->>'id',ids->0);
    matched_facts:=matched_facts||jsonb_build_object(ids->>0,true);
  end loop;
  for fact in select value from jsonb_array_elements(p_original->'facts') loop
    if fact->>'type' in ('name','email','phone','employer','role','dates','education','certification')
      and not (matched_facts ? (fact->>'id')) then perform private.grouped_import_invalid(); end if;
  end loop;
  perform private.grouped_import_check_refs(p_original->'contactFactIds',facts);
  for ref in select jsonb_array_elements_text(p_original->'contactFactIds') loop
    if facts->ref->>'type' not in ('name','email','phone','link','location') then perform private.grouped_import_invalid(); end if;
    non_entry:=non_entry||jsonb_build_object(ref,true);
  end loop;
  for section in select value from jsonb_array_elements(p_original->'sections') loop
    object_id:=section->>'id';
    if identities ? object_id or section->>'title' is distinct from private.grouped_import_trim(section->>'title')
      or private.grouped_import_utf16_length(section->>'title') not between 1 and 100 then perform private.grouped_import_invalid(); end if;
    identities:=identities||jsonb_build_object(object_id,true);
    content_units:=content_units+private.grouped_import_utf16_length(section->>'title');
    if content_units>200000 then perform private.grouped_import_invalid(); end if;
    perform private.grouped_import_check_refs(section->'factIds',facts);
    for ref in select jsonb_array_elements_text(section->'factIds') loop non_entry:=non_entry||jsonb_build_object(ref,true); end loop;
    entry_index:=0;
    for entry in select value from jsonb_array_elements(section->'entries') loop
      object_id:=entry->>'id';
      if identities ? object_id then perform private.grouped_import_invalid(); end if;
      identities:=identities||jsonb_build_object(object_id,true);
      perform private.grouped_import_check_refs(entry->'factIds',facts);
      for ref in select jsonb_array_elements_text(entry->'factIds') loop
        location:=jsonb_build_object('sectionId',section->'id','sectionType',section->'type','entryId',entry->'id','entryIndex',entry_index,
          'pure',jsonb_array_length(entry->'factIds')=1 and jsonb_array_length(entry->'bullets')=0);
        locations:=jsonb_set(locations,array[ref],coalesce(locations->ref,'[]'::jsonb)||jsonb_build_array(location),true);
      end loop;
      for bullet in select value from jsonb_array_elements(entry->'bullets') loop
        object_id:=bullet->>'id';
        if identities ? object_id or bullet->>'text' is distinct from private.grouped_import_trim(bullet->>'text')
          or private.grouped_import_utf16_length(bullet->>'text') not between 1 and 2000 then perform private.grouped_import_invalid(); end if;
        identities:=identities||jsonb_build_object(object_id,true);
        content_units:=content_units+private.grouped_import_utf16_length(bullet->>'text');
        if content_units>200000 then perform private.grouped_import_invalid(); end if;
        perform private.grouped_import_check_refs(bullet->'factIds',facts);
        if jsonb_array_length(bullet->'factIds')<>1 or facts->(bullet->'factIds'->>0)->'value' is distinct from bullet->'text' then
          perform private.grouped_import_invalid();
        end if;
        for ref in select jsonb_array_elements_text(bullet->'factIds') loop non_entry:=non_entry||jsonb_build_object(ref,true); end loop;
      end loop;
      entry_index:=entry_index+1;
    end loop;
  end loop;
  projected:=private.grouped_import_project_candidates(p_envelope,p_binding);
  select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into canonical_selection
    from jsonb_array_elements(projected) with ordinality where value in (select value from jsonb_array_elements(p_selections));
  if canonical_selection is distinct from p_selections then perform private.grouped_import_invalid(); end if;
  -- Build every mapping/removal plan before changing any returned structure.
  for selection in select value from jsonb_array_elements(canonical_selection) loop
    if jsonb_array_length(selection->'members') not between 2 and 3 then perform private.grouped_import_invalid(); end if;
    matches:='[]'; anchor:=null;
    for member in select value from jsonb_array_elements(selection->'members') loop
      fact_id:=assertion_facts->>(member->>'assertionId');
      ids:=coalesce(locations->fact_id,'[]'::jsonb);
      if fact_id is null or assigned ? fact_id or non_entry ? fact_id or jsonb_array_length(ids)<>1 then perform private.grouped_import_invalid(); end if;
      location:=ids->0;
      if location->>'sectionType'<>'experience' or location->'pure' is distinct from 'true'::jsonb then perform private.grouped_import_invalid(); end if;
      matched:=jsonb_build_object('member',member,'factId',fact_id,'location',location);
      matches:=matches||jsonb_build_array(matched); assigned:=assigned||jsonb_build_object(fact_id,true);
      if member->>'field'='employer' then anchor:=matched; end if;
    end loop;
    if anchor is null then perform private.grouped_import_invalid(); end if;
    if exists(select 1 from jsonb_array_elements(matches) where value->'location'->'sectionId' is distinct from anchor->'location'->'sectionId') then
      perform private.grouped_import_invalid();
    end if;
    select min((value->'location'->>'entryIndex')::numeric::integer) into minimum_index from jsonb_array_elements(matches);
    if minimum_index<>(anchor->'location'->>'entryIndex')::numeric::integer then perform private.grouped_import_invalid(); end if;
    select jsonb_agg(value->'factId' order by (value->'location'->>'entryIndex')::numeric::integer) into ids from jsonb_array_elements(matches);
    merged:=merged||jsonb_build_object(anchor->'location'->>'entryId',ids);
    mapping:=jsonb_build_object('selection',selection,'sectionId',anchor->'location'->'sectionId','entryId',anchor->'location'->'entryId','members','[]'::jsonb);
    for matched in select value from jsonb_array_elements(matches) order by (value->'location'->>'entryIndex')::numeric::integer loop
      if matched->'location'->'entryId' is distinct from anchor->'location'->'entryId' then removed:=removed||jsonb_build_object(matched->'location'->>'entryId',true); end if;
      member:=matched->'member';
      mapping:=jsonb_set(mapping,'{members}',(mapping->'members')||jsonb_build_array(jsonb_build_object('assertionId',member->'assertionId',
        'field',member->'field','factId',matched->'factId','originalEntryId',matched->'location'->'entryId','citations',member->'citations')));
    end loop;
    mappings:=mappings||jsonb_build_array(mapping);
  end loop;
  for section in select value from jsonb_array_elements(p_original->'sections') loop
    new_entries:='[]';
    for entry in select value from jsonb_array_elements(section->'entries') loop
      if removed ? (entry->>'id') then continue; end if;
      new_entry:=entry;
      if merged ? (entry->>'id') then new_entry:=jsonb_set(entry,'{factIds}',merged->(entry->>'id')); end if;
      new_entries:=new_entries||jsonb_build_array(new_entry);
    end loop;
    new_sections:=new_sections||jsonb_build_array(jsonb_set(section,'{entries}',new_entries));
  end loop;
  document:=jsonb_set(jsonb_set(p_original,'{sections}',new_sections),'{producerVersion}','"canonical-engine/1.0.3"'::jsonb);
  input_producer_copy:=jsonb_set(document,'{producerVersion}','"canonical-engine/1.0.1"'::jsonb);
  if private.canonical_shape_valid(input_producer_copy) is not true
    or (document-array['producerVersion','sections']) is distinct from (p_original-array['producerVersion','sections']) then
    perform private.grouped_import_invalid();
  end if;
  return jsonb_build_object('schemaVersion','grouped-original-placement/1.0.0','authority','derived_preparation_only',
    'persistable',false,'scoringEligible',false,'requiresDurableAdmission',true,'document',document,'mappings',mappings);
end;

private.entry_association_group_active:
declare g public.candidate_entry_association_groups%rowtype; v public.canonical_resume_versions%rowtype; origin public.canonical_resume_versions%rowtype;
  m public.candidate_entry_association_members%rowtype; old_fact public.resume_facts%rowtype; current_fact public.resume_facts%rowtype;
  old_section jsonb; old_entry jsonb; current_section jsonb; current_entry jsonb; matches bigint; member_ids jsonb;
begin
  select * into g from public.candidate_entry_association_groups where id=p_group_id;
  if not found then perform private.correction_fail('unavailable'); end if;
  select * into origin from public.canonical_resume_versions where id=g.result_version_id;
  if not found or (origin.owner_id,origin.organization_id,origin.resume_id,origin.source_resume_version_id)
    is distinct from (g.owner_id,g.organization_id,g.resume_id,g.source_resume_version_id) then perform private.correction_fail('unavailable'); end if;
  select * into v from public.canonical_resume_versions where id=p_version_id;
  if not found or (v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id)
    is distinct from (origin.owner_id,origin.organization_id,origin.resume_id,origin.source_resume_version_id,origin.source_evidence_version_id) then
    perform private.correction_fail('unavailable'); end if;
  select count(*),jsonb_agg(s.value)->0 into matches,old_section from jsonb_array_elements(origin.content->'sections') s where s.value->>'id'=g.section_id::text;
  if matches<>1 then perform private.correction_fail('unavailable'); end if;
  select count(*),jsonb_agg(e.value)->0 into matches,old_entry from jsonb_array_elements(old_section->'entries') e where e.value->>'id'=g.entry_id::text;
  if matches<>1 or old_section->>'type'<>'experience' or old_entry->'bullets'<>'[]'::jsonb then perform private.correction_fail('unavailable'); end if;
  select count(*),jsonb_agg(to_jsonb(m.fact_id) order by m.entry_order) into matches,member_ids
    from public.candidate_entry_association_members m where m.group_id=g.id;
  if matches not between 2 and 3 or member_ids is distinct from old_entry->'factIds' then perform private.correction_fail('unavailable'); end if;
  select count(*),jsonb_agg(s.value)->0 into matches,current_section from jsonb_array_elements(v.content->'sections') s where s.value->>'id'=g.section_id::text;
  if matches<>1 or current_section->'type' is distinct from old_section->'type' then return false; end if;
  select count(*),jsonb_agg(e.value)->0 into matches,current_entry from jsonb_array_elements(current_section->'entries') e where e.value->>'id'=g.entry_id::text;
  if matches<>1 or current_entry->'factIds' is distinct from old_entry->'factIds' or current_entry->'bullets' is distinct from old_entry->'bullets' then return false; end if;
  for m in select * from public.candidate_entry_association_members where group_id=g.id order by entry_order loop
    select * into old_fact from public.resume_facts where canonical_version_id=origin.id and id=m.fact_id;
    if not found or (old_fact.owner_id,old_fact.organization_id,old_fact.type) is distinct from (g.owner_id,g.organization_id,m.field) then
      perform private.correction_fail('unavailable'); end if;
    select * into current_fact from public.resume_facts where canonical_version_id=v.id and id=m.fact_id;
    if not found then return false; end if;
    if (current_fact.owner_id,current_fact.organization_id,current_fact.type,current_fact.value,current_fact.sources)
      is distinct from (old_fact.owner_id,old_fact.organization_id,old_fact.type,old_fact.value,old_fact.sources) then return false; end if;
    if private.correction_location(v.content,m.fact_id) is distinct from jsonb_build_array(jsonb_build_object('kind','entry','sectionId',g.section_id,
      'entryId',g.entry_id,'bulletId',null)) then return false; end if;
  end loop;
  return true;
end;

private.entry_association_validate_head:
declare v public.canonical_resume_versions%rowtype; origin public.canonical_resume_versions%rowtype; evidence public.document_evidence_attempts%rowtype;
  s public.canonical_entry_association_snapshots%rowtype; inherited public.canonical_entry_association_snapshots%rowtype;
  b public.candidate_entry_association_batches%rowtype; g public.candidate_entry_association_groups%rowtype; m public.candidate_entry_association_members%rowtype;
  normal jsonb; binding jsonb; captured jsonb; selected jsonb; reprojected jsonb; canonical_selections jsonb; member jsonb;
  assertion jsonb; expected_sources jsonb; f public.resume_facts%rowtype; ids jsonb; entry_ids jsonb; atoms text[]; k text; n integer; count_value bigint; stream_head uuid;
begin
  select * into v from public.canonical_resume_versions where id=p_version_id;
  if not found then perform private.correction_fail('unavailable'); end if;
  if v.content->>'producerVersion' not in ('canonical-engine/1.0.0','canonical-engine/1.0.1','canonical-engine/1.0.2','canonical-engine/1.0.3')
    or private.canonical_shape_valid(case when v.content->>'producerVersion'='canonical-engine/1.0.3' then jsonb_set(v.content,'{producerVersion}','"canonical-engine/1.0.1"'::jsonb) else v.content end) is not true
    or (v.content->>'ownerId',v.content->>'organizationId',v.content->>'resumeId',v.content->>'versionId',v.content->>'sourceEvidenceVersionId')
      is distinct from (v.owner_id::text,v.organization_id::text,v.resume_id::text,v.id::text,v.source_evidence_version_id::text) then perform private.correction_fail('unavailable'); end if;
  select * into evidence from public.document_evidence_attempts where id=v.source_evidence_version_id;
  if not found or (evidence.owner_id,evidence.organization_id,evidence.resume_version_id,evidence.analysis_id::text,evidence.input_sha256)
    is distinct from (v.owner_id,v.organization_id,v.source_resume_version_id,v.content->>'analysisId',v.content->>'inputSha256') then
    perform private.correction_fail('unavailable'); end if;
  select * into s from public.canonical_entry_association_snapshots where canonical_version_id=v.id;
  if not found then
    if v.content->>'producerVersion'='canonical-engine/1.0.3' or exists(
      select 1 from public.canonical_entry_association_snapshots where canonical_version_id=v.parent_version_id and origin_batch_id is not null)
      or exists(select 1 from public.canonical_resume_versions where id=v.parent_version_id and content->>'producerVersion'='canonical-engine/1.0.3') then
      perform private.correction_fail('unavailable'); end if;
    return;
  end if;
  if (s.owner_id,s.organization_id,s.resume_id,s.source_resume_version_id,s.evidence_attempt_id)
    is distinct from (v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id) then perform private.correction_fail('unavailable'); end if;
  if (v.parent_version_id is null and (s.inherited_from_version_id is not null or s.restored_from_version_id is not null))
    or (v.parent_version_id is not null and v.command->>'operation'='rollback' and s.restored_from_version_id is distinct from (v.command->>'targetVersionId')::uuid)
    or (v.parent_version_id is not null and v.command->>'operation'<>'rollback' and s.inherited_from_version_id is distinct from v.parent_version_id) then
    perform private.correction_fail('unavailable'); end if;
  if s.inherited_from_version_id is not null then
    if s.inherited_from_version_id is distinct from v.parent_version_id then perform private.correction_fail('unavailable'); end if;
    select * into inherited from public.canonical_entry_association_snapshots where canonical_version_id=s.inherited_from_version_id;
    if found and inherited.origin_batch_id is distinct from s.origin_batch_id then perform private.correction_fail('unavailable'); end if;
    if not found and s.origin_batch_id is not null then perform private.correction_fail('unavailable'); end if;
    if exists((select group_id from public.canonical_entry_association_links where canonical_version_id=v.id)
      except (select group_id from public.canonical_entry_association_links where canonical_version_id=s.inherited_from_version_id and private.entry_association_group_active(v.id,group_id)))
      or exists((select group_id from public.canonical_entry_association_links where canonical_version_id=s.inherited_from_version_id and private.entry_association_group_active(v.id,group_id))
      except (select group_id from public.canonical_entry_association_links where canonical_version_id=v.id)) then perform private.correction_fail('unavailable'); end if;
  end if;
  if s.restored_from_version_id is not null then
    if v.command->>'operation' is distinct from 'rollback' or v.command->>'targetVersionId' is distinct from s.restored_from_version_id::text then
      perform private.correction_fail('unavailable'); end if;
    select * into inherited from public.canonical_entry_association_snapshots where canonical_version_id=s.restored_from_version_id;
    if found and inherited.origin_batch_id is distinct from s.origin_batch_id then perform private.correction_fail('unavailable'); end if;
    if not found and s.origin_batch_id is not null then perform private.correction_fail('unavailable'); end if;
    if exists((select group_id from public.canonical_entry_association_links where canonical_version_id=v.id)
      except (select group_id from public.canonical_entry_association_links where canonical_version_id=s.restored_from_version_id))
      or exists((select group_id from public.canonical_entry_association_links where canonical_version_id=s.restored_from_version_id)
      except (select group_id from public.canonical_entry_association_links where canonical_version_id=v.id)) then perform private.correction_fail('unavailable'); end if;
  end if;
  if s.origin_batch_id is null then
    if v.content->>'producerVersion'='canonical-engine/1.0.3' or exists(select 1 from public.canonical_entry_association_links where canonical_version_id=v.id) then
      perform private.correction_fail('unavailable'); end if;
    return;
  end if;
  select * into b from public.candidate_entry_association_batches where id=s.origin_batch_id;
  if not found or (b.owner_id,b.organization_id,b.resume_id,b.source_resume_version_id,b.evidence_attempt_id,b.input_sha256,b.analysis_id)
    is distinct from (v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id,evidence.input_sha256,evidence.analysis_id) then
    perform private.correction_fail('unavailable'); end if;
  select * into origin from public.canonical_resume_versions where id=b.result_version_id;
  if not found or (origin.owner_id,origin.organization_id,origin.resume_id,origin.source_resume_version_id,origin.source_evidence_version_id,origin.revision)
    is distinct from (b.owner_id,b.organization_id,b.resume_id,b.source_resume_version_id,b.evidence_attempt_id,b.result_revision)
    or origin.parent_version_id is not null or origin.content->>'producerVersion' is distinct from 'canonical-engine/1.0.3'
    or origin.idempotency_key is distinct from b.storage_key
    or origin.command is distinct from jsonb_build_object('schemaVersion','grouped-original-storage/1.0.0','operation','grouped_original_import',
      'batchId',b.id,'semanticSha256',b.command_sha256,'idempotencyKey',b.storage_key)
    or encode(extensions.digest(convert_to(origin.content::text,'UTF8'),'sha256'),'hex') is distinct from b.result_content_sha256 then
    perform private.correction_fail('unavailable'); end if;
  if s.origin_kind='grouped_import' and v.id is distinct from origin.id then perform private.correction_fail('unavailable'); end if;
  if private.grouped_import_keys(b.command,array['normalForm','previewHash','idempotencyKey']) is not true then perform private.correction_fail('unavailable'); end if;
  normal:=b.command->'normalForm'; binding:=normal->'binding'; captured:=normal->'expected'; selected:=normal->'selections';
  if private.grouped_import_keys(normal,array['schemaVersion','operation','binding','expected','acknowledgementPolicy','acknowledgement','unselectedDisposition','selections']) is not true
    or normal->>'schemaVersion' is distinct from 'grouped-original-command/1.0.0' or normal->>'operation' is distinct from 'approve_and_import_grouped_original'
    or normal->>'acknowledgementPolicy' is distinct from 'relationship_only_not_fact_confirmation' or normal->'acknowledgement' is distinct from 'true'::jsonb
    or normal->>'unselectedDisposition' is distinct from 'retain_original' or jsonb_typeof(selected) is distinct from 'array'
    or b.command->>'idempotencyKey' is distinct from b.idempotency_key::text or b.command->>'previewHash' is distinct from b.command_sha256 then
    perform private.correction_fail('unavailable'); end if;
  if jsonb_array_length(selected) not between 1 and 32 or private.grouped_import_keys(captured,array['reviewRevision','reviewHeadId','assignmentRevision','assignmentHeadId',
    'associationRevision','associationHeadId','canonicalHeadId']) is not true or captured->'canonicalHeadId' is distinct from 'null'::jsonb then
    perform private.correction_fail('unavailable'); end if;
  foreach k in array array['review','assignment','association'] loop
    if private.evidence_integer(captured->(k||'Revision'),0,2147483647) is not true then perform private.correction_fail('unavailable'); end if;
    if ((captured->>(k||'Revision'))::numeric::integer=0) is distinct from (captured->(k||'HeadId')='null'::jsonb)
      or (captured->(k||'HeadId')<>'null'::jsonb and private.grouped_import_uuid(captured->(k||'HeadId')) is not true) then perform private.correction_fail('unavailable'); end if;
  end loop;
  if (captured->>'associationRevision')::numeric::integer<>b.association_revision-1
    or captured->'associationHeadId' is distinct from coalesce(to_jsonb(b.previous_batch_id),'null'::jsonb) then perform private.correction_fail('unavailable'); end if;
  if (binding->>'ownerId',binding->>'organizationId',binding->>'resumeId',binding->>'analysisId',binding->>'sourceId',binding->>'attemptId',binding->>'inputSha256',binding->>'effectiveLocale')
    is distinct from (b.owner_id::text,b.organization_id::text,b.resume_id::text,b.analysis_id::text,b.source_resume_version_id::text,b.evidence_attempt_id::text,b.input_sha256,origin.locale) then
    perform private.correction_fail('unavailable'); end if;
  reprojected:=private.grouped_import_project_candidates(evidence.envelope,binding);
  select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into canonical_selections from jsonb_array_elements(reprojected) with ordinality
    where value in (select value from jsonb_array_elements(selected));
  if canonical_selections is distinct from selected then perform private.correction_fail('unavailable'); end if;
  atoms:=array[normal->>'schemaVersion',normal->>'operation'];
  foreach k in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256','evidenceSchemaVersion','fieldExtractorVersion',
    'targetModelVersion','associationModelVersion','producerVersion','admissionPolicyVersion','structuralTextProfileVersion','correctionProjectionModelVersion',
    'correctionAdmissionPolicyVersion','effectiveLocale'] loop atoms:=array_append(atoms,binding->>k); end loop;
  foreach k in array array['reviewRevision','reviewHeadId','assignmentRevision','assignmentHeadId','associationRevision','associationHeadId','canonicalHeadId'] loop
    atoms:=array_append(atoms,case when k like '%Revision' then ((captured->>k)::numeric::integer)::text else captured->>k end);
  end loop;
  atoms:=atoms||array['relationship_only_not_fact_confirmation','1','retain_original',jsonb_array_length(selected)::text];
  for member in select value from jsonb_array_elements(selected) loop
    atoms:=atoms||array[member->>'pageId',member->>'method',jsonb_array_length(member->'members')::text];
    for assertion in select value from jsonb_array_elements(member->'members') loop
      atoms:=atoms||array[assertion->>'assertionId',assertion->>'field','1'];
      foreach k in array array['attemptId','spanId','pageId','method','start','end','pageStart','pageEnd'] loop
        atoms:=array_append(atoms,case when k in ('start','end','pageStart','pageEnd') then ((assertion->'citations'->0->>k)::numeric::integer)::text else assertion->'citations'->0->>k end);
      end loop;
    end loop;
  end loop;
  if private.grouped_import_command_bytes(atoms) is distinct from b.command_bytes
    or private.grouped_import_command_sha256(atoms) is distinct from b.command_sha256 then perform private.correction_fail('unavailable'); end if;
  select count(*) into count_value from public.candidate_entry_association_groups where batch_id=b.id;
  if count_value<>jsonb_array_length(selected) then perform private.correction_fail('unavailable'); end if;
  n:=0;
  for g in select * from public.candidate_entry_association_groups where batch_id=b.id order by group_order loop
    n:=n+1;
    if g.group_order<>n or g.source_selection is distinct from selected->(n-1) or g.page_id is distinct from g.source_selection->>'pageId'
      or g.method is distinct from g.source_selection->>'method' then perform private.correction_fail('unavailable'); end if;
    select count(*),jsonb_agg(to_jsonb(fact_id) order by entry_order),jsonb_agg(to_jsonb(original_entry_id) order by entry_order)
      into count_value,ids,entry_ids from public.candidate_entry_association_members where group_id=g.id;
    if count_value not between 2 and 3 or count_value<>jsonb_array_length(g.source_selection->'members') then perform private.correction_fail('unavailable'); end if;
    if (select min(source_order)<>1 or max(source_order)<>count_value or min(entry_order)<>1 or max(entry_order)<>count_value
      from public.candidate_entry_association_members where group_id=g.id) then perform private.correction_fail('unavailable'); end if;
    for m in select * from public.candidate_entry_association_members where group_id=g.id order by source_order loop
      member:=g.source_selection->'members'->(m.source_order-1);
      if (m.assertion_id,m.field) is distinct from (member->>'assertionId',member->>'field') or m.citations is distinct from member->'citations'
        or (m.entry_order=1 and (m.field<>'employer' or m.original_entry_id<>g.entry_id)) then perform private.correction_fail('unavailable'); end if;
      select value into assertion from jsonb_array_elements(evidence.envelope->'assertions') where value->>'id'=m.assertion_id;
      select jsonb_agg(jsonb_build_object('attemptId',b.evidence_attempt_id,'spanId',value->'spanId','start',value->'start','end',value->'end') order by ordinality)
        into expected_sources from jsonb_array_elements(assertion->'evidence') with ordinality;
      select * into f from public.resume_facts where canonical_version_id=origin.id and id=m.fact_id;
      if not found or (f.type,f.value,f.sources) is distinct from (assertion->>'field',assertion->>'value',expected_sources)
        or f.state<>'unconfirmed' or f.confirmation is not null then perform private.correction_fail('unavailable'); end if;
    end loop;
    if (select e.value->'factIds' from jsonb_array_elements(origin.content->'sections') sec cross join lateral jsonb_array_elements(sec.value->'entries') e
      where sec.value->>'id'=g.section_id::text and e.value->>'id'=g.entry_id::text) is distinct from ids
      or private.entry_association_group_active(origin.id,g.id) is not true then perform private.correction_fail('unavailable'); end if;
  end loop;
  for stream_head in select group_id from public.canonical_entry_association_links where canonical_version_id=v.id loop
    if private.entry_association_group_active(v.id,stream_head) is not true then perform private.correction_fail('unavailable'); end if;
  end loop;
  if v.id=origin.id and (select count(*) from public.canonical_entry_association_links where canonical_version_id=v.id)<>n then
    perform private.correction_fail('unavailable'); end if;
end;

private.entry_association_prefix:
declare b public.candidate_entry_association_batches%rowtype; revision_value integer:=0; head_id uuid; k text;
begin
  if jsonb_typeof(p_scope) is distinct from 'object' then perform private.correction_fail('unavailable'); end if;
  foreach k in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId'] loop
    if private.grouped_import_uuid(p_scope->k) is not true then perform private.correction_fail('unavailable'); end if;
  end loop;
  if jsonb_typeof(p_scope->'inputSha256') is distinct from 'string' or (p_scope->>'inputSha256') collate "C" !~ '^[a-f0-9]{64}$' then
    perform private.correction_fail('unavailable'); end if;
  for b in select * from public.candidate_entry_association_batches where analysis_id=(p_scope->>'analysisId')::uuid order by association_revision loop
    revision_value:=revision_value+1;
    if revision_value>1000 or b.association_revision<>revision_value or b.previous_batch_id is distinct from head_id
      or (b.owner_id::text,b.organization_id::text,b.resume_id::text,b.analysis_id::text,b.source_resume_version_id::text,b.input_sha256)
        is distinct from (p_scope->>'ownerId',p_scope->>'organizationId',p_scope->>'resumeId',p_scope->>'analysisId',p_scope->>'sourceId',p_scope->>'inputSha256') then
      perform private.correction_fail('unavailable'); end if;
    perform private.entry_association_validate_head(b.result_version_id);
    head_id:=b.id;
  end loop;
  return jsonb_build_object('associationRevision',revision_value,'associationHeadId',head_id);
end;

private.entry_association_write_snapshot:
declare v public.canonical_resume_versions%rowtype; old public.canonical_entry_association_snapshots%rowtype;
  b public.candidate_entry_association_batches%rowtype; origin_id uuid; inherited_id uuid; restored_id uuid; kind text;
  group_ids uuid[]:='{}'; group_id uuid;
begin
  select * into v from public.canonical_resume_versions where id=p_version_id;
  if not found or v.command is distinct from p_command or exists(select 1 from public.canonical_entry_association_snapshots where canonical_version_id=v.id) then
    perform private.correction_fail('unavailable'); end if;
  if v.parent_version_id is null then
    select * into b from public.candidate_entry_association_batches where result_version_id=v.id;
    if found then
      origin_id:=b.id; kind:='grouped_import';
      for group_id in select id from public.candidate_entry_association_groups where batch_id=b.id order by group_order loop
        if private.entry_association_group_active(v.id,group_id) is not true then perform private.correction_fail('unavailable'); end if;
        group_ids:=array_append(group_ids,group_id);
      end loop;
    else kind:='legacy_empty'; end if;
  elsif p_command->>'operation'='rollback' then
    restored_id:=(p_command->>'targetVersionId')::uuid;
    perform private.entry_association_validate_head(restored_id);
    select * into old from public.canonical_entry_association_snapshots where canonical_version_id=restored_id;
    if found then origin_id:=old.origin_batch_id; kind:='restore'; else kind:='legacy_empty'; end if;
    for group_id in select l.group_id from public.canonical_entry_association_links l where l.canonical_version_id=restored_id order by l.group_id loop
      if private.entry_association_group_active(v.id,group_id) is not true then perform private.correction_fail('unavailable'); end if;
      group_ids:=array_append(group_ids,group_id);
    end loop;
  else
    inherited_id:=v.parent_version_id;
    perform private.entry_association_validate_head(inherited_id);
    select * into old from public.canonical_entry_association_snapshots where canonical_version_id=inherited_id;
    if found then origin_id:=old.origin_batch_id; kind:='inherited'; else kind:='legacy_empty'; end if;
    for group_id in select l.group_id from public.canonical_entry_association_links l where l.canonical_version_id=inherited_id order by l.group_id loop
      if private.entry_association_group_active(v.id,group_id) then group_ids:=array_append(group_ids,group_id); end if;
    end loop;
  end if;
  if v.content->>'producerVersion'='canonical-engine/1.0.3' and origin_id is null then perform private.correction_fail('unavailable'); end if;
  insert into public.canonical_entry_association_snapshots(canonical_version_id,owner_id,organization_id,resume_id,source_resume_version_id,evidence_attempt_id,
    origin_batch_id,origin_kind,inherited_from_version_id,restored_from_version_id)
    values(v.id,v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id,origin_id,kind,inherited_id,restored_id);
  foreach group_id in array group_ids loop
    insert into public.canonical_entry_association_links(canonical_version_id,group_id,owner_id,organization_id,resume_id,source_resume_version_id,origin_batch_id)
      values(v.id,group_id,v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,origin_id);
  end loop;
  perform private.entry_association_validate_head(v.id);
end;

private.grouped_original_normalize:
declare normal jsonb; expected jsonb; selection jsonb; member jsonb; citation jsonb;
  projected jsonb; canonical jsonb; prefix text; key text; value jsonb;
begin
  if private.grouped_import_keys(p_command,array['normalForm','previewHash','idempotencyKey']) is not true then perform private.correction_fail('invalid'); end if;
  if private.grouped_import_uuid(p_command->'idempotencyKey') is not true
    or jsonb_typeof(p_command->'previewHash') is distinct from 'string'
    or (p_command->>'previewHash') collate "C" !~ '^[a-f0-9]{64}$' then perform private.correction_fail('invalid'); end if;
  normal:=p_command->'normalForm'; expected:=normal->'expected';
  if private.grouped_import_keys(normal,array['schemaVersion','operation','binding','expected','acknowledgementPolicy','acknowledgement','unselectedDisposition','selections']) is not true
    or private.grouped_import_keys(expected,array['reviewRevision','reviewHeadId','assignmentRevision','assignmentHeadId','associationRevision','associationHeadId','canonicalHeadId']) is not true then
    perform private.correction_fail('invalid'); end if;
  if normal->>'schemaVersion' is distinct from 'grouped-original-command/1.0.0'
    or normal->>'operation' is distinct from 'approve_and_import_grouped_original'
    or normal->>'acknowledgementPolicy' is distinct from 'relationship_only_not_fact_confirmation'
    or normal->'acknowledgement' is distinct from 'true'::jsonb
    or normal->>'unselectedDisposition' is distinct from 'retain_original'
    or expected->'canonicalHeadId' is distinct from 'null'::jsonb then perform private.correction_fail('invalid'); end if;
  foreach prefix in array array['review','assignment','association'] loop
    value:=expected->(prefix||'Revision');
    if private.evidence_integer(value,0,2147483647) is not true then perform private.correction_fail('invalid'); end if;
    if value='0'::jsonb then
      if expected->(prefix||'HeadId') is distinct from 'null'::jsonb then perform private.correction_fail('invalid'); end if;
    elsif private.grouped_import_uuid(expected->(prefix||'HeadId')) is not true then perform private.correction_fail('invalid'); end if;
  end loop;
  foreach key in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256','evidenceSchemaVersion','fieldExtractorVersion','targetModelVersion'] loop
    if normal->'binding'->key is distinct from p_scope->key then perform private.correction_fail('conflict'); end if;
  end loop;
  if jsonb_typeof(normal->'selections') is distinct from 'array' then perform private.correction_fail('invalid'); end if;
  if jsonb_array_length(normal->'selections') not between 1 and 32 then perform private.correction_fail('invalid'); end if;
  for selection in select x.value from jsonb_array_elements(normal->'selections') x loop
    if private.grouped_import_keys(selection,array['pageId','method','members']) is not true
      or jsonb_typeof(selection->'pageId') is distinct from 'string'
      or private.grouped_import_utf16_length(selection->>'pageId') not between 1 and 200
      or selection->>'method' not in ('native_text','local_ocr') or jsonb_typeof(selection->'method') is distinct from 'string'
      or jsonb_typeof(selection->'members') is distinct from 'array' then perform private.correction_fail('invalid'); end if;
    if jsonb_array_length(selection->'members') not between 2 and 3 then perform private.correction_fail('invalid'); end if;
    for member in select x.value from jsonb_array_elements(selection->'members') x loop
      if private.grouped_import_keys(member,array['assertionId','field','citations']) is not true
        or jsonb_typeof(member->'assertionId') is distinct from 'string'
        or private.grouped_import_utf16_length(member->>'assertionId') not between 1 and 200
        or jsonb_typeof(member->'field') is distinct from 'string' or member->>'field' not in ('employer','role','dates')
        or jsonb_typeof(member->'citations') is distinct from 'array' then perform private.correction_fail('invalid'); end if;
      if jsonb_array_length(member->'citations')<>1 then perform private.correction_fail('invalid'); end if;
      citation:=member->'citations'->0;
      if private.grouped_import_keys(citation,array['attemptId','spanId','pageId','method','start','end','pageStart','pageEnd']) is not true
        or private.grouped_import_uuid(citation->'attemptId') is not true
        or jsonb_typeof(citation->'spanId') is distinct from 'string' or jsonb_typeof(citation->'pageId') is distinct from 'string'
        or private.grouped_import_utf16_length(citation->>'spanId') not between 1 and 200
        or private.grouped_import_utf16_length(citation->>'pageId') not between 1 and 200
        or jsonb_typeof(citation->'method') is distinct from 'string' or citation->>'method' not in ('native_text','local_ocr') then
        perform private.correction_fail('invalid'); end if;
      foreach key in array array['start','end','pageStart','pageEnd'] loop
        if private.evidence_integer(citation->key,0,200000) is not true then perform private.correction_fail('invalid'); end if;
      end loop;
    end loop;
  end loop;
  if private.grouped_import_keys(normal->'binding',array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256',
    'evidenceSchemaVersion','fieldExtractorVersion','targetModelVersion','associationModelVersion','producerVersion','admissionPolicyVersion',
    'structuralTextProfileVersion','correctionProjectionModelVersion','correctionAdmissionPolicyVersion','effectiveLocale']) is not true then
    perform private.correction_fail('invalid'); end if;
  for key in select jsonb_object_keys(normal->'binding') loop
    if jsonb_typeof(normal->'binding'->key) is distinct from 'string'
      or private.grouped_import_utf16_length(normal->'binding'->>key)>200 then perform private.correction_fail('invalid'); end if;
  end loop;
  if octet_length(normal::text)>131072 then perform private.correction_fail('invalid'); end if;
  -- The source projector validates every binding/model/locale and all source references.
  projected:=private.grouped_import_project_candidates(p_envelope,normal->'binding');
  select coalesce(jsonb_agg(x.value order by x.ordinality),'[]'::jsonb) into canonical
    from jsonb_array_elements(projected) with ordinality x(value,ordinality)
    where x.value in (select y.value from jsonb_array_elements(normal->'selections') y);
  if canonical is distinct from normal->'selections' then perform private.correction_fail('invalid'); end if;
  return normal;
end;

private.grouped_original_atoms:
declare atoms text[]:=array[p_normal->>'schemaVersion',p_normal->>'operation']; key text; expected_value jsonb;
  selection jsonb; member jsonb; citation jsonb;
begin
  foreach key in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256',
    'evidenceSchemaVersion','fieldExtractorVersion','targetModelVersion','associationModelVersion','producerVersion',
    'admissionPolicyVersion','structuralTextProfileVersion','correctionProjectionModelVersion','correctionAdmissionPolicyVersion','effectiveLocale'] loop
    atoms:=array_append(atoms,p_normal->'binding'->>key);
  end loop;
  foreach key in array array['reviewRevision','reviewHeadId','assignmentRevision','assignmentHeadId','associationRevision','associationHeadId','canonicalHeadId'] loop
    expected_value:=p_normal->'expected'->key;
    atoms:=array_append(atoms,case when expected_value='null'::jsonb then null when jsonb_typeof(expected_value)='number' then (expected_value#>>'{}')::numeric::bigint::text else expected_value#>>'{}' end);
  end loop;
  atoms:=atoms||array[p_normal->>'acknowledgementPolicy','1',p_normal->>'unselectedDisposition',jsonb_array_length(p_normal->'selections')::text];
  for selection in select value from jsonb_array_elements(p_normal->'selections') loop
    atoms:=atoms||array[selection->>'pageId',selection->>'method',jsonb_array_length(selection->'members')::text];
    for member in select value from jsonb_array_elements(selection->'members') loop
      atoms:=atoms||array[member->>'assertionId',member->>'field',jsonb_array_length(member->'citations')::text];
      for citation in select value from jsonb_array_elements(member->'citations') loop
        atoms:=atoms||array[citation->>'attemptId',citation->>'spanId',citation->>'pageId',citation->>'method',
          (citation->>'start')::numeric::bigint::text,(citation->>'end')::numeric::bigint::text,
          (citation->>'pageStart')::numeric::bigint::text,(citation->>'pageEnd')::numeric::bigint::text];
      end loop;
    end loop;
  end loop;
  return atoms;
end;

private.grouped_original_scope:
declare scope jsonb:=private.correction_scope(p_user_id,p_analysis_id); prefix jsonb; review_head uuid; assignment_head uuid;
begin
  select id into review_head from public.evidence_corrections where analysis_id=p_analysis_id and revision=(scope->>'reviewRevision')::bigint;
  select id into assignment_head from public.candidate_correction_assignments where analysis_id=p_analysis_id and assignment_revision=(scope->>'assignmentRevision')::bigint;
  prefix:=private.entry_association_prefix(scope);
  return scope||jsonb_build_object('reviewHeadId',review_head,'assignmentHeadId',assignment_head)||prefix;
end;

public.import_canonical_grouped_original:
declare scope jsonb; evidence public.document_evidence_attempts%rowtype; normal jsonb; atoms text[]; bytes bytea; digest text;
  prior public.candidate_entry_association_batches%rowtype; expected jsonb; placement jsonb; document jsonb; event jsonb; mapping jsonb; member jsonb;
  batch_id uuid; group_id uuid; storage_key uuid; group_order integer:=0; entry_order integer; source_order integer;
  storage_command jsonb; association_revision integer; key text;
begin
  if p_user_id is null or p_analysis_id is null or p_request_id is null or char_length(p_request_id) not between 1 and 100 then perform private.correction_fail('invalid'); end if;
  -- correction_scope takes owner-write:v1 before row locks and rechecks privacy/current source.
  scope:=private.grouped_original_scope(p_user_id,p_analysis_id);
  if private.canonical_correction_write_ready() is not true then perform private.correction_fail('unavailable'); end if;
  select * into strict evidence from public.document_evidence_attempts where id=(scope->>'attemptId')::uuid
    and owner_id=p_user_id and analysis_id=p_analysis_id and resume_version_id=(scope->>'sourceId')::uuid and input_sha256=scope->>'inputSha256';
  normal:=private.grouped_original_normalize(evidence.envelope,scope,p_command);
  atoms:=private.grouped_original_atoms(normal); bytes:=private.grouped_import_command_bytes(atoms);
  digest:=private.grouped_import_command_sha256(atoms);
  if p_command->>'previewHash' is distinct from digest then perform private.correction_fail('invalid'); end if;
  -- ORIGINAL captured prefixes/locale are compared here. No fresh CAS or raw-body validation before replay.
  select * into prior from public.candidate_entry_association_batches where resume_id=(scope->>'resumeId')::uuid
    and idempotency_key=(p_command->>'idempotencyKey')::uuid;
  if found then
    if prior.command is distinct from p_command or prior.command_bytes is distinct from bytes or prior.command_sha256 is distinct from digest
      or prior.codec_version is distinct from 'a02-command-bytes/1.0.0'
      or (prior.owner_id,prior.organization_id,prior.analysis_id,prior.source_resume_version_id,prior.evidence_attempt_id,prior.input_sha256)
        is distinct from (p_user_id,(scope->>'organizationId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid,scope->>'inputSha256') then
      perform private.correction_fail('conflict'); end if;
    perform private.entry_association_validate_head(prior.result_version_id);
    return private.grouped_original_receipt(prior.id,true);
  end if;
  expected:=normal->'expected';
  if scope->'headId' is distinct from 'null'::jsonb or expected->'canonicalHeadId' is distinct from scope->'headId' then perform private.correction_fail('conflict'); end if;
  foreach key in array array['reviewRevision','reviewHeadId','assignmentRevision','assignmentHeadId','associationRevision','associationHeadId'] loop
    if expected->key is distinct from scope->key then perform private.correction_fail('conflict'); end if;
  end loop;
  if (scope->>'associationRevision')::bigint>=1000 or private.correction_original_import_allowed(scope) is not true then perform private.correction_fail('conflict'); end if;
  -- Output locale is original submitted intent; the source validator enforces the frozen canonical syntax.
  placement:=private.grouped_import_place_original(evidence.envelope,normal->'binding',p_original,normal->'selections');
  document:=placement->'document'; event:=document->'changes'->0;
  -- Technical IDs below are allocated only after an exact replay misses.
  batch_id:=gen_random_uuid(); storage_key:=gen_random_uuid(); association_revision:=(scope->>'associationRevision')::integer+1;
  storage_command:=jsonb_build_object('schemaVersion','grouped-original-storage/1.0.0','operation','grouped_original_import',
    'batchId',batch_id,'semanticSha256',digest,'idempotencyKey',storage_key);
  insert into public.candidate_entry_association_batches(id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,
    evidence_attempt_id,input_sha256,association_revision,previous_batch_id,idempotency_key,command,command_bytes,command_sha256,codec_version,
    result_version_id,result_revision,storage_key,result_content_sha256,created_at)
    values(batch_id,p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,
      evidence.id,scope->>'inputSha256',association_revision,(scope->>'associationHeadId')::uuid,(p_command->>'idempotencyKey')::uuid,p_command,bytes,digest,
      'a02-command-bytes/1.0.0',(document->>'versionId')::uuid,1,storage_key,encode(extensions.digest(convert_to(document::text,'UTF8'),'sha256'),'hex'),now());
  insert into public.canonical_resume_versions(id,resume_id,source_resume_version_id,organization_id,owner_id,locale,state,content,created_at,
    parent_version_id,source_evidence_version_id,revision,idempotency_key,command,request_id)
    values((document->>'versionId')::uuid,(scope->>'resumeId')::uuid,(scope->>'sourceId')::uuid,(scope->>'organizationId')::uuid,p_user_id,
      document->>'locale',document->>'state',document,(document->>'createdAt')::timestamptz,null,evidence.id,1,storage_key,storage_command,p_request_id);
  insert into public.resume_facts(canonical_version_id,id,organization_id,owner_id,type,value,state,sources,confirmation)
    select (document->>'versionId')::uuid,(value->>'id')::uuid,(scope->>'organizationId')::uuid,p_user_id,
      value->>'type',value->>'value',value->>'state',value->'sources',null from jsonb_array_elements(document->'facts');
  for mapping in select value from jsonb_array_elements(placement->'mappings') loop
    group_order:=group_order+1; group_id:=gen_random_uuid();
    insert into public.candidate_entry_association_groups(id,batch_id,owner_id,organization_id,resume_id,source_resume_version_id,result_version_id,
      group_order,page_id,method,section_id,entry_id,source_selection)
      values(group_id,batch_id,p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,(scope->>'sourceId')::uuid,(document->>'versionId')::uuid,
        group_order,mapping->'selection'->>'pageId',mapping->'selection'->>'method',(mapping->>'sectionId')::uuid,(mapping->>'entryId')::uuid,mapping->'selection');
    entry_order:=0;
    for member in select value from jsonb_array_elements(mapping->'members') loop
      entry_order:=entry_order+1;
      select ordinality::integer into strict source_order from jsonb_array_elements(mapping->'selection'->'members') with ordinality
        where value->'assertionId'=member->'assertionId';
      insert into public.candidate_entry_association_members(id,group_id,batch_id,owner_id,organization_id,resume_id,source_resume_version_id,result_version_id,
        source_order,entry_order,assertion_id,field,fact_id,original_entry_id,citations)
        values(gen_random_uuid(),group_id,batch_id,p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,(scope->>'sourceId')::uuid,
          (document->>'versionId')::uuid,source_order,entry_order,member->>'assertionId',member->>'field',(member->>'factId')::uuid,
          (member->>'originalEntryId')::uuid,member->'citations');
    end loop;
  end loop;
  insert into public.change_events(canonical_version_id,id,owner_id,organization_id,actor_id,operation,event,created_at)
    values((document->>'versionId')::uuid,(event->>'id')::uuid,p_user_id,(scope->>'organizationId')::uuid,p_user_id,'import',event,(document->>'createdAt')::timestamptz);
  insert into public.canonical_resume_heads(resume_id,version_id,revision,owner_id,organization_id)
    values((scope->>'resumeId')::uuid,(document->>'versionId')::uuid,1,p_user_id,(scope->>'organizationId')::uuid);
  perform private.write_correction_snapshot((document->>'versionId')::uuid,storage_command);
  perform private.entry_association_validate_head((document->>'versionId')::uuid);
  insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
    values((scope->>'organizationId')::uuid,p_user_id,'canonical.grouped_import','canonical_resume_version',(document->>'versionId')::uuid,'success',p_request_id);
  return private.grouped_original_receipt(batch_id,false);
exception
  when insufficient_privilege then return jsonb_build_object('schemaVersion','grouped-original-result/1.0.0','status','not_found','scoringEligible',false);
  when sqlstate 'P0C01' or unique_violation then return jsonb_build_object('schemaVersion','grouped-original-result/1.0.0','status','conflict','scoringEligible',false);
  when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('schemaVersion','grouped-original-result/1.0.0','status','invalid','scoringEligible',false);
  when others then return jsonb_build_object('schemaVersion','grouped-original-result/1.0.0','status','unavailable','scoringEligible',false);
end;

public.read_grouped_original_workspace:
declare scope jsonb; evidence public.document_evidence_attempts%rowtype; result jsonb; ready boolean; permitted boolean;
begin
  if p_user_id is null or p_analysis_id is null then perform private.correction_fail('not_found'); end if;
  -- Same owner/privacy/source locks and captured prefixes as the atomic writer.
  scope:=private.grouped_original_scope(p_user_id,p_analysis_id);
  select * into strict evidence from public.document_evidence_attempts
    where id=(scope->>'attemptId')::uuid and owner_id=p_user_id
      and organization_id=(scope->>'organizationId')::uuid and analysis_id=p_analysis_id
      and resume_version_id=(scope->>'sourceId')::uuid and input_sha256=scope->>'inputSha256' for share;
  ready:=private.canonical_correction_write_ready();
  permitted:=ready and has_function_privilege('service_role','public.import_canonical_grouped_original(uuid,uuid,jsonb,jsonb,text)','EXECUTE');
  result:=jsonb_build_object('schemaVersion','grouped-original-read/1.0.0','status','available',
    'compatibilityReady',ready,'canCommit',permitted,
    'freshImportAllowed',scope->'headId'='null'::jsonb and private.correction_original_import_allowed(scope),
    'scoringEligible',false,'source',jsonb_build_object(
      'ownerId',scope->'ownerId','organizationId',scope->'organizationId','resumeId',scope->'resumeId',
      'analysisId',scope->'analysisId','sourceId',scope->'sourceId','attemptId',scope->'attemptId','inputSha256',scope->'inputSha256'),
    'captured',jsonb_build_object('reviewRevision',scope->'reviewRevision','reviewHeadId',scope->'reviewHeadId',
      'assignmentRevision',scope->'assignmentRevision','assignmentHeadId',scope->'assignmentHeadId',
      'associationRevision',scope->'associationRevision','associationHeadId',scope->'associationHeadId','canonicalHeadId',scope->'headId'),
    'attempt',jsonb_build_object('id',evidence.id,'attemptNumber',evidence.attempt_number,'envelope',evidence.envelope));
  if octet_length(convert_to(result::text,'UTF8'))>16777216 then perform private.correction_fail('unavailable'); end if;
  return result;
exception when insufficient_privilege then
  return jsonb_build_object('schemaVersion','grouped-original-read/1.0.0','status','not_found','scoringEligible',false);
when others then
  return jsonb_build_object('schemaVersion','grouped-original-read/1.0.0','status','unavailable','scoringEligible',false);
end;

private.entry_regroup_original_base:
declare v public.canonical_resume_versions%rowtype; through integer; checked jsonb;
begin
  select * into strict v from public.canonical_resume_versions where id=(p_base->>'versionId')::uuid;
  select coalesce(max(regroup_revision),0) into through from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and result_revision<=v.revision;
  checked:=private.entry_regroup_prove_data(p_scope,p_base,through,private.entry_regroup_cache());
  return checked->'data';
end;

private.entry_regroup_resolve:
declare loaded jsonb; through integer; v public.canonical_resume_versions%rowtype;
begin
  select * into strict v from public.canonical_resume_versions where id=(p_base->>'versionId')::uuid;
  select coalesce(max(regroup_revision),0) into through from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and result_revision<=v.revision;
  loaded:=private.entry_regroup_prove_data(p_scope,p_base-array['content','envelope'],through,private.entry_regroup_cache());
  if loaded->'data' is distinct from p_base then perform private.correction_fail('invalid'); end if;
  return private.entry_regroup_resolve_loaded(p_scope,loaded->'data',p_selections,loaded->'cache')-array['cache'];
end;

private.entry_regroup_atoms:
declare atoms text[]; key text; atom_value jsonb; selection jsonb; member jsonb; citation jsonb;
begin
  if private.grouped_import_keys(p_normal,array['schemaVersion','operation','binding','base','expected','acknowledgementPolicy','acknowledgement','unselectedDisposition','selections']) is not true
    or jsonb_typeof(p_normal->'selections') is distinct from 'array' then perform private.correction_fail('invalid'); end if;
  if jsonb_array_length(p_normal->'selections') not between 1 and 32 then perform private.correction_fail('invalid'); end if;
  atoms:=array[p_normal->>'schemaVersion',p_normal->>'operation'];
  foreach key in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256','evidenceSchemaVersion',
    'fieldExtractorVersion','targetModelVersion','associationModelVersion','producerVersion','admissionPolicyVersion','structuralTextProfileVersion',
    'correctionProjectionModelVersion','correctionAdmissionPolicyVersion','regroupModelVersion'] loop
    atoms:=array_append(atoms,p_normal->'binding'->>key);
  end loop;
  atoms:=atoms||array[p_normal->'base'->>'versionId',(p_normal->'base'->>'revision')::numeric::bigint::text,p_normal->'base'->>'contentSha256',p_normal->'base'->>'locale'];
  foreach key in array array['reviewRevision','reviewHeadId','assignmentRevision','assignmentHeadId','associationRevision','associationHeadId','regroupRevision','regroupHeadId','canonicalHeadId'] loop
    atom_value:=p_normal->'expected'->key;
    atoms:=array_append(atoms,case when atom_value='null'::jsonb then null when jsonb_typeof(atom_value)='number' then (atom_value#>>'{}')::numeric::bigint::text else atom_value#>>'{}' end);
  end loop;
  atoms:=atoms||array[p_normal->>'acknowledgementPolicy','1',p_normal->>'unselectedDisposition',jsonb_array_length(p_normal->'selections')::text];
  for selection in select value from jsonb_array_elements(p_normal->'selections') loop
    atoms:=atoms||array[selection->>'pageId',selection->>'method',selection->>'sectionId',selection->>'anchorEntryId',
      (selection->>'insertionIndex')::numeric::bigint::text,jsonb_array_length(selection->'affectedEntryIds')::text];
    for atom_value in select x.value from jsonb_array_elements(selection->'affectedEntryIds') x loop atoms:=array_append(atoms,atom_value#>>'{}'); end loop;
    atoms:=array_append(atoms,jsonb_array_length(selection->'members')::text);
    for member in select value from jsonb_array_elements(selection->'members') loop
      atoms:=atoms||array[member->>'assertionId',member->>'field',member->>'factId',jsonb_array_length(member->'citations')::text];
      for citation in select value from jsonb_array_elements(member->'citations') loop
        atoms:=atoms||array[citation->>'spanId',(citation->>'start')::numeric::bigint::text,(citation->>'end')::numeric::bigint::text,
          (citation->>'pageStart')::numeric::bigint::text,(citation->>'pageEnd')::numeric::bigint::text];
      end loop;
      atoms:=atoms||array[member->>'mappedThrough',member->>'originVersionId',member->'location'->>'kind',member->'location'->>'entryId',member->'location'->>'bulletId'];
    end loop;
  end loop;
  if cardinality(atoms)>1700 then perform private.correction_fail('invalid'); end if;
  perform private.grouped_import_command_bytes(atoms);
  return atoms;
end;

private.entry_regroup_normalize:
declare loaded jsonb; through integer;
begin
  if private.evidence_integer(p_command->'normalForm'->'expected'->'regroupRevision',0,1000) is not true then perform private.correction_fail('invalid'); end if;
  through:=(p_command->'normalForm'->'expected'->>'regroupRevision')::numeric::integer;
  loaded:=private.entry_regroup_prove_data(p_scope,p_command->'normalForm'->'base',through,private.entry_regroup_cache());
  return private.entry_regroup_normalize_loaded(p_scope,p_command,loaded->'data',loaded->'cache')->'normal';
end;

private.entry_regroup_base_data:
declare v public.canonical_resume_versions%rowtype; checked public.canonical_resume_versions%rowtype; evidence public.document_evidence_attempts%rowtype;
  k text; fact jsonb; section jsonb; entry jsonb; bullet jsonb; change jsonb; citation jsonb; observation jsonb; facts jsonb; ids text[]; targets text[];
  adapter jsonb; idx jsonb; quote_index jsonb:='{}'; signature text; depth integer:=0; visited uuid[]:='{}'; previous_revision integer;
  total_facts bigint:=0; total_refs bigint:=0; total_text bigint:=0; doc_text bigint;
  layers jsonb[]:='{}'; origin_json jsonb; prior_json jsonb; layer integer; matches bigint;
begin
  if private.grouped_import_keys(p_scope,array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId','inputSha256']) is not true
    or private.grouped_import_keys(p_base,array['versionId','revision','contentSha256','locale']) is not true then perform private.correction_fail('invalid'); end if;
  foreach k in array array['ownerId','organizationId','resumeId','analysisId','sourceId','attemptId'] loop
    if private.grouped_import_uuid(p_scope->k) is not true then perform private.correction_fail('invalid'); end if;
  end loop;
  if private.grouped_import_uuid(p_base->'versionId') is not true or private.evidence_integer(p_base->'revision',1,2147483647) is not true
    or jsonb_typeof(p_scope->'inputSha256') is distinct from 'string' or (p_scope->>'inputSha256') collate "C" !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_base->'contentSha256') is distinct from 'string' or (p_base->>'contentSha256') collate "C" !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_base->'locale') is distinct from 'string' or (p_base->>'locale') collate "C" !~ '^[a-z]{2,3}(?:-[A-Z]{2})?$' then perform private.correction_fail('invalid'); end if;
  select * into v from public.canonical_resume_versions where id=(p_base->>'versionId')::uuid;
  if not found or v.revision<>(p_base->>'revision')::numeric::integer or v.locale is distinct from p_base->>'locale'
    or encode(extensions.digest(convert_to(v.content::text,'UTF8'),'sha256'),'hex') is distinct from p_base->>'contentSha256' then perform private.correction_fail('invalid'); end if;
  select * into evidence from public.document_evidence_attempts where id=(p_scope->>'attemptId')::uuid
    and (owner_id,organization_id,analysis_id,resume_version_id,input_sha256)=
      ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'analysisId')::uuid,(p_scope->>'sourceId')::uuid,p_scope->>'inputSha256');
  if not found then perform private.correction_fail('invalid'); end if;
  adapter:=p_scope||jsonb_build_object('evidenceSchemaVersion','evidence/2.0.0','fieldExtractorVersion','evidence-fields/1.0.1',
    'targetModelVersion','evidence-targets/1.0.0','associationModelVersion','evidence-entry-associations/1.0.0','producerVersion','canonical-engine/1.0.3',
    'admissionPolicyVersion','grouped-original-admission/1.0.0','structuralTextProfileVersion','a02-structural-text/1.0.0',
    'correctionProjectionModelVersion','canonical-corrections/1.0.1','correctionAdmissionPolicyVersion','candidate-correction-admission/1.0.0','effectiveLocale',v.locale);
  idx:=p_index;
  if idx is null then idx:=private.grouped_import_source_index(evidence.envelope,adapter); end if;
  for observation in select value from jsonb_each(idx->'observations') loop
    select jsonb_agg(jsonb_build_array(c.value->>'attemptId',c.value->>'spanId',(c.value->>'start')::numeric::integer,(c.value->>'end')::numeric::integer)
      order by convert_to(c.value->>'attemptId','UTF8'),convert_to(c.value->>'spanId','UTF8'),(c.value->>'start')::numeric::integer,(c.value->>'end')::numeric::integer)::text
      into signature from jsonb_array_elements(observation->'citations') c(value);
    signature:=jsonb_build_array(observation->>'field',signature::jsonb)::text;
    quote_index:=quote_index||jsonb_build_object(signature,coalesce(quote_index->signature,'[]'::jsonb)||jsonb_build_array(observation->'value'));
  end loop;
  checked:=v;
  loop
    if checked.id=any(visited) or (checked.owner_id,checked.organization_id,checked.resume_id,checked.source_resume_version_id,checked.source_evidence_version_id)
      is distinct from ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,(p_scope->>'attemptId')::uuid)
      or checked.content->>'producerVersion' not in ('canonical-engine/1.0.0','canonical-engine/1.0.1','canonical-engine/1.0.2','canonical-engine/1.0.3','canonical-engine/1.0.4')
      or private.canonical_shape_valid(case when checked.content->>'producerVersion' in ('canonical-engine/1.0.3','canonical-engine/1.0.4')
        then jsonb_set(checked.content,'{producerVersion}','"canonical-engine/1.0.1"'::jsonb) else checked.content end) is not true
      or octet_length(checked.content::text)>1048576 or private.grouped_import_utf16_length(checked.content->>'retentionPolicyId')>100
      or checked.content->'parentVersionId' is distinct from coalesce(to_jsonb(checked.parent_version_id),'null'::jsonb)
      or (checked.content->>'versionId',checked.content->>'ownerId',checked.content->>'organizationId',checked.content->>'resumeId',checked.content->>'analysisId',
          checked.content->>'sourceEvidenceVersionId',checked.content->>'inputSha256',checked.content->>'locale',checked.content->>'state')
        is distinct from (checked.id::text,p_scope->>'ownerId',p_scope->>'organizationId',p_scope->>'resumeId',p_scope->>'analysisId',p_scope->>'attemptId',p_scope->>'inputSha256',checked.locale,checked.state) then perform private.correction_fail('invalid'); end if;
    visited:=array_append(visited,checked.id);
    if checked.parent_version_id=any(visited) then perform private.correction_fail('invalid'); end if;
    total_facts:=total_facts+jsonb_array_length(checked.content->'facts');
    if total_facts>20000 then perform private.correction_fail('invalid'); end if;
    -- Existing metadata proof checks an actual .3 origin; shape adaptation alone grants nothing.
    if (select count(*) from public.resume_facts where canonical_version_id=checked.id)<>jsonb_array_length(checked.content->'facts')
      or exists(select 1 from jsonb_array_elements(checked.content->'facts') j(value)
        left join public.resume_facts f on f.canonical_version_id=checked.id and f.id=(j.value->>'id')::uuid
        where f.id is null or (f.owner_id,f.organization_id) is distinct from (checked.owner_id,checked.organization_id)
          or jsonb_build_object('id',f.id,'type',f.type,'value',f.value,'state',f.state,'sources',f.sources,'confirmation',f.confirmation) is distinct from j.value) then perform private.correction_fail('invalid'); end if;
    facts:='{}'; ids:=array[checked.resume_id::text,checked.id::text]; doc_text:=0;
    for fact in select value from jsonb_array_elements(checked.content->'facts') loop
      ids:=array_append(ids,fact->>'id'); facts:=facts||jsonb_build_object(fact->>'id',fact);
      doc_text:=doc_text+private.grouped_import_utf16_length(fact->>'value'); total_refs:=total_refs+jsonb_array_length(fact->'sources');
      if private.grouped_import_utf16_length(fact->>'value')>2000 or fact->>'value' is distinct from private.grouped_import_trim(fact->>'value')
        or (fact->>'state'='source_supported' and jsonb_array_length(fact->'sources')=0)
        or (fact->>'state'='candidate_confirmed') is distinct from (fact->'confirmation'<>'null'::jsonb)
        or (fact->'confirmation'<>'null'::jsonb and ((fact->'confirmation'->>'actorId',fact->'confirmation'->>'value') is distinct from (checked.owner_id::text,fact->>'value')
          or private.grouped_import_utf16_length(fact->'confirmation'->>'value')>2000)) then perform private.correction_fail('invalid'); end if;
      for citation in select value from jsonb_array_elements(fact->'sources') loop
        if citation->>'attemptId' is distinct from checked.source_evidence_version_id::text
          or private.grouped_import_utf16_length(citation->>'spanId')>100
          or private.evidence_integer(citation->'start',0,200000) is not true or private.evidence_integer(citation->'end',1,200000) is not true
          or (citation->>'end')::numeric::integer<=(citation->>'start')::numeric::integer then perform private.correction_fail('invalid'); end if;
      end loop;
      if fact->>'type' in ('name','email','phone','employer','role','dates','education','certification') and jsonb_array_length(fact->'sources')>0 then
        select jsonb_agg(jsonb_build_array(c.value->>'attemptId',c.value->>'spanId',(c.value->>'start')::numeric::integer,(c.value->>'end')::numeric::integer)
          order by convert_to(c.value->>'attemptId','UTF8'),convert_to(c.value->>'spanId','UTF8'),(c.value->>'start')::numeric::integer,(c.value->>'end')::numeric::integer)::text
          into signature from jsonb_array_elements(fact->'sources') c(value);
        signature:=jsonb_build_array(fact->>'type',signature::jsonb)::text;
        if quote_index ? signature and not exists(select 1 from jsonb_array_elements(quote_index->signature) q(value) where q.value=fact->'value') then perform private.correction_fail('invalid'); end if;
      end if;
    end loop;
    perform private.grouped_import_check_refs(checked.content->'contactFactIds',facts); total_refs:=total_refs+jsonb_array_length(checked.content->'contactFactIds');
    if exists(select 1 from jsonb_array_elements_text(checked.content->'contactFactIds') r(id) where facts->r.id->>'type' not in ('name','email','phone','link','location')) then perform private.correction_fail('invalid'); end if;
    for section in select value from jsonb_array_elements(checked.content->'sections') loop
      ids:=array_append(ids,section->>'id'); perform private.grouped_import_check_refs(section->'factIds',facts); total_refs:=total_refs+jsonb_array_length(section->'factIds');
      doc_text:=doc_text+private.grouped_import_utf16_length(section->>'title');
      if private.grouped_import_utf16_length(private.grouped_import_trim(section->>'title')) not between 1 and 100 then perform private.correction_fail('invalid'); end if;
      for entry in select value from jsonb_array_elements(section->'entries') loop
        ids:=array_append(ids,entry->>'id'); perform private.grouped_import_check_refs(entry->'factIds',facts); total_refs:=total_refs+jsonb_array_length(entry->'factIds');
        for bullet in select value from jsonb_array_elements(entry->'bullets') loop
          ids:=array_append(ids,bullet->>'id'); perform private.grouped_import_check_refs(bullet->'factIds',facts); total_refs:=total_refs+jsonb_array_length(bullet->'factIds');
          doc_text:=doc_text+private.grouped_import_utf16_length(bullet->>'text');
          if private.grouped_import_utf16_length(bullet->>'text')>2000 or bullet->>'text' is distinct from private.grouped_import_trim(bullet->>'text') then perform private.correction_fail('invalid'); end if;
        end loop;
      end loop;
    end loop;
    targets:=ids; total_text:=total_text+doc_text;
    for change in select value from jsonb_array_elements(checked.content->'changes') loop
      ids:=array_append(ids,change->>'id');
      if change->>'actorId' is distinct from checked.owner_id::text or not (change->>'targetId'=any(targets)) then perform private.correction_fail('invalid'); end if;
      if change->'priorValue'<>'null'::jsonb then
        total_text:=total_text+private.grouped_import_utf16_length(change->>'priorValue');
        if private.grouped_import_utf16_length(change->>'priorValue')>2000 or change->>'priorValue' is distinct from private.grouped_import_trim(change->>'priorValue') then perform private.correction_fail('invalid'); end if;
      end if;
    end loop;
    if cardinality(ids)<>(select count(distinct x) from unnest(ids) x) or doc_text>200000 or total_text>2000000 or total_refs>20000 then perform private.correction_fail('invalid'); end if;
    layers:=array_append(layers,facts);
    -- A bounded suffix may stop before its root, exactly as the Node projection permits.
    if checked.parent_version_id is null or depth=64 then exit; end if;
    previous_revision:=checked.revision;
    select * into checked from public.canonical_resume_versions where id=checked.parent_version_id;
    if not found or checked.revision<>previous_revision-1 then perform private.correction_fail('invalid'); end if;
    depth:=depth+1;
  end loop;
  -- Match the existing source-choice reader's additional reference budget, including unselected choices.
  for fact in select value from jsonb_array_elements(v.content->'facts') loop
    if fact->>'type' not in ('name','email','phone','employer','role','dates','education','certification') then continue; end if;
    origin_json:=fact;
    if jsonb_array_length(fact->'sources')=0 then
      origin_json:=null;
      for layer in 2..array_length(layers,1) loop
        prior_json:=layers[layer]->(fact->>'id');
        if prior_json is null or prior_json->>'type' is distinct from fact->>'type' then exit; end if;
        if jsonb_array_length(prior_json->'sources')>0 then origin_json:=prior_json; exit; end if;
      end loop;
    end if;
    if origin_json is null then continue; end if;
    select jsonb_agg(jsonb_build_array(c.value->>'attemptId',c.value->>'spanId',(c.value->>'start')::numeric::integer,(c.value->>'end')::numeric::integer)
      order by convert_to(c.value->>'attemptId','UTF8'),convert_to(c.value->>'spanId','UTF8'),(c.value->>'start')::numeric::integer,(c.value->>'end')::numeric::integer)::text
      into signature from jsonb_array_elements(origin_json->'sources') c(value);
    signature:=jsonb_build_array(origin_json->>'type',signature::jsonb)::text;
    select count(*) into matches from jsonb_array_elements(coalesce(quote_index->signature,'[]'::jsonb)) q(value) where q.value=origin_json->'value';
    total_refs:=total_refs+matches*(1+jsonb_array_length(private.correction_location(v.content,(fact->>'id')::uuid)));
    if total_refs>20000 then perform private.correction_fail('invalid'); end if;
  end loop;
  return jsonb_build_object('versionId',v.id,'revision',v.revision,'contentSha256',p_base->'contentSha256','locale',v.locale,'content',v.content,'envelope',evidence.envelope);
end;

private.entry_regroup_resolve_loaded:
declare c jsonb:=private.entry_regroup_work(p_cache,1); cache_key text; cached jsonb; source_key text; layout_cost bigint; layout_section jsonb; layout_entry jsonb; layout_bullet jsonb; base jsonb; adapter jsonb; projected jsonb; requested jsonb:='[]'; canonical jsonb; selection jsonb; member jsonb; citation jsonb; src jsonb; assertion jsonb;
  output jsonb:='[]'; members jsonb; actual_member jsonb; actual_group jsonb; selected_ids jsonb:='{}'; seen_assertions jsonb:='{}'; used_entries jsonb:='{}';
  fact public.resume_facts%rowtype; origin_fact public.resume_facts%rowtype; version public.canonical_resume_versions%rowtype; previous_revision integer;
  location jsonb; places jsonb; source_refs jsonb; original_version uuid; through text; visited uuid[]; depth integer; k text;
  section jsonb; entry jsonb; bullet jsonb; ref text; fact_index jsonb; group_facts jsonb; affected jsonb; anchor text; section_id text;
  affected_entry jsonb; direct_refs jsonb; bullets jsonb; plans jsonb:='{}'; sections jsonb:='[]'; new_entries jsonb; retired jsonb:='[]'; index_value integer; insertion integer;
begin
  if private.grouped_import_keys(p_base,array['versionId','revision','contentSha256','locale','content','envelope']) is not true
    or jsonb_typeof(p_selections) is distinct from 'array' then perform private.correction_fail('invalid'); end if;
  if jsonb_array_length(p_selections) not between 1 and 32 then perform private.correction_fail('invalid'); end if;
  -- Only checked internal callers possess this loaded base. No proof/normalizer reentry.
  base:=p_base; cache_key:=(base->>'versionId')||':'||encode(extensions.digest(convert_to(p_selections::text,'UTF8'),'sha256'),'hex');
  if c->'resolutions' ? cache_key then return (c->'resolutions'->cache_key)||jsonb_build_object('cache',c); end if;
  adapter:=p_scope||jsonb_build_object('evidenceSchemaVersion','evidence/2.0.0','fieldExtractorVersion','evidence-fields/1.0.1',
    'targetModelVersion','evidence-targets/1.0.0','associationModelVersion','evidence-entry-associations/1.0.0','producerVersion','canonical-engine/1.0.3',
    'admissionPolicyVersion','grouped-original-admission/1.0.0','structuralTextProfileVersion','a02-structural-text/1.0.0',
    'correctionProjectionModelVersion','canonical-corrections/1.0.1','correctionAdmissionPolicyVersion','candidate-correction-admission/1.0.0','effectiveLocale',base->'locale');
  source_key:=base->'envelope'->>'id';
  c:=private.entry_regroup_work(c,1); projected:=c->'projections'->source_key;
  if projected is null then
    c:=private.entry_regroup_work(c,1+jsonb_array_length(base->'envelope'->'spans')*(1+jsonb_array_length(base->'envelope'->'assertions')));
    projected:=private.entry_regroup_project_loaded(base->'envelope',c->'sourceIndexes'->source_key);
    c:=private.entry_regroup_work(c,jsonb_array_length(projected));
    c:=jsonb_set(c,'{projections}',(c->'projections')||jsonb_build_object(source_key,projected));
  end if;
  select jsonb_object_agg(value->>'id',value) into fact_index from jsonb_array_elements(base->'content'->'facts');
  for selection in select value from jsonb_array_elements(p_selections) loop
    c:=private.entry_regroup_work(c,1);
    if private.grouped_import_keys(selection,array['pageId','method','sectionId','anchorEntryId','insertionIndex','affectedEntryIds','members']) is not true
      or jsonb_typeof(selection->'members') is distinct from 'array' then perform private.correction_fail('invalid'); end if;
    if jsonb_array_length(selection->'members') not between 2 and 3 then perform private.correction_fail('invalid'); end if;
    members:='[]';
    for member in select value from jsonb_array_elements(selection->'members') loop
    c:=private.entry_regroup_work(c,1);
      if private.grouped_import_keys(member,array['assertionId','field','factId','citations','mappedThrough','originVersionId','location']) is not true
        or private.grouped_import_keys(member->'location',array['kind','sectionId','entryId','bulletId']) is not true
        or jsonb_typeof(member->'citations') is distinct from 'array' then perform private.correction_fail('invalid'); end if;
      if jsonb_array_length(member->'citations')<>1 or private.grouped_import_uuid(member->'factId') is not true then perform private.correction_fail('invalid'); end if;
      citation:=member->'citations'->0;
      if private.grouped_import_keys(citation,array['attemptId','spanId','pageId','method','start','end','pageStart','pageEnd']) is not true then perform private.correction_fail('invalid'); end if;
      members:=members||jsonb_build_array(jsonb_build_object('assertionId',member->'assertionId','field',member->'field','citations',member->'citations'));
    end loop;
    requested:=requested||jsonb_build_array(jsonb_build_object('pageId',selection->'pageId','method',selection->'method','members',members));
  end loop;
  select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into canonical from jsonb_array_elements(projected) with ordinality
    where value in (select value from jsonb_array_elements(requested));
  if canonical is distinct from requested then perform private.correction_fail('invalid'); end if;
  for selection in select value from jsonb_array_elements(p_selections) loop
    c:=private.entry_regroup_work(c,1);
    members:='[]'; group_facts:='{}'; section_id:=null; anchor:=null;
    for member in select value from jsonb_array_elements(selection->'members') loop
    c:=private.entry_regroup_work(c,1);
      if selected_ids ? (member->>'factId') or seen_assertions ? (member->>'assertionId') then perform private.correction_fail('invalid'); end if;
      selected_ids:=selected_ids||jsonb_build_object(member->>'factId',true); seen_assertions:=seen_assertions||jsonb_build_object(member->>'assertionId',true);
      select * into fact from public.resume_facts where canonical_version_id=(base->>'versionId')::uuid and id=(member->>'factId')::uuid;
      if not found or (fact.owner_id,fact.organization_id,fact.type) is distinct from ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,member->>'field') then perform private.correction_fail('invalid'); end if;
      c:=private.entry_regroup_work(c,1);
      layout_cost:=(c->'layoutCosts'->>(base->>'versionId'))::bigint;
      if layout_cost is null then
        layout_cost:=jsonb_array_length(base->'content'->'contactFactIds');
        for layout_section in select value from jsonb_array_elements(base->'content'->'sections') loop
          c:=private.entry_regroup_work(c,1); layout_cost:=layout_cost+1+jsonb_array_length(layout_section->'factIds');
          for layout_entry in select value from jsonb_array_elements(layout_section->'entries') loop
            c:=private.entry_regroup_work(c,1); layout_cost:=layout_cost+1+jsonb_array_length(layout_entry->'factIds');
            for layout_bullet in select value from jsonb_array_elements(layout_entry->'bullets') loop
              c:=private.entry_regroup_work(c,1); layout_cost:=layout_cost+1+jsonb_array_length(layout_bullet->'factIds');
            end loop;
          end loop;
        end loop;
        c:=jsonb_set(c,'{layoutCosts}',(c->'layoutCosts')||jsonb_build_object(base->>'versionId',layout_cost));
      end if;
      -- Reserve the full frozen correction_location walk, including each container and membership reference.
      c:=private.entry_regroup_work(c,layout_cost+jsonb_array_length(base->'envelope'->'assertions'));
      places:=private.correction_location(base->'content',fact.id);
      if jsonb_array_length(places)<>1 then perform private.correction_fail('invalid'); end if;
      location:=places->0;
      if location->>'kind' not in ('entry','bullet') or location->'sectionId'='null'::jsonb or location->'entryId'='null'::jsonb then perform private.correction_fail('invalid'); end if;
      if section_id is null then section_id:=location->>'sectionId'; elsif section_id<>location->>'sectionId' then perform private.correction_fail('invalid'); end if;
      if member->>'field'='employer' then anchor:=location->>'entryId'; end if;
      select value into section from jsonb_array_elements(base->'content'->'sections') where value->>'id'=section_id;
      if not found or section->>'type'<>'experience' then perform private.correction_fail('invalid'); end if;
      origin_fact:=fact; original_version:=null; through:='current_citations';
      if jsonb_array_length(origin_fact.sources)=0 then
        through:='owned_ancestor_chain'; depth:=0; visited:='{}';
        select * into version from public.canonical_resume_versions where id=(base->>'versionId')::uuid;
        loop
          if version.parent_version_id is null or depth>=64 or version.id=any(visited) then perform private.correction_fail('invalid'); end if;
          c:=private.entry_regroup_work(c,3);
          visited:=array_append(visited,version.id); previous_revision:=version.revision;
          select * into version from public.canonical_resume_versions where id=version.parent_version_id
            and (owner_id,organization_id,resume_id,source_resume_version_id,source_evidence_version_id)=
              ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,(p_scope->>'attemptId')::uuid)
            and content->>'analysisId'=p_scope->>'analysisId' and content->>'inputSha256'=p_scope->>'inputSha256';
          if not found or version.revision<>previous_revision-1
            or version.content->>'versionId' is distinct from version.id::text
            or version.content->'parentVersionId' is distinct from coalesce(to_jsonb(version.parent_version_id),'null'::jsonb) then perform private.correction_fail('invalid'); end if;
          select * into origin_fact from public.resume_facts where canonical_version_id=version.id and id=fact.id;
          if not found or (origin_fact.owner_id,origin_fact.organization_id,origin_fact.type) is distinct from (fact.owner_id,fact.organization_id,fact.type) then perform private.correction_fail('invalid'); end if;
          c:=private.entry_regroup_work(c,jsonb_array_length(version.content->'facts'));
          if not exists(select 1 from jsonb_array_elements(version.content->'facts') j(value) where j.value=jsonb_build_object('id',origin_fact.id,
            'type',origin_fact.type,'value',origin_fact.value,'state',origin_fact.state,'sources',origin_fact.sources,'confirmation',origin_fact.confirmation)) then perform private.correction_fail('invalid'); end if;
          depth:=depth+1;
          if jsonb_array_length(origin_fact.sources)>0 then original_version:=version.id; exit; end if;
        end loop;
      end if;
      select value into assertion from jsonb_array_elements(base->'envelope'->'assertions') where value->>'id'=member->>'assertionId';
      -- Selectable groups have exactly one citation, so no collation-dependent multireference ordering is introduced.
      select jsonb_agg(jsonb_build_object('attemptId',p_scope->'attemptId','spanId',value->'spanId','start',value->'start','end',value->'end') order by ordinality)
        into source_refs from jsonb_array_elements(assertion->'evidence') with ordinality;
      if origin_fact.value is distinct from assertion->>'value' or origin_fact.type is distinct from assertion->>'field'
        or origin_fact.sources is distinct from source_refs then perform private.correction_fail('invalid'); end if;
      actual_member:=jsonb_build_object('assertionId',member->'assertionId','field',member->'field','factId',fact.id,'citations',member->'citations',
        'mappedThrough',through,'originVersionId',original_version,'location',location);
      if actual_member is distinct from member then perform private.correction_fail('invalid'); end if;
      members:=members||jsonb_build_array(actual_member); group_facts:=group_facts||jsonb_build_object(fact.id::text,true);
    end loop;
    if anchor is null then perform private.correction_fail('invalid'); end if;
    select coalesce(jsonb_agg(e.value->'id' order by e.ordinality),'[]'::jsonb),min(e.ordinality)::integer-1 into affected,insertion
      from jsonb_array_elements(section->'entries') with ordinality e(value,ordinality)
      where e.value->>'id' in (select value->'location'->>'entryId' from jsonb_array_elements(members));
    direct_refs:='[]'; bullets:='[]';
    for entry in select e.value from jsonb_array_elements(section->'entries') with ordinality e(value,ordinality)
      where e.value->'id' in (select value from jsonb_array_elements(affected)) order by e.ordinality loop
      c:=private.entry_regroup_work(c,1+jsonb_array_length(entry->'bullets'));
      if used_entries ? (entry->>'id') then perform private.correction_fail('invalid'); end if;
      used_entries:=used_entries||jsonb_build_object(entry->>'id',true);
      for ref in select jsonb_array_elements_text(entry->'factIds') union all
        select jsonb_array_elements_text(b.value->'factIds') from jsonb_array_elements(entry->'bullets') b(value) loop
        c:=private.entry_regroup_work(c,2);
        if fact_index->ref->>'type' in ('employer','role','dates') and not (group_facts ? ref) then perform private.correction_fail('invalid'); end if;
      end loop;
      direct_refs:=direct_refs||(entry->'factIds'); bullets:=bullets||(entry->'bullets');
      if entry->>'id'<>anchor then retired:=retired||jsonb_build_array(entry->'id'); end if;
    end loop;
    if jsonb_array_length(direct_refs)>100 or jsonb_array_length(bullets)>100 then perform private.correction_fail('invalid'); end if;
    perform private.grouped_import_check_refs(direct_refs,fact_index);
    actual_group:=jsonb_build_object('pageId',selection->'pageId','method',selection->'method','sectionId',section_id,'anchorEntryId',anchor,
      'insertionIndex',insertion,'affectedEntryIds',affected,'members',members);
    if actual_group is distinct from selection then perform private.correction_fail('invalid'); end if;
    output:=output||jsonb_build_array(actual_group);
    plans:=plans||jsonb_build_object(section_id||':'||insertion,jsonb_build_object('id',anchor,'factIds',direct_refs,'bullets',bullets));
  end loop;
  for section in select value from jsonb_array_elements(base->'content'->'sections') loop
    c:=private.entry_regroup_work(c,1);
    new_entries:='[]'; index_value:=0;
    for entry in select value from jsonb_array_elements(section->'entries') loop
    c:=private.entry_regroup_work(c,1);
      affected_entry:=plans->((section->>'id')||':'||index_value);
      if affected_entry is not null then new_entries:=new_entries||jsonb_build_array(affected_entry);
      elsif not (used_entries ? (entry->>'id')) then new_entries:=new_entries||jsonb_build_array(entry); end if;
      index_value:=index_value+1;
    end loop;
    sections:=sections||jsonb_build_array(jsonb_set(section,'{entries}',new_entries));
  end loop;
  cached:=jsonb_build_object('selections',output,'afterSections',sections,'retiredEntryIds',retired);
  c:=jsonb_set(c,'{resolutions}',(c->'resolutions')||jsonb_build_object(cache_key,cached));
  return cached||jsonb_build_object('cache',c);
end;

private.entry_regroup_normalize_loaded:
declare c jsonb:=p_cache; normal jsonb; base jsonb; expected jsonb; binding jsonb; resolved jsonb; prefix text; revision_value integer; head uuid; n bigint; bad boolean; k text;
begin
  if private.grouped_import_keys(p_command,array['normalForm','previewHash','idempotencyKey']) is not true
    or private.grouped_import_uuid(p_command->'idempotencyKey') is not true
    or jsonb_typeof(p_command->'previewHash') is distinct from 'string' or (p_command->>'previewHash') collate "C" !~ '^[a-f0-9]{64}$' then perform private.correction_fail('invalid'); end if;
  normal:=p_command->'normalForm';
  if private.grouped_import_keys(normal,array['schemaVersion','operation','binding','base','expected','acknowledgementPolicy','acknowledgement','unselectedDisposition','selections']) is not true
    or normal->>'schemaVersion' is distinct from 'canonical-entry-regroup-command/1.0.0'
    or normal->>'operation' is distinct from 'approve_whole_entry_regroup'
    or normal->>'acknowledgementPolicy' is distinct from 'whole_entry_merge_not_fact_confirmation'
    or normal->'acknowledgement' is distinct from 'true'::jsonb
    or normal->>'unselectedDisposition' is distinct from 'retain_eligible_original_origins'
    or octet_length(normal::text)>262144 then perform private.correction_fail('invalid'); end if;
  base:=p_loaded;
  if private.evidence_integer(normal->'base'->'revision',1,2147483646) is not true then perform private.correction_fail('invalid'); end if;
  if (base-array['content','envelope']) is distinct from normal->'base' then perform private.correction_fail('invalid'); end if;
  binding:=p_scope||jsonb_build_object('evidenceSchemaVersion','evidence/2.0.0','fieldExtractorVersion','evidence-fields/1.0.1',
    'targetModelVersion','evidence-targets/1.0.0','associationModelVersion','evidence-entry-associations/1.0.0','producerVersion','canonical-engine/1.0.4',
    'admissionPolicyVersion','whole-entry-regroup-admission/1.0.0','structuralTextProfileVersion','a02-structural-text/1.0.0',
    'correctionProjectionModelVersion','canonical-corrections/1.0.1','correctionAdmissionPolicyVersion','candidate-correction-admission/1.0.0','regroupModelVersion','canonical-entry-regroup/1.0.0');
  if normal->'binding' is distinct from binding then perform private.correction_fail('invalid'); end if;
  for k in select jsonb_object_keys(binding) loop
    if jsonb_typeof(binding->k) is distinct from 'string' or private.grouped_import_utf16_length(binding->>k)>200 then perform private.correction_fail('invalid'); end if;
  end loop;
  expected:=normal->'expected';
  if private.grouped_import_keys(expected,array['reviewRevision','reviewHeadId','assignmentRevision','assignmentHeadId','associationRevision','associationHeadId','regroupRevision','regroupHeadId','canonicalHeadId']) is not true
    or expected->'canonicalHeadId' is distinct from base->'versionId' then perform private.correction_fail('invalid'); end if;
  -- Captures are immutable GLOBAL-analysis prefixes, not today's state and not attempt-filtered history.
  foreach prefix in array array['review','assignment','association','regroup'] loop
    if private.evidence_integer(expected->(prefix||'Revision'),0,2147483647) is not true then perform private.correction_fail('invalid'); end if;
    revision_value:=(expected->>(prefix||'Revision'))::numeric::integer;
    c:=private.entry_regroup_work(c,1+3::bigint*revision_value);
    if prefix='review' and revision_value>1000 then perform private.correction_fail('invalid'); end if;
    if revision_value=0 then
      if expected->(prefix||'HeadId') is distinct from 'null'::jsonb then perform private.correction_fail('invalid'); end if;
    elsif private.grouped_import_uuid(expected->(prefix||'HeadId')) is not true then perform private.correction_fail('invalid'); end if;
    head:=null;
    if prefix='review' then
      select count(*) into n from public.evidence_corrections where analysis_id=(p_scope->>'analysisId')::uuid and revision<=revision_value;
      select id into head from public.evidence_corrections where analysis_id=(p_scope->>'analysisId')::uuid and revision=revision_value;
      select exists(select 1 from public.evidence_corrections e left join public.document_evidence_attempts a on a.id=e.attempt_id
        where e.analysis_id=(p_scope->>'analysisId')::uuid and e.revision<=revision_value and
        ((e.owner_id,e.organization_id,e.actor_id) is distinct from ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'ownerId')::uuid)
          or a.id is null or (a.owner_id,a.organization_id,a.analysis_id,a.resume_version_id,a.input_sha256) is distinct from
            ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'analysisId')::uuid,(p_scope->>'sourceId')::uuid,p_scope->>'inputSha256')
          or e.expected_revision<>e.revision-1 or e.field not in ('name','email','phone','employer','role','dates','education','certification')
          or e.operation not in ('confirm','correct') or private.grouped_import_utf16_length(e.value) not between 1 and 2000
          or e.value is distinct from private.grouped_import_trim(e.value)
          or (e.operation='confirm') is distinct from (e.candidate_id is not null)
          or (e.operation='confirm' and private.grouped_import_utf16_length(e.candidate_id) not between 1 and 100)
          or (e.operation='confirm' and e.attempt_id=(p_scope->>'attemptId')::uuid and not exists(
            select 1 from jsonb_array_elements(base->'envelope'->'assertions') a(value)
            where a.value->>'id'=e.candidate_id and a.value->>'field'=e.field and a.value->>'value'=e.value)))) into bad;
    elsif prefix='assignment' then
      select count(*) into n from public.candidate_correction_assignments where analysis_id=(p_scope->>'analysisId')::uuid and assignment_revision<=revision_value;
      select id into head from public.candidate_correction_assignments where analysis_id=(p_scope->>'analysisId')::uuid and assignment_revision=revision_value;
      select exists(select 1 from public.candidate_correction_assignments where analysis_id=(p_scope->>'analysisId')::uuid and assignment_revision<=revision_value
        and (owner_id,organization_id,resume_id,source_resume_version_id,input_sha256) is distinct from
          ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,p_scope->>'inputSha256')) into bad;
    elsif prefix='association' then
      select count(*) into n from public.candidate_entry_association_batches where analysis_id=(p_scope->>'analysisId')::uuid and association_revision<=revision_value;
      select id into head from public.candidate_entry_association_batches where analysis_id=(p_scope->>'analysisId')::uuid and association_revision=revision_value;
      select exists(select 1 from public.candidate_entry_association_batches where analysis_id=(p_scope->>'analysisId')::uuid and association_revision<=revision_value
        and (owner_id,organization_id,resume_id,source_resume_version_id,input_sha256) is distinct from
          ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,p_scope->>'inputSha256')) into bad;
    else
      select count(*) into n from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and regroup_revision<=revision_value;
      select id into head from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and regroup_revision=revision_value;
      select exists(select 1 from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and regroup_revision<=revision_value
        and (owner_id,organization_id,resume_id,source_resume_version_id,evidence_attempt_id,input_sha256) is distinct from
          ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,(p_scope->>'attemptId')::uuid,p_scope->>'inputSha256')) into bad;
    end if;
    if n<>revision_value or coalesce(to_jsonb(head),'null'::jsonb) is distinct from expected->(prefix||'HeadId') or bad then perform private.correction_fail('invalid'); end if;
  end loop;
  resolved:=private.entry_regroup_resolve_loaded(p_scope,base,normal->'selections',c); c:=resolved->'cache';
  if resolved->'selections' is distinct from normal->'selections'
    or private.grouped_import_command_sha256(private.entry_regroup_atoms(normal)) is distinct from p_command->>'previewHash' then perform private.correction_fail('invalid'); end if;
  return jsonb_build_object('normal',normal,'cache',c);
end;

private.entry_regroup_work:
begin
  if p_units is null or private.evidence_integer(p_cache->'work',0,2000000) is not true or p_units<0 or (p_cache->>'work')::bigint+p_units>2000000 then perform private.correction_fail('unavailable'); end if;
  return jsonb_set(p_cache,'{work}',to_jsonb((p_cache->>'work')::bigint+p_units));
end;

private.entry_regroup_inspect:
declare c jsonb:=private.entry_regroup_work(p_cache,1); cache_key text:=p_kind||':'||p_id; f jsonb; s jsonb; e jsonb; b jsonb; x jsonb;
  fact_count bigint:=0; refs bigint:=0; text_units bigint:=0; work bigint:=1; bytes bigint;
begin
  if p_value is null or p_id is null then perform private.correction_fail('unavailable'); end if;
  if c->'seen' ? cache_key then return c; end if;
  bytes:=octet_length(convert_to(p_value::text,'UTF8'));
  if (c->>'bytes')::bigint+bytes>33554432 or (p_kind='document' and bytes>1048576) or (p_kind='attempt' and bytes>16777216) or (p_kind='command' and bytes>262144) then perform private.correction_fail('unavailable'); end if;
  if p_kind='document' then
    if jsonb_typeof(p_value->'facts') is distinct from 'array' or jsonb_typeof(p_value->'sections') is distinct from 'array' then perform private.correction_fail('unavailable'); end if;
    c:=jsonb_set(c,'{documents}',to_jsonb((c->>'documents')::bigint+1));
    for f in select value from jsonb_array_elements(p_value->'facts') loop
      fact_count:=fact_count+1; refs:=refs+jsonb_array_length(f->'sources'); work:=work+1+jsonb_array_length(f->'sources');
      text_units:=text_units+private.grouped_import_utf16_length(f->>'value');
      if f->'confirmation'<>'null'::jsonb then text_units:=text_units+private.grouped_import_utf16_length(f->'confirmation'->>'value'); end if;
    end loop;
    refs:=refs+jsonb_array_length(p_value->'contactFactIds');
    for s in select value from jsonb_array_elements(p_value->'sections') loop
      work:=work+1; refs:=refs+jsonb_array_length(s->'factIds'); text_units:=text_units+private.grouped_import_utf16_length(s->>'title');
      for e in select value from jsonb_array_elements(s->'entries') loop
        work:=work+1; refs:=refs+jsonb_array_length(e->'factIds');
        for b in select value from jsonb_array_elements(e->'bullets') loop
          work:=work+1; refs:=refs+jsonb_array_length(b->'factIds'); text_units:=text_units+private.grouped_import_utf16_length(b->>'text');
        end loop;
      end loop;
    end loop;
    for x in select value from jsonb_array_elements(p_value->'changes') loop work:=work+1; text_units:=text_units+coalesce(private.grouped_import_utf16_length(x->>'priorValue'),0); end loop;
    work:=work+refs;
  elsif p_kind='attempt' then
    c:=jsonb_set(c,'{attempts}',to_jsonb((c->>'attempts')::bigint+1));
    for x in select value from jsonb_array_elements(p_value->'assertions') loop work:=work+1; refs:=refs+jsonb_array_length(x->'evidence'); text_units:=text_units+private.grouped_import_utf16_length(x->>'value'); end loop;
    for x in select value from jsonb_array_elements(p_value->'spans') loop work:=work+1; text_units:=text_units+private.grouped_import_utf16_length(x->>'text'); end loop;
    for x in select value from jsonb_array_elements(p_value->'nativeSource'->'pages') loop work:=work+1; text_units:=text_units+private.grouped_import_utf16_length(x->>'text'); end loop;
    work:=work+refs;
  elsif p_kind='command' then
    for s in select value from jsonb_array_elements(p_value->'normalForm'->'selections') loop
      work:=work+1;
      for x in select value from jsonb_array_elements(s->'members') loop work:=work+1; refs:=refs+jsonb_array_length(x->'citations'); end loop;
      refs:=refs+jsonb_array_length(s->'affectedEntryIds');
    end loop;
    work:=work+refs;
  elsif p_kind='review' then text_units:=private.grouped_import_utf16_length(p_value->>'value');
  end if;
  c:=jsonb_set(c,'{bytes}',to_jsonb((c->>'bytes')::bigint+bytes)); c:=jsonb_set(c,'{facts}',to_jsonb((c->>'facts')::bigint+fact_count));
  c:=jsonb_set(c,'{refs}',to_jsonb((c->>'refs')::bigint+refs)); c:=jsonb_set(c,'{text}',to_jsonb((c->>'text')::bigint+text_units));
  if (c->>'documents')::bigint>2048 or (c->>'attempts')::bigint>64 or (c->>'bytes')::bigint>33554432 or (c->>'facts')::bigint>200000
    or (c->>'refs')::bigint>400000 or (c->>'text')::bigint>8000000 then perform private.correction_fail('unavailable'); end if;
  c:=jsonb_set(c,'{seen}',(c->'seen')||jsonb_build_object(cache_key,jsonb_build_object('bytes',bytes,'facts',fact_count,'refs',refs,'text',text_units,'documents',case when p_kind='document' then 1 else 0 end,'attempts',case when p_kind='attempt' then 1 else 0 end))); return private.entry_regroup_work(c,work);
end;

private.entry_regroup_load_base:
declare c jsonb:=private.entry_regroup_work(p_cache,1); loaded jsonb; v public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype;
  id_value uuid; seen uuid[]:='{}'; depth integer:=0; doc_refs bigint; doc_work bigint; current_body jsonb; layout_cost bigint; layout_section jsonb; layout_entry jsonb; layout_bullet jsonb; critical_count bigint; index_value jsonb; adapter jsonb; source_key text; key_value text:=p_key->>'versionId';
begin
  if c->'bases' ? key_value then
    loaded:=c->'bases'->key_value; loaded:=(loaded-array['_sourceRef'])||jsonb_build_object('envelope',c->'sources'->(loaded->>'_sourceRef'));
    if (loaded-array['content','envelope']) is distinct from p_key then perform private.correction_fail('invalid'); end if;
    return jsonb_build_object('data',loaded,'cache',c);
  end if;
  -- Account each actual raw-loader suffix visit; JSON/count summaries are charged once by identity.
  id_value:=(p_key->>'versionId')::uuid;
  loop
    select * into v from public.canonical_resume_versions where id=id_value;
    if not found or id_value=any(seen) then perform private.correction_fail('invalid'); end if;
    c:=private.entry_regroup_inspect(c,'document',v.id::text,v.content); seen:=array_append(seen,id_value);
    if depth=0 then current_body:=v.content; end if;
    select jsonb_array_length(v.content->'facts')+coalesce(sum(jsonb_array_length(f.value->'sources')),0) into doc_work from jsonb_array_elements(v.content->'facts') f(value);
    -- Raw validation revisits facts, references, entries/bullets and source observations. Count these visits, not just unique JSON.
    doc_work:=doc_work+jsonb_array_length(v.content->'contactFactIds');
    select doc_work+coalesce(sum(1+jsonb_array_length(s.value->'factIds')),0) into doc_work from jsonb_array_elements(v.content->'sections') s(value);
    select doc_work+coalesce(sum(1+jsonb_array_length(x.value->'factIds')),0) into doc_work from jsonb_array_elements(v.content->'sections') s(value) cross join lateral jsonb_array_elements(s.value->'entries') x(value);
    select doc_work+coalesce(sum(1+jsonb_array_length(b.value->'factIds')),0) into doc_work from jsonb_array_elements(v.content->'sections') s(value) cross join lateral jsonb_array_elements(s.value->'entries') x(value) cross join lateral jsonb_array_elements(x.value->'bullets') b(value);
    c:=private.entry_regroup_work(c,doc_work+1);
    if v.parent_version_id is null or depth=64 then exit; end if;
    id_value:=v.parent_version_id; depth:=depth+1;
  end loop;
  select * into e from public.document_evidence_attempts where id=(p_scope->>'attemptId')::uuid;
  if not found then perform private.correction_fail('invalid'); end if;
  c:=private.entry_regroup_inspect(c,'attempt',e.id::text,e.envelope);
  -- The source/index is one immutable identity shared by every base on that attempt; locale syntax remains checked per base.
  source_key:=e.id::text;
  if not (c->'sources' ? e.id::text) then c:=jsonb_set(c,'{sources}',(c->'sources')||jsonb_build_object(e.id::text,e.envelope)); end if;
  index_value:=c->'sourceIndexes'->source_key;
  if index_value is null then
    c:=private.entry_regroup_work(c,1+jsonb_array_length(e.envelope->'assertions')+jsonb_array_length(e.envelope->'spans'));
    adapter:=p_scope||jsonb_build_object('evidenceSchemaVersion','evidence/2.0.0','fieldExtractorVersion','evidence-fields/1.0.1',
      'targetModelVersion','evidence-targets/1.0.0','associationModelVersion','evidence-entry-associations/1.0.0','producerVersion','canonical-engine/1.0.3',
      'admissionPolicyVersion','grouped-original-admission/1.0.0','structuralTextProfileVersion','a02-structural-text/1.0.0',
      'correctionProjectionModelVersion','canonical-corrections/1.0.1','correctionAdmissionPolicyVersion','candidate-correction-admission/1.0.0','effectiveLocale',p_key->'locale');
    index_value:=private.grouped_import_source_index(e.envelope,adapter);
    c:=jsonb_set(c,'{sourceIndexes}',(c->'sourceIndexes')||jsonb_build_object(source_key,index_value));
  end if;
  -- Raw source-choice accounting includes UNSELECTED critical facts. Reserve every repeated frozen layout scan.
  layout_cost:=(c->'layoutCosts'->>key_value)::bigint;
  if layout_cost is null then
    layout_cost:=jsonb_array_length(current_body->'contactFactIds');
    for layout_section in select value from jsonb_array_elements(current_body->'sections') loop
      c:=private.entry_regroup_work(c,1); layout_cost:=layout_cost+1+jsonb_array_length(layout_section->'factIds');
      for layout_entry in select value from jsonb_array_elements(layout_section->'entries') loop
        c:=private.entry_regroup_work(c,1); layout_cost:=layout_cost+1+jsonb_array_length(layout_entry->'factIds');
        for layout_bullet in select value from jsonb_array_elements(layout_entry->'bullets') loop
          c:=private.entry_regroup_work(c,1); layout_cost:=layout_cost+1+jsonb_array_length(layout_bullet->'factIds');
        end loop;
      end loop;
    end loop;
    c:=jsonb_set(c,'{layoutCosts}',(c->'layoutCosts')||jsonb_build_object(key_value,layout_cost));
  end if;
  select count(*) into critical_count from jsonb_array_elements(current_body->'facts') f(value) where f.value->>'type' in ('name','email','phone','employer','role','dates','education','certification');
  c:=private.entry_regroup_work(c,critical_count*layout_cost+jsonb_array_length(current_body->'facts')*(depth+2)::bigint);
  loaded:=private.entry_regroup_base_data(p_scope,p_key,index_value);
  c:=jsonb_set(c,'{bases}',(c->'bases')||jsonb_build_object(key_value,(loaded-array['envelope'])||jsonb_build_object('_sourceRef',e.id)));
  return jsonb_build_object('data',loaded,'cache',c);
end;

private.entry_regroup_entry_signature:
declare c jsonb:=private.entry_regroup_work(p_cache,1); s jsonb; e jsonb; f jsonb; facts jsonb:='[]'; index_value jsonb; ref text; key_value text; signature jsonb; found_section integer:=0; found_entry integer:=0;
begin
  key_value:=(p_content->>'versionId')||':'||p_section::text||':'||p_entry::text;
  if c->'signatures' ? key_value then return jsonb_build_object('signature',c->'signatures'->key_value,'cache',c); end if;
  index_value:=c->'indexes'->(p_content->>'versionId');
  if index_value is null then
    index_value:='{}';
    for f in select value from jsonb_array_elements(p_content->'facts') loop
      c:=private.entry_regroup_work(c,1);
      if index_value ? (f->>'id') then perform private.correction_fail('unavailable'); end if;
      index_value:=index_value||jsonb_build_object(f->>'id',f);
    end loop;
    c:=jsonb_set(c,'{indexes}',(c->'indexes')||jsonb_build_object(p_content->>'versionId',index_value));
  end if;
  for s in select value from jsonb_array_elements(p_content->'sections') loop
    c:=private.entry_regroup_work(c,1); if s->>'id'<>p_section::text then continue; end if;
    found_section:=found_section+1; if s->>'type'<>'experience' then continue; end if;
    for e in select value from jsonb_array_elements(s->'entries') loop
      c:=private.entry_regroup_work(c,1); if e->>'id'<>p_entry::text then continue; end if; found_entry:=found_entry+1;
      for ref in select jsonb_array_elements_text(e->'factIds') union all select jsonb_array_elements_text(value->'factIds') from jsonb_array_elements(e->'bullets') loop
        c:=private.entry_regroup_work(c,2); f:=index_value->ref;
        if f is null then perform private.correction_fail('unavailable'); end if;
        c:=private.entry_regroup_work(c,jsonb_array_length(f->'sources'));
        facts:=facts||jsonb_build_array(f->'id');
      end loop;
      c:=private.entry_regroup_work(c,jsonb_array_length(e->'bullets'));
      signature:=jsonb_build_object('sectionId',p_section,'entry',e,'factIds',facts);
    end loop;
  end loop;
  if found_section<>1 or found_entry<>1 then signature:='null'::jsonb; end if;
  c:=jsonb_set(c,'{signatures}',(c->'signatures')||jsonb_build_object(key_value,signature));
  return jsonb_build_object('signature',signature,'cache',c);
end;

private.entry_regroup_links:
declare result jsonb;
begin
  if exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=p_version) then
    select coalesce(jsonb_agg(jsonb_build_object('sectionId',section_id,'entryId',entry_id,'originFamily',origin_family,
      'associationGroupId',association_group_id,'associationBatchId',association_batch_id,'regroupGroupId',regroup_group_id,'regroupBatchId',regroup_batch_id,
      'originalApprovalVersionId',original_approval_version_id) order by composition_order),'[]'::jsonb) into result
      from public.canonical_entry_regroup_links where canonical_version_id=p_version;
  else
    select coalesce(jsonb_agg(jsonb_build_object('sectionId',g.section_id,'entryId',g.entry_id,'originFamily','association',
      'associationGroupId',g.id,'associationBatchId',g.batch_id,'regroupGroupId',null,'regroupBatchId',null,'originalApprovalVersionId',g.result_version_id)
      order by s.ordinality,e.ordinality),'[]'::jsonb) into result
      from public.canonical_entry_association_links l join public.candidate_entry_association_groups g on g.id=l.group_id
      join public.canonical_resume_versions v on v.id=p_version
      cross join lateral jsonb_array_elements(v.content->'sections') with ordinality s(value,ordinality)
      cross join lateral jsonb_array_elements(s.value->'entries') with ordinality e(value,ordinality)
      where l.canonical_version_id=p_version and s.value->>'id'=g.section_id::text and e.value->>'id'=g.entry_id::text;
  end if;
  return result;
end;

private.entry_regroup_group_active:
declare c jsonb:=p_cache; step jsonb; v public.canonical_resume_versions%rowtype; origin public.canonical_resume_versions%rowtype; old_signature jsonb; current_signature jsonb; old_fact jsonb; current_fact jsonb; ref text; active boolean;
begin
  step:=private.entry_regroup_version(p_version,c); c:=step->'cache'; select * into v from jsonb_populate_record(null::public.canonical_resume_versions,step->'row');
  step:=private.entry_regroup_version((p_link->>'originalApprovalVersionId')::uuid,c); c:=step->'cache'; select * into origin from jsonb_populate_record(null::public.canonical_resume_versions,step->'row');
  if (v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id) is distinct from
    (origin.owner_id,origin.organization_id,origin.resume_id,origin.source_resume_version_id,origin.source_evidence_version_id) then perform private.correction_fail('unavailable'); end if;
  step:=private.entry_regroup_entry_signature(origin.content,(p_link->>'sectionId')::uuid,(p_link->>'entryId')::uuid,c); c:=step->'cache'; old_signature:=step->'signature';
  step:=private.entry_regroup_entry_signature(v.content,(p_link->>'sectionId')::uuid,(p_link->>'entryId')::uuid,c); c:=step->'cache'; current_signature:=step->'signature';
  if old_signature='null'::jsonb then perform private.correction_fail('unavailable'); end if;
  active:=current_signature<>'null'::jsonb and current_signature=old_signature;
  if active then
    for ref in select jsonb_array_elements_text(old_signature->'factIds') loop
      c:=private.entry_regroup_work(c,4); old_fact:=c->'indexes'->origin.id::text->ref; current_fact:=c->'indexes'->v.id::text->ref;
      if old_fact is null or current_fact is null then perform private.correction_fail('unavailable'); end if;
      c:=private.entry_regroup_work(c,jsonb_array_length(old_fact->'sources')+jsonb_array_length(current_fact->'sources'));
      if jsonb_build_object('type',old_fact->'type','value',old_fact->'value','sources',old_fact->'sources') is distinct from
        jsonb_build_object('type',current_fact->'type','value',current_fact->'value','sources',current_fact->'sources') then active:=false; exit; end if;
    end loop;
  end if;
  return jsonb_build_object('active',active,'cache',c);
end;

private.entry_regroup_expected_links:
declare c jsonb:=p_cache; links jsonb:='[]'; result jsonb:='[]'; link jsonb; step jsonb; g public.candidate_entry_regroup_groups%rowtype;
  doc jsonb; s jsonb; e jsonb; index_value jsonb:='{}'; key_value text;
begin
  for link in select value from jsonb_array_elements(private.entry_regroup_links(p_base)) loop
    c:=private.entry_regroup_work(c,1);
    if not exists(select 1 from public.candidate_entry_regroup_groups x where x.batch_id=p_batch and x.section_id=(link->>'sectionId')::uuid and (link->>'entryId')::uuid=any(x.affected_entry_ids)) then
      step:=private.entry_regroup_group_active(p_result,link,c); c:=step->'cache'; if step->'active'='true'::jsonb then links:=links||jsonb_build_array(link); end if;
    end if;
  end loop;
  for g in select * from public.candidate_entry_regroup_groups where batch_id=p_batch order by group_order loop
    c:=private.entry_regroup_work(c,1); links:=links||jsonb_build_array(jsonb_build_object('sectionId',g.section_id,'entryId',g.anchor_entry_id,'originFamily','regroup','associationGroupId',null,
      'associationBatchId',null,'regroupGroupId',g.id,'regroupBatchId',g.batch_id,'originalApprovalVersionId',g.result_version_id));
  end loop;
  for link in select value from jsonb_array_elements(links) loop
    c:=private.entry_regroup_work(c,1); key_value:=(link->>'sectionId')||':'||(link->>'entryId');
    if index_value ? key_value then perform private.correction_fail('unavailable'); end if; index_value:=index_value||jsonb_build_object(key_value,link);
  end loop;
  step:=private.entry_regroup_version(p_result,c); c:=step->'cache'; doc:=step->'row'->'content';
  for s in select value from jsonb_array_elements(doc->'sections') loop
    c:=private.entry_regroup_work(c,1);
    for e in select value from jsonb_array_elements(s->'entries') loop
      c:=private.entry_regroup_work(c,2); link:=index_value->((s->>'id')||':'||(e->>'id'));
      if link is not null then result:=result||jsonb_build_array(link); end if;
    end loop;
  end loop;
  if jsonb_array_length(result)<>jsonb_array_length(links) or jsonb_array_length(result)>1000 then perform private.correction_fail('unavailable'); end if;
  return jsonb_build_object('links',result,'cache',c);
end;

private.entry_regroup_check_header:
declare c jsonb:=private.entry_regroup_work(p_cache,1); v public.canonical_resume_versions%rowtype; s public.canonical_entry_regroup_snapshots%rowtype;
  parent public.canonical_resume_versions%rowtype; link jsonb; expected jsonb:='[]'; actual jsonb; origin uuid; g public.candidate_entry_regroup_groups%rowtype;
  a public.candidate_entry_association_groups%rowtype; cache_key text; step jsonb; e public.document_evidence_attempts%rowtype; target uuid;
begin
  select * into strict v from public.canonical_resume_versions where id=p_version;
  c:=private.entry_regroup_inspect(c,'document',v.id::text,v.content);
  select * into strict e from public.document_evidence_attempts where id=v.source_evidence_version_id;
  if (v.owner_id,v.organization_id,v.source_resume_version_id,v.content->>'analysisId',v.content->>'inputSha256')
    is distinct from (e.owner_id,e.organization_id,e.resume_version_id,e.analysis_id::text,e.input_sha256) then perform private.correction_fail('unavailable'); end if;
  select * into s from public.canonical_entry_regroup_snapshots where canonical_version_id=v.id;
  if not found then
    if v.content->>'producerVersion'='canonical-engine/1.0.4' or exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=v.parent_version_id)
      then perform private.correction_fail('unavailable'); end if;
    perform private.entry_association_validate_head(v.id); return c;
  end if;
  c:=private.entry_regroup_inspect(c,'header',v.id::text,to_jsonb(s));
  if (s.owner_id,s.organization_id,s.resume_id,s.analysis_id,s.source_resume_version_id,s.evidence_attempt_id,s.input_sha256)
    is distinct from (v.owner_id,v.organization_id,v.resume_id,e.analysis_id,v.source_resume_version_id,e.id,e.input_sha256) then perform private.correction_fail('unavailable'); end if;
  actual:=private.entry_regroup_links(v.id);
  if s.creation_kind='inherited' then
    if s.inherited_from_version_id is distinct from v.parent_version_id or v.command->>'operation'='rollback' then perform private.correction_fail('unavailable'); end if;
    for link in select value from jsonb_array_elements(private.entry_regroup_links(v.parent_version_id)) loop
      step:=private.entry_regroup_group_active(v.id,link,c); c:=step->'cache'; if step->'active'='true'::jsonb then expected:=expected||jsonb_build_array(link); end if;
    end loop;
    if actual is distinct from expected then perform private.correction_fail('unavailable'); end if;
  elsif s.creation_kind='restore' then
    target:=s.restored_from_version_id;
    select * into strict parent from public.canonical_resume_versions where id=target;
    if v.command->>'operation' is distinct from 'rollback' or v.command->>'targetVersionId' is distinct from target::text or parent.revision>=v.revision
      or (parent.owner_id,parent.organization_id,parent.resume_id,parent.source_resume_version_id,parent.source_evidence_version_id)
        is distinct from (v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id)
      or (v.content-array['versionId','parentVersionId','createdAt','state','changes']) is distinct from
        (parent.content-array['versionId','parentVersionId','createdAt','state','changes'])
      or actual is distinct from private.entry_regroup_links(target) then perform private.correction_fail('unavailable'); end if;
  elsif s.creation_kind='regroup' then
    if not (c->'origins' ? ('regroup:'||s.creating_regroup_batch_id::text)) then perform private.correction_fail('unavailable'); end if;
  else
    if v.content->>'producerVersion'='canonical-engine/1.0.4' then perform private.correction_fail('unavailable'); end if;
    perform private.entry_association_validate_head(v.id);
    if exists(select 1 from public.canonical_entry_regroup_links where canonical_version_id=v.id) then perform private.correction_fail('unavailable'); end if;
  end if;
  for link in select value from jsonb_array_elements(actual) loop
    c:=private.entry_regroup_work(c,1);
    if link->>'originFamily'='regroup' then
      select * into strict g from public.candidate_entry_regroup_groups where id=(link->>'regroupGroupId')::uuid;
      if not (c->'origins' ? ('regroup:'||g.batch_id::text)) or (g.batch_id,g.section_id,g.anchor_entry_id,g.result_version_id)
        is distinct from ((link->>'regroupBatchId')::uuid,(link->>'sectionId')::uuid,(link->>'entryId')::uuid,(link->>'originalApprovalVersionId')::uuid)
        then perform private.correction_fail('unavailable'); end if;
    else
      select * into strict a from public.candidate_entry_association_groups where id=(link->>'associationGroupId')::uuid;
      if (a.batch_id,a.section_id,a.entry_id,a.result_version_id) is distinct from
        ((link->>'associationBatchId')::uuid,(link->>'sectionId')::uuid,(link->>'entryId')::uuid,(link->>'originalApprovalVersionId')::uuid) then perform private.correction_fail('unavailable'); end if;
      cache_key:='association:'||a.batch_id::text;
      if not (c->'origins' ? cache_key) then
        perform private.entry_association_validate_head(a.result_version_id);
        c:=jsonb_set(c,'{origins}',(c->'origins')||jsonb_build_object(cache_key,true));
      end if;
    end if;
    step:=private.entry_regroup_group_active(v.id,link,c); c:=step->'cache'; if step->'active' is distinct from 'true'::jsonb then perform private.correction_fail('unavailable'); end if;
  end loop;
  return c;
end;

private.entry_regroup_origin_proof:
declare c jsonb:=p_cache; b public.candidate_entry_regroup_batches%rowtype; v public.canonical_resume_versions%rowtype;
  g public.candidate_entry_regroup_groups%rowtype; m public.candidate_entry_regroup_members%rowtype; prior uuid; n integer:=0; k text;
  loaded jsonb; plan jsonb; selection jsonb; member jsonb; data jsonb; actual jsonb; doc jsonb; bytes bytea; digest text; group_index integer; member_index integer;
  current_link jsonb; origin public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype;
begin
  if p_through not between 0 and 1000 then perform private.correction_fail('unavailable'); end if;
  for b in select * from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and regroup_revision<=p_through order by regroup_revision loop
    c:=private.entry_regroup_work(c,1); n:=n+1;
    if b.regroup_revision<>n or b.previous_batch_id is distinct from prior or (b.owner_id,b.organization_id,b.resume_id,b.analysis_id,b.source_resume_version_id,b.evidence_attempt_id,b.input_sha256)
      is distinct from ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'analysisId')::uuid,(p_scope->>'sourceId')::uuid,(p_scope->>'attemptId')::uuid,p_scope->>'inputSha256')
      then perform private.correction_fail('unavailable'); end if;
    if c->'origins' ? ('regroup:'||b.id::text) then prior:=b.id; continue; end if;
    c:=private.entry_regroup_inspect(c,'command',b.idempotency_key::text,b.command);
    loaded:=private.entry_regroup_load_base(p_scope,b.command->'normalForm'->'base',c); c:=loaded->'cache'; data:=loaded->'data';
    c:=private.entry_regroup_check_header(b.base_version_id,c);
    if (data->>'versionId')::uuid<>b.base_version_id or (data->>'revision')::integer<>b.base_revision or data->>'contentSha256'<>b.base_content_sha256
      or b.command->'normalForm'->'expected'->>'regroupRevision'<>(n-1)::text
      or b.command->'normalForm'->'expected'->'regroupHeadId' is distinct from coalesce(to_jsonb(prior),'null'::jsonb)
      or b.command->>'idempotencyKey'<>b.idempotency_key::text then perform private.correction_fail('unavailable'); end if;
    loaded:=private.entry_regroup_normalize_loaded(p_scope,b.command,data,c); c:=loaded->'cache'; actual:=loaded->'normal';
    bytes:=private.grouped_import_command_bytes(private.entry_regroup_atoms(actual)); digest:=private.grouped_import_command_sha256(private.entry_regroup_atoms(actual));
    if b.command_bytes is distinct from bytes or b.command_sha256 is distinct from digest or b.codec_version<>'a02-command-bytes/1.0.0' then perform private.correction_fail('unavailable'); end if;
    plan:=private.entry_regroup_resolve_loaded(p_scope,data,actual->'selections',c); c:=plan->'cache';
    select * into strict v from public.canonical_resume_versions where id=b.result_version_id;
    c:=private.entry_regroup_inspect(c,'document',v.id::text,v.content);
    if (v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id,v.parent_version_id,v.revision,v.idempotency_key)
      is distinct from (b.owner_id,b.organization_id,b.resume_id,b.source_resume_version_id,b.evidence_attempt_id,b.base_version_id,b.result_revision,b.storage_key)
      or b.result_revision<>b.base_revision+1 or v.command is distinct from jsonb_build_object('schemaVersion','entry-regroup-storage/1.0.0','operation','entry_regroup',
        'batchId',b.id,'semanticSha256',b.command_sha256,'idempotencyKey',b.storage_key)
      or encode(extensions.digest(convert_to(v.content::text,'UTF8'),'sha256'),'hex') is distinct from b.result_content_sha256 then perform private.correction_fail('unavailable'); end if;
    doc:=private.entry_regroup_child_body(data->'content',plan->'afterSections',v.id,(v.content->'changes'->0->>'id')::uuid,v.content->>'createdAt');
    if doc is distinct from v.content or private.canonical_shape_valid(doc) is not true then perform private.correction_fail('unavailable'); end if;
    if (select count(*) from public.resume_facts where canonical_version_id=v.id)<>jsonb_array_length(doc->'facts') or exists(
      select 1 from jsonb_array_elements(doc->'facts') j(value) left join public.resume_facts f on f.canonical_version_id=v.id and f.id=(j.value->>'id')::uuid
      where f.id is null or (f.owner_id,f.organization_id) is distinct from (v.owner_id,v.organization_id) or
        jsonb_build_object('id',f.id,'type',f.type,'value',f.value,'state',f.state,'sources',f.sources,'confirmation',f.confirmation) is distinct from j.value) then perform private.correction_fail('unavailable'); end if;
    if (select count(*) from public.candidate_entry_regroup_groups where batch_id=b.id)<>jsonb_array_length(actual->'selections') then perform private.correction_fail('unavailable'); end if;
    group_index:=0;
    for g in select * from public.candidate_entry_regroup_groups where batch_id=b.id order by group_order loop
      c:=private.entry_regroup_work(c,1); selection:=actual->'selections'->group_index; group_index:=group_index+1;
      if (g.page_id,g.method) is distinct from (selection->>'pageId',selection->>'method') or g.group_order<>group_index or (g.base_version_id,g.result_version_id,g.section_id,g.anchor_entry_id,g.insertion_index)
        is distinct from (b.base_version_id,b.result_version_id,(selection->>'sectionId')::uuid,(selection->>'anchorEntryId')::uuid,(selection->>'insertionIndex')::integer)
        or to_jsonb(g.affected_entry_ids) is distinct from selection->'affectedEntryIds'
        or g.source_selection is distinct from jsonb_build_object('pageId',selection->'pageId','method',selection->'method','members',
          (select jsonb_agg(value-array['factId','mappedThrough','originVersionId','location'] order by ordinality) from jsonb_array_elements(selection->'members') with ordinality)) then perform private.correction_fail('unavailable'); end if;
      if (select count(*) from public.candidate_entry_regroup_members where group_id=g.id)<>jsonb_array_length(selection->'members') then perform private.correction_fail('unavailable'); end if;
      member_index:=0;
      for m in select * from public.candidate_entry_regroup_members where group_id=g.id order by source_order loop
        c:=private.entry_regroup_work(c,1); member:=selection->'members'->member_index; member_index:=member_index+1;
        if m.source_order<>member_index or (m.assertion_id,m.field,m.fact_id,m.original_entry_id,m.location_kind,m.original_bullet_id,m.mapped_through,m.origin_version_id)
          is distinct from (member->>'assertionId',member->>'field',(member->>'factId')::uuid,(member->'location'->>'entryId')::uuid,
            member->'location'->>'kind',(member->'location'->>'bulletId')::uuid,member->>'mappedThrough',(member->>'originVersionId')::uuid)
          or m.citations is distinct from member->'citations' then perform private.correction_fail('unavailable'); end if;
      end loop;
    end loop;
    -- Every inherited regroup origin is earlier and already verified; no recursive proof call exists.
    for current_link in select value from jsonb_array_elements(private.entry_regroup_links(b.base_version_id)) loop
      if current_link->>'originFamily'='regroup' then
        select * into strict origin from public.canonical_resume_versions where id=(current_link->>'originalApprovalVersionId')::uuid;
        if origin.revision>=v.revision or not (c->'origins' ? ('regroup:'||(current_link->>'regroupBatchId'))) then perform private.correction_fail('unavailable'); end if;
      end if;
    end loop;
    loaded:=private.entry_regroup_expected_links(b.base_version_id,v.id,b.id,c); c:=loaded->'cache';
    if private.entry_regroup_links(v.id) is distinct from loaded->'links' then perform private.correction_fail('unavailable'); end if;
    c:=jsonb_set(c,'{origins}',(c->'origins')||jsonb_build_object('regroup:'||b.id::text,true));
    c:=private.entry_regroup_check_header(v.id,c); prior:=b.id;
  end loop;
  if n<>p_through then perform private.correction_fail('unavailable'); end if;
  return c;
end;

private.entry_regroup_scope:
declare r public.resumes%rowtype; a public.analyses%rowtype; v public.resume_versions%rowtype; e public.document_evidence_attempts%rowtype; initial_owner uuid;
begin
  select owner_id into initial_owner from public.analyses where id=p_analysis_id;
  if p_user_id is null or initial_owner is distinct from p_user_id then perform private.correction_fail('not_found'); end if;
  perform private.lock_candidate_owners(array[p_user_id]);
  if not private.try_candidate_privacy_write(p_user_id) then perform private.correction_fail('not_found'); end if;
  select root.* into r from public.resumes root join public.resume_versions src on src.resume_id=root.id join public.analyses x on x.resume_version_id=src.id
    where x.id=p_analysis_id and x.owner_id=p_user_id and src.owner_id=p_user_id and root.owner_id=p_user_id
      and root.organization_id=src.organization_id and src.organization_id=x.organization_id for update of root;
  if not found or r.status<>'active' then perform private.correction_fail('not_found'); end if;
  select * into a from public.analyses where id=p_analysis_id and owner_id=p_user_id and organization_id=r.organization_id for update;
  if not found then perform private.correction_fail('not_found'); end if;
  perform 1 from public.memberships where organization_id=r.organization_id and user_id=p_user_id and role in ('owner','admin','member') for share;
  if not found then perform private.correction_fail('not_found'); end if;
  select * into v from public.resume_versions where id=a.resume_version_id and resume_id=r.id and owner_id=p_user_id and organization_id=r.organization_id for share;
  if not found then perform private.correction_fail('not_found'); end if;
  if p_original_attempt is null then
    select * into e from public.document_evidence_attempts where analysis_id=a.id order by attempt_number desc limit 1 for share;
  else
    select * into e from public.document_evidence_attempts where id=p_original_attempt and analysis_id=a.id for share;
  end if;
  if e.id is null or (e.owner_id,e.organization_id,e.resume_version_id,e.input_sha256) is distinct from (p_user_id,r.organization_id,v.id,v.checksum)
    or (e.envelope->>'id',e.envelope->>'ownerId',e.envelope->>'analysisId',e.envelope->>'sourceId',e.envelope->>'inputSha256')
      is distinct from (e.id::text,p_user_id::text,a.id::text,v.id::text,v.checksum) then perform private.correction_fail('unavailable'); end if;
  -- No current head, global history, current prefix cap or head proof before prior lookup.
  return jsonb_build_object('ownerId',p_user_id,'organizationId',r.organization_id,'resumeId',r.id,'analysisId',a.id,'sourceId',v.id,'attemptId',e.id,'inputSha256',v.checksum);
end;

private.entry_regroup_prove_data:
declare c jsonb:=private.entry_regroup_origin_proof(p_scope,p_through,p_cache); loaded jsonb; v public.canonical_resume_versions%rowtype; id_value uuid; depth integer:=0;
begin
  loaded:=private.entry_regroup_load_base(p_scope,p_base,c); c:=loaded->'cache'; id_value:=(p_base->>'versionId')::uuid;
  loop
    c:=private.entry_regroup_check_header(id_value,c);
    select * into strict v from public.canonical_resume_versions where id=id_value;
    if v.parent_version_id is null or depth=64 then exit; end if;
    id_value:=v.parent_version_id; depth:=depth+1;
  end loop;
  return jsonb_build_object('data',loaded->'data','cache',c);
end;

private.entry_regroup_validate_head:
declare v public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype; scope jsonb; through integer; checked jsonb;
begin
  select * into strict v from public.canonical_resume_versions where id=p_version;
  if not exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=v.id) then
    if v.content->>'producerVersion'='canonical-engine/1.0.4' or exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=v.parent_version_id)
      then perform private.correction_fail('unavailable'); end if;
    perform private.entry_association_validate_head(v.id); return;
  end if;
  select * into strict e from public.document_evidence_attempts where id=v.source_evidence_version_id;
  scope:=jsonb_build_object('ownerId',v.owner_id,'organizationId',v.organization_id,'resumeId',v.resume_id,'analysisId',e.analysis_id,
    'sourceId',v.source_resume_version_id,'attemptId',e.id,'inputSha256',e.input_sha256);
  select coalesce(max(regroup_revision),0) into through from public.candidate_entry_regroup_batches
    where analysis_id=e.analysis_id and result_revision<=v.revision;
  checked:=private.entry_regroup_prove_data(scope,jsonb_build_object('versionId',v.id,'revision',v.revision,'locale',v.locale,
    'contentSha256',encode(extensions.digest(convert_to(v.content::text,'UTF8'),'sha256'),'hex')),through,private.entry_regroup_cache());
end;

private.entry_regroup_current:
declare c jsonb:=p_cache; expected jsonb; h public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype;
  review_n bigint; assignment_n bigint; association_n bigint; regroup_n bigint; review_id uuid; assignment_id uuid; association_id uuid; regroup_id uuid;
  b public.candidate_entry_association_batches%rowtype; prior uuid; n integer:=0; checked jsonb;
begin
  select * into strict e from public.document_evidence_attempts where analysis_id=(p_scope->>'analysisId')::uuid order by attempt_number desc limit 1;
  if e.id::text is distinct from p_scope->>'attemptId' then perform private.correction_fail('conflict'); end if;
  select count(*),coalesce(max(revision),0) into review_n,assignment_n from public.evidence_corrections where analysis_id=e.analysis_id;
  if review_n<>assignment_n or review_n>1000 then perform private.correction_fail('unavailable'); end if;
  select id into review_id from public.evidence_corrections where analysis_id=e.analysis_id and revision=review_n;
  select count(*),coalesce(max(assignment_revision),0) into assignment_n,association_n from public.candidate_correction_assignments where analysis_id=e.analysis_id;
  if assignment_n<>association_n or assignment_n>1000 then perform private.correction_fail('unavailable'); end if;
  select id into assignment_id from public.candidate_correction_assignments where analysis_id=e.analysis_id and assignment_revision=assignment_n;
  select count(*),coalesce(max(association_revision),0) into association_n,regroup_n from public.candidate_entry_association_batches where analysis_id=e.analysis_id;
  if association_n<>regroup_n or association_n>1000 then perform private.correction_fail('unavailable'); end if;
  for b in select * from public.candidate_entry_association_batches where analysis_id=e.analysis_id order by association_revision loop
    c:=private.entry_regroup_work(c,1); n:=n+1;
    if b.association_revision<>n or b.previous_batch_id is distinct from prior
      or (b.owner_id,b.organization_id,b.resume_id,b.source_resume_version_id,b.input_sha256) is distinct from
        ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'resumeId')::uuid,(p_scope->>'sourceId')::uuid,p_scope->>'inputSha256') then perform private.correction_fail('unavailable'); end if;
    if not (c->'origins' ? ('association:'||b.id::text)) then
      perform private.entry_association_validate_head(b.result_version_id);
      c:=jsonb_set(c,'{origins}',(c->'origins')||jsonb_build_object('association:'||b.id::text,true));
    end if;
    prior:=b.id;
  end loop;
  association_id:=prior;
  select count(*),coalesce(max(regroup_revision),0) into regroup_n,n from public.candidate_entry_regroup_batches where analysis_id=e.analysis_id;
  if regroup_n<>n or regroup_n>1000 then perform private.correction_fail('unavailable'); end if;
  select id into regroup_id from public.candidate_entry_regroup_batches where analysis_id=e.analysis_id and regroup_revision=regroup_n;
  c:=private.entry_regroup_origin_proof(p_scope,regroup_n::integer,c);
  select v.* into h from public.canonical_resume_heads x join public.canonical_resume_versions v on v.id=x.version_id
    where x.resume_id=(p_scope->>'resumeId')::uuid for update of x;
  if h.id is null then perform private.correction_fail('conflict'); end if;
  checked:=private.entry_regroup_prove_data(p_scope,jsonb_build_object('versionId',h.id,'revision',h.revision,'locale',h.locale,
    'contentSha256',encode(extensions.digest(convert_to(h.content::text,'UTF8'),'sha256'),'hex')),regroup_n::integer,c); c:=checked->'cache';
  expected:=jsonb_build_object('reviewRevision',review_n,'reviewHeadId',review_id,'assignmentRevision',assignment_n,'assignmentHeadId',assignment_id,
    'associationRevision',association_n,'associationHeadId',association_id,'regroupRevision',regroup_n,'regroupHeadId',regroup_id,'canonicalHeadId',h.id);
  return jsonb_build_object('captured',expected,'head',checked->'data','cache',c);
end;

private.entry_regroup_review_prefix:
declare c jsonb:=p_cache; events jsonb:='[]'; chunk jsonb; event jsonb; witness jsonb; received integer:=0; pages integer:=0; last_id uuid;
  attempt public.document_evidence_attempts%rowtype; limit_revision integer;
begin
  if p_revision not between 0 and 1000 or ((p_revision=0) is distinct from (p_head is null)) then perform private.correction_fail('invalid'); end if;
  while received<p_revision loop
    -- Genuine bounded reads: immutable GLOBAL prefix, not attempt-filtered rows and not a fabricated page count.
    select coalesce(jsonb_agg(jsonb_build_object('id',id,'attempt_id',attempt_id,'analysis_id',analysis_id,'owner_id',owner_id,'actor_id',actor_id,
      'revision',revision,'expected_revision',expected_revision,'field',field,'operation',operation,'value',value,'candidate_id',candidate_id,
      'created_at',to_char(created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) order by revision),'[]'::jsonb) into chunk
      from (select * from public.evidence_corrections where analysis_id=(p_scope->>'analysisId')::uuid and revision>received and revision<=p_revision order by revision limit 100) page;
    if jsonb_array_length(chunk)=0 then perform private.correction_fail('unavailable'); end if;
    pages:=pages+1; if pages>10 then perform private.correction_fail('unavailable'); end if;
    for event in select value from jsonb_array_elements(chunk) loop
      c:=private.entry_regroup_inspect(c,'review',event->>'id',event); received:=received+1;
      if (event->>'revision')::integer<>received or (event->>'expected_revision')::integer<>received-1
        or (event->>'owner_id',event->>'actor_id',event->>'analysis_id') is distinct from (p_scope->>'ownerId',p_scope->>'ownerId',p_scope->>'analysisId')
        or event->>'field' not in ('name','email','phone','employer','role','dates','education','certification')
        or event->>'operation' not in ('confirm','correct') or private.grouped_import_utf16_length(event->>'value') not between 1 and 2000
        or event->>'value' is distinct from private.grouped_import_trim(event->>'value')
        or ((event->>'operation'='confirm') is distinct from (event->'candidate_id'<>'null'::jsonb)) then perform private.correction_fail('unavailable'); end if;
      select * into strict attempt from public.document_evidence_attempts where id=(event->>'attempt_id')::uuid;
      if (attempt.owner_id,attempt.organization_id,attempt.analysis_id,attempt.resume_version_id,attempt.input_sha256)
        is distinct from ((p_scope->>'ownerId')::uuid,(p_scope->>'organizationId')::uuid,(p_scope->>'analysisId')::uuid,(p_scope->>'sourceId')::uuid,p_scope->>'inputSha256') then perform private.correction_fail('unavailable'); end if;
      c:=private.entry_regroup_inspect(c,'attempt',attempt.id::text,attempt.envelope);
      if event->>'operation'='confirm' and (private.grouped_import_utf16_length(event->>'candidate_id') not between 1 and 100 or
        (attempt.id::text=p_scope->>'attemptId' and not exists(select 1 from jsonb_array_elements(attempt.envelope->'assertions') x(value)
          where x.value->>'id'=event->>'candidate_id' and x.value->>'field'=event->>'field' and x.value->>'value'=event->>'value'))) then perform private.correction_fail('unavailable'); end if;
      last_id:=(event->>'id')::uuid;
    end loop;
    events:=events||chunk;
  end loop;
  if received<>p_revision or last_id is distinct from p_head then perform private.correction_fail('unavailable'); end if;
  select * into strict attempt from public.document_evidence_attempts where id=(p_scope->>'attemptId')::uuid;
  witness:=jsonb_build_object('schemaVersion','evidence-review-history/1.0.0','state','complete_captured_prefix',
    'binding',(p_scope-array['organizationId','resumeId'])||jsonb_build_object('evidenceSchemaVersion','evidence/2.0.0','fieldExtractorVersion',attempt.envelope->'fieldExtractorVersion','targetModelVersion','evidence-targets/1.0.0'),
    'highWaterRevision',p_revision,'highWaterEventId',p_head,'receivedCount',received,'pageCount',pages);
  return jsonb_build_object('review',jsonb_build_object('revision',p_revision,'headId',p_head,'events',events,'historyAttestation',witness),'cache',c);
end;

private.entry_regroup_save_version:
declare c jsonb; b public.candidate_entry_regroup_batches%rowtype; base public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype; event jsonb; bytes bytea; digest text;
begin
  if private.grouped_import_keys(p_command,array['schemaVersion','operation','batchId','semanticSha256','idempotencyKey']) is not true
    or p_command->>'schemaVersion'<>'entry-regroup-storage/1.0.0' or p_command->>'operation'<>'entry_regroup'
    or private.grouped_import_uuid(p_command->'batchId') is not true or private.grouped_import_uuid(p_command->'idempotencyKey') is not true
    or p_request_id is null or char_length(p_request_id) not between 1 and 100 then perform private.correction_fail('invalid'); end if;
  select * into strict b from public.candidate_entry_regroup_batches where id=(p_command->>'batchId')::uuid;
  -- Protected pending rows are the authority. Committed inner commands cannot bypass outer semantic replay.
  if exists(select 1 from public.canonical_resume_versions where id=b.result_version_id) then raise exception 'REGROUP_REQUIRES_OUTER_REPLAY' using errcode='22023'; end if;
  select * into strict base from public.canonical_resume_versions where id=b.base_version_id;
  select * into strict e from public.document_evidence_attempts where id=b.evidence_attempt_id;
  bytes:=private.grouped_import_command_bytes(private.entry_regroup_atoms(b.command->'normalForm')); digest:=private.grouped_import_command_sha256(private.entry_regroup_atoms(b.command->'normalForm'));
  if p_command is distinct from jsonb_build_object('schemaVersion','entry-regroup-storage/1.0.0','operation','entry_regroup','batchId',b.id,'semanticSha256',b.command_sha256,'idempotencyKey',b.storage_key)
    or b.command_bytes is distinct from bytes or b.command_sha256 is distinct from digest or b.command->>'previewHash' is distinct from digest
    or b.codec_version<>'a02-command-bytes/1.0.0' or b.storage_key=b.idempotency_key
    or (b.owner_id,b.organization_id,b.resume_id,b.source_resume_version_id,b.evidence_attempt_id,b.base_revision)
      is distinct from (p_user_id,base.organization_id,base.resume_id,p_source_id,base.source_evidence_version_id,base.revision)
    or (e.owner_id,e.organization_id,e.analysis_id,e.resume_version_id,e.input_sha256) is distinct from (b.owner_id,b.organization_id,b.analysis_id,b.source_resume_version_id,b.input_sha256)
    or b.base_content_sha256 is distinct from encode(extensions.digest(convert_to(base.content::text,'UTF8'),'sha256'),'hex')
    or not exists(select 1 from public.canonical_resume_heads where resume_id=b.resume_id and version_id=b.base_version_id and revision=b.base_revision)
    or b.result_content_sha256 is distinct from encode(extensions.digest(convert_to(p_body::text,'UTF8'),'sha256'),'hex')
    or private.canonical_shape_valid(p_body) is not true or octet_length(p_body::text)>1048576
    or p_body->>'producerVersion'<>'canonical-engine/1.0.4' or p_body->>'versionId'<>b.result_version_id::text
    or p_body->>'parentVersionId'<>b.base_version_id::text or b.result_revision<>b.base_revision+1
    or p_body->'facts' is distinct from base.content->'facts' or p_body->'contactFactIds' is distinct from base.content->'contactFactIds'
    or (p_body-array['versionId','parentVersionId','createdAt','producerVersion','state','sections','changes']) is distinct from
      (base.content-array['versionId','parentVersionId','createdAt','producerVersion','state','sections','changes']) then perform private.correction_fail('invalid'); end if;
  event:=p_body->'changes'->0;
  if jsonb_array_length(p_body->'changes')<>1 or event->>'actorId'<>p_user_id::text or event->>'action'<>'edit'
    or event->>'targetId'<>b.resume_id::text or event->'priorValue'<>'null'::jsonb or event->'createdAt' is distinct from p_body->'createdAt' then perform private.correction_fail('invalid'); end if;
  insert into public.canonical_resume_versions(id,resume_id,source_resume_version_id,organization_id,owner_id,locale,state,content,created_at,parent_version_id,
    source_evidence_version_id,revision,idempotency_key,command,request_id)
    values(b.result_version_id,b.resume_id,b.source_resume_version_id,b.organization_id,b.owner_id,p_body->>'locale',p_body->>'state',p_body,(p_body->>'createdAt')::timestamptz,
      b.base_version_id,b.evidence_attempt_id,b.result_revision,b.storage_key,p_command,p_request_id);
  insert into public.resume_facts(canonical_version_id,id,organization_id,owner_id,type,value,state,sources,confirmation)
    select b.result_version_id,(value->>'id')::uuid,b.organization_id,b.owner_id,value->>'type',value->>'value',value->>'state',value->'sources',nullif(value->'confirmation','null'::jsonb) from jsonb_array_elements(p_body->'facts');
  insert into public.change_events(canonical_version_id,id,organization_id,owner_id,actor_id,operation,event,created_at)
    values(b.result_version_id,(event->>'id')::uuid,b.organization_id,b.owner_id,b.owner_id,'edit',event,(p_body->>'createdAt')::timestamptz);
  update public.canonical_resume_heads set version_id=b.result_version_id,revision=b.result_revision where resume_id=b.resume_id and version_id=b.base_version_id and revision=b.base_revision;
  if not found then perform private.correction_fail('conflict'); end if;
  c:=private.entry_regroup_correction_snapshot_work(b.result_version_id,p_command,private.entry_regroup_cache());
  insert into public.audit_events(organization_id,actor_id,action,target_type,target_id,outcome,request_id)
    values(b.organization_id,b.owner_id,'canonical.entry_regroup','canonical_resume_version',b.result_version_id,'success',p_request_id);
  return jsonb_build_object('status','applied','versionId',b.result_version_id,'revision',b.result_revision,'idempotent',false,'internalAccounting',c);
end;

private.entry_regroup_receipt:
declare b public.candidate_entry_regroup_batches%rowtype;
begin
  select * into strict b from public.candidate_entry_regroup_batches where id=p_batch;
  return jsonb_build_object('schemaVersion','entry-regroup-result/1.0.0','status','applied','baseVersionId',b.base_version_id,'baseRevision',b.base_revision,
    'idempotencyKey',b.idempotency_key,'commandSha256',b.command_sha256,'versionId',b.result_version_id,'revision',b.result_revision,'batchId',b.id,
    'regroupRevision',b.regroup_revision,'regroupHeadId',b.id,'idempotent',p_replayed,'scoringEligible',false);
end;

public.apply_canonical_entry_regroup:
declare scope jsonb; prior public.candidate_entry_regroup_batches%rowtype; normal jsonb; c jsonb:=private.entry_regroup_cache(); loaded jsonb; data jsonb; current_view jsonb;
  bytes bytea; digest text; plan jsonb; document jsonb; storage jsonb; result jsonb; expected jsonb; selection jsonb; member jsonb; g uuid; batch uuid; version uuid; change uuid; inner_key uuid;
  created text; group_index integer:=0; member_index integer; through integer; checked jsonb;
begin
  if private.grouped_import_keys(p_command,array['normalForm','previewHash','idempotencyKey']) is not true or private.grouped_import_uuid(p_command->'idempotencyKey') is not true
    or private.grouped_import_uuid(p_command->'normalForm'->'binding'->'attemptId') is not true or p_request_id is null or char_length(p_request_id) not between 1 and 100 then perform private.correction_fail('invalid'); end if;
  scope:=private.entry_regroup_scope(p_user_id,p_analysis_id,(p_command->'normalForm'->'binding'->>'attemptId')::uuid);
  if private.canonical_correction_write_ready() is not true then perform private.correction_fail('unavailable'); end if;
  select * into prior from public.candidate_entry_regroup_batches where resume_id=(scope->>'resumeId')::uuid and idempotency_key=(p_command->>'idempotencyKey')::uuid;
  if found then
    if prior.command is distinct from p_command or (prior.owner_id,prior.organization_id,prior.analysis_id,prior.source_resume_version_id,prior.evidence_attempt_id,prior.input_sha256)
      is distinct from (p_user_id,(scope->>'organizationId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid,scope->>'inputSha256') then perform private.correction_fail('conflict'); end if;
    -- Only ORIGINAL prefix proof; neither current head nor later history participates.
    c:=private.entry_regroup_origin_proof(scope,prior.regroup_revision,c);
    return private.entry_regroup_receipt(prior.id,true);
  end if;
  normal:=p_command->'normalForm';
  if private.evidence_integer(normal->'expected'->'regroupRevision',0,1000) is not true then perform private.correction_fail('invalid'); end if;
  through:=(normal->'expected'->>'regroupRevision')::numeric::integer;
  loaded:=private.entry_regroup_prove_data(scope,normal->'base',through,c); c:=loaded->'cache'; data:=loaded->'data';
  c:=private.entry_regroup_inspect(c,'command',p_command->>'idempotencyKey',p_command);
  checked:=private.entry_regroup_normalize_loaded(scope,p_command,data,c); c:=checked->'cache'; normal:=checked->'normal'; bytes:=private.grouped_import_command_bytes(private.entry_regroup_atoms(normal)); digest:=private.grouped_import_command_sha256(private.entry_regroup_atoms(normal));
  current_view:=private.entry_regroup_current(scope,c); c:=current_view->'cache'; expected:=normal->'expected';
  if current_view->'captured' is distinct from expected or (current_view->'head'-array['content','envelope']) is distinct from normal->'base' then perform private.correction_fail('conflict'); end if;
  if through>=1000 then perform private.correction_fail('unavailable'); end if;
  plan:=private.entry_regroup_resolve_loaded(scope,data,normal->'selections',c); c:=plan->'cache';
  -- Technical allocation occurs only after prior miss and every fresh check.
  batch:=gen_random_uuid(); version:=gen_random_uuid(); change:=gen_random_uuid(); inner_key:=gen_random_uuid();
  created:=to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  document:=private.entry_regroup_child_body(data->'content',plan->'afterSections',version,change,created);
  c:=private.entry_regroup_inspect(c,'document',version::text,document);
  storage:=jsonb_build_object('schemaVersion','entry-regroup-storage/1.0.0','operation','entry_regroup','batchId',batch,'semanticSha256',digest,'idempotencyKey',inner_key);
  insert into public.candidate_entry_regroup_batches(id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,evidence_attempt_id,input_sha256,
    regroup_revision,previous_batch_id,idempotency_key,command,command_bytes,command_sha256,codec_version,base_version_id,base_revision,base_content_sha256,
    result_version_id,result_revision,result_content_sha256,storage_key)
    values(batch,p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid,scope->>'inputSha256',
      through+1,(expected->>'regroupHeadId')::uuid,(p_command->>'idempotencyKey')::uuid,p_command,bytes,digest,'a02-command-bytes/1.0.0',
      (data->>'versionId')::uuid,(data->>'revision')::integer,data->>'contentSha256',version,(data->>'revision')::integer+1,
      encode(extensions.digest(convert_to(document::text,'UTF8'),'sha256'),'hex'),inner_key);
  for selection in select value from jsonb_array_elements(normal->'selections') loop
    c:=private.entry_regroup_work(c,1); group_index:=group_index+1; g:=gen_random_uuid();
    insert into public.candidate_entry_regroup_groups(id,batch_id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,evidence_attempt_id,input_sha256,
      base_version_id,result_version_id,group_order,page_id,method,section_id,anchor_entry_id,insertion_index,affected_entry_ids,source_selection)
      values(g,batch,p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid,scope->>'inputSha256',
        (data->>'versionId')::uuid,version,group_index,selection->>'pageId',selection->>'method',(selection->>'sectionId')::uuid,(selection->>'anchorEntryId')::uuid,
        (selection->>'insertionIndex')::integer,array(select jsonb_array_elements_text(selection->'affectedEntryIds'))::uuid[],
        jsonb_build_object('pageId',selection->'pageId','method',selection->'method','members',(select jsonb_agg(value-array['factId','mappedThrough','originVersionId','location'] order by ordinality) from jsonb_array_elements(selection->'members') with ordinality)));
    member_index:=0;
    for member in select value from jsonb_array_elements(selection->'members') loop
      c:=private.entry_regroup_work(c,1); member_index:=member_index+1;
      insert into public.candidate_entry_regroup_members(id,group_id,batch_id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,evidence_attempt_id,input_sha256,
        base_version_id,result_version_id,source_order,assertion_id,field,fact_id,citations,original_entry_id,location_kind,original_bullet_id,mapped_through,origin_version_id,origin_fact_id)
        values(gen_random_uuid(),g,batch,p_user_id,(scope->>'organizationId')::uuid,(scope->>'resumeId')::uuid,p_analysis_id,(scope->>'sourceId')::uuid,(scope->>'attemptId')::uuid,scope->>'inputSha256',
          (data->>'versionId')::uuid,version,member_index,member->>'assertionId',member->>'field',(member->>'factId')::uuid,member->'citations',(member->'location'->>'entryId')::uuid,
          member->'location'->>'kind',(member->'location'->>'bulletId')::uuid,member->>'mappedThrough',(member->>'originVersionId')::uuid,
          case when member->>'mappedThrough'='owned_ancestor_chain' then (member->>'factId')::uuid else null end);
    end loop;
  end loop;
  result:=public.save_canonical_version(p_user_id,(scope->>'sourceId')::uuid,document,storage,p_request_id);
  if result->>'status' is distinct from 'applied' or result->'idempotent' is distinct from 'false'::jsonb or result->>'versionId' is distinct from version::text then perform private.correction_fail('conflict'); end if;
  c:=private.entry_regroup_merge_work(c,result->'internalAccounting');
  c:=private.entry_regroup_origin_proof(scope,through+1,c);
  return private.entry_regroup_receipt(batch,false);
exception when insufficient_privilege then return jsonb_build_object('schemaVersion','entry-regroup-result/1.0.0','status','not_found','scoringEligible',false);
when sqlstate 'P0C01' or unique_violation then return jsonb_build_object('schemaVersion','entry-regroup-result/1.0.0','status','conflict','scoringEligible',false);
when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('schemaVersion','entry-regroup-result/1.0.0','status','invalid','scoringEligible',false);
when others then return jsonb_build_object('schemaVersion','entry-regroup-result/1.0.0','status','unavailable','scoringEligible',false);
end;

public.read_canonical_entry_regroup_work:
declare scope jsonb; v public.canonical_resume_versions%rowtype; ancestor public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype;
  base jsonb; historical jsonb; review jsonb; current_view jsonb; c jsonb:=private.entry_regroup_cache(); loaded jsonb; ancestors jsonb:='[]'; result jsonb;
  revision_value integer; review_id uuid; depth integer:=0; through integer; compatible boolean; permitted boolean;
begin
  if p_original_capture is not null then
    if private.grouped_import_keys(p_original_capture,array['base','reviewRevision','reviewHeadId']) is not true
      or private.grouped_import_keys(p_original_capture->'base',array['versionId','revision','contentSha256','locale']) is not true
      or private.grouped_import_uuid(p_original_capture->'base'->'versionId') is not true
      or private.evidence_integer(p_original_capture->'reviewRevision',0,1000) is not true then perform private.correction_fail('invalid'); end if;
    select * into v from public.canonical_resume_versions where id=(p_original_capture->'base'->>'versionId')::uuid
      and owner_id=p_user_id and content->>'analysisId'=p_analysis_id::text;
    if not found then perform private.correction_fail('not_found'); end if;
    scope:=private.entry_regroup_scope(p_user_id,p_analysis_id,v.source_evidence_version_id);
    base:=p_original_capture->'base'; revision_value:=(p_original_capture->>'reviewRevision')::numeric::integer;
    if revision_value=0 then
      if p_original_capture->'reviewHeadId' is distinct from 'null'::jsonb then perform private.correction_fail('invalid'); end if;
    elsif private.grouped_import_uuid(p_original_capture->'reviewHeadId') is not true then perform private.correction_fail('invalid'); end if;
    review_id:=(p_original_capture->>'reviewHeadId')::uuid;
  else
    scope:=private.entry_regroup_scope(p_user_id,p_analysis_id,null);
    select cv.* into v from public.canonical_resume_heads h join public.canonical_resume_versions cv on cv.id=h.version_id
      where h.resume_id=(scope->>'resumeId')::uuid and cv.owner_id=p_user_id and cv.content->>'analysisId'=p_analysis_id::text;
    if not found then perform private.correction_fail('not_found'); end if;
    -- A saved old-attempt head is still a historical source; freshness is reported separately.
    scope:=private.entry_regroup_scope(p_user_id,p_analysis_id,v.source_evidence_version_id);
    base:=jsonb_build_object('versionId',v.id,'revision',v.revision,'locale',v.locale,'contentSha256',encode(extensions.digest(convert_to(v.content::text,'UTF8'),'sha256'),'hex'));
    select coalesce(max(revision),0) into revision_value from public.evidence_corrections where analysis_id=p_analysis_id;
    if revision_value>1000 then perform private.correction_fail('unavailable'); end if;
    select id into review_id from public.evidence_corrections where analysis_id=p_analysis_id and revision=revision_value;
  end if;
  select coalesce(max(regroup_revision),0) into through from public.candidate_entry_regroup_batches where analysis_id=p_analysis_id and result_revision<=v.revision;
  loaded:=private.entry_regroup_prove_data(scope,base,through,c); c:=loaded->'cache';
  ancestor:=v;
  while ancestor.parent_version_id is not null and depth<64 loop
    select * into strict ancestor from public.canonical_resume_versions where id=ancestor.parent_version_id;
    if (ancestor.owner_id,ancestor.organization_id,ancestor.resume_id,ancestor.source_resume_version_id,ancestor.source_evidence_version_id)
      is distinct from (v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,v.source_evidence_version_id) then perform private.correction_fail('unavailable'); end if;
    ancestors:=ancestors||jsonb_build_array(jsonb_build_object('versionId',ancestor.id,'revision',ancestor.revision,'content',ancestor.content)); depth:=depth+1;
  end loop;
  review:=private.entry_regroup_review_prefix(scope,revision_value,review_id,c); c:=review->'cache';
  historical:=jsonb_build_object('base',base||jsonb_build_object('content',loaded->'data'->'content'),'ancestors',ancestors,'review',review->'review');
  compatible:=private.canonical_correction_write_ready();
  permitted:=compatible and has_function_privilege('service_role','public.apply_canonical_entry_regroup(uuid,uuid,jsonb,text)','EXECUTE');
  begin
    current_view:=private.entry_regroup_current(scope,c); c:=current_view->'cache';
    current_view:=jsonb_build_object('status','available','captured',current_view->'captured',
      'freshCanPreview',(current_view->'head'-array['content','envelope'])=base and revision_value=(current_view->'captured'->>'reviewRevision')::integer
        and (current_view->'head'->>'revision')::bigint<2147483647 and (current_view->'captured'->>'regroupRevision')::integer<1000,
      'freshCanCommit',permitted and (current_view->'head'-array['content','envelope'])=base and revision_value=(current_view->'captured'->>'reviewRevision')::integer
        and (current_view->'head'->>'revision')::bigint<2147483647 and (current_view->'captured'->>'regroupRevision')::integer<1000);
  exception when others then current_view:=jsonb_build_object('status','unavailable'); end;
  select * into strict e from public.document_evidence_attempts where id=(scope->>'attemptId')::uuid;
  result:=jsonb_build_object('schemaVersion','entry-regroup-read/1.0.0','status','available','scoringEligible',false,'source',scope,
    'attempt',jsonb_build_object('id',e.id,'attemptNumber',e.attempt_number,'envelope',e.envelope),'historical',historical,'current',current_view,
    'compatibilityReady',compatible,'canRetry',permitted);
  if octet_length(convert_to(result::text,'UTF8'))>33554432 then perform private.correction_fail('unavailable'); end if;
  return result;
exception when insufficient_privilege then return jsonb_build_object('schemaVersion','entry-regroup-read/1.0.0','status','not_found','scoringEligible',false);
when others then return jsonb_build_object('schemaVersion','entry-regroup-read/1.0.0','status','unavailable','scoringEligible',false);
end;

private.entry_regroup_version:
declare c jsonb:=private.entry_regroup_work(p_cache,1); v public.canonical_resume_versions%rowtype; row_value jsonb;
begin
  if c->'versions' ? p_version::text then return jsonb_build_object('row',c->'versions'->p_version::text,'cache',c); end if;
  select * into strict v from public.canonical_resume_versions where id=p_version;
  c:=private.entry_regroup_inspect(c,'document',v.id::text,v.content); c:=private.entry_regroup_work(c,1);
  row_value:=to_jsonb(v); c:=jsonb_set(c,'{versions}',(c->'versions')||jsonb_build_object(p_version::text,row_value));
  return jsonb_build_object('row',row_value,'cache',c);
end;

private.entry_regroup_merge_work:
declare c jsonb:=private.entry_regroup_work(p_outer,(p_inner->>'work')::bigint); k text; metric text; summary jsonb;
begin
  for k,summary in select key,value from jsonb_each(p_inner->'seen') loop
    c:=private.entry_regroup_work(c,1);
    if not (c->'seen' ? k) then
      foreach metric in array array['documents','attempts','bytes','facts','refs','text'] loop
        c:=jsonb_set(c,array[metric],to_jsonb((c->>metric)::bigint+(summary->>metric)::bigint));
      end loop;
      c:=jsonb_set(c,'{seen}',(c->'seen')||jsonb_build_object(k,summary));
    end if;
  end loop;
  if (c->>'documents')::bigint>2048 or (c->>'attempts')::bigint>64 or (c->>'bytes')::bigint>33554432 or (c->>'facts')::bigint>200000 or (c->>'refs')::bigint>400000 or (c->>'text')::bigint>8000000 then perform private.correction_fail('unavailable'); end if;
  foreach k in array array['versions','indexes','signatures','resolutions','layoutCosts','sources','sourceIndexes','projections'] loop c:=jsonb_set(c,array[k],(c->k)||(p_inner->k)); end loop;
  return c;
end;

private.entry_regroup_snapshot_work:
declare c jsonb:=p_cache; step jsonb; v public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype; batch public.candidate_entry_regroup_batches%rowtype;
  kind text; inherited uuid; restored uuid; links jsonb:='[]'; link jsonb; i integer:=0;
begin
  select * into strict v from public.canonical_resume_versions where id=p_version;
  if v.command is distinct from p_command or exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=v.id) then perform private.correction_fail('unavailable'); end if;
  select * into batch from public.candidate_entry_regroup_batches where result_version_id=v.id;
  if batch.id is not null then
    kind:='regroup'; step:=private.entry_regroup_expected_links(batch.base_version_id,v.id,batch.id,c); c:=step->'cache'; links:=step->'links';
  elsif p_command->>'operation'='rollback' and (exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=v.parent_version_id)
    or exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=(p_command->>'targetVersionId')::uuid)) then
    kind:='restore'; restored:=(p_command->>'targetVersionId')::uuid; links:=private.entry_regroup_links(restored);
  elsif exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=v.parent_version_id) then
    kind:='inherited'; inherited:=v.parent_version_id;
    for link in select value from jsonb_array_elements(private.entry_regroup_links(inherited)) loop
      step:=private.entry_regroup_group_active(v.id,link,c); c:=step->'cache'; if step->'active'='true'::jsonb then links:=links||jsonb_build_array(link); end if;
    end loop;
  else
    if v.content->>'producerVersion'='canonical-engine/1.0.4' then perform private.correction_fail('unavailable'); end if;
    perform private.entry_association_write_snapshot(v.id,p_command); return c;
  end if;
  select * into strict e from public.document_evidence_attempts where id=v.source_evidence_version_id;
  insert into public.canonical_entry_regroup_snapshots(canonical_version_id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,evidence_attempt_id,input_sha256,
    composition_version,creation_kind,creating_regroup_batch_id,inherited_from_version_id,restored_from_version_id)
    values(v.id,v.owner_id,v.organization_id,v.resume_id,e.analysis_id,v.source_resume_version_id,e.id,e.input_sha256,
      'entry-regroup-composition/1.0.0',kind,batch.id,inherited,restored);
  for link in select value from jsonb_array_elements(links) loop
    i:=i+1;
    step:=private.entry_regroup_group_active(v.id,link,c); c:=step->'cache'; if step->'active' is distinct from 'true'::jsonb then perform private.correction_fail('unavailable'); end if;
    insert into public.canonical_entry_regroup_links(canonical_version_id,owner_id,organization_id,resume_id,analysis_id,source_resume_version_id,evidence_attempt_id,input_sha256,
      composition_order,section_id,entry_id,origin_family,association_group_id,association_batch_id,regroup_group_id,regroup_batch_id,original_approval_version_id)
      values(v.id,v.owner_id,v.organization_id,v.resume_id,e.analysis_id,v.source_resume_version_id,e.id,e.input_sha256,i,(link->>'sectionId')::uuid,(link->>'entryId')::uuid,
        link->>'originFamily',(link->>'associationGroupId')::uuid,(link->>'associationBatchId')::uuid,(link->>'regroupGroupId')::uuid,(link->>'regroupBatchId')::uuid,(link->>'originalApprovalVersionId')::uuid);
  end loop;
  return c;
end;

private.entry_regroup_project_loaded:
declare idx jsonb:=p_index; pair record; bucket record; span jsonb; obs jsonb;
  protected jsonb:='{}'; preserved jsonb:='{}'; assigned jsonb:='{}'; values_here jsonb; relevant jsonb;
  kind text; text_value text; folded text; ws text:='['||private.grouped_import_whitespace()||']';
  block jsonb; ambiguous boolean; in_employment boolean; mode text; prefix text[]; field_name text;
  group_value jsonb; result jsonb:='[]'; suffix text; start_pos integer; end_pos integer; exact_line boolean; labels_count integer;
begin
  for pair in select key,value from jsonb_each(idx->'bySpan') loop
    select coalesce(jsonb_agg(ob.value order by (ob.value->>'ordinal')::numeric::integer),'[]'::jsonb) into values_here from jsonb_each(pair.value) keys
      cross join lateral (values (idx->'observations'->keys.key)) ob(value)
      where ob.value->>'field' in ('employer','role','dates','education','certification');
    kind:=private.grouped_import_same_span(idx->'spans'->pair.key->>'text',values_here);
    if kind is not null then
      protected:=protected||jsonb_build_object(pair.key,kind);
      for obs in select value from jsonb_array_elements(values_here) loop preserved:=preserved||jsonb_build_object(obs->>'assertionId',true); end loop;
    end if;
  end loop;
  for bucket in select value->>'pageId' as page_id,value->>'method' as method,min(ordinality) as first_ordinal
    from jsonb_array_elements(p_envelope->'spans') with ordinality group by value->>'pageId',value->>'method' order by min(ordinality) loop
    in_employment:=false; block:=null; ambiguous:=false;
    for span in select value from jsonb_array_elements(p_envelope->'spans') with ordinality
      where value->>'pageId'=bucket.page_id and value->>'method'=bucket.method order by (value->>'start')::numeric::integer,ordinality loop
      text_value:=span->>'text'; folded:=private.grouped_import_ascii_lower(text_value);
      select coalesce(jsonb_agg(ob.value order by (ob.value->>'firstOrdinal')::numeric::integer,(ob.value->'citations'->0->>'start')::numeric::integer,(ob.value->>'ordinal')::numeric::integer),'[]'::jsonb)
        into values_here from jsonb_each(coalesce(idx->'bySpan'->(span->>'id'),'{}'::jsonb)) keys
        cross join lateral (values (idx->'observations'->keys.key)) ob(value) where not (preserved ? (ob.value->>'assertionId'));
      select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into relevant from jsonb_array_elements(values_here) with ordinality
        where value->>'field' in ('employer','role','dates');
      prefix:=regexp_match(folded collate "C",'^([\t ]*(employer|role|dates):[\t ]*)'); field_name:=prefix[2];
      mode:=case
        when private.grouped_import_trim(folded)=any(array['employment','experience','work experience','professional experience','employment history']) then 'heading'
        when exists(select 1 from jsonb_array_elements(values_here) where value->>'field' not in ('employer','role','dates'))
          or exists(select 1 from regexp_matches(text_value collate "C",'(?:^[\t ]*|[|;]'||ws||'*)([A-Za-z][A-Za-z ]*):','g') label
            where private.grouped_import_ascii_lower(private.grouped_import_trim(label[1])) not in ('employer','role','dates')) then 'barrier'
        when protected ? (span->>'id') then 'protected'
        when private.grouped_import_trim(text_value)='' then 'blank'
        when prefix is null then 'unlabelled' else 'labelled' end;
      if mode<>'labelled' or (in_employment and field_name='employer') then
        group_value:=private.grouped_import_flush(block,ambiguous,assigned);
        if group_value is not null then
          result:=result||jsonb_build_array(group_value);
          for obs in select value from jsonb_array_elements(group_value->'members') loop assigned:=assigned||jsonb_build_object(obs->>'assertionId',true); end loop;
        end if;
        block:=null; ambiguous:=false;
      end if;
      if mode='heading' then in_employment:=true; continue;
      elsif mode='barrier' or mode='unlabelled' then in_employment:=false; continue;
      elsif mode='protected' then if protected->>(span->>'id')<>'employment' then in_employment:=false; end if; continue;
      elsif mode='blank' then continue;
      end if;
      if not in_employment then continue; end if;
      suffix:=substring(text_value from char_length(prefix[1])+1);
      start_pos:=char_length(prefix[1])+char_length(suffix)-char_length(ltrim(suffix,private.grouped_import_whitespace()));
      end_pos:=char_length(rtrim(text_value,private.grouped_import_whitespace()));
      select count(*) into labels_count from regexp_matches(folded collate "C",'(?:^[\t ]*|[|;]'||ws||'*)(employer|role|dates)'||ws||'*:','g');
      obs:=relevant->0;
      exact_line:=jsonb_array_length(values_here)=1 and jsonb_array_length(relevant)=1 and obs->>'field'=field_name
        and jsonb_array_length(obs->'citations')=1 and obs->'citations'->0->'spanId'=span->'id'
        and obs->'citations'->0->'start'=to_jsonb(start_pos) and obs->'citations'->0->'end'=to_jsonb(end_pos)
        and obs->>'value'=private.grouped_import_trim(suffix) and labels_count=1;
      if exact_line is not true then block:=coalesce(block,'[]'::jsonb)||relevant; ambiguous:=true; continue; end if;
      if block is null and field_name<>'employer' then continue; end if;
      block:=coalesce(block,'[]'::jsonb);
      if exists(select 1 from jsonb_array_elements(block) where value->>'field'=field_name) then ambiguous:=true; end if;
      block:=block||jsonb_build_array(obs);
    end loop;
    group_value:=private.grouped_import_flush(block,ambiguous,assigned);
    if group_value is not null then
      result:=result||jsonb_build_array(group_value);
      for obs in select value from jsonb_array_elements(group_value->'members') loop assigned:=assigned||jsonb_build_object(obs->>'assertionId',true); end loop;
    end if;
  end loop;
  return result;
end;

private.entry_regroup_correction_snapsho:
declare c jsonb:=p_cache; v public.canonical_resume_versions%rowtype; application public.candidate_correction_applications%rowtype;
  source_operation uuid; origin text; inherited uuid; restored uuid;
begin
  select * into strict v from public.canonical_resume_versions where id=p_version_id;
  if exists(select 1 from public.canonical_correction_snapshots where canonical_version_id=v.id) then perform private.correction_fail('conflict'); end if;
  select * into application from public.candidate_correction_applications where result_version_id=v.id;
  if found then
    source_operation:=application.operation_id; origin:='correction'; inherited:=v.parent_version_id;
  elsif v.parent_version_id is null then
    origin:='raw_import';
    select id into source_operation from public.candidate_correction_operations where initial_import_version_id=v.id;
  elsif p_command->>'operation'='rollback' then
    restored:=(p_command->>'targetVersionId')::uuid;
    origin:=case when exists(select 1 from public.canonical_correction_snapshots where canonical_version_id=restored) then 'restore' else 'legacy_restore' end;
  else origin:='inherited'; inherited:=v.parent_version_id;
  end if;
  insert into public.canonical_correction_snapshots(canonical_version_id,owner_id,organization_id,resume_id,source_resume_version_id,
    source_operation_id,origin_kind,inherited_from_version_id,restored_from_version_id,admission_policy_version)
    values(v.id,v.owner_id,v.organization_id,v.resume_id,v.source_resume_version_id,source_operation,origin,inherited,restored,'candidate-correction-admission/1.0.0');
  insert into public.canonical_correction_snapshot_facts(canonical_version_id,fact_id,owner_id,organization_id,application_id)
    select v.id,old.fact_id,v.owner_id,v.organization_id,old.application_id
      from public.canonical_correction_snapshot_facts old
      join public.resume_facts fact on fact.canonical_version_id=v.id and fact.id=old.fact_id
      join public.candidate_correction_applications applied on applied.id=old.application_id
      join public.resume_facts original on original.canonical_version_id=applied.result_version_id and original.id=applied.result_fact_id
    where old.canonical_version_id=coalesce(inherited,restored) and old.owner_id=v.owner_id and old.organization_id=v.organization_id
      and fact.type=original.type and fact.value=original.value
      and (p_command->>'operation' is distinct from 'edit' or old.fact_id::text is distinct from p_command->>'factId')
      and (application.id is null or old.fact_id<>application.result_fact_id)
      and (application.supersedes_application_id is null or old.application_id<>application.supersedes_application_id);
  if application.id is not null then
    insert into public.canonical_correction_snapshot_facts(canonical_version_id,fact_id,owner_id,organization_id,application_id)
      values(v.id,application.result_fact_id,v.owner_id,v.organization_id,application.id);
  end if;
  c:=private.entry_regroup_snapshot_work(p_version_id,p_command,c);
  return c;
end;

private.requirement_relationship_charge:
declare c jsonb:=private.entry_regroup_work(p_cache,1); item jsonb; units bigint:=0;
begin
  if c->'seen' ? (p_kind||':'||p_id) then return c; end if;
  c:=private.entry_regroup_inspect(c,p_kind,p_id,p_value);
  -- Strict recursive value traversal; no keyvalue() call on scalar metadata.
  for item in select value from jsonb_path_query(p_value,'strict $.**') as nodes(value) loop
    c:=private.entry_regroup_work(c,1);
    if jsonb_typeof(item)='string' then units:=units+private.grouped_import_utf16_length(item#>>'{}'); end if;
    if (c->>'text')::bigint+units>8000000 then perform private.correction_fail('unavailable'); end if;
  end loop;
  c:=jsonb_set(c,'{text}',to_jsonb((c->>'text')::bigint+units));
  c:=jsonb_set(c,array['seen',p_kind||':'||p_id,'text'],to_jsonb(units));
  return c;
end;

private.requirement_header_context:
declare c jsonb:=private.entry_regroup_work(p_cache,1); link jsonb; links jsonb; source_selection jsonb; selected jsonb; members jsonb; result_members jsonb;
  member jsonb; selected_member jsonb; fact jsonb; origin_fact jsonb; observed jsonb; place jsonb; section jsonb; entry jsonb; bullet jsonb; ref text;
  index_value jsonb:='{}'; locations jsonb:='{}'; entry_indices jsonb:='{}'; ancestor_index jsonb; step jsonb; row_value jsonb;
  family text; creation text; batch uuid; group_id uuid; approval uuid; original_version uuid; previous_version uuid; mapped text;
  expected_count integer; entry_index integer; depth integer; group_index integer:=0; member_index integer; revision_value integer;
  groups jsonb:='[]'; output jsonb; selection jsonb; resolution jsonb; resolution_key text; had_resolution boolean; version_id uuid:=(p_base->>'versionId')::uuid;
  a_prefix integer; r_prefix integer; a_head uuid; r_head uuid; seen_groups jsonb:='{}'; seen_facts jsonb:='{}'; seen_assertions jsonb:='{}';
begin
  -- The public reader passes only the already proved loaded base and the SAME cache.
  for fact in select value from jsonb_array_elements(p_base->'content'->'facts') loop c:=private.entry_regroup_work(c,1); index_value:=index_value||jsonb_build_object(fact->>'id',fact); end loop;
  for ref in select jsonb_array_elements_text(p_base->'content'->'contactFactIds') loop c:=private.entry_regroup_work(c,1); locations:=jsonb_set(locations,array[ref],coalesce(locations->ref,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('kind','contact','sectionId',null,'entryId',null,'bulletId',null))); end loop;
  for section in select value from jsonb_array_elements(p_base->'content'->'sections') loop
    c:=private.entry_regroup_work(c,1);
    for ref in select jsonb_array_elements_text(section->'factIds') loop c:=private.entry_regroup_work(c,1); locations:=jsonb_set(locations,array[ref],coalesce(locations->ref,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('kind','section','sectionId',section->'id','entryId',null,'bulletId',null))); end loop;
    entry_index:=0;
    for entry in select value from jsonb_array_elements(section->'entries') loop
      c:=private.entry_regroup_work(c,1); entry_indices:=entry_indices||jsonb_build_object((section->>'id')||':'||(entry->>'id'),entry_index); entry_index:=entry_index+1;
      for ref in select jsonb_array_elements_text(entry->'factIds') loop c:=private.entry_regroup_work(c,1); locations:=jsonb_set(locations,array[ref],coalesce(locations->ref,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('kind','entry','sectionId',section->'id','entryId',entry->'id','bulletId',null))); end loop;
      for bullet in select value from jsonb_array_elements(entry->'bullets') loop
        c:=private.entry_regroup_work(c,1);
        for ref in select jsonb_array_elements_text(bullet->'factIds') loop c:=private.entry_regroup_work(c,1); locations:=jsonb_set(locations,array[ref],coalesce(locations->ref,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('kind','bullet','sectionId',section->'id','entryId',entry->'id','bulletId',bullet->'id'))); end loop;
      end loop;
    end loop;
  end loop;
  if exists(select 1 from public.canonical_entry_regroup_snapshots where canonical_version_id=version_id) then
    family:='regroup'; select creation_kind into strict creation from public.canonical_entry_regroup_snapshots where canonical_version_id=version_id;
  elsif exists(select 1 from public.canonical_entry_association_snapshots where canonical_version_id=version_id) then
    family:='association'; select origin_kind into strict creation from public.canonical_entry_association_snapshots where canonical_version_id=version_id;
  else family:='none'; creation:=null; end if;
  c:=private.entry_regroup_work(c,4); links:=private.entry_regroup_links(version_id);
  for link in select value from jsonb_array_elements(links) loop
    c:=private.entry_regroup_work(c,1); group_index:=group_index+1;
    if link->>'originFamily'='regroup' then
      select g.source_selection,g.batch_id,g.id,g.result_version_id into strict source_selection,batch,group_id,approval from public.candidate_entry_regroup_groups g where g.id=(link->>'regroupGroupId')::uuid;
      select coalesce(jsonb_agg(jsonb_build_object('sourceOrder',m.source_order,'assertionId',m.assertion_id,'field',m.field,'factId',m.fact_id) order by m.source_order),'[]'::jsonb) into selected
        from public.candidate_entry_regroup_members m where m.group_id=(link->>'regroupGroupId')::uuid;
      if batch::text is distinct from link->>'regroupBatchId' then perform private.correction_fail('unavailable'); end if;
    elsif link->>'originFamily'='association' then
      select g.source_selection,g.batch_id,g.id,g.result_version_id into strict source_selection,batch,group_id,approval from public.candidate_entry_association_groups g where g.id=(link->>'associationGroupId')::uuid;
      select coalesce(jsonb_agg(jsonb_build_object('sourceOrder',m.source_order,'assertionId',m.assertion_id,'field',m.field,'factId',m.fact_id) order by m.source_order),'[]'::jsonb) into selected
        from public.candidate_entry_association_members m where m.group_id=(link->>'associationGroupId')::uuid;
      if batch::text is distinct from link->>'associationBatchId' then perform private.correction_fail('unavailable'); end if;
    else perform private.correction_fail('unavailable'); end if;
    c:=private.entry_regroup_work(c,3+jsonb_array_length(selected));
    if approval::text is distinct from link->>'originalApprovalVersionId' or seen_groups ? ((link->>'originFamily')||':'||group_id::text)
      or jsonb_array_length(selected) not between 2 and 3 or jsonb_array_length(selected)<>jsonb_array_length(source_selection->'members') then perform private.correction_fail('unavailable'); end if;
    seen_groups:=seen_groups||jsonb_build_object((link->>'originFamily')||':'||group_id::text,true); members:='[]'; result_members:='[]'; member_index:=0;
    for member in select value from jsonb_array_elements(selected) loop
      c:=private.entry_regroup_work(c,1); member_index:=member_index+1; selected_member:=source_selection->'members'->(member_index-1); fact:=index_value->(member->>'factId');
      if fact is null or member->>'field' not in ('employer','role','dates') or fact->>'type' is distinct from member->>'field'
        or member->>'assertionId' is distinct from selected_member->>'assertionId' or member->>'field' is distinct from selected_member->>'field'
        or member->'sourceOrder'<>to_jsonb(member_index) or seen_facts ? (member->>'factId') or seen_assertions ? (member->>'assertionId') then perform private.correction_fail('unavailable'); end if;
      seen_facts:=seen_facts||jsonb_build_object(member->>'factId',true); seen_assertions:=seen_assertions||jsonb_build_object(member->>'assertionId',true);
      if jsonb_array_length(locations->(member->>'factId')) is distinct from 1 then perform private.correction_fail('unavailable'); end if;
      place:=locations->(member->>'factId')->0;
      if place->>'kind' not in ('entry','bullet') or place->'sectionId' is distinct from link->'sectionId' or place->'entryId' is distinct from link->'entryId' then perform private.correction_fail('unavailable'); end if;
      origin_fact:=fact; original_version:=null; mapped:='current_citations'; depth:=0; previous_version:=version_id; revision_value:=(p_base->>'revision')::integer;
      while jsonb_array_length(origin_fact->'sources')=0 loop
        if depth>=64 then perform private.correction_fail('unavailable'); end if;
        step:=private.entry_regroup_version(previous_version,c);c:=step->'cache';row_value:=step->'row';
        if row_value->'parent_version_id'='null'::jsonb then perform private.correction_fail('unavailable'); end if;
        previous_version:=(row_value->>'parent_version_id')::uuid;step:=private.entry_regroup_version(previous_version,c);c:=step->'cache';row_value:=step->'row';depth:=depth+1;
        if (row_value->>'revision')::integer<>revision_value-1 or (row_value->>'owner_id',row_value->>'organization_id',row_value->>'resume_id',row_value->>'source_resume_version_id',row_value->>'source_evidence_version_id')
          is distinct from (p_scope->>'ownerId',p_scope->>'organizationId',p_scope->>'resumeId',p_scope->>'sourceId',p_scope->>'attemptId') then perform private.correction_fail('unavailable'); end if;
        revision_value:=(row_value->>'revision')::integer;
        c:=private.entry_regroup_work(c,1);ancestor_index:=c->'indexes'->previous_version::text;
        if ancestor_index is null then
          ancestor_index:='{}';for origin_fact in select value from jsonb_array_elements(row_value->'content'->'facts') loop c:=private.entry_regroup_work(c,1);ancestor_index:=ancestor_index||jsonb_build_object(origin_fact->>'id',origin_fact);end loop;
          c:=jsonb_set(c,'{indexes}',(c->'indexes')||jsonb_build_object(previous_version::text,ancestor_index));
        end if;
        origin_fact:=ancestor_index->(member->>'factId');if origin_fact is null or origin_fact->'type' is distinct from fact->'type' then perform private.correction_fail('unavailable'); end if;
        mapped:='owned_ancestor_chain';original_version:=previous_version;
      end loop;
      members:=members||jsonb_build_array(jsonb_build_object('assertionId',member->'assertionId','field',member->'field','factId',member->'factId','citations',selected_member->'citations','mappedThrough',mapped,'originVersionId',original_version,'location',place));
      c:=private.entry_regroup_work(c,jsonb_array_length(p_base->'envelope'->'assertions'));
      select value into strict observed from jsonb_array_elements(p_base->'envelope'->'assertions') where value->>'id'=member->>'assertionId';
      result_members:=result_members||jsonb_build_array(jsonb_build_object('sourceOrder',member_index,'assertionId',member->'assertionId','field',member->'field','factId',member->'factId',
        'currentValue',fact->'value','currentState',fact->'state','confirmation',fact->'confirmation','sourceValue',observed->'value','citations',selected_member->'citations','location',place,
        'mappedThrough',mapped,'originVersionId',original_version,'originFactId',case when original_version is null then null else member->'factId' end));
    end loop;
    selection:=source_selection||jsonb_build_object('sectionId',link->'sectionId','anchorEntryId',link->'entryId','insertionIndex',entry_indices->((link->>'sectionId')||':'||(link->>'entryId')),'affectedEntryIds',jsonb_build_array(link->'entryId'),'members',members);
    -- One source group at a time, with shared loaded proof/cache. The 32-command selection cap is NOT a cap on active context groups.
    c:=private.entry_regroup_work(c,1+jsonb_array_length(members));
    resolution_key:=(p_base->>'versionId')||':'||encode(extensions.digest(convert_to(jsonb_build_array(selection)::text,'UTF8'),'sha256'),'hex');
    had_resolution:=c->'resolutions' ? resolution_key;
    resolution:=private.entry_regroup_resolve_loaded(p_scope,p_base,jsonb_build_array(selection),c);c:=resolution->'cache';
    if resolution->'selections' is distinct from jsonb_build_array(selection) then perform private.correction_fail('unavailable'); end if;
    -- Do not retain another full afterSections copy for every context group. Existing protected memo entries stay.
    if not had_resolution then c:=jsonb_set(c,'{resolutions}',(c->'resolutions')-resolution_key); end if;
    resolution:=null;
    groups:=groups||jsonb_build_array(jsonb_build_object('sectionId',link->'sectionId','entryId',link->'entryId','originFamily',link->'originFamily','batchId',batch,'groupId',group_id,
      'originalApprovalVersionId',approval,'sourceSelection',source_selection,'members',result_members));
  end loop;
  select coalesce(max(association_revision),0) into a_prefix from public.candidate_entry_association_batches where analysis_id=(p_scope->>'analysisId')::uuid and result_revision<=(p_base->>'revision')::integer;
  select id into a_head from public.candidate_entry_association_batches where analysis_id=(p_scope->>'analysisId')::uuid and association_revision=a_prefix;
  select coalesce(max(regroup_revision),0) into r_prefix from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and result_revision<=(p_base->>'revision')::integer;
  select id into r_head from public.candidate_entry_regroup_batches where analysis_id=(p_scope->>'analysisId')::uuid and regroup_revision=r_prefix;
  c:=private.entry_regroup_work(c,4);
  output:=jsonb_build_object('canonicalVersionId',version_id,'canonicalContentSha256',p_base->'contentSha256','snapshotFamily',family,'creationKind',creation,
    'associationPrefix',jsonb_build_object('revision',a_prefix,'headId',a_head),'regroupPrefix',jsonb_build_object('revision',r_prefix,'headId',r_head),'groups',groups);
  c:=private.requirement_relationship_charge(c,'header-output',version_id::text,output);
  return jsonb_build_object('headerSnapshot',output,'cache',c);
end;

public.read_requirement_relationship_con:
declare c jsonb:=private.entry_regroup_cache(); scope jsonb; final_scope jsonb; v public.canonical_resume_versions%rowtype; e public.document_evidence_attempts%rowtype;
  selected_jd public.job_requirement_versions%rowtype; canonical_head public.canonical_resume_heads%rowtype; final_canonical_head public.canonical_resume_heads%rowtype;
  jd_head public.job_requirement_versions%rowtype; final_jd_head public.job_requirement_versions%rowtype; a public.analyses%rowtype; job public.jobs%rowtype; src public.resume_versions%rowtype;
  loaded jsonb; base jsonb; step jsonb; row_value jsonb; headers jsonb; ancestors jsonb:='[]'; ancestor_id uuid; depth integer:=0; through integer; result jsonb; item jsonb;
