  for target in select value from jsonb_array_elements(manifest) loop
    select * into routine from pg_catalog.pg_proc where oid=to_regprocedure(target->>'signature');
    if not found or routine.prokind<>'f' or routine.proretset or routine.proisstrict
      or routine.proowner<>predecessor.proowner or routine.prorettype<>to_regtype(target->>'resultType')
      or routine.prosecdef is distinct from (target->>'definer')::boolean or routine.provolatile<>target->>'volatility'
      or routine.prolang<>(select oid from pg_catalog.pg_language where lanname=target->>'language')
      or routine.proconfig is distinct from array['search_path=""']
      or private.typed_authoring_sha256(routine.prosrc)<>target->>'sha256' then return false; end if;
    if exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) acl
      where acl.grantee<>routine.proowner and (target->>'acl'='owner_only' or acl.grantee<>service_oid or acl.privilege_type<>'EXECUTE' or acl.is_grantable)) then return false; end if;
    foreach role_name in array array['anon','authenticated'] loop
      if has_function_privilege(role_name,routine.oid,'EXECUTE') then return false; end if;
    end loop;
    if target->>'acl'='owner_only' and has_function_privilege('service_role',routine.oid,'EXECUTE') then return false; end if;
    if target->>'acl'='service_only' and (not has_function_privilege('service_role',routine.oid,'EXECUTE')
      or not exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) acl where acl.grantee=service_oid and acl.privilege_type='EXECUTE' and not acl.is_grantable)) then return false; end if;
    if target->>'acl'='optional_service' and has_function_privilege('service_role',routine.oid,'EXECUTE')
      and not exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) acl where acl.grantee=service_oid and acl.privilege_type='EXECUTE' and not acl.is_grantable) then return false; end if;
  end loop;
  -- No public/private-role direct or column-DML bypass. Exact selected column
  -- names/types/nullability are required; extra columns are drift, not ignored.
  for name,expected in select key,value from jsonb_each(columns_expected) loop
    select * into rel from pg_catalog.pg_class where oid=to_regclass('private.'||name);
    if not found or rel.relkind<>'r' or not rel.relrowsecurity or rel.relowner<>predecessor.proowner
      or exists(select 1 from aclexplode(coalesce(rel.relacl,acldefault('r',rel.relowner))) acl where acl.grantee<>rel.relowner)
      or exists(select 1 from pg_catalog.pg_attribute a cross join lateral aclexplode(a.attacl) acl where a.attrelid=rel.oid and acl.grantee<>rel.relowner) then return false; end if;
    if (select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum)
      from pg_catalog.pg_attribute a where a.attrelid=rel.oid and a.attnum>0 and not a.attisdropped) is distinct from expected then return false; end if;
    foreach role_name in array array['anon','authenticated','service_role'] loop
      if has_table_privilege(role_name,rel.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
        or has_any_column_privilege(role_name,rel.oid,'SELECT,INSERT,UPDATE,REFERENCES') then return false; end if;
    end loop;
    if exists(select 1 from pg_catalog.pg_policy where polrelid=rel.oid) then return false; end if;
  end loop;
  -- Candidate versions/head FK cascades and immutable/privacy triggers are part
  -- of the closure. Technical operations intentionally have no analysis FK.
  if exists(select 1 from pg_catalog.pg_constraint where conrelid='private.canonical_rewrite_operations'::regclass and confrelid in ('public.analyses'::regclass,'public.resume_versions'::regclass))
    or not exists(select 1 from pg_catalog.pg_constraint where conrelid='private.canonical_rewrite_operations'::regclass and contype='p') then return false; end if;
  foreach name in array array['canonical_rewrite_versions','canonical_rewrite_heads'] loop
    if not exists(select 1 from pg_catalog.pg_constraint where conrelid=to_regclass('private.'||name) and confrelid='public.analyses'::regclass and contype='f' and confdeltype='c' and convalidated)
      or not exists(select 1 from pg_catalog.pg_constraint where conrelid=to_regclass('private.'||name) and confrelid='public.resume_versions'::regclass and contype='f' and confdeltype='c' and convalidated)
      or not exists(select 1 from pg_catalog.pg_trigger where tgrelid=to_regclass('private.'||name) and tgname=name||'_privacy'
        and tgfoid=to_regprocedure('private.canonical_rewrite_content_barrier()') and not tgisinternal and tgenabled='O' and tgtype=23 and tgnargs=0 and tgqual is null) then return false; end if;
  end loop;
  if exists(select 1 from pg_catalog.pg_trigger where tgrelid='private.canonical_rewrite_versions'::regclass and not tgisinternal and tgname not in ('canonical_rewrite_versions_privacy','canonical_rewrite_versions_immutable'))
    or exists(select 1 from pg_catalog.pg_trigger where tgrelid='private.canonical_rewrite_heads'::regclass and not tgisinternal and tgname<>'canonical_rewrite_heads_privacy')
    or exists(select 1 from pg_catalog.pg_trigger where tgrelid='private.canonical_rewrite_operations'::regclass and not tgisinternal) then return false;end if;
  if not exists(select 1 from pg_catalog.pg_trigger where tgrelid='private.canonical_rewrite_versions'::regclass and tgname='canonical_rewrite_versions_immutable'
    and tgfoid=to_regprocedure('private.canonical_rewrite_immutable()') and not tgisinternal and tgenabled='O' and tgtype=19 and tgnargs=0 and tgqual is null) then return false; end if;
  select * into routine from pg_catalog.pg_proc where oid=to_regprocedure('private.canonical_rewrite_ready()');
  if not found or routine.proowner<>predecessor.proowner or routine.prosecdef or routine.provolatile<>'s'
    or routine.proconfig is distinct from array['search_path=""']
    or exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) acl where acl.grantee<>routine.proowner) then return false; end if;
  return true;
exception when others then return false;
end;

public.read_canonical_rewrite_usage:
declare a public.analyses%rowtype; period_start date; period_end date;
  legacy_tokens numeric; canonical_tokens numeric; unknown_claims bigint; values_valid boolean;
begin
  -- Derive the organization from an owned active source and current membership,
  -- never from a caller-supplied organization, date or claimed support flag.
  a:=private.canonical_rewrite_owner(p_user_id,p_analysis_id);
  if private.canonical_rewrite_ready() is not true then perform private.correction_fail('unavailable'); end if;
  period_start:=date_trunc('month',clock_timestamp() at time zone 'UTC')::date;
  period_end:=(period_start+interval '1 month')::date;
  -- One statement snapshot for both components. Preserve the existing legacy
  -- counter semantics; canonical usage belongs to immutable claimed_at month.
  with legacy as (
    select public.get_organization_ai_tokens_used(a.organization_id,period_start::timestamp at time zone 'UTC')::numeric tokens
  ), canonical as (
    select coalesce(sum(case when x.usage is null then 0 else
        (x.usage->>'inputTokens')::numeric+(x.usage->>'outputTokens')::numeric end),0) tokens,
      count(*) filter(where x.usage is null) unknown_count,
      coalesce(bool_and(case when x.usage is null then true else coalesce(
        private.evidence_keys(x.usage,array['inputTokens','outputTokens'])
        and jsonb_typeof(x.usage->'inputTokens')='string' and jsonb_typeof(x.usage->'outputTokens')='string'
        and (x.usage->>'inputTokens') ~ '^(0|[1-9][0-9]{0,15})$'
        and (x.usage->>'outputTokens') ~ '^(0|[1-9][0-9]{0,15})$'
        and (x.usage->>'inputTokens')::numeric<=9007199254740991
        and (x.usage->>'outputTokens')::numeric<=9007199254740991,false) end),true) valid
    from private.canonical_rewrite_operations x
    where x.organization_id=a.organization_id and x.claimed_at>=period_start::timestamp at time zone 'UTC'
      and x.claimed_at<period_end::timestamp at time zone 'UTC'
  ) select legacy.tokens,canonical.tokens,canonical.unknown_count,canonical.valid
    into legacy_tokens,canonical_tokens,unknown_claims,values_valid from legacy cross join canonical;
  if values_valid is not true or legacy_tokens is null or legacy_tokens<0 or legacy_tokens<>trunc(legacy_tokens)
    or canonical_tokens<0 or canonical_tokens<>trunc(canonical_tokens) then perform private.correction_fail('unavailable'); end if;
  return jsonb_build_object('schemaVersion','canonical-rewrite-usage/1.0.0','profileVersion','canonical-rewrite-readiness-profile/1.0.1',
    'usageSha256',(select private.typed_authoring_sha256(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.read_canonical_rewrite_usage(uuid,uuid)')),
    'ownerId',p_user_id,'organizationId',a.organization_id,'analysisId',p_analysis_id,
    'periodStart',to_char(period_start,'YYYY-MM-DD'),'periodEnd',to_char(period_end,'YYYY-MM-DD'),
    'legacyTokens',legacy_tokens::text,'canonicalTokens',canonical_tokens::text,'totalTokens',(legacy_tokens+canonical_tokens)::text,'unknownClaims',unknown_claims::text);
end;

public.read_canonical_rewrite_workspace_:
declare a public.analyses%rowtype; draft_row public.writer_drafts%rowtype;
  context_value jsonb; relationship jsonb; readiness jsonb;
begin
  perform private.canonical_rewrite_policy(p_policy);
  a:=private.canonical_rewrite_owner(p_user_id,p_analysis_id);
  readiness:=public.read_canonical_rewrite_workspace_readiness();
  if readiness->'schemaReady' is distinct from 'true'::jsonb then perform private.correction_fail('unavailable');end if;
  -- Select by the actual UNIQUE key, not owner-filtered absence. A foreign or
  -- corrupt conflicting row must never be relabelled initialization_required.
  select * into draft_row from public.writer_drafts where analysis_id=p_analysis_id and kind='summary';
  if found then
    if (draft_row.owner_id,draft_row.organization_id) is distinct from (p_user_id,a.organization_id) then perform private.correction_fail('not_found');end if;
    perform private.canonical_rewrite_projection(draft_row.draft);
    -- Existing reader performs its real RR/source proof and returns actual
    -- ID/time/native hashes. No exception is converted into a missing state.
    context_value:=public.read_canonical_rewrite_context(p_user_id,p_analysis_id,p_selection,p_policy);
    if context_value->>'status' is distinct from 'available' then perform private.correction_fail('unavailable');end if;
    return jsonb_build_object('schemaVersion','canonical-rewrite-workspace-state/1.0.0','status','available','context',context_value,'readiness',readiness);
  end if;
  relationship:=public.read_requirement_relationship_context(p_user_id,p_analysis_id,p_selection);
  if relationship->>'status' is distinct from 'available'
    or (relationship->'source'->>'ownerId',relationship->'source'->>'organizationId',relationship->'source'->>'analysisId',relationship->'source'->>'sourceId')
      is distinct from (p_user_id::text,a.organization_id::text,p_analysis_id::text,a.resume_version_id::text) then perform private.correction_fail('unavailable');end if;
  return jsonb_build_object('schemaVersion','canonical-rewrite-workspace-state/1.0.0','status','initialization_required','relationshipContext',relationship,'readiness',readiness);
end;

public.initialize_canonical_rewrite_work:
declare initial_state jsonb; actual_state jsonb; relationship jsonb; inserted_row public.writer_drafts%rowtype; created_value boolean;
begin
  if private.grouped_import_keys(p_selection,array['canonicalVersionId','requirementVersionId']) is not true
    or private.typed_authoring_uuid(p_selection->'canonicalVersionId') is not true
    or private.typed_authoring_uuid(p_selection->'requirementVersionId') is not true then perform private.correction_fail('invalid');end if;
  -- This call takes the common owner mutex before analysis/source rows, applies
  -- fresh R19 privacy/current membership admission, and proves the actual RR.
  initial_state:=public.read_canonical_rewrite_workspace_state(p_user_id,p_analysis_id,p_selection,p_policy);
  if initial_state->>'status'='available' then relationship:=initial_state->'context'->'relationshipContext';
  elsif initial_state->>'status'='initialization_required' then relationship:=initial_state->'relationshipContext';
  else perform private.correction_fail('unavailable');end if;
  -- Fresh POSTs always bind exact current UUIDs, even when a row already exists.
  -- Existing/historical GET remains a read; it is not initialization authority.
  if relationship->'canonical'->'versionId' is distinct from p_selection->'canonicalVersionId'
    or relationship->'requirements'->'versionId' is distinct from p_selection->'requirementVersionId'
    or relationship->'heads'->'canonicalHeadId' is distinct from p_selection->'canonicalVersionId'
    or relationship->'heads'->'requirementHeadId' is distinct from p_selection->'requirementVersionId'
    or relationship->'canonical'->'revision' is distinct from relationship->'heads'->'canonicalHeadRevision'
    or relationship->'requirements'->'revision' is distinct from relationship->'heads'->'requirementHeadRevision' then perform private.correction_fail('conflict');end if;
  if initial_state->>'status'='available' then
    return jsonb_build_object('schemaVersion','canonical-rewrite-workspace-initialization/1.0.0','created',false,'state',initial_state);
  end if;
  insert into public.writer_drafts(analysis_id,organization_id,owner_id,kind,draft)
    values(p_analysis_id,(relationship->'source'->>'organizationId')::uuid,p_user_id,'summary',jsonb_build_object('summary',null,'bullets','[]'::jsonb))
    on conflict(analysis_id,kind) do nothing returning * into inserted_row;
  created_value:=found;
  -- A concurrent legacy insertion is adopted only after its actual owned row
  -- and projection are validated. Never update a conflicting row or timestamp.
  actual_state:=public.read_canonical_rewrite_workspace_state(p_user_id,p_analysis_id,p_selection,p_policy);
  if actual_state->>'status' is distinct from 'available' then perform private.correction_fail('unavailable');end if;
  if created_value and (actual_state->'context'->'draft'->>'id' is distinct from inserted_row.id::text
    or (actual_state->'context'->'draft'->>'updatedAt')::timestamptz is distinct from inserted_row.updated_at
    or actual_state->'context'->'draft'->>'contentSha256' is distinct from private.typed_authoring_sha256(inserted_row.draft::text)) then perform private.correction_fail('conflict');end if;
  return jsonb_build_object('schemaVersion','canonical-rewrite-workspace-initialization/1.0.0','created',created_value,'state',actual_state);
end;

public.read_canonical_rewrite_workspace_:
begin
  return jsonb_build_object('schemaVersion','canonical-rewrite-workspace-readiness/1.0.0','profileVersion','canonical-rewrite-workspace-profile/1.0.0',
    'schemaReady',private.canonical_rewrite_workspace_ready(),
    'initializerExecutable',has_function_privilege('service_role',to_regprocedure('public.initialize_canonical_rewrite_workspace(uuid,uuid,jsonb,jsonb)'),'EXECUTE'),
    'checkerSha256',(select private.typed_authoring_sha256(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('private.canonical_rewrite_workspace_ready()')),
    'readerSha256',(select private.typed_authoring_sha256(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.read_canonical_rewrite_workspace_state(uuid,uuid,jsonb,jsonb)')),
    'initializerSha256',(select private.typed_authoring_sha256(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.initialize_canonical_rewrite_workspace(uuid,uuid,jsonb,jsonb)')),
    'metadataSha256',(select private.typed_authoring_sha256(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.read_canonical_rewrite_workspace_readiness()')));
end;

private.canonical_rewrite_workspace_read:
declare predecessor pg_catalog.pg_proc%rowtype; routine pg_catalog.pg_proc%rowtype; target jsonb;
  service_oid oid:=(select oid from pg_catalog.pg_roles where rolname='service_role'); role_name text;
  relation pg_catalog.pg_class%rowtype; manifest jsonb:=$workspace_catalog$[
  {
    "signature": "public.read_canonical_rewrite_workspace_state(uuid,uuid,jsonb,jsonb)",
    "sha256": "c4d92e2e4e9cf666ce2ccb3ced23c61873d2f974fd61303d9f0828331a5537e3",
    "resultType": "jsonb",
    "language": "plpgsql",
    "definer": true,
    "volatility": "v",
    "acl": "service_only"
  },
  {
    "signature": "public.initialize_canonical_rewrite_workspace(uuid,uuid,jsonb,jsonb)",
    "sha256": "07f71d4063e15301fe797a3eab876a6223a66350c6fa334295c9369accdf7f75",
    "resultType": "jsonb",
    "language": "plpgsql",
    "definer": true,
    "volatility": "v",
    "acl": "optional_service"
  },
  {
    "signature": "public.read_canonical_rewrite_workspace_readiness()",
    "sha256": "f05e249fed5e0f7852a198935780a05324505abaf182b0b6a2f22a6c3b95ccb3",
    "resultType": "jsonb",
    "language": "plpgsql",
    "definer": true,
    "volatility": "s",
    "acl": "service_only"
  }
]$workspace_catalog$::jsonb;
begin
  select * into predecessor from pg_catalog.pg_proc where oid=to_regprocedure('private.canonical_rewrite_ready()');
  if not found or predecessor.prokind<>'f' or predecessor.proretset or predecessor.proisstrict or predecessor.prosecdef
    or predecessor.provolatile<>'s' or predecessor.prorettype<>'boolean'::regtype
    or predecessor.prolang<>(select oid from pg_catalog.pg_language where lanname='plpgsql')
    or predecessor.proconfig is distinct from array['search_path=""']
    or private.typed_authoring_sha256(predecessor.prosrc)<>'b8f2c321599054fc5a05bdccdd15ebd8b3bd3bbdc8e7cf233c99cc01b205ffed'
    or exists(select 1 from aclexplode(coalesce(predecessor.proacl,acldefault('f',predecessor.proowner))) a where a.grantee<>predecessor.proowner)
    or private.canonical_rewrite_ready() is not true then return false;end if;
  for target in select value from jsonb_array_elements(manifest) loop
    select * into routine from pg_catalog.pg_proc where oid=to_regprocedure(target->>'signature');
    if not found or routine.prokind<>'f' or routine.proretset or routine.proisstrict or routine.proowner<>predecessor.proowner
      or routine.prorettype<>to_regtype(target->>'resultType') or routine.prolang<>(select oid from pg_catalog.pg_language where lanname=target->>'language')
      or routine.prosecdef is distinct from (target->>'definer')::boolean or routine.provolatile<>target->>'volatility'
      or routine.proconfig is distinct from array['search_path=""'] or private.typed_authoring_sha256(routine.prosrc)<>target->>'sha256' then return false;end if;
    if exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) a
      where a.grantee<>routine.proowner and (a.grantee<>service_oid or a.privilege_type<>'EXECUTE' or a.is_grantable)) then return false;end if;
    foreach role_name in array array['anon','authenticated'] loop
      if has_function_privilege(role_name,routine.oid,'EXECUTE') then return false;end if;
    end loop;
    if target->>'acl'='service_only' and (not has_function_privilege('service_role',routine.oid,'EXECUTE')
      or not exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) a where a.grantee=service_oid and a.privilege_type='EXECUTE' and not a.is_grantable)) then return false;end if;
    if target->>'acl'='optional_service' and has_function_privilege('service_role',routine.oid,'EXECUTE')
      and not exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) a where a.grantee=service_oid and a.privilege_type='EXECUTE' and not a.is_grantable) then return false;end if;
  end loop;
  select * into relation from pg_catalog.pg_class where oid='public.writer_drafts'::regclass;
  if not found or relation.relkind<>'r' or not relation.relrowsecurity then return false;end if;
  if exists(select 1 from (values('id','uuid'),('analysis_id','uuid'),('organization_id','uuid'),('owner_id','uuid'),
    ('kind','text'),('draft','jsonb'),('created_at','timestamp with time zone'),('updated_at','timestamp with time zone')) expected(name,type_name)
    where not exists(select 1 from pg_catalog.pg_attribute a where a.attrelid=relation.oid and a.attname=expected.name and a.atttypid=to_regtype(expected.type_name) and a.attnotnull and not a.attisdropped and a.attnum>0)) then return false;end if;
  if not exists(select 1 from pg_catalog.pg_constraint c where c.conrelid=relation.oid and c.contype='u' and c.convalidated
    and (select array_agg(a.attname::text order by k.ordinality) from unnest(c.conkey) with ordinality k(attnum,ordinality)
      join pg_catalog.pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum)=array['analysis_id','kind']) then return false;end if;
  if not exists(select 1 from pg_catalog.pg_trigger where tgrelid=relation.oid and tgname='zz_candidate_privacy_write' and not tgisinternal and tgenabled='O'
    and tgfoid=to_regprocedure('private.guard_candidate_privacy_write()') and tgtype=23 and tgnargs=1 and tgargs=convert_to('owner_id','UTF8')||decode('00','hex') and tgqual is null) then return false;end if;
  select * into routine from pg_catalog.pg_proc where oid=to_regprocedure('private.canonical_rewrite_workspace_ready()');
  if not found or routine.prokind<>'f' or routine.proretset or routine.proisstrict or routine.prorettype<>'boolean'::regtype
    or routine.prolang<>(select oid from pg_catalog.pg_language where lanname='plpgsql')
    or routine.proowner<>predecessor.proowner or routine.prosecdef or routine.provolatile<>'s'
    or routine.proconfig is distinct from array['search_path=""']
    or exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) a where a.grantee<>routine.proowner) then return false;end if;
  foreach role_name in array array['anon','authenticated','service_role'] loop
    if has_function_privilege(role_name,routine.oid,'EXECUTE') then return false;end if;
  end loop;
  return true;
exception when others then return false;
end;

private.legacy_scoring_fail:
begin
  case p_code
  when 'invalid' then raise exception 'LEGACY_SCORING_INVALID' using errcode='22023';
  when 'not_found' then raise exception 'LEGACY_SCORING_NOT_FOUND' using errcode='42501';
  when 'stale' then raise exception 'LEGACY_SCORING_STALE' using errcode='P0C01';
  else raise exception 'LEGACY_SCORING_UNAVAILABLE' using errcode='P0C03';end case;
end;

private.legacy_scoring_keys:
begin
  return jsonb_typeof(p_value)='object' and (select array_agg(key order by key) from jsonb_object_keys(p_value) key)
    is not distinct from (select array_agg(key order by key) from unnest(p_keys) key);
end;

private.legacy_scoring_lease:
begin
  return private.legacy_scoring_keys(p_lease,array['workerId','attempt','leaseFence']) is true
    and jsonb_typeof(p_lease->'workerId')='string' and p_lease->>'workerId' ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    and jsonb_typeof(p_lease->'attempt')='number' and p_lease->>'attempt' ~ '^[1-3]$'
    and jsonb_typeof(p_lease->'leaseFence')='string' and p_lease->>'leaseFence' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$';
end;

private.legacy_scoring_access:
declare a public.analyses%rowtype;v public.resume_versions%rowtype;
begin
  select * into a from public.analyses where id=p_analysis_id for update;
  if not found or (p_user_id is not null and a.owner_id<>p_user_id) then perform private.legacy_scoring_fail('not_found');end if;
  if not private.try_candidate_privacy_write(a.owner_id) then perform private.legacy_scoring_fail('not_found');end if;
  -- Same analysis -> queue -> membership -> source/root order as the stage fence.
  perform 1 from public.analysis_jobs where analysis_id=a.id for update;
  perform 1 from public.memberships where organization_id=a.organization_id and user_id=a.owner_id
    and role in ('owner','admin','member') for share skip locked;
  if not found then perform private.legacy_scoring_fail('not_found');end if;
  select * into v from public.resume_versions where id=a.resume_version_id and organization_id=a.organization_id
    and owner_id=a.owner_id for no key update skip locked;
  if not found then perform private.legacy_scoring_fail('not_found');end if;
  perform 1 from public.resumes where id=v.resume_id and organization_id=a.organization_id and owner_id=a.owner_id
    and status='active' for share skip locked;
  if not found then perform private.legacy_scoring_fail('not_found');end if;
  -- Every evidence-v2 attempt remains uncalibrated. No new scored path bypass.
  if exists(select 1 from public.document_evidence_attempts where analysis_id=a.id) then perform private.legacy_scoring_fail('unavailable');end if;
  return a;
end;

private.legacy_scoring_static_job:
begin
  return exists(select 1 from public.analysis_jobs where analysis_id=p_analysis_id and lease_owner=p_lease->>'workerId'
    and attempt_count=(p_lease->>'attempt')::integer and lease_fence=(p_lease->>'leaseFence')::uuid);
end;

private.legacy_scoring_input_data:
declare e public.analysis_extractions%rowtype;v public.resume_versions%rowtype;j public.jobs%rowtype;
  source_value jsonb;extraction_value jsonb;job_value jsonb;producer_value jsonb;core_value jsonb;binding_value jsonb;answer jsonb;
begin
  select * into v from public.resume_versions where id=p_analysis.resume_version_id and owner_id=p_analysis.owner_id and organization_id=p_analysis.organization_id;
  if not found then perform private.legacy_scoring_fail('not_found');end if;
  select * into e from public.analysis_extractions where analysis_id=p_analysis.id and owner_id=p_analysis.owner_id
    and organization_id=p_analysis.organization_id for share;
  if not found then perform private.legacy_scoring_fail('unavailable');end if;
  if e.page_count not between 1 and 20 or char_length(e.extracted_text) not between 1 and 200000
    or e.text_checksum is distinct from encode(sha256(convert_to(e.extracted_text,'UTF8')),'hex')
    or jsonb_typeof(e.page_texts) is distinct from 'array'
    or exists(select 1 from jsonb_array_elements(e.page_texts) x where jsonb_typeof(x) is distinct from 'string') then perform private.legacy_scoring_fail('unavailable');end if;
  if p_analysis.request_id is not null and p_analysis.request_id !~ '^[ -~]{1,128}$' then perform private.legacy_scoring_fail('unavailable');end if;
  source_value:=jsonb_build_object('resumeId',v.resume_id,'resumeVersionId',v.id,'fileChecksum',v.checksum,'bytes',v.bytes,'mediaType',v.media_type);
  extraction_value:=jsonb_build_object('text',e.extracted_text,'pageCount',e.page_count,'pageTexts',e.page_texts,'textChecksum',e.text_checksum,'extractorVersion',e.extractor_version);
  extraction_value:=extraction_value||jsonb_build_object('contentSha256',encode(sha256(convert_to(extraction_value::text,'UTF8')),'hex'));
  if p_analysis.job_id is null then job_value:=jsonb_build_object('kind','none');
  else
    select * into j from public.jobs where id=p_analysis.job_id and owner_id=p_analysis.owner_id and organization_id=p_analysis.organization_id for share;
    if not found then perform private.legacy_scoring_fail('not_found');end if;
    job_value:=jsonb_build_object('kind','owned_job','id',j.id,'title',j.title,'description',j.description,'companyName',j.company_name);
    job_value:=job_value||jsonb_build_object('contentSha256',encode(sha256(convert_to(job_value::text,'UTF8')),'hex'));
  end if;
  producer_value:=jsonb_build_object('parserVersion','parse-sim-v1','rulesetVersion','ats-rules-v4','normalizerVersion','normalizer-v1','taxonomyVersion','skills-taxonomy-v1');
  core_value:=jsonb_build_object('schemaVersion','legacy-scoring-input-snapshot/1.0.0','analysisId',p_analysis.id,'ownerId',p_analysis.owner_id,
    'organizationId',p_analysis.organization_id,'source',source_value,'extraction',extraction_value,'job',job_value,'producer',producer_value);
  binding_value:=jsonb_build_object('schemaVersion','legacy-scoring-binding/1.0.0','analysisId',p_analysis.id,'ownerId',p_analysis.owner_id,
    'organizationId',p_analysis.organization_id,'resumeId',v.resume_id,'resumeVersionId',v.id,'fileChecksum',v.checksum,'textChecksum',e.text_checksum,
    'extractionSha256',extraction_value->>'contentSha256','jobId',p_analysis.job_id,'jobSha256',job_value->>'contentSha256',
    'inputBindingSha256',encode(sha256(convert_to(core_value::text,'UTF8')),'hex'));
  answer:=(core_value-'schemaVersion')||jsonb_build_object('schemaVersion','legacy-scoring-input/1.0.0','requestId',p_analysis.request_id,'binding',binding_value);
  if octet_length(convert_to(answer::text,'UTF8'))>4194304 then perform private.legacy_scoring_fail('unavailable');end if;
  return answer;
end;

private.legacy_scoring_receipt:
begin
  return jsonb_build_object('schemaVersion','legacy-scoring-receipt/1.0.0','analysisId',p_row.analysis_id,'ownerId',p_row.owner_id,
    'organizationId',p_row.organization_id,'resumeVersionId',p_row.resume_version_id,'inputBindingSha256',p_row.input_binding_sha256,
    'resultChecksum',p_row.result_checksum,'deterministicContentSha256',p_row.deterministic_content_sha256,
    'createdAt',to_char(p_row.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'replayed',p_replayed);
end;

private.legacy_scoring_row_sha256:
begin
  -- created_at is the only temporal column in this actual record. Keep all row
  -- fields/identity; replace its session-dependent JSON timestamp before hashing.
  return encode(sha256(convert_to((to_jsonb(p_row)||jsonb_build_object('created_at',
    to_char(p_row.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))::text,'UTF8')),'hex');
end;

private.guard_legacy_scoring_input:
declare a public.analyses%rowtype;d public.analysis_deterministic_results%rowtype;actual jsonb;
begin
  if tg_op='UPDATE' then raise exception 'LEGACY_SCORING_INPUT_IMMUTABLE' using errcode='23514';end if;
  a:=private.legacy_scoring_access(new.analysis_id,new.owner_id);
  actual:=private.legacy_scoring_input_data(a);
  select * into d from public.analysis_deterministic_results where analysis_id=a.id and owner_id=a.owner_id and organization_id=a.organization_id;
  if not found or new.input_context is distinct from actual or new.organization_id<>a.organization_id
    or new.resume_version_id<>a.resume_version_id or new.resume_id::text is distinct from actual->'source'->>'resumeId'
    or new.extraction_analysis_id<>a.id or new.job_id is distinct from a.job_id
    or not private.legacy_scoring_static_job(a.id,jsonb_build_object('workerId',new.worker_id,'attempt',new.attempt,'leaseFence',new.lease_fence))
    or new.input_binding_sha256 is distinct from actual->'binding'->>'inputBindingSha256'
    or new.result_checksum is distinct from d.result_checksum
    or new.deterministic_content_sha256 is distinct from private.legacy_scoring_row_sha256(d) then
    raise exception 'LEGACY_SCORING_INPUT_BINDING' using errcode='23514';end if;
  return new;
end;

public.read_legacy_scoring_input:
declare a public.analyses%rowtype;s private.analysis_scoring_inputs%rowtype;d public.analysis_deterministic_results%rowtype;context_value jsonb;
begin
  if private.legacy_scoring_lease(p_lease) is not true then perform private.legacy_scoring_fail('invalid');end if;
  a:=private.legacy_scoring_access(p_analysis_id,null);
  if not private.legacy_scoring_ready() then perform private.legacy_scoring_fail('unavailable');end if;
  select * into s from private.analysis_scoring_inputs where analysis_id=a.id and owner_id=a.owner_id and organization_id=a.organization_id;
  if found then
    perform private.legacy_scoring_stored_source(s);
    if p_lease is distinct from jsonb_build_object('workerId',s.worker_id,'attempt',s.attempt,'leaseFence',s.lease_fence)
      and not private.legacy_scoring_static_job(a.id,p_lease) then perform private.legacy_scoring_fail('not_found');end if;
    select * into d from public.analysis_deterministic_results where analysis_id=a.id;
    if not found or s.deterministic_content_sha256 is distinct from private.legacy_scoring_row_sha256(d) then perform private.legacy_scoring_fail('unavailable');end if;
    return jsonb_build_object('schemaVersion','legacy-scoring-read/1.0.0','status','committed','receipt',private.legacy_scoring_receipt(s,true));
  end if;
  if not private.legacy_scoring_static_job(a.id,p_lease) then perform private.legacy_scoring_fail('not_found');end if;
  if a.status<>'scoring' then return jsonb_build_object('schemaVersion','legacy-scoring-read/1.0.0','status','skipped','analysisId',a.id,'reason','not_scoring');end if;
  if exists(select 1 from public.analysis_deterministic_results where analysis_id=a.id) then perform private.legacy_scoring_fail('unavailable');end if;
  if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid) then perform private.legacy_scoring_fail('stale');end if;
  context_value:=private.legacy_scoring_input_data(a);
  if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
    or not private.try_candidate_privacy_write(a.owner_id) then perform private.legacy_scoring_fail('stale');end if;
  return jsonb_build_object('schemaVersion','legacy-scoring-read/1.0.0','status','ready','context',context_value);
end;

public.finish_legacy_scoring_input:
declare a public.analyses%rowtype;s private.analysis_scoring_inputs%rowtype;d public.analysis_deterministic_results%rowtype;
  context_value jsonb;persisted boolean;
begin
  if private.legacy_scoring_lease(p_lease) is not true or p_process_id is null or p_process_id !~ '^[ -~]{1,128}$'
    or p_request_id is null or p_request_id !~ '^[ -~]{1,128}$'
    or private.legacy_scoring_keys(p_binding,array['schemaVersion','analysisId','ownerId','organizationId','resumeId','resumeVersionId','fileChecksum','textChecksum','extractionSha256','jobId','jobSha256','inputBindingSha256']) is not true
    or private.legacy_scoring_keys(p_result,array['score','parseView','ruleTrace','keywordCoverage','inputTextChecksum','parserVersion','rulesetVersion','normalizerVersion','taxonomyVersion','resultChecksum']) is not true
    or octet_length(convert_to(p_result::text,'UTF8'))>4194304 or octet_length(convert_to(p_binding::text,'UTF8'))>4194304
    or jsonb_typeof(p_result->'score') is distinct from 'number' or p_result->>'score' !~ '^(0|[1-9][0-9]?|100)$'
    or jsonb_typeof(p_result->'parseView') is distinct from 'object' or jsonb_typeof(p_result->'ruleTrace') is distinct from 'array'
    or private.legacy_scoring_keys(p_result->'keywordCoverage',array['taxonomyVersion','job','matched','missing','uncertain','evidence']) is not true
    or p_result->>'parserVersion' is distinct from 'parse-sim-v1' or p_result->>'rulesetVersion' is distinct from 'ats-rules-v4'
    or p_result->>'normalizerVersion' is distinct from 'normalizer-v1' or p_result->>'taxonomyVersion' is distinct from 'skills-taxonomy-v1'
    or p_result->'keywordCoverage'->>'taxonomyVersion' is distinct from 'skills-taxonomy-v1'
    or jsonb_typeof(p_result->'resultChecksum') is distinct from 'string' or p_result->>'resultChecksum' !~ '^[a-f0-9]{64}$' then perform private.legacy_scoring_fail('invalid');end if;
  a:=private.legacy_scoring_access(p_analysis_id,null);
  if not private.legacy_scoring_ready() then perform private.legacy_scoring_fail('unavailable');end if;
  select * into s from private.analysis_scoring_inputs where analysis_id=a.id and owner_id=a.owner_id and organization_id=a.organization_id;
  -- Exact original receipt precedes fresh status, current lease and mutable JD.
  if found then
    perform private.legacy_scoring_stored_source(s);
    select * into d from public.analysis_deterministic_results where analysis_id=a.id;
    if not found or s.input_context->'binding' is distinct from p_binding
      or p_lease is distinct from jsonb_build_object('workerId',s.worker_id,'attempt',s.attempt,'leaseFence',s.lease_fence)
      or private.legacy_scoring_result(d) is distinct from p_result
      or s.deterministic_content_sha256 is distinct from private.legacy_scoring_row_sha256(d) then perform private.legacy_scoring_fail('stale');end if;
    return private.legacy_scoring_receipt(s,true);
  end if;
  if a.status<>'scoring' or exists(select 1 from public.analysis_deterministic_results where analysis_id=a.id)
    or not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid) then perform private.legacy_scoring_fail('stale');end if;
  context_value:=private.legacy_scoring_input_data(a);
  if p_binding is distinct from context_value->'binding' or p_result->'inputTextChecksum' is distinct from context_value->'extraction'->'textChecksum' then perform private.legacy_scoring_fail('stale');end if;
  -- No exception is converted to a successful JSON receipt. Any false result or
  -- post-check raises, rolling back the old insert/transition and new proof.
  begin
    persisted:=public.persist_deterministic_analysis(a.id,p_result->>'inputTextChecksum',p_result->'keywordCoverage',p_result->>'normalizerVersion',
      p_result->'parseView',p_result->>'parserVersion',p_process_id,p_request_id,p_result->>'resultChecksum',p_result->'ruleTrace',
      p_result->>'rulesetVersion',(p_result->>'score')::integer,p_result->>'taxonomyVersion');
    if persisted is not true then perform private.legacy_scoring_fail('stale');end if;
    select * into d from public.analysis_deterministic_results where analysis_id=a.id for update;
    if not found or d.owner_id<>a.owner_id or d.organization_id<>a.organization_id or private.legacy_scoring_result(d) is distinct from p_result then perform private.legacy_scoring_fail('unavailable');end if;
    insert into private.analysis_scoring_inputs(analysis_id,organization_id,owner_id,resume_id,resume_version_id,extraction_analysis_id,job_id,
      worker_id,attempt,lease_fence,process_id,request_id,input_context,input_binding_sha256,result_checksum,deterministic_content_sha256)
    values(a.id,a.organization_id,a.owner_id,(context_value->'source'->>'resumeId')::uuid,a.resume_version_id,a.id,a.job_id,
      p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid,p_process_id,p_request_id,context_value,
      p_binding->>'inputBindingSha256',d.result_checksum,private.legacy_scoring_row_sha256(d)) returning * into s;
    if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
      or not private.try_candidate_privacy_write(a.owner_id) then perform private.legacy_scoring_fail('stale');end if;
    return private.legacy_scoring_receipt(s,false);
  end;
end;

public.read_legacy_scoring_context:
declare a public.analyses%rowtype;s private.analysis_scoring_inputs%rowtype;d public.analysis_deterministic_results%rowtype;actual jsonb;
begin
  if p_user_id is null then perform private.legacy_scoring_fail('invalid');end if;
  a:=private.legacy_scoring_access(p_analysis_id,p_user_id);
  if not private.legacy_scoring_ready() then perform private.legacy_scoring_fail('unavailable');end if;
  select * into d from public.analysis_deterministic_results where analysis_id=a.id and owner_id=a.owner_id and organization_id=a.organization_id;
  if not found then perform private.legacy_scoring_fail('not_found');end if;
  select * into s from private.analysis_scoring_inputs where analysis_id=a.id and owner_id=p_user_id and organization_id=a.organization_id;
  if not found then return jsonb_build_object('schemaVersion','legacy-scoring-context/1.0.0','status','legacy_unbound','analysisId',a.id,'reason','original_input_binding_missing');end if;
  perform private.legacy_scoring_stored_source(s);
  if s.deterministic_content_sha256 is distinct from private.legacy_scoring_row_sha256(d) then perform private.legacy_scoring_fail('unavailable');end if;
  actual:=private.legacy_scoring_input_data(a);
  return jsonb_build_object('schemaVersion','legacy-scoring-context/1.0.0','status','bound',
    'currentness',case when actual->'binding' is not distinct from s.input_context->'binding' then 'current' else 'historical' end,
    'context',s.input_context,'result',private.legacy_scoring_result(d),'receipt',private.legacy_scoring_receipt(s,true));
end;

public.export_legacy_scoring_inputs:
declare answer jsonb;item jsonb;row_count integer;total_bytes bigint:=256;
begin
  if p_user_id is null or not exists(select 1 from auth.users where id=p_user_id) then perform private.legacy_scoring_fail('not_found');end if;
  if not private.legacy_scoring_ready() then perform private.legacy_scoring_fail('unavailable');end if;
  select count(*) into row_count from (select 1 from private.analysis_scoring_inputs where owner_id=p_user_id limit 4097) limited;
  if row_count>4096 then perform private.legacy_scoring_fail('unavailable');end if;
  for item in select to_jsonb(s)||jsonb_build_object('created_at',to_char(s.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) from private.analysis_scoring_inputs s where owner_id=p_user_id loop
    total_bytes:=total_bytes+octet_length(convert_to(item::text,'UTF8'))+2;
    if total_bytes>33554432 then perform private.legacy_scoring_fail('unavailable');end if;
  end loop;
  select jsonb_build_object('schemaVersion','legacy-scoring-export/1.0.0','scoringInputs',coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('created_at',to_char(s.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) order by s.analysis_id),'[]'::jsonb)) into answer
    from private.analysis_scoring_inputs s where owner_id=p_user_id;
  if octet_length(convert_to(answer::text,'UTF8'))>33554432 then perform private.legacy_scoring_fail('unavailable');end if;
  return answer;
end;

public.read_legacy_scoring_readiness:
begin
  return jsonb_build_object('schemaVersion','legacy-scoring-readiness/1.0.0','profileVersion','legacy-scoring-profile/1.0.0',
    'schemaReady',private.legacy_scoring_ready(),'writerExecutable',has_function_privilege('service_role',to_regprocedure('public.finish_legacy_scoring_input(uuid,jsonb,jsonb,jsonb,text,text)'),'EXECUTE'),
    'checkerSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('private.legacy_scoring_ready()')),
    'readerSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('public.read_legacy_scoring_input(uuid,jsonb)')),
    'finishSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('public.finish_legacy_scoring_input(uuid,jsonb,jsonb,jsonb,text,text)')),
    'contextSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('public.read_legacy_scoring_context(uuid,uuid)')),
    'exportSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('public.export_legacy_scoring_inputs(uuid)')),
    'metadataSha256',(select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_catalog.pg_proc where oid=to_regprocedure('public.read_legacy_scoring_readiness()')));
end;

