  if (t collate "C")!~*('^(?:(?:I|We) +)?(?:(?:did +not|never) +)?('||verbs||')(?=$|[^A-Za-z0-9_])') then return t;end if;
  if (t collate "C")~'[0-9`"''“”‘’\\/<>\[\]{}=:@_$#|*]' then return t;end if;
  if (t collate "C")!~'[­ﬀﬁﬂﬃﬄﬅﬆ]' then return t;end if;
