    if (word collate "C")~'^[a-z­ﬀﬁﬂﬃﬄﬅﬆ]+[.,;!?]?$' and (word collate "C")~'[­ﬀﬁﬂﬃﬄﬅﬆ]' and not coalesce((last collate "C")=any(cues),false) then
