      if (token collate "C")!~'(^|[^a-zﬀﬁﬂﬃﬄﬅﬆ])­|­($|[^a-zﬀﬁﬂﬃﬄﬅﬆ])' then
        token:=replace(replace(replace(replace(replace(replace(replace(token,'ﬀ','ff'),'ﬁ','fi'),'ﬂ','fl'),'ﬃ','ffi'),'ﬄ','ffl'),'ﬅ','st'),'ﬆ','st');
        word:=replace(token,'­','')||punct;
