private.ifp_metrics:
declare m text[];n integer:=0;pos integer:=1;at_pos integer;pattern text:='(?<![A-Za-z0-9])[+−-]?[0-9]+([.,][0-9]+)*( *(%|percent|milliseconds?|ms|seconds?|minutes?|hours?|users?|requests?|engineers?))?';before_value text;
