private.ifp_lower_better:
declare m text[];amount double precision;suffix text;raw_suffix text;pattern text:='^(API +)?(latency|response time) +by +([+]?[0-9]+([.][0-9]+)?) *(%|percent|milliseconds?|ms|seconds?)(.*)$';
