private.legacy_scoring_stored_source:
declare actual private.analysis_scoring_inputs%rowtype;
begin
  -- The immutable row's FK identity protects the ORIGINAL source. All locks
  -- below are nonblocking: current-source admission already holds its locks,
  -- so never wait in the reverse path of source retirement/FK deletion.
  select * into actual from private.analysis_scoring_inputs where analysis_id=p_stored.analysis_id
    for key share skip locked;
  if not found or actual is distinct from p_stored then perform private.legacy_scoring_fail('not_found');end if;
  perform 1 from public.resume_versions where id=actual.resume_version_id and resume_id=actual.resume_id
    and owner_id=actual.owner_id and organization_id=actual.organization_id for share skip locked;
  if not found then perform private.legacy_scoring_fail('not_found');end if;
  perform 1 from public.resumes where id=actual.resume_id and owner_id=actual.owner_id
    and organization_id=actual.organization_id and status='active' for share skip locked;
  if not found then perform private.legacy_scoring_fail('not_found');end if;
end;

private.ifo_fail:
begin
  case p_code
    when 'invalid' then raise exception 'INITIAL_FEEDBACK_INVALID' using errcode='22023';
    when 'not_found' then raise exception 'INITIAL_FEEDBACK_NOT_FOUND' using errcode='42501';
    when 'stale' then raise exception 'INITIAL_FEEDBACK_STALE' using errcode='P0C01';
    else raise exception 'INITIAL_FEEDBACK_UNAVAILABLE' using errcode='P0C03';
  end case;
end;

private.ifo_keys:
begin
  if jsonb_typeof(p_value) is distinct from 'object' then return false;end if;
  return (select array_agg(key order by key collate "C") from jsonb_object_keys(p_value) key)
    is not distinct from (select array_agg(key order by key collate "C") from unnest(p_expected) key);
end;

private.ifo_atom:
begin
  if p_value is null then return 'N;';end if;
  return 'T'||octet_length(convert_to(p_value,'UTF8'))::text||':'||p_value||';';
end;

private.ifo_stamp:
begin
  if p_value is null then return null;end if;
  return to_char(p_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
end;

private.ifo_usage_valid:
declare key text;
begin
  if p_usage is null or p_usage='null'::jsonb then return true;end if;
  if private.ifo_keys(p_usage,array['inputTokens','outputTokens']) is not true then return false;end if;
  foreach key in array array['inputTokens','outputTokens'] loop
    if jsonb_typeof(p_usage->key) is distinct from 'string'
      or (p_usage->>key) collate "C" !~ '^(0|[1-9][0-9]{0,15})$' then return false;end if;
    if (p_usage->>key)::numeric>9007199254740991 then return false;end if;
  end loop;
  return true;
end;

private.ifo_policy_frame:
declare answer text:=E'INITIAL-FEEDBACK-POLICY/1\n';key text;
begin
  foreach key in array array['version','provider','model','promptVersion','maxOutputTokens','attemptLimit','budgetPolicyVersion',
    'supportVersion','supportSha256','planVersion','planSha256','writingSupportPolicyVersion'] loop
    answer:=answer||private.ifo_atom(p_policy->>key);
  end loop;
  foreach key in array array['schemaVersion','profileVersion','checkerSha256','readerSha256','finishSha256','contextSha256','exportSha256','metadataSha256'] loop
    answer:=answer||private.ifo_atom(p_policy->'scoringInputProfile'->>key);
  end loop;
  foreach key in array array['schemaVersion','profileVersion','policyVersion','policySha256','checkerSha256','rendererSha256','metadataSha256'] loop
    answer:=answer||private.ifo_atom(p_policy->'planProfile'->>key);
  end loop;
  return answer;
end;

private.ifo_policy_valid:
declare key text;
begin
  if private.ifo_keys(p_policy,array['version','sha256','provider','model','promptVersion','maxOutputTokens','attemptLimit','budgetPolicyVersion',
      'supportVersion','supportSha256','planVersion','planSha256','writingSupportPolicyVersion','scoringInputProfile','planProfile']) is not true
    or octet_length(convert_to(p_policy::text,'UTF8'))>16384 then return false;end if;
  foreach key in array array['version','sha256','provider','model','promptVersion','supportVersion','supportSha256','planVersion','planSha256','writingSupportPolicyVersion'] loop
    if jsonb_typeof(p_policy->key) is distinct from 'string' then return false;end if;
  end loop;
  if p_policy->>'version' is distinct from 'initial-feedback-publication/1.0.0' or p_policy->>'provider' is distinct from 'openai'
    or (p_policy->>'model') collate "C" !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}$'
    or p_policy->>'promptVersion' is distinct from 'qualitative-cited-prose/3.0.0'
    or (p_policy->>'sha256') collate "C" !~ '^[a-f0-9]{64}$'
    or p_policy->>'supportVersion' is distinct from 'qualitative-content-support/1.0.0'
    or p_policy->>'supportSha256' is distinct from '230f22333dd468f3bf78395b118330ec1ff78de18be9da5349356e84d0f6bd13'
    or p_policy->>'planVersion' is distinct from 'initial-feedback-plan-policy/1.0.0'
    or p_policy->>'planSha256' is distinct from '972b648ccc90b29c0c88fc504ac2746ab1489e17f05cfd2048cb487a2b38cc48'
    or p_policy->>'writingSupportPolicyVersion' is distinct from 'legacy-source-transforms/1.0.4'
    or (p_policy->'scoringInputProfile' is distinct from $scoring${"schemaVersion":"legacy-scoring-readiness/1.0.0","profileVersion":"legacy-scoring-profile/1.0.0","checkerSha256":"56a92f65d533a2f1b053078dbb372b1271728224e5df1c74b201b4cffb21a8d3","readerSha256":"2ea3c5071d8d56e421a37053127dea08fe8eb08ce91e4de9f5c3b4c4b1172ccf","finishSha256":"5db61206ed04f32af7052fce2d64e2ccf414d6fea13645f58eecf67f616b61a2","contextSha256":"d64ba9ac11ba732c983cd195cd7d83fba878e67f4ae0bffc8b6e166a600a8bd9","exportSha256":"e4c17997fdbec81d931e4838b3522c6c7d3c861b0bfa07b6fb3ab5ece160f0a2","metadataSha256":"f18e6abfd698c4dbf4f7f6040fb577b2e49e78e4125bfd9d31e8166d0e678da8"}$scoring$::jsonb
      and p_policy->'scoringInputProfile' is distinct from $current_scoring${"schemaVersion":"legacy-scoring-readiness/1.0.0","profileVersion":"legacy-scoring-profile/1.0.0","checkerSha256":"31eda986fe7a6ba0607197e1ddfd3316a977f93900007097b815d8e77b573fed","readerSha256":"2ea3c5071d8d56e421a37053127dea08fe8eb08ce91e4de9f5c3b4c4b1172ccf","finishSha256":"5db61206ed04f32af7052fce2d64e2ccf414d6fea13645f58eecf67f616b61a2","contextSha256":"d64ba9ac11ba732c983cd195cd7d83fba878e67f4ae0bffc8b6e166a600a8bd9","exportSha256":"e4c17997fdbec81d931e4838b3522c6c7d3c861b0bfa07b6fb3ab5ece160f0a2","metadataSha256":"f18e6abfd698c4dbf4f7f6040fb577b2e49e78e4125bfd9d31e8166d0e678da8"}$current_scoring$::jsonb)
    or p_policy->'planProfile' is distinct from $plan${"schemaVersion":"initial-feedback-plan-readiness/1.0.0","profileVersion":"initial-feedback-plan-profile/1.0.0","policyVersion":"initial-feedback-plan-policy/1.0.0","policySha256":"972b648ccc90b29c0c88fc504ac2746ab1489e17f05cfd2048cb487a2b38cc48","checkerSha256":"c5d8c0e8e5ac52c8b06a4fad5ea78f6fe6e42297bbbfd51cd2779243c8418b36","rendererSha256":"c8bc131aacc7f9ddd8e30dcca8f5f429e78ee84180e5dd4542254883001cedc6","metadataSha256":"3c133694d11334e9430821945c94782b562ab1efb3f26bb8d4e7a9f2699369c5"}$plan$::jsonb then return false;end if;
  if jsonb_typeof(p_policy->'maxOutputTokens') is distinct from 'number' or (p_policy->>'maxOutputTokens') collate "C" !~ '^[1-9][0-9]{0,9}$'
    or jsonb_typeof(p_policy->'attemptLimit') is distinct from 'number' or (p_policy->>'attemptLimit') collate "C" !~ '^[1-3]$' then return false;end if;
  if (p_policy->>'maxOutputTokens')::numeric not between 256 and 8000 then return false;end if;
  if p_policy->'budgetPolicyVersion'<>'null'::jsonb and (jsonb_typeof(p_policy->'budgetPolicyVersion') is distinct from 'string'
    or (p_policy->>'budgetPolicyVersion') collate "C" !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}$') then return false;end if;
  return p_policy->>'sha256'=private.ifo_sha(private.ifo_policy_frame(p_policy));
end;

private.ifo_selected_policy:
declare sel private.initial_feedback_selections%rowtype;pol jsonb;
begin
  if private.ifo_keys(p_selector,array['version','sha256']) is not true
    or jsonb_typeof(p_selector->'version') is distinct from 'string'
    or jsonb_typeof(p_selector->'sha256') is distinct from 'string'
    or (p_selector->>'sha256') collate "C" !~ '^[a-f0-9]{64}$' then perform private.ifo_fail('invalid');end if;
  select * into sel from private.initial_feedback_selections where organization_id=p_org and enabled for share skip locked;
  if not found then perform private.ifo_fail('unavailable');end if;
  if sel.policy_version is distinct from p_selector->>'version' or sel.policy_sha256 is distinct from p_selector->>'sha256' then perform private.ifo_fail('stale');end if;
  select descriptor into pol from private.initial_feedback_policies where version=sel.policy_version and sha256=sel.policy_sha256 for share skip locked;
  if not found or private.ifo_policy_valid(pol) is not true then perform private.ifo_fail('unavailable');end if;
  if pol->'scoringInputProfile' is distinct from $current_scoring${"schemaVersion":"legacy-scoring-readiness/1.0.0","profileVersion":"legacy-scoring-profile/1.0.0","checkerSha256":"31eda986fe7a6ba0607197e1ddfd3316a977f93900007097b815d8e77b573fed","readerSha256":"2ea3c5071d8d56e421a37053127dea08fe8eb08ce91e4de9f5c3b4c4b1172ccf","finishSha256":"5db61206ed04f32af7052fce2d64e2ccf414d6fea13645f58eecf67f616b61a2","contextSha256":"d64ba9ac11ba732c983cd195cd7d83fba878e67f4ae0bffc8b6e166a600a8bd9","exportSha256":"e4c17997fdbec81d931e4838b3522c6c7d3c861b0bfa07b6fb3ab5ece160f0a2","metadataSha256":"f18e6abfd698c4dbf4f7f6040fb577b2e49e78e4125bfd9d31e8166d0e678da8"}$current_scoring$::jsonb then perform private.ifo_fail('unavailable');end if;
  return pol;
end;

private.ifo_original:
declare s private.analysis_scoring_inputs%rowtype;d public.analysis_deterministic_results%rowtype;
  ctx jsonb;core jsonb;
begin
  select * into s from private.analysis_scoring_inputs where analysis_id=p_analysis.id and owner_id=p_analysis.owner_id
    and organization_id=p_analysis.organization_id for key share skip locked;
  if not found then perform private.ifo_fail('unavailable');end if;
  perform private.legacy_scoring_stored_source(s);
  select * into d from public.analysis_deterministic_results where analysis_id=p_analysis.id and owner_id=p_analysis.owner_id
    and organization_id=p_analysis.organization_id for share skip locked;
  if not found or private.legacy_scoring_row_sha256(d) is distinct from s.deterministic_content_sha256
    or d.result_checksum is distinct from s.result_checksum then perform private.ifo_fail('unavailable');end if;
  ctx:=s.input_context;
  if ctx->>'schemaVersion' is distinct from 'legacy-scoring-input/1.0.0'
    or ctx->>'analysisId' is distinct from s.analysis_id::text or ctx->>'ownerId' is distinct from s.owner_id::text
    or ctx->>'organizationId' is distinct from s.organization_id::text
    or ctx->'source'->>'resumeId' is distinct from s.resume_id::text or ctx->'source'->>'resumeVersionId' is distinct from s.resume_version_id::text
    or ctx->'binding'->>'analysisId' is distinct from s.analysis_id::text or ctx->'binding'->>'ownerId' is distinct from s.owner_id::text
    or ctx->'binding'->>'organizationId' is distinct from s.organization_id::text
    or ctx->'binding'->>'resumeId' is distinct from s.resume_id::text or ctx->'binding'->>'resumeVersionId' is distinct from s.resume_version_id::text
    or ctx->'binding'->>'inputBindingSha256' is distinct from s.input_binding_sha256
    or ctx->'binding'->>'jobId' is distinct from s.job_id::text
    or ctx->'binding'->>'fileChecksum' is distinct from ctx->'source'->>'fileChecksum'
    or ctx->'binding'->>'textChecksum' is distinct from ctx->'extraction'->>'textChecksum'
    or ctx->'extraction'->>'textChecksum' is distinct from private.ifo_sha(ctx->'extraction'->>'text')
    or ctx->'binding'->>'extractionSha256' is distinct from ctx->'extraction'->>'contentSha256'
    or ctx->'extraction'->>'contentSha256' is distinct from private.ifo_sha(((ctx->'extraction')-'contentSha256')::text)
    or ctx->'binding'->>'jobSha256' is distinct from ctx->'job'->>'contentSha256'
    or octet_length(convert_to(ctx::text,'UTF8'))>4194304 then perform private.ifo_fail('unavailable');end if;
  if s.job_id is null then
    if ctx->'job' is distinct from jsonb_build_object('kind','none') then perform private.ifo_fail('unavailable');end if;
  elsif ctx->'job'->>'kind' is distinct from 'owned_job' or ctx->'job'->>'id' is distinct from s.job_id::text
    or ctx->'job'->>'contentSha256' is distinct from private.ifo_sha(((ctx->'job')-'contentSha256')::text) then perform private.ifo_fail('unavailable');end if;
  core:=(ctx-array['binding','requestId'])||jsonb_build_object('schemaVersion','legacy-scoring-input-snapshot/1.0.0');
  if private.ifo_sha(core::text) is distinct from s.input_binding_sha256 then perform private.ifo_fail('unavailable');end if;
  -- Original admission only. No mutable JD/extraction read before exact replay.
  return jsonb_build_object('scoringContext',ctx,'deterministicResult',private.legacy_scoring_result(d));
end;

private.ifo_binding:
declare c jsonb:=p_context->'scoringContext';s private.analysis_scoring_inputs%rowtype;
begin
  select * into s from private.analysis_scoring_inputs where analysis_id=(c->>'analysisId')::uuid and owner_id=(c->>'ownerId')::uuid
    and organization_id=(c->>'organizationId')::uuid;
  if not found then perform private.ifo_fail('not_found');end if;
  return jsonb_build_object('schemaVersion','initial-feedback-binding/1.0.0','analysisId',s.analysis_id,'ownerId',s.owner_id,
    'organizationId',s.organization_id,'resumeId',s.resume_id,'resumeVersionId',s.resume_version_id,
    'scoringInputSha256',s.input_binding_sha256,'deterministicContentSha256',s.deterministic_content_sha256,
    'resultChecksum',s.result_checksum,'sourceTextSha256',c->'extraction'->'textChecksum','jobId',s.job_id,'jobSha256',c->'job'->'contentSha256','policy',p_policy);
end;

private.ifo_operation_json:
begin
  return jsonb_build_object('schemaVersion','initial-feedback-operation/1.0.0','operationId',p_operation.operation_id,
    'analysisId',p_operation.analysis_id,'ownerId',p_operation.owner_id,'organizationId',p_operation.organization_id,
    'binding',p_operation.binding,'bindingSha256',p_operation.binding_sha256,'state',p_operation.state,'attemptLimit',p_operation.attempt_limit,
    'attempts',coalesce((select jsonb_agg(private.ifo_attempt_json(a) order by a.ordinal) from private.initial_feedback_attempts a
      where a.operation_id=p_operation.operation_id),'[]'::jsonb),'publicationId',p_operation.publication_id);
end;

private.ifo_immutable:
begin
 if tg_op='DELETE' then perform private.ifo_fail('stale');end if;
 if tg_table_name='initial_feedback_policies' then
  if tg_op='UPDATE' or private.ifo_policy_valid(new.descriptor) is not true then perform private.ifo_fail('stale');end if;
 elsif tg_table_name='initial_feedback_operations' then
  if tg_op='UPDATE' then
   if old.state<>'open' or old.publication_id is not null or new.state<>'published' or new.publication_id is null
    or (to_jsonb(new)-'state'-'publication_id') is distinct from (to_jsonb(old)-'state'-'publication_id')
    or not exists(select 1 from private.initial_feedback_publications p where p.id=new.publication_id and p.operation_id=new.operation_id
     and p.analysis_id=new.analysis_id and p.owner_id=new.owner_id and p.organization_id=new.organization_id and p.binding_sha256=new.binding_sha256)
    then perform private.ifo_fail('stale');end if;
   return new;
  end if;
  if new.state<>'open' or new.publication_id is not null or new.binding->>'analysisId' is distinct from new.analysis_id::text
   or new.binding->>'ownerId' is distinct from new.owner_id::text or new.binding->>'organizationId' is distinct from new.organization_id::text
   or new.binding->>'resumeId' is distinct from new.resume_id::text or new.binding->>'resumeVersionId' is distinct from new.resume_version_id::text
   or new.binding->'policy'->>'version' is distinct from new.policy_version or new.binding->'policy'->>'sha256' is distinct from new.policy_sha256
   or (new.binding->'policy'->>'attemptLimit')::integer is distinct from new.attempt_limit
   or not exists(select 1 from private.initial_feedback_policies where version=new.policy_version and sha256=new.policy_sha256 and descriptor=new.binding->'policy')
   then perform private.ifo_fail('invalid');end if;
 else perform private.ifo_fail('invalid');end if;
 return new;
end;

private.ifo_attempt_guard:
declare op private.initial_feedback_operations%rowtype;previous private.initial_feedback_attempts%rowtype;
begin
 if tg_op='DELETE' then perform private.ifo_fail('stale');end if;
 select * into op from private.initial_feedback_operations where operation_id=new.operation_id for update;
 if not found then perform private.ifo_fail('stale');end if;
 if tg_op='INSERT' then
  if op.state<>'open' or op.publication_id is not null or new.state<>'reserved' or new.ordinal>op.attempt_limit then perform private.ifo_fail('stale');end if;
  select * into previous from private.initial_feedback_attempts where operation_id=op.operation_id order by ordinal desc limit 1 for update;
  if found then
   if new.ordinal<>previous.ordinal+1 or previous.state<>'failed' or previous.usage is null or previous.error_code not in ('provider_failed','timeout') then perform private.ifo_fail('stale');end if;
  elsif new.ordinal<>1 then perform private.ifo_fail('stale');end if;
 else
  if (new.attempt_id,new.operation_id,new.ordinal,new.created_at) is distinct from (old.attempt_id,old.operation_id,old.ordinal,old.created_at)
   or (old.claimed_at is not null and (new.claimed_at,new.claim_lease,new.budget_attempt_id) is distinct from (old.claimed_at,old.claim_lease,old.budget_attempt_id))
   or (old.usage is not null and new.usage is distinct from old.usage) or (old.error_code is not null and new.error_code is distinct from old.error_code)
   then perform private.ifo_fail('stale');end if;
  if op.state='published' then
   -- Candidate content may already have cascaded away. Exact immutable
   -- claimed metadata alone admits this first known fill, never a new dispatch.
   -- Identity-retention expiry is a separate, not-yet-adopted lifecycle.
   if not(old.state='held_unknown' and old.usage is null and old.error_code is not null and new.state='failed' and new.usage is not null
      and new.error_code=old.error_code) then
    if to_jsonb(new) is distinct from to_jsonb(old) then perform private.ifo_fail('stale');end if;
   end if;
  elsif old.state='reserved' then
   if not((new.state='dispatched' and new.claimed_at is not null and new.claim_lease is not null and new.usage is null and new.error_code is null)
    or (new.state='cancelled_before_dispatch' and new.claimed_at is null and new.claim_lease is null and new.budget_attempt_id is null and new.usage is null and new.error_code is null))
    then perform private.ifo_fail('stale');end if;
  elsif new.state='published' then
   if old.state<>'known' or old.usage is null or old.error_code is not null
    or not exists(select 1 from private.initial_feedback_publications p where p.operation_id=op.operation_id and p.attempt_id=new.attempt_id and p.state='assessed')
    then perform private.ifo_fail('stale');end if;
  elsif old.state in ('published','cancelled_before_dispatch') or new.state not in ('known','held_unknown','failed') then perform private.ifo_fail('stale');end if;
 end if;return new;
end;

private.ifo_context:
declare actual jsonb;currentness text;eligibility text;
begin
  actual:=private.legacy_scoring_input_data(p_analysis);
  currentness:=case when actual->'binding' is not distinct from p_original->'scoringContext'->'binding' then 'current' else 'historical' end;
  eligibility:=case when currentness='historical' then 'historical_inputs'
    when private.ifp_u16_length(p_original->'scoringContext'->'extraction'->>'text')>100000 then 'source_resource_limit' else 'eligible' end;
  return p_original||jsonb_build_object('currentness',currentness,'generationEligibility',eligibility);
end;

public.prepare_initial_feedback:
declare a public.analyses%rowtype;op private.initial_feedback_operations%rowtype;att private.initial_feedback_attempts%rowtype;
  pub private.initial_feedback_publications%rowtype;replayed_attempt private.initial_feedback_attempts%rowtype;original jsonb;ctx jsonb;pol jsonb;b jsonb;next_ordinal integer:=1;
begin
  if private.legacy_scoring_lease(p_lease) is not true or p_analysis_id is null
    or private.ifo_keys(p_policy,array['version','sha256']) is not true
    or jsonb_typeof(p_policy->'version') is distinct from 'string' or jsonb_typeof(p_policy->'sha256') is distinct from 'string'
    or p_policy->>'version' is distinct from 'initial-feedback-publication/1.0.0' or (p_policy->>'sha256') collate "C" !~ '^[a-f0-9]{64}$'
    then perform private.ifo_fail('invalid');end if;
  if private.initial_feedback_operation_ready() is not true then perform private.ifo_fail('unavailable');end if;
  a:=private.legacy_scoring_access(p_analysis_id,null);original:=private.ifo_original(a);
  select * into op from private.initial_feedback_operations where analysis_id=a.id for update;
  if found then
    if op.owner_id<>a.owner_id or op.organization_id<>a.organization_id
      or op.binding is distinct from private.ifo_binding(original,op.binding->'policy') then perform private.ifo_fail('not_found');end if;
    if op.state='published' then
      select * into pub from private.initial_feedback_publications where id=op.publication_id and operation_id=op.operation_id for key share skip locked;
      if not found then perform private.ifo_fail('unavailable');end if;
      if private.legacy_scoring_static_job(a.id,p_lease) is not true and pub.finish_lease is distinct from p_lease
        and not exists(select 1 from private.initial_feedback_attempts where operation_id=op.operation_id and claim_lease=p_lease)
        then perform private.ifo_fail('not_found');end if;
      if p_retry_after_attempt_id is not null and not exists(select 1 from private.initial_feedback_attempts where operation_id=op.operation_id and attempt_id=p_retry_after_attempt_id)
        then perform private.ifo_fail('stale');end if;
      return jsonb_build_object('schemaVersion','initial-feedback-prepare/1.0.0','status','published','operation',private.ifo_operation_json(op),
        'publication',private.ifpub_json(pub,true),'context',null,'dispatchAllowed',false,'replayed',true);
    end if;
    if private.legacy_scoring_static_job(a.id,p_lease) is not true and not exists(select 1 from private.initial_feedback_attempts
      where operation_id=op.operation_id and claim_lease=p_lease) then perform private.ifo_fail('not_found');end if;
    select * into att from private.initial_feedback_attempts where operation_id=op.operation_id order by ordinal desc limit 1 for update;
    if not found then perform private.ifo_fail('unavailable');end if;
    -- Null selector and a replayed explicit retry return status BEFORE fresh
    -- policy/lease/current-JD/consent/rate/budget checks. No dispatch context.
    if p_retry_after_attempt_id is not null then
      select next_attempt.* into replayed_attempt from private.initial_feedback_attempts previous_attempt
        join private.initial_feedback_attempts next_attempt on next_attempt.operation_id=previous_attempt.operation_id
          and next_attempt.ordinal=previous_attempt.ordinal+1
        where previous_attempt.attempt_id=p_retry_after_attempt_id and previous_attempt.operation_id=op.operation_id
        for update of next_attempt;
      if found then
        return jsonb_build_object('schemaVersion','initial-feedback-prepare/1.0.0','status','pending','operation',private.ifo_operation_json(op),
          'attempt',private.ifo_attempt_json(replayed_attempt),'context',null,'dispatchAllowed',false,'replayed',true);
      end if;
    end if;
    if p_retry_after_attempt_id is null then
      return jsonb_build_object('schemaVersion','initial-feedback-prepare/1.0.0','status','pending','operation',private.ifo_operation_json(op),
        'attempt',private.ifo_attempt_json(att),'context',null,'dispatchAllowed',false,'replayed',true);
    end if;
    if att.attempt_id<>p_retry_after_attempt_id or att.state<>'failed' or att.usage is null or att.error_code not in ('provider_failed','timeout')
      or att.ordinal>=op.attempt_limit then perform private.ifo_fail('stale');end if;
    next_ordinal:=att.ordinal+1;
  elsif p_retry_after_attempt_id is not null then perform private.ifo_fail('stale');end if;
  if a.status<>'qualitative_review' or not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
    then perform private.ifo_fail('stale');end if;
  pol:=private.ifo_selected_policy(a.organization_id,p_policy);ctx:=private.ifo_context(a,original);b:=private.ifo_binding(ctx,pol);
  if op.operation_id is not null then
    if op.policy_version<>pol->>'version' or op.policy_sha256<>pol->>'sha256' or op.binding is distinct from b
      or ctx->>'generationEligibility'<>'eligible' then perform private.ifo_fail('stale');end if;
    -- Retry preparation requires actual current consent; initial preparation
    -- remains usable for AI-off/historical/resource deterministic-only recovery.
    perform 1 from public.consents where user_id=a.owner_id and purpose='qualitative_ai' and policy_version='candidate-ai-v1' for share skip locked;
    if not found then perform private.ifo_fail('not_found');end if;
  else
    insert into private.initial_feedback_operations(analysis_id,owner_id,organization_id,resume_id,resume_version_id,policy_version,policy_sha256,binding,binding_sha256,attempt_limit)
      values(a.id,a.owner_id,a.organization_id,(b->>'resumeId')::uuid,(b->>'resumeVersionId')::uuid,pol->>'version',pol->>'sha256',b,private.ifo_sha(b::text),(pol->>'attemptLimit')::integer)
      returning * into op;
  end if;
  insert into private.initial_feedback_attempts(operation_id,ordinal) values(op.operation_id,next_ordinal) returning * into att;
  if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
    or private.try_candidate_privacy_write(a.owner_id) is not true then perform private.ifo_fail('stale');end if;
  return jsonb_build_object('schemaVersion','initial-feedback-prepare/1.0.0','status','prepared','operation',private.ifo_operation_json(op),
    'attempt',private.ifo_attempt_json(att),'context',ctx,'dispatchAllowed',false,'replayed',false);
end;

public.claim_initial_feedback_dispatch:
declare a public.analyses%rowtype;op private.initial_feedback_operations%rowtype;att private.initial_feedback_attempts%rowtype;
  original jsonb;ctx jsonb;pol jsonb;budget jsonb:=null;req jsonb;
begin
  if p_analysis_id is null or p_operation_id is null or p_attempt_id is null or p_binding_sha256 is null
    or p_binding_sha256 collate "C" !~ '^[a-f0-9]{64}$' or private.legacy_scoring_lease(p_lease) is not true then perform private.ifo_fail('invalid');end if;
  if private.initial_feedback_operation_ready() is not true then perform private.ifo_fail('unavailable');end if;
  a:=private.legacy_scoring_access(p_analysis_id,null);original:=private.ifo_original(a);
  select * into op from private.initial_feedback_operations where operation_id=p_operation_id and analysis_id=a.id
    and owner_id=a.owner_id and organization_id=a.organization_id for update;
  if not found or op.binding_sha256<>p_binding_sha256
    or op.binding is distinct from private.ifo_binding(original,op.binding->'policy') then perform private.ifo_fail('not_found');end if;
  select * into att from private.initial_feedback_attempts where attempt_id=p_attempt_id and operation_id=op.operation_id for update;
  if not found then perform private.ifo_fail('not_found');end if;
  if private.legacy_scoring_static_job(a.id,p_lease) is not true and att.claim_lease is distinct from p_lease then perform private.ifo_fail('not_found');end if;
  if op.state<>'open' or op.publication_id is not null or att.state<>'reserved' then
    return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),
      'dispatchAllowed',false,'replayed',true,'budget',null);
  end if;
  if (op.binding->'policy'->>'budgetPolicyVersion') is null or p_budget is null or p_budget='null'::jsonb then perform private.ifo_fail('unavailable');end if;
  if a.status<>'qualitative_review' or not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
    then perform private.ifo_fail('stale');end if;
  pol:=private.ifo_selected_policy(a.organization_id,jsonb_build_object('version',op.policy_version,'sha256',op.policy_sha256));
  if pol is distinct from op.binding->'policy' then perform private.ifo_fail('stale');end if;
  ctx:=private.ifo_context(a,original);
  if ctx->>'generationEligibility'<>'eligible' or private.ifo_binding(ctx,pol) is distinct from op.binding then perform private.ifo_fail('stale');end if;
  -- The actual frozen source parser checks its source-domain/resource limits
  -- BEFORE any provider permission; it supplies no candidate qualification.
  perform private.ifp_document(ctx->'scoringContext'->'extraction'->>'text');
  perform 1 from public.consents where user_id=a.owner_id and purpose='qualitative_ai' and policy_version='candidate-ai-v1' for share skip locked;
  if not found then perform private.ifo_fail('not_found');end if;
  if pol->'budgetPolicyVersion'='null'::jsonb then
    if p_budget is not null and p_budget<>'null'::jsonb then perform private.ifo_fail('invalid');end if;
  else
    if private.ifo_keys(p_budget,array['p_user_id','p_organization_id','p_request']) is not true
      or p_budget->>'p_user_id' is distinct from a.owner_id::text or p_budget->>'p_organization_id' is distinct from a.organization_id::text
      then perform private.ifo_fail('invalid');end if;
    req:=p_budget->'p_request';
    if private.ai_budget_request_valid(req,'claim_dispatch') is not true or req->>'operationId' is distinct from op.operation_id::text
      or req->>'attemptId' is distinct from att.attempt_id::text or (req->>'attemptOrdinal')::numeric is distinct from att.ordinal::numeric
      or req->>'surface' is distinct from 'qualitative' or req->>'model' is distinct from pol->>'model'
      or req->>'promptPolicyVersion' is distinct from pol->>'promptVersion' or req->>'policyVersion' is distinct from pol->>'budgetPolicyVersion'
      or req->>'payloadSha256' is distinct from op.binding_sha256
      or (req->>'reservedOutputTokens')::numeric is distinct from (pol->>'maxOutputTokens')::numeric then perform private.ifo_fail('invalid');end if;
    -- Never wait for the inverse org -> membership order of generic R03 while
    -- already holding analysis/queue/source/membership locks. Reentrant after.
    perform 1 from public.organizations where id=a.organization_id for update skip locked;
    if not found then perform private.ifo_fail('stale');end if;
    perform 1 from public.memberships where organization_id=a.organization_id and user_id=a.owner_id
      and role in ('owner','admin','member') for update skip locked;
    if not found then perform private.ifo_fail('stale');end if;
    if not exists(select 1 from private.ai_budget_operation_sources s where s.kind='initial_feedback' and (s.operation_id,s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id)
      =(op.operation_id,a.owner_id,a.organization_id,a.id,op.resume_id,op.resume_version_id)) then perform private.ifo_fail('invalid');end if;
    budget:=private.ai_budget_transition(a.owner_id,a.organization_id,req,'claim_dispatch');
    if budget->>'status'='denied' then
      return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),
        'dispatchAllowed',false,'replayed',false,'budget',budget);
    end if;
    -- An existing generic winner cannot be adopted as this still-reserved
    -- feedback attempt. Never mark/release that winner or dispatch a new one.
    if budget->>'status' is distinct from 'ok' or budget->'receipt'->'dispatchAllowed' is distinct from 'true'::jsonb then perform private.ifo_fail('stale');end if;
    if budget->'receipt'->>'attemptId' is distinct from att.attempt_id::text or budget->'receipt'->>'operationId' is distinct from op.operation_id::text
      or budget->'receipt'->'replayed' is distinct from 'false'::jsonb then perform private.ifo_fail('stale');end if;
  end if;
  if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)
    or private.try_candidate_privacy_write(a.owner_id) is not true then perform private.ifo_fail('stale');end if;
  update private.initial_feedback_attempts set state='dispatched',claim_lease=p_lease,claimed_at=clock_timestamp(),
    budget_attempt_id=case when budget is null then null else att.attempt_id end
    where attempt_id=att.attempt_id and state='reserved' returning * into att;
  if not found then perform private.ifo_fail('stale');end if;
  return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),
    'dispatchAllowed',true,'replayed',false,'budget',budget);
end;

public.settle_initial_feedback_attempt:
declare op private.initial_feedback_operations%rowtype;att private.initial_feedback_attempts%rowtype;
  actual jsonb:=nullif(p_usage,'null'::jsonb);replayed boolean;
begin
  if p_operation_id is null or p_attempt_id is null or p_binding_sha256 is null or p_binding_sha256 collate "C" !~ '^[a-f0-9]{64}$'
    or private.ifo_usage_valid(actual) is not true or (p_error_code is not null and p_error_code not in
      ('provider_failed','timeout','cancelled','invalid_output','unsupported_output','storage_failed','unknown')) then perform private.ifo_fail('invalid');end if;
  if private.initial_feedback_operation_ready() is not true then perform private.ifo_fail('unavailable');end if;
  -- No current candidate/auth/source/lease/policy-selection read. Static exact
  -- metadata remains settleable after withdrawal; this NEVER calls R03 settle.
  select * into op from private.initial_feedback_operations where operation_id=p_operation_id for update;
  if not found or op.binding_sha256<>p_binding_sha256 then perform private.ifo_fail('not_found');end if;
  select * into att from private.initial_feedback_attempts where attempt_id=p_attempt_id and operation_id=op.operation_id for update;
  if not found or att.claimed_at is null or att.claim_lease is null or att.state='reserved' then perform private.ifo_fail('stale');end if;
  if (att.usage is not null and actual is not null and att.usage is distinct from actual)
    or (att.error_code is not null and p_error_code is not null and att.error_code<>p_error_code) then perform private.ifo_fail('stale');end if;
  if att.state='published' then
    -- Saved assessed output cannot be converted into a technical failure.
    if p_error_code is not null then perform private.ifo_fail('stale');end if;
    return jsonb_build_object('schemaVersion','initial-feedback-settlement/1.0.0','operationId',op.operation_id,'attemptId',att.attempt_id,
      'bindingSha256',op.binding_sha256,'state','known','usage',att.usage,'errorCode',null,'replayed',true);
  end if;
  if op.state='published' and att.usage is null and att.error_code is null then perform private.ifo_fail('stale');end if;
  replayed:=(actual is null or att.usage is not distinct from actual) and (p_error_code is null or att.error_code is not distinct from p_error_code)
    and att.state<>'dispatched';
  if not replayed then
    update private.initial_feedback_attempts set usage=coalesce(usage,actual),error_code=coalesce(error_code,p_error_code),
      state=case when coalesce(usage,actual) is null then 'held_unknown' when coalesce(error_code,p_error_code) is not null then 'failed' else 'known' end
      where attempt_id=att.attempt_id returning * into att;
  end if;
  return jsonb_build_object('schemaVersion','initial-feedback-settlement/1.0.0','operationId',op.operation_id,'attemptId',att.attempt_id,
    'bindingSha256',op.binding_sha256,'state',att.state,'usage',att.usage,'errorCode',att.error_code,'replayed',replayed);
end;

