 select * into pub from private.initial_feedback_publications where id=new.publication_id and operation_id=op.operation_id for key share skip locked;
 if not found or op.state<>'published' or op.publication_id<>pub.id
  or (new.owner_id,new.organization_id,new.analysis_id,new.resume_id,new.resume_version_id,new.binding_sha256)
   is distinct from (op.owner_id,op.organization_id,op.analysis_id,op.resume_id,op.resume_version_id,op.binding_sha256)
  or (new.attempt_id,new.run_id,new.publication_state) is distinct from (pub.attempt_id,pub.run_id,pub.state)
  or (pub.owner_id,pub.organization_id,pub.analysis_id,pub.resume_id,pub.resume_version_id,pub.binding_sha256)
   is distinct from (op.owner_id,op.organization_id,op.analysis_id,op.resume_id,op.resume_version_id,op.binding_sha256)
  or not isfinite(new.retired_at) or new.retired_at>clock_timestamp() then perform private.ifo_fail('unavailable');end if;
 if new.deletion_request_id is not null and new.retention_item_id is null then
  if not exists(select 1 from public.data_requests d join private.privacy_deletion_plans plan on plan.request_id=d.id
    where d.id=new.deletion_request_id and d.user_id=new.owner_id and d.kind='deletion' and d.status='processing'
      and d.lease_owner is not null and d.lease_expires_at>clock_timestamp()) then perform private.ifo_fail('unavailable');end if;
 elsif new.retention_item_id is not null and new.deletion_request_id is null then
  if not exists(select 1 from private.retention_items t join public.resume_versions v on v.storage_key=t.storage_key and v.resume_id=t.resume_id
    join public.resumes r on r.id=t.resume_id where t.id=new.retention_item_id and t.owner_id=new.owner_id and t.resume_id=new.resume_id
      and r.owner_id=new.owner_id and r.status='deleted' and v.owner_id=new.owner_id and t.status='deleted'
      and not exists(select 1 from private.retention_items x where x.resume_id=r.id and x.status<>'deleted')) then perform private.ifo_fail('unavailable');end if;
 else perform private.ifo_fail('invalid');end if;
 return new;
end;

private.retire_initial_feedback_publicat:
declare op_id uuid;op private.initial_feedback_operations%rowtype;pub private.initial_feedback_publications%rowtype;
 att private.initial_feedback_attempts%rowtype;run public.analysis_ai_runs%rowtype;
begin
 if private.owned_ai_retirement_ready() is not true then perform private.ifo_fail('unavailable');end if;
 if p_owner_id is null or (p_deletion_request_id is not null)::integer+(p_retention_item_id is not null)::integer<>1
  or current_setting('transaction_isolation') not in ('read committed','read uncommitted') then perform private.ifo_fail('invalid');end if;
 -- Existing producer may hold request/item rows: owner acquisition never waits.
 if not private.try_lock_candidate_owners(array[p_owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
 if p_deletion_request_id is not null then
  if p_resume_id is not null then perform private.ifo_fail('invalid');end if;
  perform 1 from public.data_requests d join private.privacy_deletion_plans plan on plan.request_id=d.id
   where d.id=p_deletion_request_id and d.user_id=p_owner_id and d.kind='deletion' and d.status='processing'
    and d.lease_owner is not null and d.lease_expires_at>clock_timestamp() for update of d skip locked;
 else
  perform 1 from private.retention_items t join public.resumes r on r.id=t.resume_id
   where t.id=p_retention_item_id and t.owner_id=p_owner_id and t.resume_id=p_resume_id and t.status='deleted'
    and r.owner_id=p_owner_id and r.status='deleted'
    and not exists(select 1 from private.retention_items x where x.resume_id=r.id and x.status<>'deleted') for update of t skip locked;
 end if;
 if not found then perform private.ifo_fail('unavailable');end if;
 for op_id in select operation_id from private.initial_feedback_operations where owner_id=p_owner_id and publication_id is not null
   and (p_resume_id is null or resume_id=p_resume_id) order by analysis_id,operation_id loop
  -- Root/source -> analysis -> operation -> attempt -> publication -> run.
  -- Every object lock is nonblocking: no reverse waiting with request/item locks.
  perform 1 from public.resumes r join public.resume_versions v on v.resume_id=r.id
   join private.initial_feedback_operations o on o.resume_version_id=v.id and o.resume_id=r.id
   where o.operation_id=op_id and r.owner_id=p_owner_id and v.owner_id=p_owner_id and v.organization_id=o.organization_id
   for share of r,v skip locked;
  if not found then
   -- Exact already-retired operations have no content; no invented new proof.
   if exists(select 1 from private.initial_feedback_content_retirements s join private.initial_feedback_operations oldop on oldop.operation_id=s.operation_id
     where s.operation_id=op_id and oldop.state='published' and s.publication_id=oldop.publication_id
      and (s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id,s.binding_sha256)
       =(oldop.owner_id,oldop.organization_id,oldop.analysis_id,oldop.resume_id,oldop.resume_version_id,oldop.binding_sha256)
      and not exists(select 1 from private.initial_feedback_publications p where p.operation_id=op_id)) then continue;end if;
   perform private.ifo_fail('unavailable');
  end if;
  perform 1 from public.analyses a join private.initial_feedback_operations o on o.analysis_id=a.id
   where o.operation_id=op_id and a.owner_id=p_owner_id and a.organization_id=o.organization_id and a.resume_version_id=o.resume_version_id
   for update of a skip locked;
  if not found then perform private.ifo_fail('unavailable');end if;
  select * into op from private.initial_feedback_operations where operation_id=op_id for update skip locked;
  if not found or op.state<>'published' then perform private.ifo_fail('unavailable');end if;
  if exists(select 1 from private.initial_feedback_content_retirements where operation_id=op_id) then perform private.ifo_fail('unavailable');end if;
  -- Publication is immutable; read its selector before locking the selected attempt.
  select * into pub from private.initial_feedback_publications where id=op.publication_id and operation_id=op_id;
  if not found then perform private.ifo_fail('unavailable');end if;
  if pub.attempt_id is not null then
   select * into att from private.initial_feedback_attempts where attempt_id=pub.attempt_id and operation_id=op_id for update skip locked;
   if not found then perform private.ifo_fail('unavailable');end if;
  end if;
  select * into pub from private.initial_feedback_publications where id=op.publication_id and operation_id=op_id for update skip locked;
  if not found or (pub.owner_id,pub.organization_id,pub.analysis_id,pub.resume_id,pub.resume_version_id,pub.binding_sha256)
    is distinct from (op.owner_id,op.organization_id,op.analysis_id,op.resume_id,op.resume_version_id,op.binding_sha256)
   then perform private.ifo_fail('unavailable');end if;
  if pub.state='assessed' then
   if pub.attempt_id is null or pub.run_id is null or att.state<>'published' or att.error_code is not null
     or att.claimed_at is null or att.usage is null or private.ifo_usage_valid(att.usage) is not true then perform private.ifo_fail('unavailable');end if;
   select * into run from public.analysis_ai_runs where id=pub.run_id for share skip locked;
   if not found or (run.owner_id,run.organization_id,run.analysis_id) is distinct from (op.owner_id,op.organization_id,op.analysis_id)
    or run.provider<>'openai' or run.model_id<>op.binding->'policy'->>'model' or run.prompt_version<>op.binding->'policy'->>'promptVersion'
    or run.input_hash<>op.binding_sha256 or run.input_tokens::text<>att.usage->>'inputTokens' or run.output_tokens::text<>att.usage->>'outputTokens'
    or private.ifo_sha(private.ifpub_run_json(run)::text)<>pub.run_content_sha256 then perform private.ifo_fail('unavailable');end if;
  elsif pub.state<>'deterministic_only' or pub.run_id is not null then perform private.ifo_fail('unavailable');end if;
  insert into private.initial_feedback_content_retirements(operation_id,publication_id,attempt_id,run_id,owner_id,organization_id,analysis_id,
    resume_id,resume_version_id,publication_state,binding_sha256,retired_at,deletion_request_id,retention_item_id)
   values(op.operation_id,pub.id,pub.attempt_id,pub.run_id,op.owner_id,op.organization_id,op.analysis_id,op.resume_id,op.resume_version_id,
    pub.state,op.binding_sha256,clock_timestamp(),p_deletion_request_id,p_retention_item_id);
 end loop;
end;

public.export_owned_ai_retirement_record:
declare rows jsonb[]:=array[]::jsonb[];row_value jsonb;answer jsonb;n integer:=0;bytes bigint:=1024;
begin
 if p_user_id is null then perform private.ifo_fail('invalid');end if;
 if private.owned_ai_retirement_ready() is not true then perform private.ifo_fail('unavailable');end if;
 perform 1 from auth.users where id=p_user_id for key share skip locked;if not found then perform private.ifo_fail('not_found');end if;
 -- Entire owner across orgs/periods/flags; no membership/source requirement.
 for row_value in select to_jsonb(s)||jsonb_build_object('retired_at',private.ifo_stamp(s.retired_at))
  from private.initial_feedback_content_retirements s where s.owner_id=p_user_id order by s.operation_id limit 4097 loop
  n:=n+1;bytes:=bytes+octet_length(convert_to(row_value::text,'UTF8'))+1;
  if n>4096 or bytes>33554432 then perform private.ifo_fail('unavailable');end if;
  rows:=array_append(rows,row_value);
 end loop;
 answer:=jsonb_build_object('schemaVersion','owned-ai-retirement-export/1.0.0','retirements',to_jsonb(rows));
 if octet_length(convert_to(answer::text,'UTF8'))>33554432 then perform private.ifo_fail('unavailable');end if;
 return answer;
end;

public.read_owned_ai_retirement_readines:
begin
 return jsonb_build_object('schemaVersion','owned-ai-retirement-readiness/1.0.0','profileVersion','owned-ai-retirement-profile/1.0.0',
  'schemaReady',private.owned_ai_retirement_ready(),
  'exportExecutable',has_function_privilege('service_role',to_regprocedure('public.export_owned_ai_retirement_records(uuid)'),'EXECUTE'),
  'checkerSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('private.owned_ai_retirement_ready()')),
  'captureSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('private.retire_initial_feedback_publications(uuid,uuid,uuid,uuid)')),
  'exportSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.export_owned_ai_retirement_records(uuid)')),
  'metadataSha256',(select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.read_owned_ai_retirement_readiness()')));
end;

