declare item jsonb;p pg_catalog.pg_proc%rowtype;owner_oid oid;service_oid oid;role_name text;rel pg_catalog.pg_class%rowtype;col jsonb;expected smallint[];
 manifest jsonb:=$retirement_catalog$[{"signature":"private.owned_ai_retirement_guard()","sha256":"8cbbd706652a3f41eb39db83da3a34757557950bd06364d4b5741fdcf86d7ff2","resultType":"trigger","language":"plpgsql","definer":false,"strict":false,"volatility":"v","acl":"private"},{"signature":"private.retire_initial_feedback_publications(uuid,uuid,uuid,uuid)","sha256":"d066dfb3459d527b551ab81a564f85e896220e8b8f88749d21e378bd2b84cce0","resultType":"void","language":"plpgsql","definer":false,"strict":false,"volatility":"v","acl":"private"},{"signature":"public.export_owned_ai_retirement_records(uuid)","sha256":"dc09528d888b8089e5e87d2d1edf32a8796267683021b2085dac2d0e80f3db27","resultType":"jsonb","language":"plpgsql","definer":true,"strict":false,"volatility":"v","acl":"optional_service"},{"signature":"public.prepare_deletion_request(uuid,text)","sha256":"9f6e5fce4165a54d30007c73f48424ea70d7e650fda719b8c68f73fe009cd5fb","resultType":"jsonb","language":"plpgsql","definer":true,"strict":false,"volatility":"v","acl":"service"},{"signature":"public.complete_retention_item(uuid)","sha256":"ee73fa96bea622c7e0e6ed21318488646afbf754406eefd55574d1e087e69a2a","resultType":"boolean","language":"plpgsql","definer":true,"strict":false,"volatility":"v","acl":"service"},{"signature":"public.read_owned_ai_retirement_readiness()","sha256":"55a9f1dd2000b1a4cd1e258e68b0e56d36872422f7a76ced5c08585fe31d70b7","resultType":"jsonb","language":"plpgsql","definer":true,"strict":false,"volatility":"s","acl":"metadata"},{"signature":"private.initial_feedback_publication_ready()","sha256":"e3b968b748f2e67983a034885c920510566bb71c69fc3d7bc0204b7d22b005d4","resultType":"boolean","language":"plpgsql","definer":false,"strict":false,"volatility":"s","acl":"private"}]$retirement_catalog$::jsonb;
